export default {"1":{"html":"<p>راوی کا ایک سادہ سا منصوبہ تھا۔ ہر ماہ وہ ایک مستحکم انڈیکس فنڈ میں 10,000 روپے کا اضافہ کرتا اور اسے بھول جاتا۔ یہ ایک سال تک خاموشی سے کام کرتا رہا۔ پھر، 2023 کے آخر میں، اس کے ساتھیوں نے کچھ مہینوں میں دوگنا ہونے کی بات کرتے رہے۔ روی نے اسے چڑھتے ہوئے دیکھا، تمام رقم کی کھینچ کو محسوس کیا جو اسے \"کرنا چاہیے\" تھا، اور آخر کار 1,50,000 روپے لے کر داخل ہوا، جو اس کے معمول کے سائز سے کہیں زیادہ تھا۔ دو ہفتوں تک وہ بہت اچھا محسوس کرتا تھا۔ پھر تین سیشنز میں اسٹاک میں 20 فیصد کمی ہوئی۔ اس نے اپنے آپ سے کہا کہ یہ اچھال جائے گا۔ مزید گر گیا۔ ایک شام، تھکے ہارے اور خوفزدہ ہو کر، اس نے پوری چیز نیچے کے قریب بیچ دی اور اپنے محتاط ایس آئی پیز کے ایک سال سے بھی بڑے نقصان میں بند کر دیا۔ راوی کے پاس ذہانت کی کمی نہیں تھی۔ اس کا دماغ بالکل وہی کر رہا تھا جو اسے کرنے کے لیے بنایا گیا تھا۔</p>\n<p>یہ وہ غیر آرام دہ سچائی ہے جس سے یہ کورس شروع ہوتا ہے۔ وہ وائرنگ جس نے آپ کے آباؤ اجداد کو سوانا پر زندہ رکھا وہی وائرنگ ہے جو آپ کو اتار چڑھاؤ والے بازار میں سبوتاژ کرتی ہے۔</p>\n<h2 id=\"the-brain-you-trade-with-is-very-old\">آپ جس دماغ کے ساتھ تجارت کرتے ہیں وہ بہت پرانا ہے۔</h2>\n<p>تقریباً تمام انسانی تاریخ کے لیے، بقا نے چند سادہ جبلتوں کا بدلہ دیا۔ خطرے سے تیزی سے بھاگو۔ ریوڑ کے ساتھ رہو، کیونکہ اکیلا انسان مر گیا۔ جب تک یہ آپ کے سامنے ہو ثواب حاصل کریں۔ گھاس میں ایک نمونہ دیکھیں اور فرض کریں کہ یہ ایک شکاری ہے، کیونکہ غلط ہونے کی قیمت بہت کم تھی اور حقیقی گم ہونے کی قیمت موت تھی۔</p>\n<p>وہ جبلتیں زندہ رہنے کے لیے شاندار تھیں۔ وہ بازاروں میں پیسے کو سنبھالنے کے لیے تباہ کن ہونے کے قریب ہیں، کیونکہ مارکیٹ تقریباً بالکل برعکس رویے کا بدلہ دیتی ہے۔ خطرہ، ایک حادثہ، اکثر ہوتا ہے جب آپ کو خریدنا چاہیے۔ ریوڑ عام طور پر سب سے اونچی آواز میں ہوتا ہے۔ انعام کا پیچھا کرنا آپ کو بدترین قیمت پر لے جاتا ہے۔ اور قیمتوں کے چارٹ پر زیادہ تر \"پیٹرن\" صرف معنی کی طرح نظر آنے کے لیے تیار کیے گئے شور ہوتے ہیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"دو کالم ساتھ ساتھ۔ بائیں طرف قدیم دماغی جبلتوں کی فہرست دی گئی ہے جنہوں نے آباؤ اجداد کو زندہ رکھا۔ صحیح فہرست کرتا ہے کہ بازار اصل میں کیا انعامات دیتا ہے، جو کہ ہر جبلت کے برعکس ہے۔\">\n<rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" fill=\"#0d1117\"/>\n<defs>\n<marker id=\"psx\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#c44e52\"/></marker>\n</defs>\n<g font-family=\"ui-sans-serif, system-ui, sans-serif\">\n<rect x=\"30\" y=\"34\" width=\"320\" height=\"234\" rx=\"12\" fill=\"#11161d\" stroke=\"#dd8452\" stroke-width=\"1.6\"/>\n<text x=\"190\" y=\"60\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\">تمہارا پرانا دماغ کہتا ہے۔</text>\n<text x=\"50\" y=\"98\" fill=\"#cdd9e5\" font-size=\"12.5\">خطرے سے بھاگو، تیزی سے</text>\n<text x=\"50\" y=\"138\" fill=\"#cdd9e5\" font-size=\"12.5\">ریوڑ کے ساتھ رہیں</text>\n<text x=\"50\" y=\"178\" fill=\"#cdd9e5\" font-size=\"12.5\">ابھی انعام حاصل کریں۔</text>\n<text x=\"50\" y=\"218\" fill=\"#cdd9e5\" font-size=\"12.5\">ہر پیٹرن کا مطلب کچھ نہ کچھ ہوتا ہے۔</text>\n<rect x=\"410\" y=\"34\" width=\"320\" height=\"234\" rx=\"12\" fill=\"#11161d\" stroke=\"#4c72b0\" stroke-width=\"1.6\"/>\n<text x=\"570\" y=\"60\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\">مارکیٹ انعامات</text>\n<text x=\"430\" y=\"98\" fill=\"#9db4d6\" font-size=\"12.5\">خطرہ اکثر ہوتا ہے جب خریدنا ہے۔</text>\n<text x=\"430\" y=\"138\" fill=\"#9db4d6\" font-size=\"12.5\">ریوڑ سب سے اونچی آواز میں ہے۔</text>\n<text x=\"430\" y=\"178\" fill=\"#9db4d6\" font-size=\"12.5\">پیچھا کرنے سے آپ کو بدترین قیمت مل جاتی ہے۔</text>\n<text x=\"430\" y=\"218\" fill=\"#9db4d6\" font-size=\"12.5\">زیادہ تر پیٹرن صرف شور ہیں</text>\n<line x1=\"352\" y1=\"92\" x2=\"408\" y2=\"92\" stroke=\"#c44e52\" stroke-width=\"1.6\" marker-end=\"url(#psx)\"/>\n<line x1=\"352\" y1=\"132\" x2=\"408\" y2=\"132\" stroke=\"#c44e52\" stroke-width=\"1.6\" marker-end=\"url(#psx)\"/>\n<line x1=\"352\" y1=\"172\" x2=\"408\" y2=\"172\" stroke=\"#c44e52\" stroke-width=\"1.6\" marker-end=\"url(#psx)\"/>\n<line x1=\"352\" y1=\"212\" x2=\"408\" y2=\"212\" stroke=\"#c44e52\" stroke-width=\"1.6\" marker-end=\"url(#psx)\"/>\n</g>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">آپ کو زندہ رکھنے والی ہر جبلت بازار میں غلط راستے کی طرف اشارہ کرتی ہے۔</figcaption>\n</figure><h2 id=\"the-five-emotions-that-move-your-money\">پانچ جذبات جو آپ کے پیسے کو منتقل کرتے ہیں۔</h2>\n<p>آپ کو \"مارکیٹ\" محسوس نہیں ہوتا۔ آپ پانچ بہت ہی مخصوص جذبات محسوس کرتے ہیں، اور ہر ایک آپ کو پیشین گوئی کی غلطی کی طرف دھکیلتا ہے۔</p>\n<p><strong>خوف</strong> آپ کو نیچے فروخت کرتا ہے۔ مارچ 2020 میں، NIFTY چند ہفتوں میں 38% کے قریب گر گیا کیونکہ COVID پھیل گیا۔ جن سرمایہ کاروں کے پاس آواز کی ٹوکری تھی وہ تقریباً ایک سال کے اندر مکمل طور پر بحال ہو گئے۔ لیکن بہت سے لوگ گرتے ہوئے اسکرین کو برداشت نہیں کر سکے اور خوف کو روکنے کے لیے، کم کے قریب فروخت ہو گئے۔ خوف اس وقت برا فیصلہ نہیں لگتا۔ یہ راحت کی طرح محسوس ہوتا ہے۔</p>\n<p><strong>لالچ</strong> آپ کو پیچھا اور بڑا بناتا ہے. یہ وہی ہے جو راوی کو سا لگا۔ جب ایک چھوٹی ٹوپی یا گرم IPO دوگنا ہو رہا ہے اور آپ کے آس پاس ہر کوئی پیسہ کما رہا ہے، تو لالچ سرگوشی کرتا ہے کہ اس بار قوانین لاگو نہیں ہوتے ہیں۔ آپ دیر سے خریدتے ہیں، آپ بڑی خریدتے ہیں، اور آپ اسی طرح پہنچتے ہیں جیسے سمارٹ پیسہ جا رہا ہو۔</p>\n<p><strong>امید</strong> آپ کو ہارنے والا بناتا ہے، دعا کرنا کہ وہ واپس آجائے۔ ایسی پوزیشن جو 30٪ نیچے ہے عام طور پر کاٹ دی جانی چاہئے۔ لیکن امید نقصان کو \"حقیقی نہیں جب تک میں فروخت نہ کروں\" کے طور پر بیان کرتی ہے، لہذا آپ انتظار کریں، اور شامل کریں، اور انتظار کریں، جب کہ ایک چھوٹا سا زخم گہرا بن جاتا ہے۔</p>\n<p><strong>افسوس</strong> آپ کو اس اقدام کا پیچھا کرتا ہے جو آپ پہلے ہی کھو چکے ہیں۔ آپ اپنے بغیر کسی اسٹاک کو چلتے ہوئے دیکھتے ہیں، پچھتاوا ہوتا ہے، اور آپ اس احساس کو روکنے کے لیے دیر سے چھلانگ لگاتے ہیں، عام طور پر اس کے پلٹنے سے پہلے۔ یہ FOMO کا انجن ہے، گم ہونے کا خدشہ۔</p>\n<p><strong>ڈوپامائن</strong> خاموش ہے. جیتنے والی تجارت آپ کے دماغ کو ایک حقیقی کیمیکل ہٹ دیتی ہے، وہی انعامی نظام جو جوئے کو نشہ آور بنا دیتا ہے۔ خطرہ خود جیت نہیں ہے۔ یہ ہے کہ آپ کا دماغ پیچھا کرنے لگتا ہے۔ <em>احساس</em> جیتنے پر، لہذا آپ زیادہ تجارت کرتے ہیں، وہ سیٹ اپ لیتے ہیں جسے آپ عام طور پر چھوڑ دیتے ہیں، اور سنسنی کو مہارت کے ساتھ الجھا دیتے ہیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 340\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"مارکیٹ کی قیمت کا وکر ایک لہر کی طرح ہوتا ہے۔ نیچے کے قریب اس پر خوف اور بیچنے کی خواہش کا لیبل لگا ہوا ہے۔ راستے میں، امید اور FOMO۔ عروج پر، لالچ اور بڑا خریدنے کی خواہش۔ نیچے کے راستے میں، ایک ہارے ہوئے کو پکڑنے کی امید۔ صحیح جوابات احساس کے برعکس ہیں۔\">\n<rect x=\"0\" y=\"0\" width=\"760\" height=\"340\" fill=\"#0d1117\"/>\n<g font-family=\"ui-sans-serif, system-ui, sans-serif\">\n<line x1=\"70\" y1=\"40\" x2=\"70\" y2=\"270\" stroke=\"#30363d\" stroke-width=\"1.4\"/>\n<line x1=\"70\" y1=\"270\" x2=\"720\" y2=\"270\" stroke=\"#30363d\" stroke-width=\"1.4\"/>\n<text x=\"44\" y=\"160\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\" transform=\"rotate(-90 44 160)\">قیمت</text>\n<text x=\"395\" y=\"292\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\">وقت، وہی چکر جو بار بار دہرایا جاتا ہے۔</text>\n<path d=\"M70,250 C200,250 230,90 360,80 C470,72 500,250 620,250 C660,250 690,210 720,150\" fill=\"none\" stroke=\"#4c72b0\" stroke-width=\"2.6\"/>\n<circle cx=\"360\" cy=\"80\" r=\"6\" fill=\"#dd8452\"/>\n<text x=\"360\" y=\"56\" text-anchor=\"middle\" fill=\"#e0a878\" font-size=\"12.5\" font-weight=\"700\">GREED: یہاں بڑا خریدیں۔</text>\n<text x=\"360\" y=\"42\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\">سب سے محفوظ محسوس ہوتا ہے، سب سے زیادہ خطرناک ہے۔</text>\n<circle cx=\"210\" cy=\"170\" r=\"5\" fill=\"#8172b3\"/>\n<text x=\"210\" y=\"150\" text-anchor=\"middle\" fill=\"#a99bd0\" font-size=\"11.5\" font-weight=\"600\">FOMO / افسوس</text>\n<text x=\"210\" y=\"135\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"9.5\">اس اقدام کا پیچھا کریں جس سے آپ محروم ہو گئے۔</text>\n<circle cx=\"500\" cy=\"170\" r=\"5\" fill=\"#c8a04e\"/>\n<text x=\"520\" y=\"160\" text-anchor=\"middle\" fill=\"#d2b15e\" font-size=\"11.5\" font-weight=\"600\">HOPE: ہارنے والے کو پکڑو</text>\n<circle cx=\"620\" cy=\"250\" r=\"6\" fill=\"#c44e52\"/>\n<text x=\"628\" y=\"248\" fill=\"#e09ea0\" font-size=\"12.5\" font-weight=\"700\">FEAR: یہاں فروخت کریں۔</text>\n<text x=\"628\" y=\"264\" fill=\"#8b949e\" font-size=\"10\">راحت کی طرح محسوس ہوتا ہے، نقصان کو تالا لگا دیتا ہے</text>\n</g>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">احساس سب سے مضبوط ہے جہاں یہ سب سے زیادہ غلط ہے: سب سے اوپر لالچی، نیچے خوفزدہ۔</figcaption>\n</figure><h2 id=\"why-uncertainty-makes-it-worse\">کیوں غیر یقینی صورتحال اسے بدتر بناتی ہے۔</h2>\n<p>پرانی وائرنگ کا ایک اور ٹکڑا ہے جو اہمیت رکھتا ہے: آپ کا دماغ نہ جاننے سے نفرت کرتا ہے۔ بے یقینی خطرے کی طرح محسوس ہوتی ہے، اس لیے دماغ اس پر کہانی مسلط کرنے کے لیے دوڑتا ہے۔ تین سبز موم بتیاں \"ایک اپ ٹرینڈ\" بن جاتی ہیں۔ ایک اسٹاک جو ایک سطح سے دو بار اچھالتا ہے وہ \"سپورٹ جو ہمیشہ برقرار رہتا ہے\" بن جاتا ہے۔ تین جیتنے والی تجارتوں کا ایک رن بن جاتا ہے \"میں نے اپنا کنارہ ڈھونڈ لیا ہے۔\"</p>\n<p>مارکیٹیں بے ترتیبی سے بھری ہوئی ہیں، اور ایک دماغ جس کو پیٹرن کی ضرورت ہے وہ خالص شور سے تیار کرے گا۔ یہ غلط یقین تسلی بخش ہے، اور یہ بالکل وہی ہے جو آپ کو بڑا بناتا ہے اور اپنے خطرے کی جانچ کرنا چھوڑ دیتا ہے۔ \"مجھے نہیں معلوم\" کی تکلیف وہ احساس ہے جس کے ساتھ ایک نظم و ضبط تاجر بیٹھنا سیکھتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آپ خوف، لالچ، امید، ندامت، یا ڈوپامائن ہائی کو حذف نہیں کر سکتے۔ وہ اندر سے بنائے گئے ہیں۔ پورا کھیل کم محسوس کرنے کے لیے نہیں ہے، بلکہ سادہ سسٹم اور اصول بنانا ہے جو جذبات کے آنے سے پہلے آپ کے لیے فیصلہ کریں۔</p>\n</div></div>\n<h2 id=\"emotion-mistake-and-the-better-response\">جذبات، غلطی، اور بہتر جواب</h2>\n<table>\n<thead>\n<tr>\n<th>جذبات</th>\n<th>یہ آپ کو کیا کرنے پر مجبور کرتا ہے۔</th>\n<th>بہتر جواب</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>خوف</td>\n<td>نچلے حصے میں آواز کی پوزیشن فروخت کریں۔</td>\n<td>داخل ہونے سے پہلے اپنے باہر نکلنے کا فیصلہ کریں، پھر اصول کی پیروی کریں، احساس کی نہیں۔</td>\n</tr>\n<tr>\n<td>لالچ</td>\n<td>ایک ریلی کا پیچھا کریں اور بڑا کریں</td>\n<td>اپنی پوزیشن کا سائز پہلے سے طے کریں۔ غلط سائز پر ایک اچھا خیال اب بھی برا تجارت ہے۔</td>\n</tr>\n<tr>\n<td>امید</td>\n<td>ہارے ہوئے کو پکڑو، دعا کرو کہ وہ لوٹ آئے</td>\n<td>داخل ہونے پر سٹاپ لاس سیٹ کریں؛ امید ایک منصوبہ نہیں ہے</td>\n</tr>\n<tr>\n<td>افسوس / FOMO</td>\n<td>اس اقدام کا پیچھا کریں جو آپ پہلے ہی کھو چکے ہیں۔</td>\n<td>مس قبول کریں؛ کل ہمیشہ ایک اور سیٹ اپ ہوتا ہے۔</td>\n</tr>\n<tr>\n<td>ڈوپامائن</td>\n<td>اگلی جیت کا پیچھا کرتے ہوئے اوور ٹریڈ</td>\n<td>اپنے آپ کو پیروی کے عمل سے پرکھیں، جیت کے سنسنی سے نہیں۔</td>\n</tr>\n</tbody></table>\n<p>دائیں ہاتھ کے کالم میں پیٹرن کو دیکھیں: ہر اچھا ردعمل ایک فیصلہ ہوتا ہے۔ <em>پیشگی، پرسکون میں</em>، تاکہ اس لمحے میں جذبات کو ہائی جیک کرنے کے لئے کچھ نہیں بچا۔</p>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>سب سے عام جال یہ ماننا ہے کہ آپ صرف \"اگلی بار پرسکون رہیں گے۔\" آپ نہیں کریں گے۔ پرسکون - آپ ایک منصوبہ لکھنا خوفزدہ شخص سے مختلف ہے - آپ صبح 9:30 بجے پوزیشن کو 20٪ گرتے ہوئے دیکھتے ہیں۔ اس وقت قوتِ ارادی آپ کی ملکیت کا سب سے کمزور آلہ ہے۔ ایک تحریری قاعدہ، ایک مقررہ پوزیشن کا سائز، ایک پہلے سے طے شدہ اسٹاپ، یہ وہی ہیں جو حقیقت میں جب جذبات سے ٹکرا جاتے ہیں۔</p>\n</div></div>\n<h2 id=\"which-emotion-bites-each-type-hardest\">کون سا جذبات ہر قسم کو سختی سے کاٹتا ہے۔</h2>\n<p>وہی پانچ جذبات عالمگیر ہیں، لیکن ہر قسم کے شریک میں ایک ایسا ہوتا ہے جو انہیں سب سے زیادہ تکلیف دیتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>حصہ لینے والا</th>\n<th>جذبات جو سب سے زیادہ کاٹتے ہیں۔</th>\n<th>یہ عام طور پر کیسے ظاہر ہوتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>خوف</td>\n<td>مارچ 2020 جیسے حادثے میں آواز کی ٹوکری کو گھبراہٹ میں بیچنا</td>\n</tr>\n<tr>\n<td>اسٹاک تاجر</td>\n<td>افسوس / FOMO</td>\n<td>اس اقدام کے بعد بریک آؤٹ کا پیچھا کرتے ہوئے، گرم چھوٹی ٹوپی کا سب سے اوپر خریدنا</td>\n</tr>\n<tr>\n<td>ایف اینڈ او خریدار</td>\n<td>لالچ</td>\n<td>سستے ہفتہ وار اختیارات پر بڑا کرنا، 10x ادائیگی کا خواب دیکھنا</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>امید</td>\n<td>ہارنے والے شارٹ کو کاٹنے سے انکار کرنا کیونکہ اقدام ان کے خلاف چلتا رہتا ہے۔</td>\n</tr>\n</tbody></table>\n<p>اگر آپ اپنے کردار کو جانتے ہیں، تو آپ پہلے ہی جانتے ہیں کہ اپنے اندر کس جذبات کو سب سے زیادہ قریب سے دیکھنا ہے۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>اپنے جذبات کو سمجھنا پہلا قدم ہے، لیکن صرف آگاہی ہی ایک کمزور ڈھال ہے، اور یہ کہنا ایمانداری کی بات ہے کہ یہ باب کہاں رکتا ہے۔</p>\n<p>جال کو جاننا آپ کو اس میں پڑنے سے نہیں روکتا۔ بہت سارے لوگ خوف اور لالچ کو بالکل ٹھیک بیان کر سکتے ہیں اور پھر بھی اگلے مہینے سب سے نیچے فروخت کر سکتے ہیں۔ بصیرت ایک نظام نہیں ہے۔ یہی وجہ ہے کہ آگے کے ابواب ٹھوس اصول، پوزیشن کا سائز، سٹاپ لاسز، چیک لسٹ بناتے ہیں، تاکہ اچھے برتاؤ کا انحصار اس بات پر نہ ہو کہ آپ کسی برے دن مضبوط محسوس کرتے ہیں۔</p>\n<p>مخالف ناکامی بھی حقیقی ہے۔ کچھ لوگ اس کو پڑھتے ہیں اور تمام جذبات کو دبانے کا فیصلہ کرتے ہیں، \"روبوٹ\" بن جاتے ہیں۔ یہ بھی کام نہیں کرتا؛ جذبات مفید معلومات لے جاتے ہیں، اور ان کو بوتل میں ڈالنا حتمی ردعمل کو بدتر بنا دیتا ہے۔ مقصد ایک بے حس تاجر نہیں ہے۔ یہ ایک تاجر ہے جو خوف محسوس کرتا ہے، اسے محسوس کرتا ہے، اور بہرحال تحریری اصول کی پیروی کرتا ہے۔</p>\n<p>اور نفسیات کی کوئی مقدار کسی بری حکمت عملی کو ٹھیک نہیں کرتی ہے۔ اگر آپ کے طریقہ کار میں کوئی حقیقی برتری نہیں ہے، تو پرسکون رہنا آپ کو زیادہ آہستہ اور شائستگی سے پیسے کھونے دیتا ہے۔ مائنڈ سیٹ ایک صوتی عمل کو ضرب دیتا ہے۔ یہ ٹوٹے ہوئے کو نہیں بچا سکتا۔</p>\n<p>یہ باب صرف سیکھنے کے لیے ہے اور سرمایہ کاری کا مشورہ نہیں ہے۔ یہاں ہر نمبر اور مثال کو مثال کے طور پر سمجھیں، نہ کہ اپنے پیسے کے لیے سفارش۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> انسانی دماغ غیر مستحکم بازاروں میں پیسے کو سنبھالنے کے لیے بری طرح سے موزوں کیوں ہے؟</summary><p>یہ بقا کی جبلتوں کے لیے وائرڈ ہے جس نے ہمارے آباؤ اجداد کی مدد کی: خطرے سے بھاگیں، ریوڑ کی پیروی کریں، انعامات حاصل کریں، اور ہر جگہ نمونے دیکھیں۔ مارکیٹیں تقریباً اس کے برعکس انعام دیتی ہیں، لہٰذا وہی جبلتیں ہمیں نیچے بیچنے، اوپر کا پیچھا کرنے اور شور میں معنی تلاش کرنے پر مجبور کرتی ہیں۔</p>\n</details><details>\n<summary><strong>2.</strong> ہر جذبات کو اس غلطی سے جوڑیں: خوف، لالچ، امید، ندامت۔</summary><p>خوف آپ کو نیچے کی آواز کی پوزیشن بیچنے پر مجبور کرتا ہے۔ لالچ آپ کا پیچھا کرتا ہے اور بڑا کرتا ہے۔ امید آپ کو ہارے ہوئے کو پکڑنے کے لیے دعا کرتی ہے کہ وہ صحت یاب ہو جائے۔ افسوس، یا FOMO، آپ کو اس اقدام کا پیچھا کرنے پر مجبور کرتا ہے جس سے آپ پہلے ہی چھوٹ چکے ہیں۔</p>\n</details><details>\n<summary><strong>3.</strong> جیتنے والی تجارت سے ڈوپامائن کے مارے جانے کا کیا خطرہ ہے؟</summary><p>جیت ایک حقیقی کیمیائی انعام کو متحرک کرتی ہے، جوا کی لت کے پیچھے وہی نظام۔ آپ کا دماغ اچھے فیصلوں کی بجائے جیتنے کے احساس کا پیچھا کرنا شروع کر دیتا ہے، اس لیے آپ زیادہ تجارت کرتے ہیں، کمزور سیٹ اپ لیتے ہیں، اور سنسنی کو مہارت سمجھ کر غلطی کرتے ہیں۔</p>\n</details><details>\n<summary><strong>4.</strong> غیر یقینی صورتحال ابتدائیوں کو غلطیوں کی طرف کیوں دھکیلتی ہے؟</summary><p>دماغ نہ جانے کو خطرہ سمجھتا ہے اور کہانی مسلط کرنے کے لیے دوڑتا ہے، بے ترتیب قیمتوں کو غلط \"رجحانات\" اور \"سپورٹ لیولز\" میں بدل دیتا ہے۔ اس سے تیار شدہ یقین آرام دہ محسوس کرتا ہے اور لوگوں کو بڑا بناتا ہے اور ان کے خطرے کو دیکھنا چھوڑ دیتا ہے۔</p>\n</details><details>\n<summary><strong>5.</strong> اگر آپ ان جذبات کو حذف نہیں کر سکتے تو اصل مقصد کیا ہے؟</summary><p>کم محسوس کرنے کے لئے نہیں، لیکن سادہ نظام اور قواعد، فکسڈ پوزیشن سائز، پہلے سے طے شدہ اسٹاپس، تحریری منصوبے، جذبات کے آنے سے پہلے پرسکون انداز میں فیصلہ کرنے کے لیے۔ پہلے سے بنایا گیا اصول وہی ہے جو اس وقت برقرار رہتا ہے جب قوت ارادی ناکام ہوجاتی ہے۔</p>\n</details>\n","toc":[{"level":2,"text":"آپ جس دماغ کے ساتھ تجارت کرتے ہیں وہ بہت پرانا ہے۔","id":"the-brain-you-trade-with-is-very-old"},{"level":2,"text":"پانچ جذبات جو آپ کے پیسے کو منتقل کرتے ہیں۔","id":"the-five-emotions-that-move-your-money"},{"level":2,"text":"کیوں غیر یقینی صورتحال اسے بدتر بناتی ہے۔","id":"why-uncertainty-makes-it-worse"},{"level":2,"text":"جذبات، غلطی، اور بہتر جواب","id":"emotion-mistake-and-the-better-response"},{"level":2,"text":"کون سا جذبات ہر قسم کو سختی سے کاٹتا ہے۔","id":"which-emotion-bites-each-type-hardest"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"2":{"html":"<p>بازاروں میں پیسے کے بارے میں سب سے عجیب بات یہ ہے: اسے کھونا اور حاصل کرنا برابر محسوس نہیں ہوتا۔ 5,000 روپے جیتیں اور آپ ایک منٹ کے لیے مسکرا دیں۔ وہی 5000 روپے کھو دیں اور یہ گھنٹوں، شاید ساری رات ڈنکتا رہتا ہے۔ وہ یک طرفہ احساس آپ میں کوئی عیب نہیں ہے۔ یہ تقریباً ہر انسانی دماغ میں بنا ہوا ہے۔ اور ایک بار جب آپ اسے سمجھ لیں، تو آپ بالکل دیکھ سکتے ہیں کہ کیوں بہت سارے ابتدائی افراد ایک ہی سہ پہر کے اندر ایک چھوٹے، عام نقصان کو بہت بڑے نقصان میں بدل دیتے ہیں۔ یہ باب اس پھندے کے بارے میں ہے، \"اسے واپس حاصل کرنے\" کی خواہش، اور اس سے پہلے کہ یہ آپ کے کھاتے کو کھا لے، اس سے کیسے بچیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>میرا کا منگل کا ایک پرسکون منصوبہ تھا: ایک تجارت، ایک سخت سٹاپ لاس، صبح 10 بجے تک تجارت اس کے خلاف ہو گئی اور اس کے سٹاپ نقصان نے اسے مائنس 4,000 روپے پر لے لیا۔ پریشان کن، لیکن چھوٹا، اس کی منصوبہ بندی کے اندر اندر. سوائے اس کے کہ اسے چھوٹا محسوس نہیں ہوا۔ یہ ایک توہین کی طرح محسوس ہوا۔ تو وہ سیدھی واپس اندر کود پڑی، اس بار بڑا، کوئی حقیقی سیٹ اپ نہیں، بس صحیح ہونے کی ضرورت ہے۔ اس کا 9000 روپے کا نقصان ہوا۔ اب غصے میں، اس نے \"یہ سب ایک ہی شاٹ میں واپس کرنے\" کے لیے دوبارہ دوگنا کیا۔ صبح 11:30 بجے تک 4,000 روپے کا معمول کا نقصان 38,000 روپے بن گیا تھا، جو کہ اس کے پچھلے دو مہینوں کے مجموعی نقصان سے زیادہ تھا۔ مارکیٹ نے کبھی کوئی ڈرامائی نہیں کیا۔ میرا نے کیا۔</p>\n</div></div>\n<p>میرا تجزیہ سے لاپرواہ نہیں تھی۔ وہ ایک احساس سے ہائی جیک ہو گئی تھی۔ پہلا نقصان ٹھیک تھا۔ اس کے بعد سب کچھ اس کا دماغ ڈنک کو مٹانے کی کوشش کر رہا تھا، اور صافی مزید مہنگا ہوتا رہا۔</p>\n<h2 id=\"a-loss-hurts-about-twice-as-much-as-a-gain-feels-good\">نقصان اس سے دوگنا زیادہ تکلیف دیتا ہے جتنا فائدہ اچھا لگتا ہے۔</h2>\n<p>طرز عمل کے محققین نے کئی دہائیوں سے اس کا مطالعہ کیا ہے، اور یہ تلاش نمایاں طور پر مطابقت رکھتی ہے: زیادہ تر لوگوں کے لیے، رقم کھونے کا درد تقریباً ہوتا ہے۔ <em>دو بار</em> اتنی ہی مضبوط اتنی ہی رقم حاصل کرنے کی خوشی۔ اسے کہتے ہیں۔ <strong>نقصان سے بچنا</strong>بس، ہم جیتنے سے کہیں زیادہ ہارنے سے نفرت کرتے ہیں۔</p>\n<p>آپ اسے بازار سے باہر بھی محسوس کرتے ہیں۔ سڑک پر 500 روپے تلاش کرنا ایک چھوٹی سی لفٹ ہے۔ آپ کی جیب سے 500 روپے کا کھو جانا باقی دن آپ کا موڈ خراب کر دیتا ہے۔ وہی 500 روپے۔ بہت مختلف وزن۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 280\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"مرکزی لائن سے دو بار۔ اوپر کی طرف اشارہ کرنے والی ایک چھوٹی سبز بار پانچ ہزار روپے کے منافع سے چھوٹی خوشی کو ظاہر کرتی ہے۔ نیچے کی طرف اشارہ کرنے والی ایک سرخ بار، تقریباً دوگنا لمبا، پانچ ہزار روپے کے نقصان سے بڑے درد کو ظاہر کرتی ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"280\" fill=\"#0d1117\"/>\n  <text x=\"30\" y=\"34\" fill=\"#e6edf3\" font-weight=\"700\" font-family=\"sans-serif\" font-size=\"15\">وہی روپیہ، غیر مساوی احساسات</text>\n  <line x1=\"60\" y1=\"150\" x2=\"710\" y2=\"150\" stroke=\"#30363d\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n  <text x=\"715\" y=\"154\" fill=\"#8b949e\" font-family=\"sans-serif\" font-size=\"10\">غیر جانبدار</text>\n  <!-- gain bar -->\n  <rect x=\"200\" y=\"100\" width=\"120\" height=\"50\" rx=\"6\" fill=\"#55a868\" fill-opacity=\"0.85\"/>\n  <text x=\"260\" y=\"90\" fill=\"#cdd9e5\" font-family=\"sans-serif\" font-size=\"12\" text-anchor=\"middle\">+5,000 روپے کا فائدہ</text>\n  <text x=\"260\" y=\"130\" fill=\"#0d1117\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\">تھوڑا اچھا</text>\n  <!-- loss bar -->\n  <rect x=\"440\" y=\"150\" width=\"120\" height=\"100\" rx=\"6\" fill=\"#c44e52\" fill-opacity=\"0.85\"/>\n  <text x=\"500\" y=\"205\" fill=\"#ffffff\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\">دو گنا برا</text>\n  <text x=\"500\" y=\"270\" fill=\"#cdd9e5\" font-family=\"sans-serif\" font-size=\"12\" text-anchor=\"middle\">-5000 روپے کا نقصان</text>\n  <!-- height bracket note -->\n  <text x=\"610\" y=\"200\" fill=\"#dd8452\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"700\">تقریبا 2x</text>\n  <text x=\"610\" y=\"216\" fill=\"#8b949e\" font-family=\"sans-serif\" font-size=\"11\">کھینچنا</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">مساوی مقدار، لیکن نقصان آپ کو تقریباً دوگنا سخت کر دیتا ہے۔ یہ فرق سب سے زیادہ برے فیصلوں کو چلاتا ہے۔</figcaption>\n</figure>\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>نقصان تقریباً دو گنا زیادہ تکلیف دیتا ہے جتنا کہ مساوی فائدہ اچھا لگتا ہے۔ یہ عدم توازن، برا تجزیہ نہیں، وہی ہے جو ابتدائی افراد کو جلدی، بڑے، جذباتی تجارت میں دھکیلتا ہے۔</p>\n</div></div>\n<h2 id=\"how-the-imbalance-warps-your-trading\">عدم توازن آپ کی تجارت کو کس طرح روکتا ہے۔</h2>\n<p>یہ واحد نرالا آپ کے رویے کو دو مخالف اور یکساں طور پر نقصان دہ طریقوں سے موڑ دیتا ہے۔</p>\n<p><strong>آپ نے جیتنے والوں کو بہت جلد کاٹ دیا۔</strong> جب کوئی تجارت منافع میں ہوتی ہے تو اس نفع کو واپس دینے کا خوف بہت زیادہ محسوس ہوتا ہے، کیونکہ نقصان سے دوگنا نقصان ہوتا ہے۔ لہذا آپ چھوٹی جیت کو تیزی سے پکڑیں ​​گے اور راحت محسوس کریں گے۔ آپ نے اپنی اچھی تجارت کو اسی طرح بیچ دیا جیسے یہ کام کرنا شروع کر رہا تھا۔</p>\n<p><strong>آپ ہارنے والوں کو بہت لمبا رکھتے ہیں۔</strong> جب تجارت کم ہو تو اسے بند کرنا <em>نقصان کو حقیقی بناتا ہے۔</em>، اور آپ کا دماغ اس درد سے بچنے کے لیے تقریباً کچھ بھی کرے گا۔ تو تم انتظار کرو۔ آپ امید کرتے ہیں۔ آپ اپنے آپ کو بتائیں کہ یہ \"کسی بھی لمحے\" واپس آجائے گا۔ نقصان خاموشی سے بڑھتا ہے جب آپ چھوٹے کو قبول کرنے سے انکار کرتے ہیں۔</p>\n<p>ان کو ایک ساتھ رکھیں اور آپ کو کام کے بالکل برعکس ملے گا: چھوٹی جیت، بڑا نقصان۔ آپ اپنے جذبات کو اپنی تجارت کا سائز دینے دیتے ہیں، اور احساسات ہمیشہ ان کا سائز پیچھے کی طرف کرتے ہیں۔</p>\n<h2 id=\"the-revenge-trade-and-the-tilt-state\">انتقامی تجارت، اور \"جھکاؤ\" کی حالت</h2>\n<p>اب ہم خطرناک حصے کی طرف آتے ہیں۔ اے <strong>انتقامی تجارت</strong> وہی ہوتا ہے جو نقصان کے فوراً بعد ہوتا ہے، جب ڈنک تازہ ہوتا ہے۔ آپ اپنے منصوبے کی تجارت بند کر دیں اور اپنے جذبات کی تجارت شروع کر دیں۔ مقصد خاموشی سے \"ایک اچھا فیصلہ کریں\" سے \"میرے پیسے واپس حاصل کریں، ابھی\" میں بدل جاتا ہے۔ آپ ایک بڑی، ڈھیلی پوزیشن پر رکھتے ہیں، اکثر کوئی حقیقی سیٹ اپ کے بغیر، بس دوبارہ محسوس کرنے کے لیے۔</p>\n<p>پوکر کے کھلاڑیوں کے پاس اس ذہنی حالت کے لیے ایک بہترین لفظ ہے: <strong>جھکاؤ</strong>. جھکاؤ پر، آپ ابھی بھی اسکرین پر بیٹھے ہیں، لیکن آپ کے دماغ کا پرسکون، اصول کے مطابق چلنے والا حصہ لاگ آف ہو چکا ہے۔ اب ہر فیصلہ غصے اور عجلت سے ہوتا ہے۔ اور یہاں ظالمانہ موڑ ہے، آپ کا آخری نقصان جتنا بڑا ہوگا، بدلہ لینے کی تجارت کی خواہش اتنی ہی مضبوط ہوگی، جو بالکل اسی وقت ہوتا ہے جب آپ کا فیصلہ بدترین ہوتا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 350\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک چار قدمی لوپ۔ نقصان اٹھانا ڈنک کو محسوس کرنے اور جھکاؤ کی طرف لے جاتا ہے، جس کی وجہ سے ایک بڑی سستی تجارت ہوتی ہے، جو اس سے بھی بڑے نقصان کی طرف جاتا ہے، جو شروع میں واپس آتا ہے۔ ایک ضمنی پیمانہ ظاہر کرتا ہے کہ اکاؤنٹ ہر لیپ میں مزید گرتا ہے: مائنس پانچ ہزار، پھر مائنس پندرہ ہزار، پھر مائنس چالیس ہزار۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"350\" fill=\"#0d1117\"/>\n  <defs>\n    <marker id=\"rv\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n      <path d=\"M0,0 L10,5 L0,10 z\" fill=\"#dd8452\"/>\n    </marker>\n  </defs>\n  <text x=\"30\" y=\"32\" fill=\"#e6edf3\" font-weight=\"700\" font-family=\"sans-serif\" font-size=\"15\">انتقامی سرپل: ہر گود بدتر ہے۔</text>\n  <!-- boxes -->\n  <rect x=\"60\" y=\"60\" width=\"210\" height=\"62\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\" stroke-width=\"1.5\"/>\n  <text x=\"165\" y=\"88\" fill=\"#cdd9e5\" font-family=\"sans-serif\" font-size=\"13\" text-anchor=\"middle\">1. ایک چھوٹا سا نقصان لے لو</text>\n  <text x=\"165\" y=\"107\" fill=\"#8b949e\" font-family=\"sans-serif\" font-size=\"11\" text-anchor=\"middle\">سٹاپ-لاس ہٹ، منصوبہ بندی کے اندر</text>\n  <rect x=\"430\" y=\"60\" width=\"230\" height=\"62\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\" stroke-width=\"1.5\"/>\n  <text x=\"545\" y=\"88\" fill=\"#cdd9e5\" font-family=\"sans-serif\" font-size=\"13\" text-anchor=\"middle\">2. ڈنک محسوس کریں (جھکاؤ)</text>\n  <text x=\"545\" y=\"107\" fill=\"#8b949e\" font-family=\"sans-serif\" font-size=\"11\" text-anchor=\"middle\">ابھی، برابر ہونے کی ترغیب دیں۔</text>\n  <rect x=\"430\" y=\"240\" width=\"230\" height=\"62\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\" stroke-width=\"1.5\"/>\n  <text x=\"545\" y=\"268\" fill=\"#cdd9e5\" font-family=\"sans-serif\" font-size=\"13\" text-anchor=\"middle\">3. بڑی، میلی تجارت</text>\n  <text x=\"545\" y=\"287\" fill=\"#8b949e\" font-family=\"sans-serif\" font-size=\"11\" text-anchor=\"middle\">کوئی حقیقی سیٹ اپ نہیں، زیادہ سائز</text>\n  <rect x=\"60\" y=\"240\" width=\"210\" height=\"62\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\" stroke-width=\"1.5\"/>\n  <text x=\"165\" y=\"268\" fill=\"#cdd9e5\" font-family=\"sans-serif\" font-size=\"13\" text-anchor=\"middle\">4. اس سے بھی بڑا نقصان</text>\n  <text x=\"165\" y=\"287\" fill=\"#8b949e\" font-family=\"sans-serif\" font-size=\"11\" text-anchor=\"middle\">قدم 1 پر واپس، لیکن کم</text>\n  <!-- arrows clockwise -->\n  <line x1=\"270\" y1=\"91\" x2=\"424\" y2=\"91\" stroke=\"#dd8452\" stroke-width=\"2\" marker-end=\"url(#rv)\"/>\n  <line x1=\"545\" y1=\"122\" x2=\"545\" y2=\"234\" stroke=\"#dd8452\" stroke-width=\"2\" marker-end=\"url(#rv)\"/>\n  <line x1=\"430\" y1=\"271\" x2=\"276\" y2=\"271\" stroke=\"#dd8452\" stroke-width=\"2\" marker-end=\"url(#rv)\"/>\n  <line x1=\"165\" y1=\"240\" x2=\"165\" y2=\"128\" stroke=\"#c44e52\" stroke-width=\"2\" marker-end=\"url(#rv)\"/>\n  <!-- worsening account scale -->\n  <text x=\"360\" y=\"172\" fill=\"#c44e52\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\">ہر گود کا حساب لگائیں</text>\n  <text x=\"360\" y=\"195\" fill=\"#8b949e\" font-family=\"sans-serif\" font-size=\"12\" text-anchor=\"middle\">-5,000  &#8594;  -15,000  &#8594;  -40,000</text>\n  <text x=\"360\" y=\"330\" fill=\"#dd8452\" font-family=\"sans-serif\" font-size=\"11\" text-anchor=\"middle\">جیتنے کا واحد طریقہ یہ ہے کہ لوپ کو گھمانے کو روکا جائے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">لوپ واپس لڑنے کی طرح محسوس ہوتا ہے. یہ دراصل سوراخ کو تیزی سے کھود رہا ہے۔</figcaption>\n</figure>\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>بدلہ لینے کا کلاسک اقدام: سٹاپ لوس کے فوراً بعد، آپ \"ایک ہی شاٹ میں اسے واپس جیتنے\" کے لیے فوری طور پر ایک بڑی تجارت شروع کر دیتے ہیں۔ تجارت میں یہ سب سے مہنگی عادت ہے۔ بہتر اقدام یہ ہے کہ کچھ نہ کیا جائے، اس بات کو قبول کریں کہ منصوبہ بند نقصان کا نظام صحیح طریقے سے کام کر رہا تھا، اور عام نقصان کو جذباتی ہونے دینے سے انکار کر دیں۔</p>\n</div></div>\n<h2 id=\"how-to-stop-after-damage\">نقصان کے بعد کیسے روکا جائے۔</h2>\n<p>جب آپ جھکاؤ پر ہوتے ہیں تو آپ جھکاؤ سے نکلنے کا راستہ نہیں سوچ سکتے۔ درست کرنا اس وقت قوت ارادی نہیں ہے، یہ ایک اصول ہے جسے آپ پہلے سے ترتیب دیتے ہیں، جب آپ پرسکون ہوتے ہیں، جو آپ کے لرزتے ہاتھوں سے فیصلہ لے لیتا ہے۔ تین پرتیں مل کر کام کرتی ہیں۔</p>\n<p><strong>1. روزانہ نقصان کی سخت حد۔</strong> فیصلہ کریں، دن شروع ہونے سے پہلے، آپ ایک ہی دن میں سب سے زیادہ کھونا چاہتے ہیں۔ جب آپ اسے مارتے ہیں، تو آپ کام کرچکے ہیں، اسکرین آف، کوئی استثنا نہیں ہے۔ یہ رسک مینجمنٹ کورس کے پوزیشن کے سائز اور تباہی کے خطرے سے متعلق آئیڈیاز سے سیدھا تعلق رکھتا ہے: اگر آپ فی تجارت میں ایک چھوٹا سا ٹکڑا خطرے میں ڈالتے ہیں، تو ایک برا دن ایک معروف، زندہ رہنے کے قابل نمبر پر ختم ہو جاتا ہے۔ کہو کہ آپ کا اکاؤنٹ 1,00,000 روپے ہے اور آپ کا یومیہ سٹاپ 3% ہے، یعنی 3,000 روپے۔ 3,000 روپے کے نقصان کے بعد، تجارتی دن ختم ہو گیا، جیتنے کی خواہش ہے یا نہیں۔</p>\n<p><strong>2. ایک خراب نقصان کے بعد ٹھنڈا ہونے کا اصول۔</strong> آپ کو پیچھے ہٹنے کے لیے روزانہ کی حد کو مارنے کی ضرورت نہیں ہے۔ ایک تکلیف دہ نقصان توقف کی کافی وجہ ہے۔ اٹھو۔ ایک مقررہ وقت، پندرہ منٹ، ایک گھنٹہ، باقی سیشن کے لیے اسکرین سے دور چلیں۔ جب آپ چارٹ کی طرف نہیں گھور رہے ہوتے ہیں تو ڈنک تیزی سے ختم ہو جاتا ہے۔ اگر آپ بھوکے رہتے ہیں تو جھکاؤ کی شیلف لائف مختصر ہوتی ہے۔</p>\n<p><strong>3. جسمانی طور پر دور ہونا۔</strong> یہ بات کرنے میں بہت آسان لگتا ہے، لیکن یہ وہاں کا سب سے قابل اعتماد ٹول ہے۔ آپ انتقامی تجارت نہیں کر سکتے جس مقام تک آپ پہنچ نہیں سکتے۔ ایپ بند کریں۔ کمرہ چھوڑ دو۔ چائے بنائیں۔ مارکیٹ کل بھی موجود رہے گی، اور اسی طرح، اہم طور پر، آپ کا سرمایہ ہوگا۔</p>\n<p>اس لمحے کو چلانے کے لیے یہاں ایک ٹھنڈا چیک لسٹ ہے جس سے نقصان ہونا چاہیے سے زیادہ ہوتا ہے:</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> اسے اونچی آواز میں نام دیں: \"میں نے ابھی نقصان اٹھایا ہے اور میں اسے واپس لینا چاہتا ہوں۔\" یہ کہنے سے آٹو پائلٹ ٹوٹ جاتا ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> نمبر چیک کریں: کیا یہ ایک ہے۔ <em>منصوبہ بندی</em> نقصان (میرے اسٹاپ نے اپنا کام کیا) یا ایک <em>غیر منصوبہ بند</em> ایک (میں نے ایک اصول توڑا)؟</li>\n<li><input disabled=\"\" type=\"checkbox\"> کیا میں اپنے یومیہ نقصان کی حد پر یا اس کے قریب ہوں؟ اگر ہاں، تو دن ختم ہو گیا ہے۔ چپٹا اور روکنا۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> کم از کم ٹھنڈا ہونے والے وقت کے لیے اسکرین سے دور ہٹیں جو میں نے پہلے سے طے کیا تھا۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> کسی بھی نئی تجارت سے پہلے، پوچھیں: کیا میں یہ درست تجارت کروں گا اگر آخری ایک فاتح ہوتا؟ اگر نہیں، تو یہ انتقام ہے، اسے چھوڑ دیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں نے کیا محسوس کیا اس کے بارے میں ایک جریدے میں ایک لائن لکھیں۔ کل میں اسے پڑھوں گا اور سیکھوں گا۔</li>\n</ul>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>یہ تعلیم ہے، ذاتی مشورے نہیں۔ 3% یومیہ-حد کا اعداد و شمار آپ کے اکاؤنٹ کے لیے تجویز نہیں بلکہ وجدان پیدا کرنے کے لیے ایک مثالی مثال ہے۔ صحیح نمبر آپ کے سرمائے، حکمت عملی اور خطرے کی برداشت پر منحصر ہے۔</p>\n</div></div>\n<h2 id=\"how-revenge-shows-up-for-each-kind-of-participant\">ہر قسم کے شریک کے لیے بدلہ کیسے ظاہر ہوتا ہے۔</h2>\n<p>نقصان سے بچنا عالمگیر ہے، لیکن بدلے کی تجارت ایک مختلف لباس پہنتی ہے اس پر منحصر ہے کہ آپ مارکیٹ کے ساتھ کس طرح مشغول ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>آپ ایک...</th>\n<th>انتقامی اقدام کیسا لگتا ہے۔</th>\n<th>کولڈ ڈاؤن جو مدد کرتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>گھبراہٹ میں گرتے ہوئے اسٹاک کو بیچنا، پھر صحیح محسوس کرنے کے لیے اس میں بہت زیادہ \"نیچے\"</td>\n<td>روزانہ پورٹ فولیو کی جانچ کرنا بند کریں۔ ایڈوانس کا فیصلہ پہلے سے کریں، اس وقت کبھی نہیں۔</td>\n</tr>\n<tr>\n<td>ایکٹو / انٹرا ڈے ٹریڈر</td>\n<td>دوگنا سائز اور بغیر سیٹ اپ کے ساتھ سٹاپ لوس کے فوراً بعد دوبارہ داخل ہونا</td>\n<td>سخت روزانہ نقصان کی حد، پھر سیشن کے لیے اسکرین آف</td>\n</tr>\n<tr>\n<td>ایف اینڈ او خریدار</td>\n<td>ابھی کھوئے ہوئے پریمیم کو \"بازیافت\" کرنے کے لیے زیادہ سستے، پیسے سے باہر کے اختیارات خریدنا</td>\n<td>خرچ شدہ پریمیم پر یومیہ کیپ؛ کھوئے ہوئے پریمیم کو ڈوبی لاگت کے طور پر قبول کریں۔</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>نقصان کے بعد اور بھی زیادہ اختیارات فروخت کرنا، پریمیم واپس اکٹھا کرنا، جس سے خطرہ تیزی سے بڑھتا ہے۔</td>\n<td>کھلے سے پہلے مقرر کردہ سخت پوزیشن کی حدیں؛ نقصان کو \"واپس کمانے\" میں کبھی بھی خطرہ شامل نہ کریں۔</td>\n</tr>\n</tbody></table>\n<p>خاص طور پر آپشن بیچنے والے کی قطار کو دیکھیں۔ نقصان کے بعد مزید مختصر آپشنز کو شامل کرنا مستقل آمدنی کی طرح محسوس ہوتا ہے لیکن جب آپ جذباتی ہوتے ہیں تو خاموشی سے لامحدود خطرے والی پوزیشنوں کو ڈھیر لگا دیتے ہیں، زیادہ لینے کا بالکل غلط وقت ہے۔ جو اصول آپ کو بچاتا ہے وہ سب کے لیے یکساں ہے: سائز اور حدود کا فیصلہ اس وقت ہوتا ہے جب آپ پرسکون ہوتے ہیں، نہ کہ جب آپ ڈنک مار رہے ہوتے ہیں۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>یہ ٹولز طاقتور ہیں، لیکن ان کے کناروں کے بارے میں ایماندار رہیں۔</p>\n<ul>\n<li><strong>جس اصول کو آپ اوور رائڈ کر سکتے ہیں وہ اصول نہیں ہے۔</strong> روزانہ نقصان کی حد صرف اس صورت میں کام کرتی ہے جب آپ حقیقت میں اس کی پابندی کرتے ہیں۔ اگر آپ \"صرف یہ ایک بار\" فنڈز شامل کرتے ہیں یا ٹوپی درمیانی جھکاؤ کو اٹھاتے ہیں، تو تحفظ ختم ہو جائے گا۔ نظم و ضبط کو اس لمحے کی گرمی سے باہر بیٹھنا پڑتا ہے، مثالی طور پر ایک عادت کے طور پر جس کے ساتھ آپ کبھی بات چیت نہیں کرتے ہیں۔</li>\n<li><strong>دور ہٹنا ایک گہرا مسئلہ چھپا سکتا ہے۔</strong> اگر آپ کو ہر ایک دن ٹھنڈا کرنے کی ضرورت ہوتی ہے، تو مسئلہ جھکاؤ کا شکار نہیں ہوسکتا ہے، یہ ہوسکتا ہے کہ آپ کی حکمت عملی میں کوئی برتری نہ ہو، یا آپ کا سائز آپ کے اعصاب کے لیے بہت بڑا ہو۔ ٹھنڈا ہونا علامت کا علاج کرتا ہے۔ ایک ناقص نظام کو جڑ سے ٹھیک کرنے کی ضرورت ہے۔</li>\n<li><strong>کچھ نقصانات آپ کے قابو میں نہیں ہیں۔</strong> راتوں رات کا وقفہ، نچلے سرکٹس میں بند اسٹاک، خبروں کی تیز حرکت، یہ آپ کو ایک نقصان پہنچا سکتے ہیں جس سے کوئی ٹھنڈک نہیں روک سکتا تھا۔ مقصد روکنا ہے۔ <em>خود کو متاثر کیا</em> سرپل، صفر نقصانات کا وعدہ نہیں کرنا۔</li>\n<li><strong>حد سے زیادہ درست کرنا آپ کو منجمد کر دیتا ہے۔</strong> انتقامی تجارت کا خوف لینے سے انکار کر سکتا ہے۔ <em>کوئی بھی</em> نقصان کے بعد تجارت کریں، یہاں تک کہ اچھے بھی۔ بقا منزل ہے، پورا کھیل نہیں۔ مقصد پرسکون، اصول پر مبنی عمل ہے، فالج نہیں۔</li>\n</ul>\n<p>بات یہ نہیں ہے کہ کبھی ڈنک محسوس نہ ہو۔ آپ کریں گے۔ نقطہ یہ یقینی بنانا ہے کہ ڈنک کبھی بھی آپ کے پیسے خرچ نہیں کرسکتا۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> مساوی فائدہ کے مقابلے میں نقصان کتنا نقصان پہنچاتا ہے؟</summary><p>تقریباً دو گنا زیادہ۔ طرز عمل کی تحقیق میں مستقل طور پر معلوم ہوتا ہے کہ رقم کھونے کا درد اسی رقم حاصل کرنے کی خوشی سے تقریبا دوگنا ہے۔ اس عدم توازن کو نقصان سے بچنے کا نام دیا جاتا ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> نقصان سے بچنا ہمیں پیچھے کی طرف تجارت کیسے کرتا ہے؟</summary><p>یہ ہمیں جیتنے والوں کو بہت جلد کاٹنے پر مجبور کرتا ہے (کھانے سے پہلے چھوٹے فائدے حاصل کرنا) اور ہارنے والوں کو بہت لمبا پکڑنا (نقصان کو حقیقی بنانے کے درد سے بچنا)۔ نتیجہ چھوٹی جیت اور بڑا نقصان ہے، جو کام کرتا ہے اس کے برعکس۔</p>\n</details><details>\n<summary><strong>3.</strong> انتقامی تجارت کیا ہے، اور \"جھکاؤ\" کیا ہے؟</summary><p>بدلے کی تجارت ایک بڑی، گھٹیا پوزیشن ہے جسے آپ نقصان کے بعد صرف \"اپنا پیسہ واپس حاصل کرنے\" کے لیے لگاتے ہیں۔ جھکاؤ اس کے پیچھے جذباتی حالت ہے، جہاں غصہ اور عجلت آپ کے معمول کے اصولوں کی جگہ لے لیتی ہے۔ جتنا بڑا نقصان ہوگا، اتنا ہی مضبوط کھینچا جائے گا، اور آپ کا فیصلہ اتنا ہی برا ہوگا۔</p>\n</details><details>\n<summary><strong>4.</strong> روزانہ نقصان کی سخت حد پہلے سے کیوں مقرر کی جاتی ہے، اس لمحے میں نہیں؟</summary><p>کیونکہ آپ جھکاؤ پر ہوتے ہوئے پرسکون فیصلے نہیں کر سکتے۔ پہلے سے طے شدہ حد آپ کے جذباتی ہاتھوں سے انتخاب لے جاتی ہے۔ جب آپ اسے مارتے ہیں، تو دن ختم ہو جاتا ہے، کوئی بات چیت نہیں، جو کہ ایک برے دن کو معلوم، زندہ رہنے والی رقم پر لے جاتی ہے۔</p>\n</details><details>\n<summary><strong>5.</strong> نقصان کے فوراً بعد تجارت لینے سے پہلے ایک فوری ٹیسٹ، یہ کیا ہے؟</summary><p>پوچھیں: \"اگر میرا آخری ایک فاتح ہوتا تو کیا میں یہ صحیح تجارت کروں گا؟\" اگر جواب نفی میں ہے، تو یہ ایک انتقامی تجارت ہے جو اسٹنگ کے ذریعے چلائی جاتی ہے، سیٹ اپ نہیں، لہذا اسے چھوڑ دیں اور اسکرین سے ہٹ جائیں۔</p>\n</details>\n","toc":[{"level":2,"text":"نقصان اس سے دوگنا زیادہ تکلیف دیتا ہے جتنا فائدہ اچھا لگتا ہے۔","id":"a-loss-hurts-about-twice-as-much-as-a-gain-feels-good"},{"level":2,"text":"عدم توازن آپ کی تجارت کو کس طرح روکتا ہے۔","id":"how-the-imbalance-warps-your-trading"},{"level":2,"text":"انتقامی تجارت، اور \"جھکاؤ\" کی حالت","id":"the-revenge-trade-and-the-tilt-state"},{"level":2,"text":"نقصان کے بعد کیسے روکا جائے۔","id":"how-to-stop-after-damage"},{"level":2,"text":"ہر قسم کے شریک کے لیے بدلہ کیسے ظاہر ہوتا ہے۔","id":"how-revenge-shows-up-for-each-kind-of-participant"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"3":{"html":"<p>ارجن کے آفس گروپ چیٹ میں گونجنا بند نہیں ہوتا تھا۔ ایک چھوٹا کیمیکل اسٹاک چار مہینوں میں تین گنا بڑھ گیا تھا، اور دو ساتھی اپنے منافع کے اسکرین شاٹس پوسٹ کرتے رہے۔ ہر صبح اسٹاک دوبارہ بڑھ جاتا تھا۔ اس وقت تک جب ارجن مزید گمشدہ نہیں رہ سکتا تھا، اس نے تین ماہ کی بچت سب سے اوپر رکھی۔ اگلے ہی ہفتے اسٹاک عروج پر پہنچ گیا۔ دو مہینوں میں یہ آدھا رہ گیا تھا۔ دونوں ساتھیوں نے اسے ایک سال پہلے، تقریباً حادثاتی طور پر خریدا تھا، اور خاموشی سے اپنا بیشتر حصہ ارجن کی خرید میں بیچ دیا تھا۔ ارجن نہیں ہارا کیونکہ وہ بیوقوف تھا۔ وہ ہار گیا کیونکہ بازاروں میں تین انتہائی فطری انسانی احساسات نے اسے ایک ہی وقت میں ایک ہی غلط سمت میں دھکیل دیا۔</p>\n<p>یہ باب ان تین احساسات کے بارے میں ہے: FOMO، زیادہ اعتماد، اور ریوڑ۔ وہ کردار کی خامیاں نہیں ہیں۔ وہ عام ہیں، اور وہ عین وقت پر سب سے زیادہ سخت حملہ کرتے ہیں جس پر ان کی قیمت سب سے زیادہ ہوتی ہے۔</p>\n<h2 id=\"fomo-the-fear-of-being-left-behind\">FOMO: پیچھے رہ جانے کا خوف</h2>\n<p>FOMO غائب ہونے کا خوف ہے۔ بازاروں میں یہ ایک خاص درد کے طور پر ظاہر ہوتا ہے: پیسے کھونے کا درد نہیں، بلکہ دوسرے لوگوں کو آپ کے بغیر اسے بناتے ہوئے دیکھنے کا درد۔</p>\n<p>دیکھیں کہ یہ کتنا پیچھے ہے۔ ایک اسٹاک جو پہلے ہی تین گنا بڑھ چکا ہے، تعریف کے مطابق، زیادہ مہنگا ہے اور عام طور پر اس سے زیادہ ہجوم ہوتا ہے۔ پھر بھی یہ بالکل وہی ہے جب اسے خریدنا سب سے محفوظ محسوس ہوتا ہے، کیونکہ ثبوت ہر جگہ موجود ہے۔ آپ کا دوست کاغذ پر امیر ہے۔ خبریں چمک رہی ہیں۔ چارٹ صرف اوپر جاتا ہے۔ FOMO سب سے زیادہ خطرناک لمحہ لیتا ہے اور اسے سب سے واضح لمحے کے طور پر تیار کرتا ہے۔</p>\n<p>ٹریپ یہ ہے کہ جو ثبوت FOMO کو فیڈ کرتا ہے وہ حقیقی ہے۔ دوسرے لوگوں نے جو فوائد حاصل کیے وہ حقیقی تھے۔ چارٹ واقعی اوپر چلا گیا. FOMO آپ سے ماضی کے بارے میں جھوٹ نہیں بولتا۔ یہ آپ سے جھوٹ بولتا ہے کہ ماضی آپ کو مستقبل کے بارے میں کیا بتاتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>FOMO خرید رہا ہے کیونکہ قیمت پہلے ہی بڑھ چکی ہے، اس لیے نہیں کہ آپ کے پاس یہ سوچنے کی کوئی وجہ ہے کہ یہ یہاں سے بڑھ جائے گی۔ حقیقت یہ ہے کہ دوسرے لوگوں نے پیسہ کمایا یہ ان کے ماضی کے بارے میں ایک حقیقت ہے، نہ کہ آپ کے مستقبل کے بارے میں۔</p>\n</div></div>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"قیمت کا بڑھتا ہوا وکر۔ خریداروں کی چھوٹی تعداد ابتدائی اور کم تعداد میں شامل ہوتی ہے۔ خریداروں کا ہجوم عروج پر ہی اپنے سب سے بڑے سائز تک بڑھ جاتا ہے، پھر قیمت گر جاتی ہے۔\">\n<rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" fill=\"#0d1117\"/>\n<text x=\"30\" y=\"34\" fill=\"#e6edf3\" font-size=\"16\" font-weight=\"700\">بھیڑ بالکل سب سے اوپر ہے۔</text>\n<!-- axes -->\n<line x1=\"60\" y1=\"240\" x2=\"710\" y2=\"240\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n<line x1=\"60\" y1=\"60\" x2=\"60\" y2=\"240\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n<text x=\"60\" y=\"262\" fill=\"#8b949e\" font-size=\"11\">جلد</text>\n<text x=\"660\" y=\"262\" fill=\"#8b949e\" font-size=\"11\">دیر سے</text>\n<text x=\"20\" y=\"150\" fill=\"#8b949e\" font-size=\"11\" transform=\"rotate(-90 20 150)\">قیمت</text>\n<!-- price curve: rise then fall -->\n<path d=\"M60 225 C 220 215, 330 150, 430 95 C 500 60, 540 70, 580 110 C 630 165, 670 205, 710 225\" fill=\"none\" stroke=\"#4c72b0\" stroke-width=\"3.5\"/>\n<!-- few buyers early -->\n<circle cx=\"150\" cy=\"210\" r=\"5\" fill=\"#55a868\"/>\n<circle cx=\"170\" cy=\"205\" r=\"5\" fill=\"#55a868\"/>\n<text x=\"120\" y=\"190\" fill=\"#8b949e\" font-size=\"11\">کچھ پرسکون خریدار</text>\n<!-- crowd at the peak -->\n<circle cx=\"430\" cy=\"74\" r=\"5\" fill=\"#dd8452\"/>\n<circle cx=\"445\" cy=\"70\" r=\"5\" fill=\"#dd8452\"/>\n<circle cx=\"460\" cy=\"76\" r=\"5\" fill=\"#dd8452\"/>\n<circle cx=\"438\" cy=\"58\" r=\"5\" fill=\"#dd8452\"/>\n<circle cx=\"455\" cy=\"58\" r=\"5\" fill=\"#dd8452\"/>\n<circle cx=\"470\" cy=\"64\" r=\"5\" fill=\"#dd8452\"/>\n<circle cx=\"423\" cy=\"64\" r=\"5\" fill=\"#dd8452\"/>\n<text x=\"395\" y=\"40\" fill=\"#dd8452\" font-size=\"12\" font-weight=\"700\">سب یہاں ڈھیر ہو جاتے ہیں۔</text>\n<!-- the fall -->\n<text x=\"600\" y=\"200\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\">زوال</text>\n<text x=\"60\" y=\"288\" fill=\"#8b949e\" font-size=\"11.5\">ہجوم جتنا بلند اور زیادہ یقینی ہوگا، آپ عام طور پر حرکت میں اتنے ہی دیر میں ہوتے ہیں۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">جب تک کوئی حرکت سب پر واضح ہو، اس میں سے زیادہ تر ہو چکا ہے۔</figcaption>\n</figure><h2 id=\"overconfidence-mistaking-a-bull-market-for-skill\">حد سے زیادہ اعتماد: مہارت کے لیے بیل مارکیٹ کو غلط سمجھنا</h2>\n<p>دوسرا احساس آپ کے چند بار جیتنے کے بعد ظاہر ہوتا ہے۔ تین یا چار تجارت آپ کے راستے پر چلتی ہیں۔ کھاتہ سبز ہے۔ ایک پُرسکون آواز کہتی ہے: شاید مجھے اس میں کوئی مہارت ہے۔ لہذا آپ اگلی بار ایک بڑی پوزیشن پر آتے ہیں، \"صرف ایک بار\" سٹاپ لوس کو چھوڑ دیں اور اپنے منصوبے پر اپنے گٹ پر بھروسہ کریں۔</p>\n<p>یہ ہے ناگوار حقیقت۔ بڑھتی ہوئی مارکیٹ میں، تقریباً ہر چیز اوپر جاتی ہے۔ ایک مبتدی جس نے 2020 اور 2021 میں تقریباً کچھ بھی خریدا، COVID حادثے کے ٹھیک ہونے کے بعد، ایک باصلاحیت شخص کی طرح نظر آیا۔ وہ جینیئس نہیں تھے۔ وہ ایک ایسیلیٹر پر کھڑے تھے جو اوپر جا رہا تھا اور اسے اپنا چڑھنا سمجھ رہے تھے۔ جب ایسکلیٹر رک گیا، تو جیت بھی ہوئی، اور جو بڑے عہدوں پر وہ بڑھے تھے، چھوٹے منافع کو حقیقی نقصان میں بدل دیا۔</p>\n<p>حد سے زیادہ اعتماد خطرناک ہے کیونکہ یہ بدترین وقت پر آپ کے رویے کو بدل دیتا ہے۔ جیتنے کے بعد آپ کا سائز بڑھ جاتا ہے، جو عام طور پر آسان مارکیٹوں کے دوران کلسٹرز میں آتے ہیں، اس لیے آپ حالات کے سخت ہونے سے پہلے ہی اپنی سب سے بڑی پوزیشن سنبھال رہے ہیں۔</p>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>تین یا چار جیتنے والی تجارتوں کے بعد آپ اپنی پوزیشن کا سائز دوگنا کر دیتے ہیں اور سٹاپ لاس کا استعمال بند کر دیتے ہیں، کیونکہ واضح طور پر آپ نے اس کا اندازہ لگا لیا ہے۔ ایک آسان مارکیٹ میں جیتنے کا سلسلہ ایک واحد سب سے عام وجہ ہے جو ابتدائی لوگوں کو اڑا دیتی ہے۔ بہتر اقدام یہ ہے کہ اپنی پوزیشن کے سائز کو اصول کے مطابق طے کریں، مزاج کے مطابق نہیں، اور جب تک ثابت نہ ہو جائے تب تک لکیر کو قسمت سمجھیں۔</p>\n</div></div>\n<h2 id=\"luck-versus-skill-telling-them-apart-honestly\">قسمت بمقابلہ مہارت: انہیں ایمانداری سے الگ کرنا</h2>\n<p>زیادہ اعتماد کے پیچھے سارا مسئلہ یہ ہے کہ قسمت اور ہنر اندر سے ایک جیسے محسوس ہوتے ہیں۔ دونوں منافع پیدا کرتے ہیں۔ دونوں کمائی محسوس کرتے ہیں۔ آپ ایک نتیجہ دیکھ کر ان کو الگ نہیں بتا سکتے، اسی طرح آپ ایک ہی پلٹنے کے بعد کسی خوش قسمت سے مناسب سکہ نہیں بتا سکتے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 290\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"دو راستے دونوں منافع کی طرف لے جاتے ہیں۔ بائیں راستے پر مہارت کا لیبل لگا ہوا ہے: ایک دوبارہ قابل عمل عمل۔ صحیح راستے پر قسمت کا لیبل لگا ہوا ہے: ایک خوش قسمت بازار اور ایک ٹپ۔ صرف منافع سے آپ یہ نہیں بتا سکتے کہ آپ نے کون سا راستہ اختیار کیا۔\">\n<rect x=\"0\" y=\"0\" width=\"760\" height=\"290\" fill=\"#0d1117\"/>\n<text x=\"30\" y=\"34\" fill=\"#e6edf3\" font-size=\"16\" font-weight=\"700\">ایک ہی منافع، دو بہت مختلف وجوہات</text>\n<!-- profit box centre bottom -->\n<rect x=\"300\" y=\"220\" width=\"160\" height=\"46\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\" stroke-width=\"1.8\"/>\n<text x=\"380\" y=\"249\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"14\" font-weight=\"700\">A PROFIT</text>\n<!-- skill path -->\n<rect x=\"60\" y=\"70\" width=\"250\" height=\"80\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\" stroke-width=\"1.8\"/>\n<text x=\"185\" y=\"98\" text-anchor=\"middle\" fill=\"#4c72b0\" font-size=\"14\" font-weight=\"700\">SKILL</text>\n<text x=\"185\" y=\"120\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\">ایک قابل تکرار عمل آپ</text>\n<text x=\"185\" y=\"137\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\">وضاحت اور دوبارہ کر سکتے ہیں.</text>\n<!-- luck path -->\n<rect x=\"450\" y=\"70\" width=\"250\" height=\"80\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\" stroke-width=\"1.8\"/>\n<text x=\"575\" y=\"98\" text-anchor=\"middle\" fill=\"#dd8452\" font-size=\"14\" font-weight=\"700\">LUCK</text>\n<text x=\"575\" y=\"120\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\">ایک بڑھتی ہوئی مارکیٹ، ایک گرم ٹپ،</text>\n<text x=\"575\" y=\"137\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\">ایک سکہ جو آپ کے راستے میں آیا۔</text>\n<!-- arrows -->\n<line x1=\"185\" y1=\"150\" x2=\"330\" y2=\"218\" stroke=\"#8b949e\" stroke-width=\"2\"/>\n<line x1=\"575\" y1=\"150\" x2=\"430\" y2=\"218\" stroke=\"#8b949e\" stroke-width=\"2\"/>\n<text x=\"380\" y=\"190\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\">صرف نتیجہ سے، آپ یہ نہیں بتا سکتے کہ آپ نے کون سا لیا ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ہنر دہرایا جاتا ہے اور اس کی وضاحت کی جاسکتی ہے۔ قسمت نہیں کر سکتی۔ وقت اور ایمانداری انہیں الگ کرتی ہے۔</figcaption>\n</figure><p>ان کو الگ کرنے کا واحد ایماندار طریقہ بہت ساری تجارتوں پر ہے اور اس عمل کے ساتھ جس کی آپ وضاحت کر سکتے ہیں۔ مہارت ظاہر ہوتی ہے جس کے نتیجے میں آپ دہر سکتے ہیں اور ایک وجہ جسے آپ تجارت سے پہلے بیان کر سکتے ہیں، بعد میں نہیں۔ قسمت اس کے نتیجے میں ظاہر ہوتی ہے جس کی وضاحت آپ نتیجہ کی طرف اشارہ کرنے کے علاوہ نہیں کر سکتے۔ اپنی جیت پر اس مختصر، ظالمانہ چیک لسٹ کا استعمال کریں:</p>\n<p><strong>قسمت یا ہنر؟ خود ایمانداری کی چیک لسٹ</strong></p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> کیا میں اس تجارت کی اپنی وجہ لکھ سکتا ہوں؟ <em>پہلے</em> میں داخل ہوا، اس کے بعد نہیں؟</li>\n<li><input disabled=\"\" type=\"checkbox\"> کیا یہی وجہ ہے کہ میں ہر بار ایک اصول کی پیروی کرتا ہوں، یا یک طرفہ احساس؟</li>\n<li><input disabled=\"\" type=\"checkbox\"> کیا میں نے اپنے فیصلے کی وجہ سے پیسہ کمایا، یا اس وجہ سے کہ سارا بازار اوپر چلا گیا؟</li>\n<li><input disabled=\"\" type=\"checkbox\"> کیا یہی فیصلہ بیس دیگر تجارتوں پر کام کرتا، یا صرف یہ ایک؟</li>\n<li><input disabled=\"\" type=\"checkbox\"> اگر کسی دوست نے مجھ سے یہ بتانے کو کہا کہ یہ کیوں کام کرتا ہے، تو کیا میں یہ کہے بغیر کہ \"یہ اوپر چلا گیا\"؟</li>\n</ul>\n<p>اگر زیادہ تر خانوں پر نشان نہیں لگایا گیا ہے، تو شاید آپ کا منافع مارکیٹ سے تحفہ تھا، نہ کہ آپ کی کوئی مہارت۔ تحفے واپس لیے جاتے ہیں۔</p>\n<h2 id=\"herd-behaviour-why-agreement-feels-safe-and-is-not\">ریوڑ کا برتاؤ: معاہدہ کیوں محفوظ محسوس ہوتا ہے اور کیوں نہیں ہے۔</h2>\n<p>تیسرا احساس ریوڑ ہے۔ انسان ایک دوسرے کی نقل کرنے کے لیے وائرڈ ہوتے ہیں، اور زیادہ تر زندگی کے لیے وائرنگ ہمیں محفوظ رکھتی ہے۔ اگر سب دوڑ رہے ہیں تو آپ پہلے دوڑیں گے اور بعد میں پوچھیں گے کیوں؟ بازاروں میں یہ جبلت خاموشی سے آپ کو دھوکہ دیتی ہے۔</p>\n<p>ایک بلبلہ وہ ہوتا ہے جب خریدنے کی واحد وجہ باقی رہ جاتی ہے کہ باقی سب خرید رہے ہوتے ہیں۔ قیمت کاروبار سے منسلک ہونا بند ہو جاتی ہے اور ہجوم کے مزاج سے منسلک ہو جاتی ہے۔ ہندوستان نے اسے بار بار دیکھا ہے: چھوٹے کیپ اور مائیکرو کیپ کے جنون جہاں نامعلوم کمپنیاں ہفتوں میں دوگنی ہوجاتی ہیں، IPO مینیا جہاں لوگ صرف اس لیے درخواست دیتے ہیں کہ درخواستیں زیادہ سبسکرائب ہوجاتی ہیں، اور \"ٹپس\" جو چیٹ گروپس پر گردش کرتی ہیں جب تک کہ آخری خریدار خرید نہ لے۔</p>\n<p>ظالمانہ حصہ وقت ہے. جس لمحے ایک اسٹاک کو سب سے زیادہ محفوظ محسوس ہوتا ہے، جب ہر وہ شخص جس کو آپ جانتے ہیں اس سے اتفاق کرتا ہے کہ یہ صرف اوپر جا سکتا ہے، اکثر زیادہ سے زیادہ خطرے کا لمحہ ہوتا ہے۔ کیوں؟ کیونکہ اگر سب نے پہلے ہی خرید لیا ہے، تو خریدنے کے لیے تقریباً کوئی نہیں بچا ہے۔ قیمت بڑھتے رہنے کے لیے نئے خریداروں کی ضرورت ہے۔ جب بھیڑ متفق ہو جائے تو ایندھن ختم ہو جاتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>\"ہر کوئی اسے خرید رہا ہے\" خریدنے کی کوئی وجہ نہیں ہے۔ یہ ایک انتباہ ہے کہ آپ آخری خریداروں میں سے ایک ہوسکتے ہیں۔ جب آپ کو ایک بھی ایسا شخص نہیں ملتا جو متفق نہ ہو تو پوچھیں کہ کس کو بیچنا ہے۔</p>\n</div></div>\n<h2 id=\"how-the-three-feelings-hit-each-type-of-trader\">کس طرح تین احساسات ہر قسم کے تاجر کو متاثر کرتے ہیں۔</h2>\n<p>ایک ہی ہجوم کے جذبات مختلف طریقے سے ظاہر ہوتے ہیں اس پر منحصر ہے کہ آپ کیا تجارت کرتے ہیں۔ لیوریج اور رفتار بڑھنے سے خطرہ بڑھ جاتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>کیسے FOMO اور ریوڑ عام طور پر ہڑتال کرتے ہیں۔</th>\n<th>یہ کیوں زیادہ تکلیف دے سکتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>طویل مدتی سرمایہ کار</strong></td>\n<td>سب سے اوپر کے قریب \"ہاٹ\" سمال کیپ یا ہائپڈ IPO خریدنا کیونکہ دوستوں کو فائدہ ہوا</td>\n<td>کاٹنے میں سب سے سست؛ ایک متنوع SIP سرمایہ کار برسوں کے دوران ایک خراب اندراج کر سکتا ہے۔</td>\n</tr>\n<tr>\n<td><strong>اسٹاک تاجر</strong></td>\n<td>ایک ایسے اسٹاک کا پیچھا کرنا جو پہلے ہی تیزی سے اوپر ہے، جیتنے کے سلسلے کے بعد اسٹاپ کو چھوڑنا</td>\n<td>تیز نقصان؛ ایک مقررہ سٹاپ کے خلاف ایک پیچھا زندہ ہے، بار بار پیچھا نہیں ہے</td>\n</tr>\n<tr>\n<td><strong>ایف اینڈ او تاجر</strong></td>\n<td>چند لیوریجڈ جیت کے بعد ٹرینڈنگ انڈیکس یا آپشن میں ڈھیر لگانا، اعتماد کو بڑھانا</td>\n<td>لیوریج اس فائدے کو بڑھاتا ہے جس سے زیادہ اعتماد پیدا ہوتا ہے اور اس کے بعد ہونے والے نقصان</td>\n</tr>\n<tr>\n<td><strong>آپشن بیچنے والا</strong></td>\n<td>پرسکون مارکیٹ میں زیادہ سے زیادہ اختیارات فروخت کرنا کیونکہ \"یہ ہمیشہ بیکار ختم ہوجاتا ہے\"</td>\n<td>ایک طویل خاموش سلسلہ اس وقت تک مہارت کی طرح محسوس ہوتا ہے جب تک کہ ایک تیز اقدام مہینوں کے پریمیم کو ایک ساتھ ختم نہ کر دے۔</td>\n</tr>\n</tbody></table>\n<p>پیٹرن پر توجہ دیں۔ سرمایہ کار کے لیے، ہجوم کا جذبہ ایک سست رساو ہے۔ آپشن بیچنے والے کے لیے، پرسکون مارکیٹ میں ایک طویل جیتنے والا سلسلہ سب سے زیادہ خطرناک سیٹ اپ ہے، کیونکہ یہ بالکل وہی حد سے زیادہ اعتماد پیدا کرتا ہے جسے ایک پرتشدد میعاد ختم ہونے سے سزا مل سکتی ہے۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>ہجوم سے بچنا ہمیشہ اس کے برعکس کرنے جیسا نہیں ہے۔ یہ اس کا اپنا جال ہے۔</p>\n<ul>\n<li><strong>ہجوم کبھی کبھی صحیح ہوتا ہے۔</strong> مضبوط اسٹاک مضبوط رہ سکتے ہیں، اور بڑھتی ہوئی مارکیٹ برسوں تک بڑھتی رہ سکتی ہے۔ ہر چیز کو صرف اس لیے بیچنا کہ دوسرے خرید رہے ہیں بھیڑ کا ردعمل ہے، صرف اس کے برعکس۔ مقصد یہ ہے کہ آپ کی اپنی وجہ ہو، نہ کہ ہجوم کا رخ موڑنا۔</li>\n<li><strong>\"یہ ایک بلبلہ ہے\" کہنا آسان ہے اور وقت کے لیے مشکل۔</strong> مارکیٹیں اس سے کہیں زیادہ غیر معقول رہ سکتی ہیں جتنا آپ سالوینٹ رہ سکتے ہیں۔ ٹاپ کو کال کرنے اور اسے شارٹ کرنے نے اتنے ہی لوگوں کو برباد کر دیا ہے جتنے لوگ ٹاپ خریدنے والے تھے۔</li>\n<li><strong>کچھ FOMO صرف ایک چھوٹا موقع ہے، اور یہ ٹھیک ہے۔</strong> آپ فاتحین کی کمی محسوس کریں گے۔ کسی فاتح کو یاد کرنے سے آپ کو کچھ بھی نہیں پڑتا ہے جو آپ کے پاس کبھی نہیں تھا۔ کسی کا پیچھا کرنے سے آپ کو پیسہ خرچ ہو سکتا ہے جو آپ نے کیا تھا۔ وہ ایک جیسے نہیں ہیں، حالانکہ وہ ایک جیسے محسوس کرتے ہیں۔</li>\n<li><strong>کھونے کا سلسلہ آپ کو بھی بیوقوف بنا سکتا ہے۔</strong> جس طرح جیتنے والا سلسلہ حد سے زیادہ اعتماد پیدا کرتا ہے، اسی طرح بد قسمتی کا ایک دوڑ ایک اچھے عمل کو ٹوٹا ہوا محسوس کر سکتا ہے اور آپ کو اس کے کام کرنے سے پہلے ہی اسے ترک کرنے پر آمادہ کر سکتا ہے۔</li>\n</ul>\n<p>یہ باب تعلیم ہے نصیحت نہیں۔ مقصد اپنے اندر ان احساسات کو پہچاننا ہے، نہ کہ آپ کو عمل کرنے کا اشارہ دینا۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> FOMO، ایک جملے میں کیا ہے، اور یہ کیوں خطرناک ہے؟</summary><p>FOMO خرید رہا ہے کیونکہ قیمت پہلے ہی بڑھ گئی ہے اور دوسرے منافع کر رہے ہیں، اس لیے نہیں کہ آپ کے پاس اس کے مزید بڑھنے کی توقع کرنے کی کوئی وجہ ہے۔ یہ خطرناک ہے کیونکہ یہ آپ کو سب سے زیادہ ہجوم، مہنگے ترین لمحے خریدنے پر مجبور کرتا ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> آپ نے لگاتار چار تجارتیں جیتی ہیں۔ سب سے محفوظ مفروضہ کیا ہے؟</summary><p>فرض کریں کہ یہ قسمت تھی جب تک کہ دوسری صورت میں ثابت نہ ہو، خاص طور پر اگر پوری مارکیٹ بڑھ رہی تھی۔ اعتماد میں اضافہ کرنے کے بجائے اپنی پوزیشن کا سائز اصول کے مطابق رکھیں۔</p>\n</details><details>\n<summary><strong>3.</strong> ایک منافع بخش تجارت سے، کیا آپ بتا سکتے ہیں کہ آپ ہنر مند ہیں یا خوش قسمت؟</summary><p>نہیں، قسمت اور ہنر دونوں ہی منافع پیدا کرتے ہیں اور دونوں کو کمایا ہوا محسوس ہوتا ہے۔ صرف بہت ساری تجارتیں اور ایک وجہ جو آپ پیشگی وضاحت کر سکتے ہیں انہیں الگ کریں۔</p>\n</details><details>\n<summary><strong>4.</strong> کیوں \"ہر کوئی اسے خرید رہا ہے\" وجہ کے بجائے ایک انتباہ ہے؟</summary><p>کیونکہ بڑھتی ہوئی قیمتوں کو نئے خریداروں کی ضرورت ہے۔ اگر تقریباً سبھی نے پہلے ہی خرید لیا ہے، تو تھوڑا سا ایندھن بچا ہے، لہذا متفقہ معاہدہ اکثر محفوظ اندراج کے بجائے ٹاپ کو نشان زد کرتا ہے۔</p>\n</details><details>\n<summary><strong>5.</strong> ایک طویل جیتنے والا سلسلہ آپشن بیچنے والے کو خاص طور پر سخت کیوں مارتا ہے؟</summary><p>ایک پرسکون بازار میں، آپشنز بیچنا جو بے کار ختم ہوتے رہتے ہیں خالص مہارت کی طرح محسوس کرتے ہیں اور آپ کو سائز بڑھانے پر اکساتے ہیں۔ ایک تیز، اچانک حرکت پھر مہینوں کے جمع کردہ پریمیم کو ایک ساتھ ختم کر سکتی ہے۔</p>\n</details>\n","toc":[{"level":2,"text":"FOMO: پیچھے رہ جانے کا خوف","id":"fomo-the-fear-of-being-left-behind"},{"level":2,"text":"حد سے زیادہ اعتماد: مہارت کے لیے بیل مارکیٹ کو غلط سمجھنا","id":"overconfidence-mistaking-a-bull-market-for-skill"},{"level":2,"text":"قسمت بمقابلہ مہارت: انہیں ایمانداری سے الگ کرنا","id":"luck-versus-skill-telling-them-apart-honestly"},{"level":2,"text":"ریوڑ کا برتاؤ: معاہدہ کیوں محفوظ محسوس ہوتا ہے اور کیوں نہیں ہے۔","id":"herd-behaviour-why-agreement-feels-safe-and-is-not"},{"level":2,"text":"کس طرح تین احساسات ہر قسم کے تاجر کو متاثر کرتے ہیں۔","id":"how-the-three-feelings-hit-each-type-of-trader"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"4":{"html":"<p>ارجن، 29، اپنے قوانین کو سرد جانتا تھا۔ یہاں تک کہ اس نے انہیں اپنی اسکرین کے اوپر ایک چسپاں نوٹ پر بھی لکھا تھا: دن میں دو تجارت، 1% پر سٹاپ لاس، نقصان کے بعد کوئی تجارت نہیں۔ پیر بری طرح گزرا۔ وہ اپنی پہلی تجارت میں ہار گیا، اپنے سینے میں گرمی بڑھنے کو محسوس کیا، اور خود سے کہا \"میں اسے واپس جیتوں گا، پھر میں رک جاؤں گا۔\" اس نے تیسری تجارت کی، پھر چوتھی تجارت کی۔ جب پوزیشن اس کے خلاف ہو گئی، تو اس نے اپنے سٹاپ لاس کو \"صرف ایک بار\" گھسیٹ لیا تاکہ یہ حرکت نہ کرے۔ بند ہونے تک وہ اپنی معمول کی رقم سے چار گنا کھو چکا تھا۔ اس کے پاس اصولوں کی کمی نہیں تھی۔ اس کے پاس ایسے نظام کی کمی تھی جس نے انہیں توڑنا مشکل بنا دیا۔</p>\n<p>زیادہ تر ابتدائی لوگ سوچتے ہیں کہ نظم و ضبط ایک شخصیت کی خاصیت ہے، کچھ مستحکم لوگ جس کے ساتھ پیدا ہوتے ہیں اور اچھلنے والے لوگ نہیں ہوتے ہیں۔ یہ نہیں ہے. نظم و ضبط ایک ایسا نظام ہے جسے آپ بناتے ہیں۔ <em>باہر</em> گرم لمحہ، تاکہ جب گرمی آئے، فیصلہ پہلے ہی ہو چکا ہو۔ یہ پورے کورس میں سب سے اہم خیال ہے، لہذا ہم اس پر سست روی کرنے جا رہے ہیں۔</p>\n<h2 id=\"why-willpower-loses\">قوتِ ارادی کیوں کھو جاتی ہے۔</h2>\n<p>پرسکون لمحے میں، آپ عقلمند ہیں۔ آپ اپنے سٹاپ لاس کو جانتے ہیں، آپ کو اپنا سائز معلوم ہے، آپ جانتے ہیں کہ دو تجارتیں کافی ہیں۔ لیکن جس لمحے کوئی تجارت آپ کے خلاف حرکت کرتی ہے، آپ کے دماغ کا ایک مختلف حصہ اپنی لپیٹ میں لے لیتا ہے: تیز، تیز، درد سے الرجک۔ یہ منصوبہ پر عمل نہیں کرنا چاہتا۔ یہ چاہتا ہے کہ درد رک جائے۔ <em>اب</em>. یہ وہ حصہ ہے جو سرگوشی کرتا ہے \"اسٹاپ کو ہٹا دیں\"، \"سائز کو دوگنا کریں\"، \"ایک اور تجارت\"۔</p>\n<p>قوتِ ارادی یہ ہے کہ آپ گھڑی چلتے ہوئے پیسے کھوتے ہوئے، حقیقی وقت میں اس آواز پر بحث کرنے کی کوشش کر رہے ہیں۔ آپ زیادہ تر دن اس دلیل کو کھو دیں گے۔ اس لیے نہیں کہ آپ کمزور ہیں، بلکہ اس لیے کہ جذباتی دماغ اس لمحے جیتنے کے لیے بنایا گیا ہے۔ یہی اس کا کام ہے۔</p>\n<p>تو چال یہ نہیں ہے کہ زیادہ سخت لڑیں۔ چال یہ ہے کہ لڑائی میں بالکل بھی شامل نہ ہوں۔ آپ فیصلے کو ایسے وقت میں منتقل کرتے ہیں جب آپ کا پرسکون، عقلمند ورژن انچارج ہوتا ہے، اور آپ اسے بند کر دیتے ہیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 770 300\" style=\"width:100%;height:auto;max-width:770px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"جذباتی لمحے سے دو راستے۔ قوتِ ارادی کا راستہ تسلسل اور ٹوٹے ہوئے اصول کے ذریعے اڑا ہوا نقصان کی طرف لے جاتا ہے۔ نظام کا راستہ ایک کنٹرول شدہ، منصوبہ بند نتیجہ تک پہنچنے کے لیے پہلے سے طے شدہ قواعد اور ایک چیک لسٹ کا استعمال کرتا ہے۔\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\">\n  <rect x=\"0\" y=\"0\" width=\"770\" height=\"300\" fill=\"#0d1117\"/>\n  <defs>\n    <marker id=\"awR\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#c44e52\"/></marker>\n    <marker id=\"awG\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#55a868\"/></marker>\n  </defs>\n  <text x=\"385\" y=\"26\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"15\">وہی گرم لمحہ، دو راستے</text>\n  <rect x=\"300\" y=\"48\" width=\"170\" height=\"44\" rx=\"12\" fill=\"#11161d\" stroke=\"#dd8452\" stroke-width=\"1.5\"/>\n  <text x=\"385\" y=\"68\" text-anchor=\"middle\" fill=\"#f0c9a8\" font-size=\"12\" font-weight=\"700\">تجارت آپ کے خلاف ہے۔</text>\n  <text x=\"385\" y=\"84\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10.5\">گرمی بڑھتی ہے</text><p>  <text x=\"120\" y=\"120\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\">قوت ارادی کا راستہ</text>\n  <line x1=\"300\" y1=\"78\" x2=\"210\" y2=\"140\" stroke=\"#c44e52\" stroke-width=\"1.5\" marker-end=\"url(#awR)\"/>\n  <rect x=\"40\" y=\"140\" width=\"150\" height=\"34\" rx=\"9\" fill=\"#2a1416\" stroke=\"#c44e52\"/>\n  <text x=\"115\" y=\"162\" text-anchor=\"middle\" fill=\"#f3c9c9\" font-size=\"11\">\"صرف یہ ایک بار\" تسلسل</text>\n  <line x1=\"115\" y1=\"174\" x2=\"115\" y2=\"196\" stroke=\"#c44e52\" stroke-width=\"1.5\" marker-end=\"url(#awR)\"/>\n  <rect x=\"40\" y=\"196\" width=\"150\" height=\"34\" rx=\"9\" fill=\"#2a1416\" stroke=\"#c44e52\"/>\n  <text x=\"115\" y=\"218\" text-anchor=\"middle\" fill=\"#f3c9c9\" font-size=\"11\">اصول لمحے میں ٹوٹ گیا۔</text>\n  <line x1=\"115\" y1=\"230\" x2=\"115\" y2=\"252\" stroke=\"#c44e52\" stroke-width=\"1.5\" marker-end=\"url(#awR)\"/>\n  <rect x=\"40\" y=\"252\" width=\"150\" height=\"34\" rx=\"9\" fill=\"#2a1416\" stroke=\"#c44e52\"/>\n  <text x=\"115\" y=\"274\" text-anchor=\"middle\" fill=\"#f3c9c9\" font-size=\"11\">بڑا، بدصورت نقصان</text></p>\n<p>  <text x=\"640\" y=\"120\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"12\" font-weight=\"700\">سسٹم کا راستہ</text>\n  <line x1=\"470\" y1=\"78\" x2=\"560\" y2=\"140\" stroke=\"#55a868\" stroke-width=\"1.5\" marker-end=\"url(#awG)\"/>\n  <rect x=\"580\" y=\"140\" width=\"150\" height=\"34\" rx=\"9\" fill=\"#10241a\" stroke=\"#55a868\"/>\n  <text x=\"655\" y=\"162\" text-anchor=\"middle\" fill=\"#b9e6c8\" font-size=\"11\">قوانین پہلے ہی طے کر چکے ہیں۔</text>\n  <line x1=\"655\" y1=\"174\" x2=\"655\" y2=\"196\" stroke=\"#55a868\" stroke-width=\"1.5\" marker-end=\"url(#awG)\"/>\n  <rect x=\"580\" y=\"196\" width=\"150\" height=\"34\" rx=\"9\" fill=\"#10241a\" stroke=\"#55a868\"/>\n  <text x=\"655\" y=\"218\" text-anchor=\"middle\" fill=\"#b9e6c8\" font-size=\"11\">چیک لسٹ اور آٹو اسٹاپ</text>\n  <line x1=\"655\" y1=\"230\" x2=\"655\" y2=\"252\" stroke=\"#55a868\" stroke-width=\"1.5\" marker-end=\"url(#awG)\"/>\n  <rect x=\"580\" y=\"252\" width=\"150\" height=\"34\" rx=\"9\" fill=\"#10241a\" stroke=\"#55a868\"/>\n  <text x=\"655\" y=\"274\" text-anchor=\"middle\" fill=\"#b9e6c8\" font-size=\"11\">کنٹرول شدہ، منصوبہ بند اخراج</text>\n</svg></p>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">لمحہ ایک ہی ہے۔ قوت ارادی کا راستہ دلیل دیتا ہے اور ہار جاتا ہے۔ جب پرسکون ہو تو نظام کا راستہ پہلے ہی طے کر چکا ہے۔</figcaption>\n</figure><h2 id=\"discipline-is-a-system-not-a-feeling\">نظم و ضبط ایک نظام ہے، احساس نہیں۔</h2>\n<p>یہاں وہ ریفریم ہے جو ہر چیز کو بدل دیتا ہے۔ پوچھنا بند کرو \"میں مزید نظم و ضبط کیسے بن سکتا ہوں؟\" پوچھنا شروع کریں \"کون سا نظام صحیح عمل کو آسان ڈیفالٹ اور غلط عمل کو پریشانی بنائے گا؟\"</p>\n<p>ایک اچھا تجارتی نظام جذباتی لمحات سے فیصلوں کو ہٹا دیتا ہے۔ اس کے کچھ آسان حصے ہیں، اور آپ ان سب کو ایک دوپہر میں بنا سکتے ہیں:</p>\n<ul>\n<li><strong>پہلے سے طے شدہ اصول۔</strong> بازار کھلنے سے پہلے اندراج، باہر نکلنا، سٹاپ لاس اور ہدف لکھا جاتا ہے۔ \"میں دیکھوں گا کہ یہ کیسا محسوس ہوتا ہے\" نہیں بلکہ \"اگر X، تو Y\"۔</li>\n<li><strong>پوزیشن کے سائز کا فیصلہ پہلے سے کیا گیا تھا۔</strong> کتنے حصص یا لاٹ، ایک اصول کے ذریعہ طے شدہ، لہذا آپ کا سائز کبھی نہیں بڑھتا کیونکہ آپ \"یقین محسوس کرتے ہیں\"۔ رسک مینجمنٹ کورس سے یہ سائزنگ ریاضی ہے: ایک مقررہ چھوٹے ٹکڑے کا خطرہ مول لیں، کہیے کہ سرمایہ کا 1%، فی تجارت، اور اسے مقدار کا فیصلہ کرنے دیں۔</li>\n<li><strong>ایک پری ٹریڈ چیک لسٹ۔</strong> ایک مختصر فہرست ہر تجارت کو آرڈر جانے سے پہلے پاس کرنا ضروری ہے۔ کوئی نشان نہیں، کوئی تجارت نہیں۔</li>\n<li><strong>اسکرینوں کو گھورنے کے بجائے خودکار الرٹس۔</strong> قیمت کا الرٹ مقرر کریں اور ہر ٹک دیکھنے اور اسکرین کو آپ کو عمل میں لانے کی بجائے دور چلیں۔</li>\n<li><strong>ایک جریدہ۔</strong> ہر تجارت کے بعد چند سطریں: اصول نے کیا کہا، آپ نے کیا کیا، آپ کو کیسا لگا۔ اس طرح پرسکون آپ جذباتی آپ کو ایماندار رکھتا ہے۔</li>\n</ul>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>نظم و ضبط وہ قوت نہیں ہے جو آپ کو اس وقت کی گرمی میں طلب کریں۔ یہ ایک ایسا نظام ہے جسے آپ پرسکون ہونے پر بناتے ہیں، لہذا صحیح عمل پہلے سے طے شدہ ہو جاتا ہے اور غلط عمل کے لیے اضافی کوشش کی ضرورت ہوتی ہے۔ تم اپنے ارادوں پر نہیں اٹھتے۔ آپ اپنے سسٹم پر گر جاتے ہیں۔</p>\n</div></div>\n<h2 id=\"make-the-right-thing-the-default\">صحیح چیز کو ڈیفالٹ بنائیں</h2>\n<p>یہاں سب سے گہرے خیال کا ایک نام ہے: <strong>پہلے سے عزم</strong>. آپ اب ایک ایسا انتخاب کرتے ہیں جو آپ کو مستقبل سے منسلک کرتا ہے، لہذا آپ اسے آسانی سے کالعدم نہیں کر سکتے۔</p>\n<p>ایک مشکل سٹاپ نقصان رکھا گیا ہے <em>کے ساتھ</em> آرڈر پری کمٹمنٹ ہے۔ باہر نکلنا پہلے ہی مارکیٹ میں ہے؛ اب غلط کام کرنے کا مطلب ہے فعال طور پر تحفظ کو منسوخ کرنا، جو کام کی طرح محسوس ہوتا ہے اور غلط محسوس ہوتا ہے۔ اس کا موازنہ \"ذہنی روک\" سے کریں، جو صرف ایک امید ہے کہ آپ بعد میں بہادر بن جائیں گے۔ ایک ہی ارادہ، بالکل مختلف مشکلات، کیونکہ ایک پہلے سے طے شدہ ہے اور دوسرے کو قوت ارادی کی ضرورت ہے۔</p>\n<p>آپ ان کو اسٹیک کر سکتے ہیں۔ کھلنے سے پہلے اپنے یومیہ نقصان کی حد اور تجارت کی زیادہ سے زیادہ تعداد کا فیصلہ کریں۔ اپنے آرڈرز پہلے سے لکھیں۔ انتباہات مرتب کریں تاکہ آپ اسکرین پر چپکے نہ رہیں۔ ہر چھوٹی رکاوٹ \"ایک کلک\" سے \"متعدد جان بوجھ کر اقدامات\" میں ایک زبردست عمل کو بدل دیتی ہے، اور یہ رگڑ اکثر پرسکون دماغ کے لیے کافی ہوتا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 770 300\" style=\"width:100%;height:auto;max-width:770px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"تجارتی خیال کو چیک لسٹ گیٹ سے گزرنا چاہیے۔ اگر ہر آئٹم پر ٹک کیا جاتا ہے تو آرڈر کو مارکیٹ تک پہنچانے کی اجازت ہے۔ اگر کوئی شے ناکام ہو جاتی ہے تو آرڈر کو بلاک کر دیا جاتا ہے اور کوئی تجارت نہیں کی جاتی ہے۔\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\">\n  <rect x=\"0\" y=\"0\" width=\"770\" height=\"300\" fill=\"#0d1117\"/>\n  <defs>\n    <marker id=\"gtB\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#4c72b0\"/></marker>\n    <marker id=\"gtG\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#55a868\"/></marker>\n    <marker id=\"gtR\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#c44e52\"/></marker>\n  </defs>\n  <text x=\"385\" y=\"26\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"15\">چیک لسٹ ہر آرڈر سے پہلے ایک گیٹ ہے۔</text>\n  <rect x=\"28\" y=\"120\" width=\"150\" height=\"50\" rx=\"12\" fill=\"#11161d\" stroke=\"#4c72b0\" stroke-width=\"1.5\"/>\n  <text x=\"103\" y=\"142\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-weight=\"700\">تجارتی خیال</text>\n  <text x=\"103\" y=\"159\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10.5\">عمل کرنے کی خواہش</text>\n  <line x1=\"178\" y1=\"145\" x2=\"232\" y2=\"145\" stroke=\"#4c72b0\" stroke-width=\"1.5\" marker-end=\"url(#gtB)\"/>\n  <rect x=\"236\" y=\"70\" width=\"230\" height=\"150\" rx=\"14\" fill=\"#11161d\" stroke=\"#8172b3\" stroke-width=\"1.5\"/>\n  <text x=\"351\" y=\"92\" text-anchor=\"middle\" fill=\"#cbb8e8\" font-size=\"12\" font-weight=\"700\">CHECKLISTGATE</text>\n  <text x=\"252\" y=\"118\" fill=\"#cdd9e5\" font-size=\"11\">میرے منصوبے میں؟</text>\n  <text x=\"252\" y=\"142\" fill=\"#cdd9e5\" font-size=\"11\">روکیں اور ہدف سیٹ کریں؟</text>\n  <text x=\"252\" y=\"166\" fill=\"#cdd9e5\" font-size=\"11\">1٪ خطرے کے اندر سائز؟</text>\n  <text x=\"252\" y=\"190\" fill=\"#cdd9e5\" font-size=\"11\">روزانہ کی حد کے اندر؟</text>\n  <text x=\"252\" y=\"210\" fill=\"#8b949e\" font-size=\"10.5\">ہر باکس کو نشان زد کرنا ضروری ہے</text>\n  <line x1=\"466\" y1=\"120\" x2=\"560\" y2=\"95\" stroke=\"#55a868\" stroke-width=\"1.5\" marker-end=\"url(#gtG)\"/>\n  <rect x=\"566\" y=\"70\" width=\"176\" height=\"46\" rx=\"12\" fill=\"#10241a\" stroke=\"#55a868\"/>\n  <text x=\"654\" y=\"90\" text-anchor=\"middle\" fill=\"#b9e6c8\" font-size=\"11.5\" font-weight=\"700\">سب پر نشان لگایا گیا: آرڈر اندر جاتا ہے۔</text>\n  <text x=\"654\" y=\"106\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\">سٹاپ منسلک کے ساتھ</text>\n  <line x1=\"466\" y1=\"180\" x2=\"560\" y2=\"210\" stroke=\"#c44e52\" stroke-width=\"1.5\" marker-end=\"url(#gtR)\"/>\n  <rect x=\"566\" y=\"190\" width=\"176\" height=\"46\" rx=\"12\" fill=\"#2a1416\" stroke=\"#c44e52\"/>\n  <text x=\"654\" y=\"210\" text-anchor=\"middle\" fill=\"#f3c9c9\" font-size=\"11.5\" font-weight=\"700\">کوئی بھی خانہ ناکام ہو جاتا ہے: کوئی تجارت نہیں۔</text>\n  <text x=\"654\" y=\"226\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\">اور یہ ایک جیت ہے</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">کوئی ٹک نہیں، کوئی تجارت نہیں۔ گیٹ کہتا ہے- نہیں لہذا آپ کو اپنے آپ سے بحث کرنے کی ضرورت نہیں ہے۔</figcaption>\n</figure><h2 id=\"practise-the-rules-without-money-on-the-line\">لائن پر پیسے کے بغیر قواعد پر عمل کریں۔</h2>\n<p>ایک نظام ایک مہارت ہے، اور مہارتوں کو نمائندوں کی ضرورت ہے۔ ایماندارانہ مسئلہ یہ ہے کہ حقیقی پیسہ جذباتی دماغ کو بلند کرتا ہے، جو سیکھنے کا بدترین وقت ہے۔ لہذا پہلے مشق کریں جہاں کچھ بھی داؤ پر نہ لگے۔</p>\n<p>OpenAlgo ہے a <strong>سینڈ باکس ٹریڈنگ موڈ (Analyzer mode in OpenAlgo)</strong>. یہ آپ کو ایک بھی روپیہ خطرے میں ڈالے بغیر، حقیقی مارکیٹ کے رویے کے خلاف آرڈر دینے اور اپنا مکمل معمول، چیک لسٹ، سائزنگ، اسٹاپس، الرٹس اور جرنل چلانے دیتا ہے۔ بورنگ حصوں کی مشق کرنے کے لیے اسے استعمال کریں جب تک کہ وہ خودکار نہ ہو جائیں: چیک لسٹ کو بھرنا، آرڈر کے ساتھ اسٹاپ سیٹ کرنا، الرٹ کے بعد چلنا۔ جب آپ کے ہاتھ معمول کی سردی کو جانتے ہیں، تو گرم لمحے میں آپ کو ہائی جیک کرنے کی گنجائش بہت کم ہوتی ہے۔ یہ تعلیم اور عمل ہے، سرمایہ کاری کا مشورہ نہیں۔</p>\n<h2 id=\"your-pre-trade-checklist\">آپ کی پری ٹریڈ چیک لسٹ</h2>\n<p>یہ باب کی چیک لسٹ ہے، ڈایاگرام سے گیٹ۔ اس سے پہلے چلائیں۔ <em>ہر</em> حکم اگر آپ تمام چھ پر نشان نہیں لگا سکتے ہیں، تو آپ تجارت نہیں لیتے ہیں۔</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> کیا یہ سیٹ اپ دراصل میرے تحریری منصوبے میں ہے، یا میں بہتر بنا رہا ہوں؟</li>\n<li><input disabled=\"\" type=\"checkbox\"> کیا میری انٹری، اسٹاپ لاس اور ٹارگٹ سب کا فیصلہ ہے۔ <em>پہلے</em> میں کلک کروں؟</li>\n<li><input disabled=\"\" type=\"checkbox\"> کیا میری پوزیشن کا سائز میرے اصول کے مطابق مقرر کیا گیا ہے، جو کہ میرے مقررہ ٹکڑوں (1%) سے زیادہ خطرے میں نہیں ہے؟</li>\n<li><input disabled=\"\" type=\"checkbox\"> کیا میں اب بھی اپنی روزانہ کی حدود میں ہوں: تجارت کی تعداد اور دن کے لیے زیادہ سے زیادہ نقصان؟</li>\n<li><input disabled=\"\" type=\"checkbox\"> کیا میرا سٹاپ لاس اندر جا رہا ہے؟ <em>کے ساتھ</em> حکم، نہ صرف میرے سر میں رہتے ہیں؟</li>\n<li><input disabled=\"\" type=\"checkbox\"> کیا میں پرسکون ہوں، ہار کا پیچھا نہیں کر رہا ہوں یا جیت کے نشے میں ہوں؟</li>\n</ul>\n<h2 id=\"what-each-type-of-trader-must-systematise\">ہر قسم کے تاجر کو کس چیز کو منظم کرنا چاہیے۔</h2>\n<p>سسٹم سب کے لیے ایک جیسا خیال ہے، لیکن پریشر پوائنٹس مختلف ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>سب سے بڑا جذباتی خطرہ</th>\n<th>پہلے کس چیز کو منظم کرنا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>ایک حادثے میں گھبراہٹ بیچنا</td>\n<td>ایک خودکار SIP اور لکھا ہوا \"جب تک فروخت نہ کریں\" اصول</td>\n</tr>\n<tr>\n<td>فعال تاجر</td>\n<td>نقصان کے بعد بدلہ لینا</td>\n<td>روزانہ نقصان کی ایک سخت حد اور تجارت سے پہلے کی چیک لسٹ</td>\n</tr>\n<tr>\n<td>F&amp;O ابتدائی</td>\n<td>\"یقینی\" ایکسپائری پنٹ پر اوورسائزنگ</td>\n<td>فکسڈ چھوٹے سائز اور ایک مشکل اسٹاپ، پیشگی سیٹ</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>کسی پوزیشن کو نظر انداز کرنا جب تک کہ نقصان بہت زیادہ نہ ہو۔</td>\n<td>خودکار انتباہات اور بنیادی پر پہلے سے طے شدہ ایگزٹ</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>کلاسک ٹریپ اپنے آپ کو بتا رہا ہے \"میں قواعد جانتا ہوں، میں صرف اگلی بار نظم و ضبط کروں گا۔\" یہ قوتِ ارادی ہے، اور قوتِ ارادی وہی ہے جو اس وقت ناکام ہو جاتی ہے۔ بہتر اقدام یہ ہے کہ آپ مستقبل پر بھروسہ کرنا چھوڑ دیں اور اس کے بجائے ابھی ایک رکاوٹ بنائیں: اسٹاپ کو آرڈر کے ساتھ جوڑیں، روزانہ نقصان کی سخت حد مقرر کریں، اور ہر بار چیک لسٹ چلائیں، اس لیے غیر نظم و ضبط کے لیے حقیقی کوشش کی ضرورت ہے۔</p>\n</div></div>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>ایک نظام جادو نہیں ہے، اور یہ کہنا ایمانداری ہے کہ یہ کہاں جھکتا ہے۔</p>\n<p>ایسا نظام جسے آپ ایک کلک میں اوور رائیڈ کر سکتے ہیں بمشکل ایک سسٹم ہے۔ اگر آپ کا اسٹاپ \"ذہنی\" ہے اور آپ کے نقصان کی حد ایک مبہم ارادہ ہے، تو آپ نے بغیر دانتوں کے قواعد لکھے ہیں۔ تحفظ رگڑ سے آتا ہے، بازار میں بیٹھنے سے رک جانا، وہ تنبیہ جو آپ کو دور چلنے دیتی ہے، لفظوں سے نہیں۔</p>\n<p>ایک نظام بھی خراب حکمت عملی کو ٹھیک نہیں کر سکتا۔ کھوتے ہوئے کنارے پر بنایا گیا ایک مکمل نظم و ضبط والا عمل آسانی سے اور قابل اعتماد طریقے سے پیسہ کھو دے گا۔ نظم و ضبط کے کنٹرول <em>کس طرح</em> آپ تجارت کرتے ہیں، نہیں۔ <em>چاہے</em> خیال پیسہ کماتا ہے؛ دونوں الگ الگ مسائل ہیں.</p>\n<p>اور اگر آپ اس پر جھوٹ بولتے ہیں تو کوئی چیک لسٹ باقی نہیں رہتی ہے۔ اگر آپ \"میں پرسکون ہوں\" پر ٹک لگاتے ہیں جب آپ کا دل دھڑک رہا ہے، یا خاموشی سے اپنے \"فکسڈ\" سائز کو اس دن چوڑا کریں جس دن آپ کو یقین ہو، گیٹ کھلا ہے اور سسٹم تھیٹر ہے۔ پورا ڈھانچہ اپنے آپ کے ساتھ ایماندار ہونے پر منحصر ہے جس لمحے میں آپ خود کو بے وقوف بنانا چاہتے ہیں۔ رکاوٹیں بنائیں، انہیں چھیڑ چھاڑ سے محفوظ رکھیں، اور انہیں سینڈ باکس موڈ میں اس وقت تک مشق کریں جب تک کہ آپ ان کی پیروی نہ کریں۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> اس لمحے میں قوت ارادی پر بھروسہ کرنا عام طور پر ناکام کیوں ہوتا ہے؟</summary><p>کیونکہ جب کوئی تجارت آپ کے خلاف حرکت میں آتی ہے، تو تیز رفتار، درد سے بچنے والا جذباتی دماغ سنبھال لیتا ہے اور اس لمحے جیتنے کے لیے تیار ہوتا ہے۔ قوتِ ارادی کا مطلب ہے کہ پیسے کھوتے ہوئے حقیقی وقت میں اس آواز کے ساتھ بحث کرنا، اور آپ زیادہ تر دنوں میں اس دلیل کو کھو دیں گے۔ ایک نظام پہلے سے فیصلہ کرکے لڑائی سے بچتا ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> صحیح عمل کو \"پہلے سے طے شدہ\" بنانے کا کیا مطلب ہے؟</summary><p>اس کا مطلب ہے چیزوں کو ترتیب دینا تاکہ درست اقدام خود بخود ہو جائے اور غلط اقدام کے لیے اضافی، جان بوجھ کر کوشش کرنی پڑتی ہے۔ آرڈر کے ساتھ رکھا گیا ایک مشکل اسٹاپ ڈیفالٹ ایگزٹ ہے۔ غلط کام کرنے کے لیے پھر فعال طور پر تحفظ کو منسوخ کرنے کی ضرورت ہوتی ہے، جسے پرسکون دماغ کے پکڑنے کا زیادہ امکان ہوتا ہے۔</p>\n</details><details>\n<summary><strong>3.</strong> نظم و ضبط کے نظام کے تین حصوں کے نام بتائیں جو آپ پرسکون ہونے پر بنا سکتے ہیں۔</summary><p>ان میں سے کوئی بھی تین: پہلے سے طے شدہ اندراج، باہر نکلنے اور روکنے کے قواعد؛ تجارت سے پہلے ایک اصول کے ذریعہ پوزیشن کا سائز مقرر کیا گیا ہے۔ ایک پری ٹریڈ چیک لسٹ؛ اسکرین دیکھنے کے بجائے خودکار قیمت کے انتباہات؛ اور ہر تجارت کے بعد ایک جرنل کا جائزہ لیا جاتا ہے۔</p>\n</details><details>\n<summary><strong>4.</strong> سب سے پہلے سینڈ باکس ٹریڈنگ میں اپنے اصولوں کی مشق کیوں کریں ( OpenAlgo میں تجزیہ کار وضع)؟</summary><p>کیونکہ حقیقی پیسہ جذباتی دماغ کو بلند کرتا ہے، جو کہ ایک نیا معمول سیکھنے کی بدترین حالت ہے۔ سینڈ باکس موڈ آپ کو چیک لسٹ، سائزنگ، اسٹاپس اور حقیقی مارکیٹ کے رویے کے خلاف انتباہات کی مشق کرنے دیتا ہے، جب تک کہ روٹین خودکار نہ ہوجائے۔</p>\n</details><details>\n<summary><strong>5.</strong> آپ کا سٹاپ نقصان صرف \"آپ کے دماغ میں\" ہے اور آپ کے روزانہ نقصان کی حد ایک مبہم ارادہ ہے۔ کیا غلط ہے؟</summary><p>نظام کے دانت نہیں ہیں۔ جن قواعد کو آپ ایک کلک میں نظر انداز کر سکتے ہیں وہ تقریباً کوئی تحفظ فراہم نہیں کرتے ہیں، کیونکہ رگڑ، بازار میں بیٹھنا بند ہونا اور سخت حد ہی دراصل جذباتی حرکتوں کو روکتی ہے۔ رکاوٹوں کو حقیقی اور اوور رائڈ کرنا مشکل بنائیں۔</p>\n</details>\n","toc":[{"level":2,"text":"قوتِ ارادی کیوں کھو جاتی ہے۔","id":"why-willpower-loses"},{"level":2,"text":"نظم و ضبط ایک نظام ہے، احساس نہیں۔","id":"discipline-is-a-system-not-a-feeling"},{"level":2,"text":"صحیح چیز کو ڈیفالٹ بنائیں","id":"make-the-right-thing-the-default"},{"level":2,"text":"لائن پر پیسے کے بغیر قواعد پر عمل کریں۔","id":"practise-the-rules-without-money-on-the-line"},{"level":2,"text":"آپ کی پری ٹریڈ چیک لسٹ","id":"your-pre-trade-checklist"},{"level":2,"text":"ہر قسم کے تاجر کو کس چیز کو منظم کرنا چاہیے۔","id":"what-each-type-of-trader-must-systematise"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"5":{"html":"<p>میرا نے چھ ماہ تک NIFTY آپشنز کی تجارت کی اور یہ سمجھ نہیں پا رہی تھی کہ وہ کیوں ہارتی رہی۔ کچھ ہفتے وہ اٹھ رہی تھی، کچھ ہفتے اس نے سب کچھ واپس کر دیا، اور اکاؤنٹ آہستہ آہستہ ختم ہو گیا۔ اس نے مزید کتابیں پڑھیں، مزید ویڈیوز دیکھیں، تین بار اپنی حکمت عملی تبدیل کی۔ کسی چیز نے مدد نہیں کی۔ پھر ایک دوست نے اسے ایک بورنگ کام کرنے پر مجبور کیا: ہر تجارت کو لکھیں، اس میں یہ بھی شامل ہے کہ اسے کیسا لگا اور اس نے اسے کیوں لیا۔ چار ہفتوں بعد ایک نمونہ صفحہ سے اچھل پڑا۔ تقریباً ہر بڑا نقصان ایک کے بعد ہوا۔ <em>جیتنا</em> تجارت، جب اس نے ناقابل تسخیر محسوس کیا اور اس سیٹ اپ پر اپنے سائز کو دوگنا کر دیا جو واقعی وہاں نہیں تھا۔ چارٹ کبھی بھی اس کا مسئلہ نہیں تھا۔ اس کا اپنا ہی جوش تھا۔ ایک بار جب وہ اسے دیکھ سکتی تھی، وہ آخر کار اسے ٹھیک کر سکتی تھی۔</p>\n<h2 id=\"the-one-habit-that-turns-losses-into-lessons\">ایک عادت جو نقصانات کو سبق میں بدل دیتی ہے۔</h2>\n<p>نقصان خود آپ کو کچھ نہیں سکھاتا ہے۔ بس درد ہوتا ہے۔ آپ کو ایک گھنٹے تک برا لگتا ہے، آپ آگے بڑھتے ہیں، اور اگلے ہفتے آپ دوبارہ وہی غلطی کرتے ہیں۔ وہ چیز جو نقصان کو عبرت میں بدل دیتی ہے۔ <strong>ریکارڈ</strong>.</p>\n<p>اے <strong>ٹریڈنگ جرنل</strong> آپ جو بھی تجارت کرتے ہیں اس کا محض ایک تحریری ریکارڈ ہے، ایمانداری کے ساتھ رکھا جاتا ہے، تاکہ درجنوں تجارتوں کے اندر چھپے ہوئے نمونے ظاہر ہو جائیں۔ ایک تجارت آپ کو تقریباً کچھ نہیں بتاتی۔ پچاس تجارتیں، جو لکھی ہوئی ہیں، آپ کو بالکل بتاتی ہیں کہ آپ بطور تاجر کون ہیں، آپ کہاں نظم و ضبط کے تحت ہیں، اور آپ کہاں سے پیسے لیک کرتے رہتے ہیں۔</p>\n<p>زیادہ تر ابتدائی لوگ اسے چھوڑ دیتے ہیں کیونکہ یہ ہوم ورک کی طرح محسوس ہوتا ہے۔ لیکن بہتر ہونے والے تاجروں اور پھنسے رہنے والے تاجروں کے درمیان فرق شاذ و نادر ہی ہنر یا حکمت عملی ہے۔ یہ تقریبا ہمیشہ ایک عادت ہے. مارکیٹ خوشی سے آپ سے ایک ہی ٹیوشن فیس وصول کرے گی، بار بار، جب تک کہ آپ یہ نہ لکھیں کہ وہ آپ کو کیا سکھانے کی کوشش کر رہا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 360\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک تجارت مکمل طور پر کارڈ کے طور پر ریکارڈ کی گئی ہے: سیٹ اپ، داخلے کی وجہ، روپے میں منصوبہ بند خطرہ، داخلے کے وقت جذبات، باہر نکلتے وقت جذبات، غلطی کی گئی، اور نتیجہ، چارٹ اسکرین شاٹ کے ساتھ۔\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"360\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"15\">ایک تجارت، مکمل طور پر ریکارڈ شدہ</text>\n  <rect x=\"28\" y=\"50\" width=\"468\" height=\"288\" rx=\"12\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <g font-size=\"12\">\n    <text x=\"48\" y=\"84\" fill=\"#8b949e\">سیٹ اپ</text>\n    <text x=\"200\" y=\"84\" fill=\"#cdd9e5\" font-weight=\"700\">رینج بریک آؤٹ</text>\n    <line x1=\"44\" y1=\"98\" x2=\"480\" y2=\"98\" stroke=\"#22272e\"/>\n    <text x=\"48\" y=\"122\" fill=\"#8b949e\">وجہ میں نے لے لی</text>\n    <text x=\"200\" y=\"122\" fill=\"#cdd9e5\" font-weight=\"700\">چیک لسٹ پاس ہو گئی۔</text>\n    <line x1=\"44\" y1=\"136\" x2=\"480\" y2=\"136\" stroke=\"#22272e\"/>\n    <text x=\"48\" y=\"160\" fill=\"#8b949e\">منصوبہ بند خطرہ</text>\n    <text x=\"200\" y=\"160\" fill=\"#cdd9e5\" font-weight=\"700\">1,000 روپے (سرمایہ کا 1%)</text>\n    <line x1=\"44\" y1=\"174\" x2=\"480\" y2=\"174\" stroke=\"#22272e\"/>\n    <text x=\"48\" y=\"198\" fill=\"#8b949e\">داخلے پر جذبات</text>\n    <text x=\"200\" y=\"198\" fill=\"#86c79b\" font-weight=\"700\">پرسکون</text>\n    <line x1=\"44\" y1=\"212\" x2=\"480\" y2=\"212\" stroke=\"#22272e\"/>\n    <text x=\"48\" y=\"236\" fill=\"#8b949e\">باہر نکلتے وقت جذبات</text>\n    <text x=\"200\" y=\"236\" fill=\"#dd8452\" font-weight=\"700\">بے چین ہو کر باہر بھاگا۔</text>\n    <line x1=\"44\" y1=\"250\" x2=\"480\" y2=\"250\" stroke=\"#22272e\"/>\n    <text x=\"48\" y=\"274\" fill=\"#8b949e\">غلطی</text>\n    <text x=\"200\" y=\"274\" fill=\"#dd8452\" font-weight=\"700\">میرے سٹاپ کو وسیع کیا</text>\n    <line x1=\"44\" y1=\"288\" x2=\"480\" y2=\"288\" stroke=\"#22272e\"/>\n    <text x=\"48\" y=\"312\" fill=\"#8b949e\">نتیجہ</text>\n    <text x=\"200\" y=\"312\" fill=\"#e08a8a\" font-weight=\"700\">مائنس 1,450 روپے</text>\n  </g>\n  <rect x=\"520\" y=\"66\" width=\"216\" height=\"152\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\"/>\n  <polyline points=\"538,184 562,150 586,166 610,118 634,138 658,98 686,128 716,96\" fill=\"none\" stroke=\"#4c72b0\" stroke-width=\"2\"/>\n  <text x=\"628\" y=\"92\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\">اندراج پر چارٹ</text>\n  <text x=\"628\" y=\"244\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-weight=\"700\">اسکرین شاٹ</text>\n  <text x=\"628\" y=\"264\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10.5\">واحد ایماندار گواہ</text>\n  <text x=\"628\" y=\"300\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10.5\">اکیلے نمبر سستے ہیں۔</text>\n  <text x=\"628\" y=\"318\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10.5\">یہ وہ جگہ ہے جہاں آپ بڑھتے ہیں۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ایک حقیقی اندراج ریکارڈ کرتا ہے جو آپ کا بروکر کبھی نہیں کر سکتا: آپ کی وجہ، آپ کے جذبات، آپ کی غلطی۔</figcaption>\n</figure><h2 id=\"what-to-actually-write-down\">اصل میں کیا لکھنا ہے۔</h2>\n<p>نمبر آسان حصہ ہیں، اور کم سے کم مفید۔ آپ کا بروکر قیمت، وقت اور منافع یا نقصان کو پہلے سے ہی ریکارڈ کرتا ہے۔ آپ کا بروکر کیا کرتا ہے۔ <em>نہیں</em> ریکارڈ وہ واحد چیز ہے جو آپ کے رویے کو بدل سکتی ہے: آپ کے دماغ میں کیا چل رہا تھا۔ لہذا ایک حقیقی جریدہ ہر تجارت کے لیے سات چیزوں کو حاصل کرتا ہے۔</p>\n<ul>\n<li><strong>سیٹ اپ</strong> - وہ نمونہ یا حالت جس نے اسے تجارت بنایا۔ \"صبح کی حد سے اوپر بریک آؤٹ۔\" اسے چند لفظوں میں نام دیں۔</li>\n<li><strong>جس کی وجہ سے آپ نے اسے لیا۔</strong> - ایماندار کیوں. کیا آپ کی چیک لسٹ گزر گئی، یا آپ اس وجہ سے کود گئے کہ آپ بور تھے، یا ناراض تھے، یا گم ہونے سے خوفزدہ تھے؟</li>\n<li><strong>منصوبہ بند خطرہ</strong> - آپ نے کتنا کھونے کا فیصلہ کیا۔ <em>پہلے</em> آپ نے روپے میں داخل کیا۔ \"اگر میں غلط ہوں تو مجھے 1000 روپے کا نقصان ہو گا۔\" پہلے لکھا ہے بعد میں نہیں۔</li>\n<li><strong>داخلے پر آپ کے جذبات</strong> ١ - پرسکون، پر اعتماد، خوف زدہ، لالچی، جلدی۔ ایک لفظ کافی ہے۔</li>\n<li><strong>باہر نکلتے وقت آپ کا جذبات</strong> - ایک ہی لفظ، آپ کے بند ہونے کے وقت پکڑا گیا ہے۔ یہ وہ جگہ ہے جہاں خوف اور انتقام چھپا ہوتا ہے۔</li>\n<li><strong>غلطی، اگر کوئی ہے۔</strong> - کیا آپ نے کوئی اصول توڑا؟ اپنا اسٹاپ منتقل کریں؟ جلدی داخل کریں؟ سائز بہت بڑا ہے؟ یہاں اپنے ساتھ سفاکانہ سلوک کرو۔</li>\n<li><strong>نتیجہ</strong> --.اصلی روپیہ جیتا یا ہارا نیز a <strong>اسکرین شاٹ</strong> داخلے اور باہر نکلنے کے وقت چارٹ کا۔</li>\n</ul>\n<p>وہ اسکرین شاٹ اس کی آواز سے زیادہ اہمیت رکھتا ہے۔ ہفتوں بعد، چارٹ اس بات کا واحد ایماندار گواہ ہے جو آپ نے دیکھا۔ یادداشت آپ کی انا کی حفاظت کے لیے خاموشی سے ماضی کو دوبارہ لکھتی ہے۔ اسکرین شاٹ ایسا نہیں کرتا۔</p>\n<h2 id=\"the-journal-template-you-can-copy\">جرنل ٹیمپلیٹ جسے آپ کاپی کر سکتے ہیں۔</h2>\n<p>ان کالمز کو اسپریڈشیٹ، نوٹ بک، یا نوٹ ایپ میں کاپی کریں، جو بھی آپ اصل میں کھولیں گے۔ آلے سے کوئی فرق نہیں پڑتا۔ ایمانداری کرتا ہے۔ یہاں دو بھری ہوئی قطاریں ہیں تاکہ آپ دیکھ سکیں کہ یہ عملی طور پر کیسا لگتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>تاریخ</th>\n<th>علامت</th>\n<th>سیٹ اپ</th>\n<th>داخلے کی وجہ</th>\n<th>منصوبہ بند خطرہ</th>\n<th>جذبات میں</th>\n<th>جذبات باہر</th>\n<th>غلطی</th>\n<th>نتیجہ</th>\n<th>اسکرین شاٹ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>12 جون</td>\n<td>NIFTY 23500 CE</td>\n<td>رینج بریک آؤٹ</td>\n<td>چیک لسٹ گزر گئی، حجم بڑھ گیا۔</td>\n<td>1,000 روپے</td>\n<td>پرسکون</td>\n<td>بے چین</td>\n<td>چوڑا اسٹاپ</td>\n<td>مائنس 1,450 روپے</td>\n<td>لنک</td>\n</tr>\n<tr>\n<td>13 جون</td>\n<td>BANKNIFTY fut</td>\n<td>20-EMAپر پل بیک</td>\n<td>کوئی نہیں، آخری نقصان کے بعد بدلہ</td>\n<td>1,000 روپے</td>\n<td>ناراض</td>\n<td>راحت ملی</td>\n<td>نان سیٹ اپ لیا۔</td>\n<td>مائنس 900 روپے</td>\n<td>لنک</td>\n</tr>\n</tbody></table>\n<p>غور کریں کہ کس طرح دو ہارنے والی قطاریں پہلے سے ہی اپنی وجہ کا اعتراف کرتی ہیں: ایک منتقلی روک، اور وجہ کالم میں \"کوئی نہیں\" کے ساتھ بدلہ لینے والی تجارت۔ اس کو تلاش کرنے کے لیے آپ کو کوچ کی ضرورت نہیں ہے۔ آپ کو صرف اسے لکھنے کی ضرورت ہے۔</p>\n<h2 id=\"why-a-weekly-review-beats-daily-self-judgment\">کیوں ایک ہفتہ وار جائزہ روزانہ خود فیصلے کو ہرا دیتا ہے۔</h2>\n<p>ہر ایک دن کو دیکھنا ایک جال ہے۔ ایک ہی دن زیادہ تر ہوتا ہے۔ <strong>شور</strong>، بے ترتیب قسمت، ایک خبر کا واقعہ، ایک تیز اقدام۔ اپنے آپ کو روزانہ فیصلہ کریں اور آپ خوش قسمت سبز دن کے بعد اپنی تعریف کریں گے اور ایک بدقسمت سرخ دن کے بعد اپنے آپ کو سزا دیں گے، دونوں پر غلط سبق سیکھیں گے۔ اس سے بھی بدتر، روزانہ کا جائزہ جذباتی ہوتا ہے۔ نقصان اب بھی ڈنک رہا ہے، لہذا آپ اس کے بارے میں سیدھا نہیں سوچ سکتے۔</p>\n<p>اے <strong>ہفتہ وار جائزہ</strong> پرسکون اور واضح ہے. ہفتے میں ایک بار، ایک پرسکون شام کو، آپ پچھلے پانچ تجارتی دنوں کی اپنی تمام اندراجات کے ساتھ بیٹھتے ہیں اور انہیں ایک سیٹ کے طور پر ایک ساتھ پڑھتے ہیں۔ ایک خراب تجارت ایک حادثہ ہے۔ ایک ہفتے میں چار بار وہی خراب تجارت a <em>پیٹرن</em>اور پیٹرن بالکل وہی ہیں جو آپ ڈھونڈنے آئے تھے۔ پیٹرن کو ظاہر کرنے کے لیے ایک ہفتہ کافی لمبا ہے اور اتنا مختصر ہے کہ آپ کو اب بھی تجارت یاد ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 290\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک چار قدمی ہفتہ وار لوپ جو دہرایا جاتا ہے: ہر تجارت کو لاگ ان کریں، پورے ہفتے کا ایک ساتھ جائزہ لیں، دہرائے جانے والے پیٹرن کو دیکھیں، پھر ایک اصول کو ایڈجسٹ کریں، اور لاگنگ پر واپس جائیں۔\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"290\" fill=\"#0d1117\"/>\n  <defs>\n    <marker id=\"wlArr\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#8b949e\"/></marker>\n  </defs>\n  <text x=\"380\" y=\"28\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"15\">ہفتہ وار جائزہ لوپ</text>\n  <rect x=\"70\" y=\"56\" width=\"200\" height=\"74\" rx=\"10\" fill=\"#10241a\" stroke=\"#55a868\"/>\n  <text x=\"170\" y=\"88\" text-anchor=\"middle\" fill=\"#b9e6c8\" font-size=\"13\" font-weight=\"700\">1. LOG ہر تجارت</text>\n  <text x=\"170\" y=\"108\" text-anchor=\"middle\" fill=\"#86c79b\" font-size=\"10.5\">سیٹ اپ، وجہ، جذبات</text>\n  <rect x=\"490\" y=\"56\" width=\"200\" height=\"74\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\"/>\n  <text x=\"590\" y=\"88\" text-anchor=\"middle\" fill=\"#bcd0ee\" font-size=\"13\" font-weight=\"700\">2. REVIEW ہفتہ</text>\n  <text x=\"590\" y=\"108\" text-anchor=\"middle\" fill=\"#8fb0e0\" font-size=\"10.5\">ایک ساتھ تمام اندراجات پڑھیں</text>\n  <rect x=\"490\" y=\"174\" width=\"200\" height=\"74\" rx=\"10\" fill=\"#1a1430\" stroke=\"#8172b3\"/>\n  <text x=\"590\" y=\"206\" text-anchor=\"middle\" fill=\"#cbbfe6\" font-size=\"13\" font-weight=\"700\">3. SPOT پیٹرن</text>\n  <text x=\"590\" y=\"226\" text-anchor=\"middle\" fill=\"#a99cd0\" font-size=\"10.5\">لیک جو آپ دہراتے ہیں۔</text>\n  <rect x=\"70\" y=\"174\" width=\"200\" height=\"74\" rx=\"10\" fill=\"#2a1d12\" stroke=\"#dd8452\"/>\n  <text x=\"170\" y=\"206\" text-anchor=\"middle\" fill=\"#f0d3b9\" font-size=\"13\" font-weight=\"700\">4. ADJUST ایک اصول</text>\n  <text x=\"170\" y=\"226\" text-anchor=\"middle\" fill=\"#d6a878\" font-size=\"10.5\">چھوٹا، مخصوص، قابل امتحان</text>\n  <line x1=\"270\" y1=\"93\" x2=\"486\" y2=\"93\" stroke=\"#8b949e\" stroke-width=\"1.8\" marker-end=\"url(#wlArr)\"/>\n  <line x1=\"590\" y1=\"130\" x2=\"590\" y2=\"170\" stroke=\"#8b949e\" stroke-width=\"1.8\" marker-end=\"url(#wlArr)\"/>\n  <line x1=\"490\" y1=\"211\" x2=\"274\" y2=\"211\" stroke=\"#8b949e\" stroke-width=\"1.8\" marker-end=\"url(#wlArr)\"/>\n  <line x1=\"170\" y1=\"174\" x2=\"170\" y2=\"134\" stroke=\"#8b949e\" stroke-width=\"1.8\" marker-end=\"url(#wlArr)\"/>\n  <text x=\"380\" y=\"148\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11.5\" font-weight=\"700\">دہرائیں</text>\n  <text x=\"380\" y=\"166\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11.5\" font-weight=\"700\">ہر ہفتے</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">روزانہ لاگ ان کریں، لیکن ہفتہ وار فیصلہ کریں۔ ہفتہ وہ جگہ ہے جہاں پیٹرن ظاہر ہوتا ہے۔</figcaption>\n</figure><h2 id=\"finding-your-recurring-patterns\">اپنے بار بار چلنے والے نمونوں کو تلاش کرنا</h2>\n<p>جب آپ ایک ہفتے کے اندراجات کو ایک نشست میں پڑھتے ہیں، تو آپ کے اصلی لیک ظاہر ہونے لگتے ہیں۔ وہ تقریبا ہمیشہ بورنگ طور پر مخصوص ہوتے ہیں۔ آپ کو مل سکتا ہے:</p>\n<ul>\n<li><strong>\"میں پیر کو اپنے زیادہ تر پیسے کھو دیتا ہوں۔\"</strong> شاید آپ ہفتے کے آخر میں بچ جانے والے جوش و خروش کو مارکیٹ کے طے ہونے سے پہلے ہی تجارت کرتے ہیں۔</li>\n<li><strong>\"میری بدترین تجارت انتقامی تجارت ہے۔\"</strong> وجہ کالم میں \"کوئی نہیں\" کے ساتھ، اسے واپس جیتنے کے لیے، ہارنے کے چند منٹ بعد۔</li>\n<li><strong>\"میں صرف اس وقت ہارتا ہوں جب میں اپنی چیک لسٹ کو چھوڑ دیتا ہوں۔\"</strong> وہ اندراجات جہاں وجہ یہ کہتی ہے کہ اصلی نام کے سیٹ اپ کے بجائے \"صحیح محسوس کیا\"۔</li>\n</ul>\n<p>یہ نتائج سونے کے ہیں۔ ہر ایک ایک اصول پر پوائنٹ کرتا ہے جسے آپ تبدیل کر سکتے ہیں۔ جو تاجر پیر کا نمونہ تلاش کرتا ہے وہ صرف ایک مہینے تک پیر کو تجارت نہیں کر سکتا اور دیکھ سکتا ہے کہ کیا ہوتا ہے۔ وہ تاجر جو بدلے کی تجارت کو دیکھتا ہے وہ کسی بھی نقصان کے بعد تیس منٹ کے وقفے پر مجبور کر سکتا ہے۔ فکس عام طور پر چھوٹا، مخصوص اور مفت ہوتا ہے۔ لیکن آپ صرف ایک پیٹرن کو ٹھیک کر سکتے ہیں جسے آپ دیکھ سکتے ہیں، اور آپ اسے صرف اس صورت میں دیکھ سکتے ہیں جب آپ نے اسے لکھا ہو۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>تجارتی جریدہ وہ واحد عادت ہے جو نقصان کو سبق میں بدل دیتی ہے۔ نہ صرف قیمت اور منافع، بلکہ سیٹ اپ، آپ کی وجہ، آپ کا منصوبہ بند خطرہ، داخلے اور باہر نکلتے وقت آپ کے جذبات، اور کوئی بھی غلطی ریکارڈ کریں، پھر ایک ہی پیٹرن کو تلاش کرنے کے لیے پورے ہفتے کا جائزہ لیں جسے آپ دہراتے رہتے ہیں۔</p>\n</div></div>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>عام غلطی یہ ہے کہ کوئی جریدہ بالکل بھی نہ رکھنا، یا صرف نمبر، داخلے کی قیمت، اخراج کی قیمت، منافع اور نقصان کو لاگو کرنے والا رکھنا۔ وہ نمبر جو آپ کے بروکر کے پاس پہلے سے موجود ہیں۔ وجہ اور جذبات کے بغیر آپ کبھی نہیں دیکھ سکتے <em>کیوں</em> آپ ہار گئے، لہذا آپ اسے اگلے ہفتے دہرائیں۔ بہتر اقدام: ہر ایک تجارت پر آپ نے کیا محسوس کیا اور آپ کو کیا غلط ہوا اس کے بارے میں ایک ایماندار لائن لکھیں۔</p>\n</div></div>\n<h2 id=\"what-each-type-should-track\">ہر قسم کو کیا ٹریک کرنا چاہئے۔</h2>\n<p>جریدہ سب کے لیے ہے، لیکن کالم جو آپ کی تجارت کرتے ہیں اس کے ساتھ سب سے زیادہ اہمیت رکھتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>سب سے زیادہ کس چیز کو ٹریک کرنا ہے۔</th>\n<th>شکار کرنے کا نمونہ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>کریش کے دوران خریدنے کا تھیسس، بیچنے کا منصوبہ، اور آپ کے جذبات</td>\n<td>گھبراہٹ میں فروخت; ایک بڑی دوڑ کے بعد ہائپ پر خریدنا</td>\n</tr>\n<tr>\n<td>فعال تاجر (انٹرا ڈے / سوئنگ)</td>\n<td>سیٹ اپ، منصوبہ بند خطرہ، اندر اور باہر جذبات، ہر اصول کا توڑ</td>\n<td>بدلے کی تجارت، چیک لسٹ کو چھوڑنا، جیت کے بعد سائز بڑھانا</td>\n</tr>\n<tr>\n<td>F&amp;O ابتدائی</td>\n<td>مندرجہ بالا سبھی، نیز ادا شدہ چارجز اور وقت کے زوال کا مفروضہ</td>\n<td>ہارنے والوں کو الٹ جانے کی امید میں رکھنا۔ ہر ہفتہ وار ختم ہونے پر ٹریڈنگ</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>مارجن کا استعمال کیا جاتا ہے، حقیقت پسندانہ بدترین نقصان، جذبات جب یہ آپ کے خلاف ہوتا ہے۔</td>\n<td>دم کے خطرے کو نظر انداز کرنا؛ اسے \"اوسط\" میں کھونے والے مختصر میں شامل کرنا</td>\n</tr>\n</tbody></table>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>ایک جریدہ طاقتور ہے، لیکن یہ جادو نہیں ہے، اور اس کی حقیقی حدود ہیں۔</p>\n<p>یہ صرف کام کرتا ہے اگر آپ ہیں <strong>ایماندار</strong>. ان دنوں میں \"اچھے نظم و ضبط\" سے بھرا ہوا جریدہ جن دنوں آپ نے جوا کھیلا تھا وہ کسی جریدے سے بدتر ہے، کیونکہ یہ غلط اعتماد پیدا کرتا ہے۔ لکھنے کے لئے سب سے مشکل اندراجات، گھبراہٹ سے باہر نکلنا، انتقام کی احمقانہ تجارت، وہ ہیں جو تمام قیمتوں کو لے کر جاتی ہیں۔ اگر آپ پرائیویٹ نوٹ بک کے ساتھ سچے نہیں ہو سکتے تو ٹول آپ کی مدد نہیں کر سکتا۔</p>\n<p>یہ آپ کا فرضی کام بھی بن سکتا ہے، بغیر سوچے سمجھے ٹک ٹک بکس۔ ایک مختصر، ایماندار جریدہ ہر بار ایک طویل، بے ایمان کو مارتا ہے۔</p>\n<p>اور ایک جرنل ٹھیک کرتا ہے۔ <em>سلوک</em>، ٹوٹی ہوئی حکمت عملی نہیں ہے۔ اگر آپ کے طریقہ کار میں کوئی حقیقی برتری نہیں ہے، تو کامل نظم و ضبط صرف آپ کو زیادہ آہستہ آہستہ کھونے میں مدد کرے گا۔ تاہم، جریدہ آپ کو یہ بھی دکھائے گا، نمبر سرخ رہتے ہیں چاہے آپ کا عمل کتنا ہی صاف کیوں نہ ہو، جو بذات خود ایک ایماندار اور مفید اشارہ ہے کہ مسئلہ حکمت عملی کا ہے، آپ کے اعصاب کا نہیں۔</p>\n<p>آخر میں، چھوٹے نمونے گمراہ کرتے ہیں. پانچ تجارتیں ایک نمونہ ثابت نہیں کر سکتیں، یہ صرف قسمت ہو سکتی ہے۔ جو کچھ آپ دیکھتے ہیں اس پر بھروسہ کرنے سے پہلے اسے چند ہفتوں کے اندراجات دیں۔ یہ باب تعلیم کا ہے، ذاتی مشورہ نہیں۔ آپ کے پیٹرن آپ کو تلاش کرنے کے لئے اکیلے ہیں.</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> نقصان خود آپ کو کچھ کیوں نہیں سکھاتا؟</summary><p>ایک نقصان صرف تھوڑی دیر کے لیے تکلیف دیتا ہے اور پھر یادداشت سے مٹ جاتا ہے۔ تحریری ریکارڈ کے بغیر آپ اصل وجہ بھول جاتے ہیں اور وہی غلطی دہراتے ہیں۔ جریدہ وہ ہے جو درد کو ایک مرئی، قابل فکس اسباق میں بدل دیتا ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> آپ کا بروکر پہلے ہی اندراج کی قیمت، اخراج کی قیمت اور منافع کو ریکارڈ کرتا ہے، تو جرنل اصل میں کیا اضافہ کرتا ہے؟</summary><p>وہ چیزیں جو بروکر نہیں دیکھ سکتا: تجارت کی آپ کی وجہ، آپ کا منصوبہ بند خطرہ، داخلے اور باہر نکلتے وقت آپ کا جذبہ، اور آپ کی غلطی۔ یہی وہ حصہ ہے جو اس بات کی وضاحت کرتا ہے کہ آپ کیوں جیت گئے یا ہار گئے، اور وہ واحد حصہ جسے آپ تبدیل کر سکتے ہیں۔</p>\n</details><details>\n<summary><strong>3.</strong> ہر ایک دن کے بعد کے بجائے ہفتہ وار کیوں جائزہ لیں؟</summary><p>ایک دن زیادہ تر شور ہوتا ہے، اور نقصان کے فوراً بعد آپ واضح طور پر سوچنے کے لیے بہت جذباتی ہو جاتے ہیں۔ ایک ہفتہ اتنا لمبا ہوتا ہے کہ وہ دہرائے جانے والے نمونے کو ظاہر کرے اور اسے ایمانداری سے پڑھنے کے لیے کافی پرسکون ہو، تاکہ آپ خوش قسمت یا بدقسمت کے بجائے اصل سبق سیکھیں۔</p>\n</details><details>\n<summary><strong>4.</strong> آپ نے محسوس کیا کہ اس ماہ آپ کے تین سب سے بڑے نقصانات نقصان کے فوراً بعد کیے گئے تمام انتقامی تجارت تھے۔ آسان اگلا قدم کیا ہے؟</summary><p>ایک مخصوص قاعدہ بنائیں، مثال کے طور پر کسی بھی نقصان کے بعد تیس منٹ کا زبردستی وقفہ کریں، اور اسے چند ہفتوں تک جانچیں۔ واضح پیٹرن کے لیے درست کرنا عام طور پر ایک چھوٹا سا اصول ہوتا ہے، اور جرنل آپ کو یہ چیک کرنے دیتا ہے کہ آیا اس نے واقعی کام کیا ہے۔</p>\n</details><details>\n<summary><strong>5.</strong> ایک دیانتدار، بدصورت جریدے کے اندراج کی قیمت چاپلوسی سے زیادہ کیوں ہے؟</summary><p>کیونکہ جو اندراجات آپ کم از کم لکھنا چاہتے ہیں، گھبراہٹ سے باہر نکلنا، ٹوٹا ہوا اصول، تمام اسباق کو تھامے ہوئے ہیں۔ ایک جریدہ جو آپ کی غلطیوں کو چھپاتا ہے غلط اعتماد پیدا کرتا ہے اور آپ کو کچھ نہیں سکھاتا ہے۔</p>\n</details>\n","toc":[{"level":2,"text":"ایک عادت جو نقصانات کو سبق میں بدل دیتی ہے۔","id":"the-one-habit-that-turns-losses-into-lessons"},{"level":2,"text":"اصل میں کیا لکھنا ہے۔","id":"what-to-actually-write-down"},{"level":2,"text":"جرنل ٹیمپلیٹ جسے آپ کاپی کر سکتے ہیں۔","id":"the-journal-template-you-can-copy"},{"level":2,"text":"کیوں ایک ہفتہ وار جائزہ روزانہ خود فیصلے کو ہرا دیتا ہے۔","id":"why-a-weekly-review-beats-daily-self-judgment"},{"level":2,"text":"اپنے بار بار چلنے والے نمونوں کو تلاش کرنا","id":"finding-your-recurring-patterns"},{"level":2,"text":"ہر قسم کو کیا ٹریک کرنا چاہئے۔","id":"what-each-type-should-track"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"6":{"html":"<p>ارجن کو صبح کی پہلی تجارت میں 4000 روپے کا نقصان ہوا۔ یہ ایک صاف سٹاپ نقصان تھا، بالکل منصوبہ بندی کے مطابق۔ لیکن یہ ڈنکا۔ نوے سیکنڈ کے اندر وہ واپس آ گیا، سائز دوگنا، کوئی سیٹ اپ نہیں، بس اسے \"واپس حاصل کرنے\" کی ضرورت تھی۔ وہ تجارت بھی ہار گئی۔ اسی طرح اگلا کیا۔ 10:30 تک اس نے ایک معمولی، عام نقصان کو 22,000 روپے کے سوراخ میں تبدیل کر دیا تھا، اور ان میں سے ایک بھی اضافی تجارت اس کی چیک لسٹ میں نہیں تھی۔ اس صبح اس کی حکمت عملی میں کچھ بھی غلط نہیں تھا۔ جذبات کو محسوس کرنے اور اس پر عمل کرنے کے درمیان فرق کے ساتھ کچھ غلط تھا۔</p>\n<p>یہ باب اس خلا کو ختم کرنے کے بارے میں ہے۔ یہ وہ ہنر ہے جو پورے ماڈیول A کو ایک ساتھ جوڑتا ہے: محسوس کرتے وقت آپ کیا محسوس کر رہے ہیں، اور پہلے ہی جاننا کہ آپ اس کے بارے میں کیا کریں گے۔</p>\n<h2 id=\"what-emotional-intelligence-really-means-here\">یہاں واقعی جذباتی ذہانت کا کیا مطلب ہے۔</h2>\n<p>جذباتی ذہانت ایک نرم، مبہم خیال کی طرح لگتا ہے۔ ایک تاجر کے لیے یہ بہت ٹھوس ہے۔ یہ دو آسان صلاحیتیں ہیں۔</p>\n<p>پہلے، <strong>کسی جذبات کو پہچاننا جیسے یہ ہوتا ہے۔</strong> - اس لمحے میں \"میں ابھی ناراض ہوں\" کو پکڑنا، جب نقصان ہو جائے تو تین بار نہیں بعد میں۔ دوسرا، <strong>پہلے سے طے شدہ جواب ہونا</strong> - ایک ایسا اقدام جس کا آپ نے پہلے سے انتخاب کیا ہے، پرسکون رہتے ہوئے، لہذا آپ کو اس وقت ایجاد کرنے کی ضرورت نہیں ہے جب آپ کا دل دوڑ رہا ہو۔</p>\n<p>یہ دوسرا حصہ لوگوں کی توقع سے زیادہ اہمیت رکھتا ہے۔ نقصان کی گرمی میں آپ کا سوچنے والا دماغ خاموش ہو جاتا ہے اور آپ کے اضطراب پر قابو پا لیتے ہیں۔ آپ گھبراہٹ کے درمیان ایک اچھے فیصلے کے لیے اپنے راستے کا سبب نہیں بنیں گے۔ صرف وہی چیز جو آپ کو بچاتی ہے وہ اصول ہے جو آپ نے پہلے ترتیب دیا تھا: <em>اگر میں X محسوس کرتا ہوں تو میں Y کرتا ہوں۔</em> اس باب کا کام X (احساس) کو مرئی بنانا، اور Y (جواب) کو درست کرنا ہے اس سے پہلے کہ آپ کو اس کی ضرورت ہو۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 360\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"اسے پہچاننے اور نام دینے کے لیے ٹرگر سے جذبات کی طرف ایک بہاؤ، جو تین جوابات میں شامل ہوتا ہے - توقف، سائز کم کرنا، قدم دور کرنا - پھر دوبارہ ترتیب میں ضم ہوجاتا ہے۔\">\n  <defs>\n    <marker id=\"ar1\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\" markerUnits=\"strokeWidth\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8b949e\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"360\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"28\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ایک ٹرگر سے ایک پرسکون، پہلے سے طے شدہ جواب تک</text>  <rect x=\"210\" y=\"44\" width=\"340\" height=\"42\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\"/>\n  <text x=\"380\" y=\"70\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">محرک: ایک نقصان، بوریت، ایک چھوٹی حرکت</text>\n  <line x1=\"380\" y1=\"86\" x2=\"380\" y2=\"102\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar1)\"/>  <rect x=\"210\" y=\"104\" width=\"340\" height=\"42\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\"/>\n  <text x=\"380\" y=\"130\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">جذبات میں اضافہ: خوف، غصہ، لالچ</text>\n  <line x1=\"380\" y1=\"146\" x2=\"380\" y2=\"162\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar1)\"/>  <rect x=\"210\" y=\"164\" width=\"340\" height=\"42\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\"/>\n  <text x=\"380\" y=\"190\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">پہچانیں اور اس کا نام دیں: \"یہ غصہ ہے۔\"</text>  <line x1=\"380\" y1=\"206\" x2=\"380\" y2=\"224\" stroke=\"#8b949e\" stroke-width=\"2\"/>\n  <line x1=\"130\" y1=\"224\" x2=\"630\" y2=\"224\" stroke=\"#8b949e\" stroke-width=\"2\"/>\n  <line x1=\"130\" y1=\"224\" x2=\"130\" y2=\"238\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar1)\"/>\n  <line x1=\"380\" y1=\"224\" x2=\"380\" y2=\"238\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar1)\"/>\n  <line x1=\"630\" y1=\"224\" x2=\"630\" y2=\"238\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar1)\"/>  <rect x=\"60\" y=\"240\" width=\"140\" height=\"46\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\"/>\n  <text x=\"130\" y=\"268\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">توقف</text>\n  <rect x=\"310\" y=\"240\" width=\"140\" height=\"46\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\"/>\n  <text x=\"380\" y=\"268\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">سائز کو کم کریں۔</text>\n  <rect x=\"560\" y=\"240\" width=\"140\" height=\"46\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\"/>\n  <text x=\"630\" y=\"268\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">دور ہو جاؤ</text>  <line x1=\"130\" y1=\"286\" x2=\"360\" y2=\"302\" stroke=\"#8b949e\" stroke-width=\"2\"/>\n  <line x1=\"380\" y1=\"286\" x2=\"380\" y2=\"302\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar1)\"/>\n  <line x1=\"630\" y1=\"286\" x2=\"400\" y2=\"302\" stroke=\"#8b949e\" stroke-width=\"2\"/>\n  <rect x=\"240\" y=\"304\" width=\"280\" height=\"44\" rx=\"10\" fill=\"#11161d\" stroke=\"#37b3a4\"/>\n  <text x=\"380\" y=\"331\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">ری سیٹ کریں، پھر پلان کو دوبارہ ٹریڈ کریں۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">آپ محرک یا جذبات کو نہیں روک سکتے۔ آپ درمیان میں قدم کو تربیت دے سکتے ہیں۔</figcaption>\n</figure><h2 id=\"the-five-states-that-wreck-trades\">تجارت کو تباہ کرنے والی پانچ ریاستیں۔</h2>\n<p>زیادہ تر اڑا دیئے گئے اکاؤنٹس پانچ جذباتی حالتوں میں سے ایک کا پتہ لگاتے ہیں۔ ان کے نام جانیں۔ کسی احساس کا نام دینا آدھا علاج ہے، کیونکہ جس لمحے آپ اسے لیبل لگاتے ہیں، آپ کے دماغ کا پرسکون حصہ کمرے میں واپس آ جاتا ہے۔</p>\n<p><strong>خوف۔</strong> آپ جیتنے والے کو بہت جلد بند کر دیتے ہیں کیونکہ آپ منافع واپس نہیں کر سکتے۔ یا آپ منجمد ہوجاتے ہیں اور کسی سیٹ اپ پر کلک نہیں کرسکتے جو بالکل وہی ہے جو آپ کا منصوبہ چاہتا ہے۔ خوف آپ کو سکڑتا ہے۔</p>\n<p><strong>غصہ، نقصان کے بعد۔</strong> یہ ارجن کی صبح ہے۔ ایک عام، منصوبہ بند نقصان ایک توہین کی طرح محسوس ہوتا ہے، اور آپ مارکیٹ میں واپس آنا چاہتے ہیں۔ یہیں سے بدلے کی تجارت جنم لیتی ہے، اور یہ چھوٹے نقصان کو بڑے نقصان میں بدلنے کا تیز ترین طریقہ ہے۔</p>\n<p><strong>بوریت۔</strong> خاموش قاتل۔ کوئی سیٹ اپ نہیں ہے، آپ کی چیک لسٹ میں کچھ بھی نہیں ہے، لیکن اسکرین کھلی ہے اور آپ کی انگلیاں کھجلی ہیں۔ لہذا آپ عمل کے لئے تجارت کرتے ہیں، کنارے کے لئے نہیں۔ بور ٹریڈ ایک ٹیکس ہے جسے آپ خاموش بیٹھنے سے قاصر ہونے کی وجہ سے ادا کرتے ہیں۔</p>\n<p><strong>لالچ۔</strong> جیت آپ کو ناقابل تسخیر محسوس کرتی ہے، اس لیے آپ کا سائز بڑھ جاتا ہے، اپنے ہدف کو نظر انداز کرتے ہیں، اور \"تھوڑا زیادہ\" تک پہنچ جاتے ہیں۔ لالچ ایک اچھی تجارت کو آپ کے داخلے پر واپسی کے چکر میں بدل دیتا ہے۔</p>\n<p><strong>شرم</strong> پانچوں میں سب سے زیادہ پوشیدہ۔ آپ نقصان اٹھاتے ہیں اور آپ اسے چھپاتے ہیں - آپ اسے لاگ نہیں کرتے، آپ دور دیکھتے ہیں، ہوسکتا ہے کہ آپ کسی (بشمول آپ) کے نوٹس لینے سے پہلے اسے مٹانے کے لیے بڑی تجارت کریں۔ شرم بالکل خطرناک ہے کیونکہ یہ اندھیرے میں کام کرتی ہے۔ جس نقصان کو آپ دیکھنے سے انکار کرتے ہیں وہ ایک سبق ہے جس کی قیمت آپ دو بار ادا کریں گے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آپ خوف، غصہ، بوریت، لالچ یا شرم کو حذف نہیں کرسکتے ہیں۔ آپ صرف ان کو جلد تلاش کرنا سیکھ سکتے ہیں اور ہر ایک کے لیے ایک پہلے سے طے شدہ اقدام کو تیار رکھ سکتے ہیں۔ شناخت کے علاوہ منصوبہ بند ردعمل پوری مہارت ہے۔</p>\n</div></div>\n<h3 id=\"name-it-and-respond\">اس کا نام دیں اور جواب دیں۔</h3>\n<p>اس میز کو ایسی جگہ رکھیں جہاں آپ تجارت کرتے وقت اسے دیکھ سکیں۔ بات کم محسوس کرنے کی نہیں ہے۔ یہ احساس کو محسوس کرنا اور آٹو پائلٹ پر ردعمل کو چلانا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>جذبات</th>\n<th>وارننگ کا نشان</th>\n<th>پہلے سے طے شدہ جواب</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>خوف</td>\n<td>فاتحین کو جلد ختم کرنا؛ ایک درست سیٹ اپ پر کلک نہیں کر سکتے</td>\n<td>سائز کو کم کریں جب تک کہ خطرہ چھوٹا محسوس نہ ہو، پھر منصوبہ بند تجارت کریں۔</td>\n</tr>\n<tr>\n<td>غصہ (نقصان کے بعد)</td>\n<td>\"مجھے اسے ابھی واپس لینا ہے\"؛ اگلی تجارت میں چھلانگ لگانا</td>\n<td>اسکرین سے دور ہو جاؤ؛ منٹوں کی ایک مقررہ تعداد کے لیے کوئی نئی تجارت نہیں۔</td>\n</tr>\n<tr>\n<td>بوریت</td>\n<td>تجارت کے لیے کسی چیز، کسی بھی چیز کے لیے سکرول کرنا</td>\n<td>پلیٹ فارم بند کریں؛ غیر تجارت تجارت ہے۔</td>\n</tr>\n<tr>\n<td>لالچ</td>\n<td>جیت کے بعد سائز بڑھانا؛ اپنے ہدف کو نظر انداز کرنا</td>\n<td>پوزیشن کا بینک حصہ؛ منصوبہ بندی کے سائز پر واپس</td>\n</tr>\n<tr>\n<td>شرم</td>\n<td>نقصان کو چھپانا؛ اسے لاگ ان نہیں کرنا؛ اسے مٹانے کے لیے بڑی تجارت کرنا</td>\n<td>بالکل اسی طرح لاگ ان کریں جیسے یہ ہوا تھا۔ اگلی تجارت پر نصف سائز</td>\n</tr>\n</tbody></table>\n<h2 id=\"the-simple-moves-that-follow-recognition\">سادہ چالیں جو تسلیم کی پیروی کرتی ہیں۔</h2>\n<p>اس جدول میں جوابات پیچیدہ نہیں ہیں۔ واقعی صرف چار ہیں، اور وہ اوورلیپ ہوتے ہیں۔</p>\n<p><strong>توقف۔</strong> احساس اور کلک کے درمیان فاصلہ رکھیں۔ یہاں تک کہ دس سست سیکنڈ اور ایک پوری سانس بھی اکثر سوچنے والے دماغ کو پکڑنے کے لیے کافی ہوتی ہے۔</p>\n<p><strong>سائز کو کم کریں۔</strong> جب جذبات زیادہ ہوتے ہیں تو چھوٹی پوزیشنیں داؤ پر لگ جاتی ہیں تاکہ آپ سوچ سکیں۔ چوتھائی سائز کی تجارت آپ کو اس طرح نقصان نہیں پہنچا سکتی جس طرح بدلہ لینے والا کر سکتا ہے۔</p>\n<p><strong>دور ہو جاؤ۔</strong> جسمانی طور پر اسکرین کو چھوڑ دیں۔ کھڑے ہو جاؤ، پانی لو، پانچ منٹ چلو۔ آپ بدلہ نہیں لے سکتے ایک چارٹ جس کو آپ نہیں دیکھ رہے ہیں۔</p>\n<p><strong>سانس لیں اور دوبارہ ترتیب دیں۔</strong> جسم کو سست کریں اور دماغ اس کی پیروی کرتا ہے۔ کچھ گہری سانسیں حقیقی طور پر گھبراہٹ کے ردعمل کو کم کرتی ہیں۔ پھر آپ اپنے تحریری منصوبے پر واپس جائیں، نہ کہ اپنے جذبات کی طرف۔</p>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>دو کلاسک ابتدائی غلطیاں یہ ثابت کرنے کے لیے ٹریڈنگ کر رہی ہیں کہ آپ صحیح تھے، اور ٹریڈنگ کر رہے ہیں کیونکہ آپ بور ہو گئے ہیں۔ دونوں \"ایکٹو\" ہونے کی طرح محسوس کرتے ہیں۔ دونوں آپ کی چیک لسٹ کو نظر انداز کرتے ہیں۔ بہتر اقدام اتنا ہی مشکل ہے: کچھ نہ کریں۔ درست سیٹ اپ کے بغیر ایک فلیٹ اسکرین بالکل اچھی تجارت ہے۔ ہاتھ پر ہاتھ دھرے بیٹھنا ایک ہنر ہے ناکامی نہیں۔</p>\n</div></div>\n<h2 id=\"do-not-trade-your-identity\">اپنی شناخت کا سودا نہ کریں۔</h2>\n<p>یہاں سب سے گہرا جال ہے، اور یہ پانچوں جذبات کے نیچے بیٹھا ہے۔ جس لمحے کوئی تجارت سیٹ اپ کے بارے میں ہونا بند ہو جاتی ہے اور اس کے بارے میں ہونا شروع ہو جاتی ہے۔ <em>آپ</em> - صحیح ہونے کے بارے میں، اپنی ذہانت کے بارے میں، اپنی قدر کے بارے میں - آپ نے خطرے کو سنبھالنا چھوڑ دیا ہے اور اپنی انا کا دفاع کرنا شروع کر دیا ہے۔</p>\n<p>تجارت صرف ایک شرط ہے جس میں معلوم، محدود منفی پہلو ہے۔ اس پر ہونے والا نقصان ڈیٹا ہے: مارکیٹ نے کچھ کیا، آپ کے اصول نے آپ کو ختم کردیا، آگے بڑھیں۔ لیکن انا ایک فیصلے کے طور پر نقصان سنتا ہے: <em>میں غلط تھا، اس لیے میں ناکام ہوں۔</em> اس فیصلے سے بچنے کے لیے یہ خطرناک کام کرتا ہے - یہ اسٹاپ کو حرکت دیتا ہے، یہ خیال کو \"ثابت\" کرنے کے لیے ہارنے والے کو جوڑتا ہے، یہ باہر نکلنے سے انکار کرتا ہے۔ ان میں سے ہر ایک خطرے کا انتظام خاموشی سے بند ہے تاکہ احساس کو محفوظ رکھا جا سکے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"دو کالم کنٹراسٹ: بائیں طرف آپ کے پلان کی تجارت کرنا نقصان کو ڈیٹا سمجھتا ہے، جب کہ دائیں طرف آپ کی انا کی تجارت نقصان کو آپ کی مالیت کے فیصلے کے طور پر سمجھتی ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"28\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">اپنے منصوبے کی تجارت بمقابلہ اپنی انا کی تجارت</text>  <rect x=\"30\" y=\"48\" width=\"340\" height=\"232\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\"/>\n  <rect x=\"30\" y=\"48\" width=\"340\" height=\"40\" rx=\"10\" fill=\"#16241b\" stroke=\"#55a868\"/>\n  <text x=\"200\" y=\"74\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">اپنے منصوبے کی تجارت</text>\n  <circle cx=\"52\" cy=\"112\" r=\"4\" fill=\"#55a868\"/><text x=\"66\" y=\"117\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">تحریری اصولوں پر عمل کرتا ہے۔</text>\n  <circle cx=\"52\" cy=\"146\" r=\"4\" fill=\"#55a868\"/><text x=\"66\" y=\"151\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">داخلے سے پہلے خطرہ طے ہوتا ہے۔</text>\n  <circle cx=\"52\" cy=\"180\" r=\"4\" fill=\"#55a868\"/><text x=\"66\" y=\"185\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">سٹاپ نقصان کو لاگت کے طور پر قبول کرتا ہے۔</text>\n  <circle cx=\"52\" cy=\"214\" r=\"4\" fill=\"#55a868\"/><text x=\"66\" y=\"219\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">باہر نکلتا ہے جب قاعدہ باہر نکلنے کا کہتا ہے۔</text>\n  <circle cx=\"52\" cy=\"248\" r=\"4\" fill=\"#55a868\"/><text x=\"66\" y=\"253\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">نقصان ڈیٹا ہے، فیصلہ نہیں۔</text>  <rect x=\"390\" y=\"48\" width=\"340\" height=\"232\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\"/>\n  <rect x=\"390\" y=\"48\" width=\"340\" height=\"40\" rx=\"10\" fill=\"#241619\" stroke=\"#c44e52\"/>\n  <text x=\"560\" y=\"74\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">اپنی انا کی تجارت</text>\n  <circle cx=\"412\" cy=\"112\" r=\"4\" fill=\"#c44e52\"/><text x=\"426\" y=\"117\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">تجارت کو درست کرنے کی ضرورت ہے۔</text>\n  <circle cx=\"412\" cy=\"146\" r=\"4\" fill=\"#c44e52\"/><text x=\"426\" y=\"151\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">سٹاپ کو حرکت دیتا ہے یا ہٹاتا ہے۔</text>\n  <circle cx=\"412\" cy=\"180\" r=\"4\" fill=\"#c44e52\"/><text x=\"426\" y=\"185\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">اسے \"ثابت\" کرنے کے لیے ہارنے والے کو شامل کرتا ہے۔</text>\n  <circle cx=\"412\" cy=\"214\" r=\"4\" fill=\"#c44e52\"/><text x=\"426\" y=\"219\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">نقصان کو چھپاتا ہے، لاگ کو چھوڑ دیتا ہے۔</text>\n  <circle cx=\"412\" cy=\"248\" r=\"4\" fill=\"#c44e52\"/><text x=\"426\" y=\"253\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">نقصان کا مطلب ہے \"میں ناکام ہوں\"</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ایک ہی نقصان، دو کہانیاں۔ ان میں سے صرف ایک آپ کو خطرے کا انتظام کرنے دیتا ہے۔</figcaption>\n</figure><p>درست کرنا ایک چھوٹی سی ذہنی علیحدگی ہے جس پر آپ مشق کر سکتے ہیں: <em>میں اپنی تجارت نہیں ہوں۔</em> تجارت غلط ہو سکتی ہے جب کہ آپ بالکل ٹھیک ہیں۔ اپنے نتائج کے بارے میں عمل کی زبان میں بات کریں - \"میں نے اپنے منصوبے پر عمل کیا\" یا \"میں نے اپنا اصول توڑا\" - کبھی بھی \"میں ایک باصلاحیت ہوں\" یا \"میں نا امید ہوں\"۔ اپنی عزت نفس کو پوزیشن سے دور رکھنا وہی ہے جو آپ کو ہارنے والے کو صاف طور پر کاٹنے دیتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کسی بھی کلک سے پہلے ایک سادہ ٹیسٹ: \"کیا میں یہ تجارت اس لیے لے رہا ہوں کہ میری چیک لسٹ ایسا کہتی ہے، یا اس لیے کہ میں صحیح ہونا چاہتا ہوں / میں بور ہوں / میں اسے واپس چاہتا ہوں؟\" اگر یہ دوسرا ہے تو جواب نہیں ہے۔</p>\n</div></div>\n<h2 id=\"a-personal-reset-routine\">ایک ذاتی ری سیٹ کا معمول</h2>\n<p>جب آپ محسوس کرتے ہیں کہ آپ پریشان ہیں، آپ کو سوچنے کی ضرورت نہیں ہے۔ آپ کا ایک معمول ہونا چاہئے جو آپ چلاتے ہیں، ہر بار اسی طرح۔ اس کا اپنا ورژن لکھیں اور اسے اپنی اسکرین کے قریب ٹیپ کریں۔</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>اسے نام دیں۔</strong> جذبات کو اونچی آواز میں کہو: \"یہ غصہ / بوریت / لالچ ہے۔\"</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>ہاتھ بند۔</strong> روٹین ختم ہونے تک کوئی نیا آرڈر نہیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>سانس لینا۔</strong> چار آہستہ سانسیں، اندر سے زیادہ لمبی۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>دور ہو جاؤ۔</strong> اسکرین سے دو سے پانچ منٹ، اپنے پیروں پر۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>منصوبہ چیک کریں۔</strong> کیا ابھی چیک لسٹ پر کوئی درست سیٹ اپ ہے؟ اگر نہیں، تو کوئی تجارت نہیں ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>کم کرنا یا روکنا۔</strong> اگر آپ دوبارہ داخل ہوتے ہیں تو اسے چھوٹے سائز میں کریں۔ اگر آپ نے اپنے یومیہ نقصان کی حد کو مارا ہے، تو آپ کا دن پورا ہو گیا ہے۔</li>\n</ul>\n<p>یہ مشورہ نہیں ہے کہ کیا خریدنا یا بیچنا ہے۔ یہ ایک ذاتی عمل ہے - اسے ایک بار، پرسکون طریقے سے بنائیں، اور اسے آپ کو ان لمحات میں لے جانے دیں جب آپ سیدھا نہیں سوچ سکتے۔</p>\n<h2 id=\"how-this-differs-across-trader-types\">یہ تاجروں کی اقسام میں کس طرح مختلف ہے۔</h2>\n<p>وہی پانچ جذبات ہر ایک کے لیے ظاہر ہوتے ہیں، لیکن آپ جس سیٹ پر بیٹھتے ہیں اس کے ساتھ خطرناک اور محرک بدل جاتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>سب سے خطرناک جذبات</th>\n<th>عام محرک</th>\n<th>ری سیٹ جو مدد کرتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>خوف</td>\n<td>2020 COVID زوال جیسا حادثہ (NIFTY تقریباً 38% نیچے)</td>\n<td>دنوں کے لئے دور؛ کچھ نہ کرو SIP پلان پر دوبارہ جائیں، اسکرین پر نہیں۔</td>\n</tr>\n<tr>\n<td>انٹرا ڈے تاجر</td>\n<td>غصہ یا بوریت</td>\n<td>صبح کا نقصان، یا سست، فلیٹ سیشن</td>\n<td>تجارت پر سخت حد اور روزانہ نقصان کی حد؛ جب دونوں مارے جائیں تو دور چلے جائیں۔</td>\n</tr>\n<tr>\n<td>F&amp;O (فیوچر) تاجر</td>\n<td>لالچ پلس انا</td>\n<td>سرگوشی کا فائدہ اٹھائیں \"تیزی سے صحت یاب ہونے کے لیے سائز بڑھائیں\"</td>\n<td>لگاتار دو ہارنے والوں کے بعد لاٹ کاٹیں۔ اسے واپس جیتنے کے لیے کبھی بھی سائز نہ بڑھائیں۔</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>تیز رفتار حرکت کا خوف</td>\n<td>ایک مختصر آپشن کے خلاف اچانک فرق</td>\n<td>پہلے سے طے شدہ اخراج؛ سٹاپ کو کبھی وسیع نہ کریں؛ سائز تو ایک برا دن آپ کو مٹا نہیں سکتا</td>\n</tr>\n</tbody></table>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>جذباتی ذہانت ایک طاقتور ٹول ہے، لیکن یہ جادو نہیں ہے، اور یہ ایک بری بنیاد کو نہیں بچائے گی۔</p>\n<p>یہ اس وقت ناکام ہوجاتا ہے جب واپس جانے کا کوئی منصوبہ نہیں ہوتا ہے۔ \"پہچاننا اور جواب دینا\" فرض کرتا ہے کہ آپ کے پاس تحریری قواعد اور ایک چیک لسٹ ہے جس پر واپس جانا ہے۔ بغیر کسی منصوبہ بندی کے، پرسکون ہونا آپ کو ایک پرسکون جواری بنا دیتا ہے۔</p>\n<p>یہ تھکن، نیند کی کمی، پیسے کے دباؤ، یا نقصانات کے بعد ناکام ہوجاتا ہے۔ سیلف کنٹرول ایک بیٹری ہے، اور یہ فلیٹ چلتی ہے۔ ان دنوں ایماندارانہ اقدام یہ ہوتا ہے کہ چھوٹی تجارت کی جائے یا بالکل نہیں، کیونکہ کوئی بھی معمول مکمل طور پر کمزور دماغ کی جگہ نہیں لیتا۔</p>\n<p>اگر آپ صرف اس کے بارے میں پڑھتے ہیں تو یہ ناکام ہوجاتا ہے۔ یہ حرکتیں تربیت یافتہ عادات کے طور پر کام کرتی ہیں، خیالات کے طور پر نہیں۔ پہلی چند بار جب آپ درمیانی جھکاؤ کو دور کرنے کی کوشش کریں گے تو یہ تقریباً ناممکن محسوس ہوگا۔ یہ عام بات ہے۔ یہ نمائندوں کے ساتھ آسان ہو جاتا ہے، کسی بھی مہارت کی طرح۔</p>\n<p>اور یہ ایک ایسی حکمت عملی کو ٹھیک نہیں کر سکتا جس کا کوئی کنارہ نہ ہو، یا پوزیشن کے سائز کے ارد گرد سوچنا بہت بڑا ہو۔ اگر ایک تجارت آپ کو بری طرح نقصان پہنچا سکتی ہے، تو خوف اور لالچ ہمیشہ جیتیں گے۔ جذباتی مہارت صوتی رسک مینجمنٹ کے سب سے اوپر ہے - یہ بالکل وہی ہے جہاں اس کورس کا باقی حصہ آگے جاتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>یہ ماڈیول اے کو بند کر دیتا ہے۔ اب آپ کے پاس اندرونی ٹول کٹ ہے: مارکیٹ آپ کے دماغ پر کیسے چلتی ہے، وہ تعصبات جو آپ کے نظریہ کو بگاڑتے ہیں، منصوبہ بندی کا نظم و ضبط، اور اس پر عمل کرنے کی جذباتی مہارت۔ یہاں سے کورس باہر کی طرف موڑتا ہے - ہیجنگ، سرمائے کی حفاظت، اور ریڈی میڈ پلے بکس تک جو آپ پہنچتے ہیں جب کوئی پوزیشن آپ کے خلاف ہوتی ہے۔ مضبوط نفسیات وہی ہے جو ان پلے بکس کو اصل میں کام کرنے دیتی ہے، کیونکہ ایک منصوبہ صرف تاجر کو اسے چلانے کے لیے کافی پرسکون ہونے میں مدد دیتا ہے۔</p>\n</div></div>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> ایک تاجر کے لیے جذباتی ذہانت کے دو حصے کیا ہیں؟</summary><p>کسی جذبات کو پہچاننا جیسا کہ یہ ہو رہا ہے، اور اس کا جواب دینا آپ نے پہلے سے فیصلہ کیا ہے۔ پہلے سے طے شدہ اقدام کے بغیر احساس کو محسوس کرنا کافی نہیں ہے۔ بیداری کے بغیر منصوبہ بند اقدام کبھی متحرک نہیں ہوتا۔</p>\n</details><details>\n<summary><strong>2.</strong> ایک ابتدائی شخص ایک سست، پرسکون سیشن کے دوران ایسی تجارت کرتا ہے جو ان کی چیک لسٹ میں نہیں ہے۔ کام پر کون سا جذبہ زیادہ ہوتا ہے؟</summary><p>بوریت - جب کوئی سیٹ اپ نہ ہو تو کارروائی کے لیے تجارت۔ پہلے سے طے شدہ جواب پلیٹ فارم کو بند کرنا ہے، کیونکہ غیر تجارت بالکل درست تجارت ہے۔</p>\n</details><details>\n<summary><strong>3.</strong> \"اپنی شناخت کی تجارت\" اتنا خطرناک کیوں ہے؟</summary><p>جب کوئی تجارت صحیح ہونے یا آپ کی عزت نفس کے بارے میں ہو جاتی ہے، تو آپ اپنے سرمائے کی بجائے اپنی انا کی حفاظت کرتے ہیں - آپ سٹاپ کو منتقل کرتے ہیں، ہارنے والوں میں اضافہ کرتے ہیں، اور باہر نکلنے سے انکار کرتے ہیں۔ حل یہ ہے کہ خود کو تجارت سے الگ کر لیا جائے: نقصان ڈیٹا ہے، آپ پر کوئی فیصلہ نہیں۔</p>\n</details><details>\n<summary><strong>4.</strong> ان سادہ چالوں کے نام بتائیں جو جذبات کو پہچاننے کے بعد چلتے ہیں۔</summary><p>رکیں (اداکاری کرنے سے پہلے ایک وقفہ رکھیں)، سائز کو کم کریں (داؤ کو کم کریں)، اسکرین سے دور رہیں، اور دوبارہ سیٹ کرنے کے لیے سانس لیں - پھر اپنے جذبات کے بجائے اپنے تحریری منصوبے پر واپس جائیں۔</p>\n</details><details>\n<summary><strong>5.</strong> نقصان (شرم) کو چھپانا یا لاگ نہ کرنا خاص طور پر نقصان دہ کیوں ہے؟</summary><p>ایک نقصان جسے آپ دیکھنے سے انکار کرتے ہیں وہ سبق ہے جو آپ کبھی نہیں سیکھتے ہیں، لہذا آپ اسے دوبارہ ادا کرتے ہیں۔ اسے بالکل لاگ کرنا، اسے بلند آواز میں نام دینا، اور اگلی بار سائز کو کم کرنا غلطی کو روشنی میں لے جاتا ہے جہاں آپ حقیقت میں بہتری لا سکتے ہیں۔</p>\n</details>\n","toc":[{"level":2,"text":"یہاں واقعی جذباتی ذہانت کا کیا مطلب ہے۔","id":"what-emotional-intelligence-really-means-here"},{"level":2,"text":"تجارت کو تباہ کرنے والی پانچ ریاستیں۔","id":"the-five-states-that-wreck-trades"},{"level":3,"text":"اس کا نام دیں اور جواب دیں۔","id":"name-it-and-respond"},{"level":2,"text":"سادہ چالیں جو تسلیم کی پیروی کرتی ہیں۔","id":"the-simple-moves-that-follow-recognition"},{"level":2,"text":"اپنی شناخت کا سودا نہ کریں۔","id":"do-not-trade-your-identity"},{"level":2,"text":"ایک ذاتی ری سیٹ کا معمول","id":"a-personal-reset-routine"},{"level":2,"text":"یہ تاجروں کی اقسام میں کس طرح مختلف ہے۔","id":"how-this-differs-across-trader-types"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"7":{"html":"<p>کرن نے 50,000 روپے سے شروعات کی جو وہ حقیقی طور پر بچا سکتے تھے۔ چند مہینوں میں یہ ختم ہو گیا، لیکن رکنا کبھی بھی اس کے ذہن میں نہیں آیا - اسے واپس جیتنے کے لیے صرف ایک اچھی دوڑ کی ضرورت تھی۔ چنانچہ اس نے ذاتی قرض لیا اور اپنی بیوی سے کہا کہ یہ کام کے اخراجات کے لیے ہے۔ نقصانات جو اس نے چھپا رکھے تھے۔ نایاب جیتنے والی تجارت کو اس نے گھنٹوں تک اپنے سر میں دہرایا۔ جب تک اس نے اعتراف کیا کہ کیا ہو رہا ہے، پیسہ سب سے برا حصہ نہیں تھا۔ سب سے بری بات یہ تھی کہ وہ رک نہیں سکتا تھا، یہاں تک کہ صبح اس نے خود سے قسم کھائی تھی کہ وہ کرے گا۔</p>\n<p>یہ ماڈیول کا سب سے مشکل باب ہے، اور سب سے اہم۔ ہر دوسرا باب فرض کرتا ہے کہ جواب تجارت کرنا ہے۔ <em>بہتر</em>. یہ ایک لائن کے بارے میں ہے جسے کچھ لوگ خاموشی سے عبور کرتے ہیں، جہاں ایماندارانہ جواب یہ ہے کہ رکنا اور مدد حاصل کریں۔ اس میں شرم کی کوئی بات نہیں۔ یہ ایک معروف، قابل علاج نمونہ ہے، اور آپ کو انتباہی علامات کی ضرورت سے پہلے ان کو جاننے کا حق ہے۔</p>\n<h2 id=\"when-a-habit-becomes-a-hook\">جب عادت بن جاتی ہے۔</h2>\n<p>زیادہ تر لوگوں کے لیے، فعال تجارت صرف ایک سرگرمی ہے۔ تم یہ کرو، تم رک جاؤ، تم رات کے کھانے پر جاؤ۔ کچھ لوگوں کے لیے کچھ اور ہوتا ہے۔ ٹریڈنگ آپ کے کچھ ہونے سے رک جاتی ہے اور ایسی چیز بن جاتی ہے جو آپ کرتی ہے۔ جب آپ اسکرین پر نہیں ہوتے ہیں تو آپ اس کے بارے میں سوچتے ہیں۔ جب آپ تجارت نہیں کر سکتے تو آپ بے چین محسوس کرتے ہیں۔ پوزیشن کا سائز اس سے کم اہمیت رکھتا ہے۔ <em>ضرورت</em> ایک پر ہونا</p>\n<p>یہ کردار کی خرابی نہیں ہے، اور یہ کمزور یا لالچی ہونے کے بارے میں نہیں ہے۔ انٹرا ڈے اور ایف اینڈ او ٹریڈنگ کا تیز رفتار فیڈ بیک - پیسہ ہر سیکنڈ میں منتقل ہوتا ہے، ایک بٹن جو فوری طور پر ادائیگی کرتا ہے یا سزا دیتا ہے - ایک سلاٹ مشین کی طرح دماغ میں وہی وائرنگ روشن کرتا ہے۔ جو محققین مسئلہ جوئے کا مطالعہ کرتے ہیں وہ کچھ فعال تاجروں میں ایک ہی لوپ دیکھتے ہیں۔ ایمانداری سے نام رکھنا توہین نہیں ہے۔ یہ اس سے آزاد ہونے کا پہلا قدم ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>یہ باب تعلیم کا ہے، طبی یا مالی مشورہ نہیں۔ اگر نیچے دیا گیا نمونہ آپ کی طرح لگتا ہے یا کوئی آپ سے پیار کرتا ہے، تو براہ کرم اسے کسی پیشہ ور سے بات کرنے کی وجہ سمجھیں - ڈاکٹر، ایک مشیر، یا ہیلپ لائن - نہ کہ شرم محسوس کرنے کی وجہ کے طور پر۔</p>\n</div></div>\n<h2 id=\"the-loop-that-hooks-you\">وہ لوپ جو آپ کو جوڑتا ہے۔</h2>\n<p>لت واقعی انعام کے بارے میں نہیں ہے۔ یہ کے بارے میں ہے <em>غیر متوقع</em> انعام اگر تجارت ہر بار ایک ہی رقم ادا کرتی ہے، تو آپ بور ہو جائیں گے۔ جو چیز ہک کو اندر رکھتی ہے وہ یہ ہے کہ آپ کبھی نہیں جانتے ہیں - یہ اگلا بڑا ہوسکتا ہے۔ یہ غیر یقینی صورتحال بالکل وہی ہے جس سے دماغ کو دور رہنا مشکل لگتا ہے۔</p>\n<p>دو چیزیں لوپ کو کھانا کھلاتی ہیں۔ پہلا ہے <strong>قریب کی یاد</strong>: وہ تجارت جس نے تقریباً کام کیا، قیمت آپ کے راستے میں بھاگنے سے پہلے سٹاپ کو دو پوائنٹس کا نقصان ہوا۔ قریب کی کمی دماغ کے گہرے نقصان کی طرح محسوس نہیں کرتی ہے۔ ایسا محسوس ہوتا ہے۔ <em>اتنے قریب</em>، جس سے آپ دوبارہ جانا چاہتے ہیں۔ دوسرا ہے <strong>کبھی کبھار بڑی جیت</strong>. آپ کو اکثر جیتنے کی ضرورت نہیں ہے۔ ہر بار ایک بڑی، حیران کن جیت آپ کو نقصانات کے طویل سلسلے میں بٹن دبانے کے لیے کافی ہے، کیونکہ آپ کا کچھ حصہ ہمیشہ اس کے دوبارہ ہونے کا انتظار کرتا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 320\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک بار بار چلنے والا لوپ: ایک نقصان اسے واپس جیتنے کی خواہش کا باعث بنتا ہے، جس کی وجہ سے تجارت شروع ہوتی ہے، راحت کا ایک مختصر احساس، اور عام طور پر ایک بڑا نقصان، جو شروع میں واپس آتا ہے۔\">\n  <defs>\n    <marker id=\"lp\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\" markerUnits=\"strokeWidth\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8b949e\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"320\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">وہ لوپ جو آپ کو بٹن دباتا رہتا ہے۔</text>  <rect x=\"40\" y=\"60\" width=\"200\" height=\"60\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\"/>\n  <text x=\"140\" y=\"88\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">ایک نقصان</text>\n  <text x=\"140\" y=\"106\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">یہ کاٹتا ہے</text>  <rect x=\"280\" y=\"60\" width=\"200\" height=\"60\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\"/>\n  <text x=\"380\" y=\"88\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">اسے واپس جیتنے کی ترغیب دیں۔</text>\n  <text x=\"380\" y=\"106\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">\"صرف ایک اور\"</text>  <rect x=\"520\" y=\"60\" width=\"200\" height=\"60\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\"/>\n  <text x=\"620\" y=\"88\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">تجارت کریں۔</text>\n  <text x=\"620\" y=\"106\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">کارروائی خود</text>  <rect x=\"520\" y=\"200\" width=\"200\" height=\"60\" rx=\"10\" fill=\"#11161d\" stroke=\"#37b3a4\"/>\n  <text x=\"620\" y=\"228\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">مختصر ریلیف</text>\n  <text x=\"620\" y=\"246\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">ڈوپامین کی ایک ہٹ</text>  <rect x=\"40\" y=\"200\" width=\"200\" height=\"60\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\"/>\n  <text x=\"140\" y=\"228\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">عام طور پر ایک بڑا نقصان</text>\n  <text x=\"140\" y=\"246\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">اور سائیکل دوبارہ شروع ہوتا ہے</text>  <line x1=\"240\" y1=\"90\" x2=\"276\" y2=\"90\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#lp)\"/>\n  <line x1=\"480\" y1=\"90\" x2=\"516\" y2=\"90\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#lp)\"/>\n  <line x1=\"620\" y1=\"120\" x2=\"620\" y2=\"196\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#lp)\"/>\n  <line x1=\"520\" y1=\"230\" x2=\"244\" y2=\"230\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#lp)\"/>\n  <line x1=\"140\" y1=\"200\" x2=\"140\" y2=\"124\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#lp)\"/><p>  <text x=\"380\" y=\"170\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">قریب کی کمی اور کبھی کبھار بڑی جیت لوپ کو گھومتی رہتی ہے۔</text>\n  <text x=\"380\" y=\"190\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11.5\" font-family=\"sans-serif\">یہ کنٹرول کی طرح محسوس ہوتا ہے۔ یہ اس کے برعکس ہے۔</text>\n</svg></p>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">وہی لوپ ایک مسئلہ جواری چلاتا ہے۔ ریلیف حقیقی ہے، لیکن یہ کرائے پر ہے، اور کرایہ بڑھ جاتا ہے۔</figcaption>\n</figure><h2 id=\"the-honest-red-flags\">ایماندار سرخ جھنڈے</h2>\n<p>یہ اس بارے میں نہیں ہیں کہ آپ نے کتنا کھویا ہے۔ ایک شخص بہت کچھ کھو سکتا ہے اور ٹھیک ہو سکتا ہے، اور ایک شخص تھوڑا کھو سکتا ہے اور مصیبت میں پڑ سکتا ہے۔ سرخ جھنڈے آپ کے بارے میں ہیں۔ <em>رشتہ</em> ٹریڈنگ کے ساتھ. انہیں آہستہ اور نرمی سے پڑھیں۔ ان میں سے کوئی بھی آپ کو برا شخص نہیں بناتا۔</p>\n<ul>\n<li><strong>تجارت کے لیے رقم ادھار لینا۔</strong> قرض لینا، کریڈٹ کارڈ کا استعمال کرنا، یا کرائے، فیس، EMIs یا گروسری کے لیے رقم میں ڈبونا تجارت کو فنڈ دینے یا نقصان کی وصولی کے لیے۔</li>\n<li><strong>نقصانات کے بارے میں چھپانا یا جھوٹ بولنا۔</strong> اپنے خاندان، اپنے ساتھی، یا خود سے حقیقی نمبر رکھنا۔ پیغامات کو حذف کرنا، اکاؤنٹ کی کل رقم کو غلط کرنا، موضوع کو تبدیل کرنا۔</li>\n<li><strong>روکنے کے قابل نہ ہونا۔</strong> آپ واضح طور پر اور سکون سے فیصلہ کرتے ہیں کہ آپ کل تجارت نہیں کریں گے - اور کل آپ بہرحال تجارت کریں گے۔ فیصلہ کرنا اور کرنا الگ ہو گیا ہے۔</li>\n<li><strong>فرار ہونے کے لیے تجارت۔</strong> اسکرین کو اس لیے نہیں کھولنا کہ کوئی سیٹ اپ ہے، بلکہ تناؤ، بوریت، تنہائی، اضطراب یا کم مزاجی سے بچنے کے لیے۔ درد کش دوا کے طور پر تجارت کرنا۔</li>\n<li><strong>نقصانات کا پیچھا کرنا۔</strong> اسے واپس جیتنے کی مجبوری <em>ابھی</em>، ہر نقصان کے بعد سائز بڑھانا، جب آپ نیچے ہوتے ہیں تو میز چھوڑنے سے قاصر رہتے ہیں۔</li>\n<li><strong>اپنی زندگی کو نظرانداز کرنا۔</strong> نیند کھونا، کام غائب کرنا، اپنے ساتھی، اپنے بچوں، اپنے دوستوں سے دور ہونا، کیونکہ اسکرین سب سے پہلے آتی ہے۔</li>\n<li><strong>عمل کی ضرورت ہے۔</strong> جب آپ پوزیشن میں نہ ہوں تو چپٹا، چڑچڑاپن یا خالی محسوس کرنا۔ شرط کی ضرورت ہے، پیسے کی نہیں۔</li>\n</ul>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 360\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"سات سرخ جھنڈوں کی ایک چیک لسٹ، جن میں سے ہر ایک کو سرخ رنگ میں نشان زد کیا گیا ہے، ایک فوٹر کے ساتھ جس میں لکھا ہے کہ کئی کو ٹک کرنا رکنے اور مدد حاصل کرنے کا اشارہ ہے، حکمت عملی کا مسئلہ نہیں۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"360\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">سرخ جھنڈے - انہیں ایمانداری سے پڑھیں</text>  <rect x=\"30\" y=\"48\" width=\"700\" height=\"240\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/><p>  <circle cx=\"58\" cy=\"78\" r=\"5\" fill=\"#c44e52\"/><text x=\"76\" y=\"83\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">تجارت کے لیے رقم ادھار لینا - قرض، کریڈٹ کارڈ، بلوں کے لیے رقم</text>\n  <line x1=\"48\" y1=\"96\" x2=\"712\" y2=\"96\" stroke=\"#22272e\"/>\n  <circle cx=\"58\" cy=\"116\" r=\"5\" fill=\"#c44e52\"/><text x=\"76\" y=\"121\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">خاندان کے نقصانات کو چھپانا یا جھوٹ بولنا - یا اپنے آپ کو</text>\n  <line x1=\"48\" y1=\"134\" x2=\"712\" y2=\"134\" stroke=\"#22272e\"/>\n  <circle cx=\"58\" cy=\"154\" r=\"5\" fill=\"#c44e52\"/><text x=\"76\" y=\"159\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">رکنے کا فیصلہ کرنا، پھر اگلی صبح ویسے بھی تجارت کرنا</text>\n  <line x1=\"48\" y1=\"172\" x2=\"712\" y2=\"172\" stroke=\"#22272e\"/>\n  <circle cx=\"58\" cy=\"192\" r=\"5\" fill=\"#c44e52\"/><text x=\"76\" y=\"197\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">تناؤ، بوریت، تنہائی یا کم موڈ سے بچنے کے لیے تجارت</text>\n  <line x1=\"48\" y1=\"210\" x2=\"712\" y2=\"210\" stroke=\"#22272e\"/>\n  <circle cx=\"58\" cy=\"230\" r=\"5\" fill=\"#c44e52\"/><text x=\"76\" y=\"235\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">نقصانات کا پیچھا کرنا - ابھی اسے واپس جیتنے کے لیے سائز بڑھانا</text>\n  <line x1=\"48\" y1=\"248\" x2=\"712\" y2=\"248\" stroke=\"#22272e\"/>\n  <circle cx=\"58\" cy=\"268\" r=\"5\" fill=\"#c44e52\"/><text x=\"76\" y=\"273\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">اسکرین پر نیند، کام اور رشتوں کو کھونا، اور عمل کی ضرورت ہے۔</text></p>\n  <rect x=\"30\" y=\"304\" width=\"700\" height=\"44\" rx=\"10\" fill=\"#241619\" stroke=\"#c44e52\"/>\n  <text x=\"380\" y=\"331\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">ان میں سے کئی حکمت عملی کا مسئلہ نہیں ہے۔ یہ رکنے اور پہنچنے کا اشارہ ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">کوئی ایک جھنڈا تشخیص نہیں ہے۔ ان میں سے ایک جھرمٹ سننے کے قابل ایک قسم کی، واضح انتباہ ہے۔</figcaption>\n</figure><h2 id=\"a-red-flags-self-assessment\">ایک سرخ پرچم خود تشخیص</h2>\n<p>یہ باب کا مرکز ہے۔ کہیں خاموش بیٹھیں اور ایمانداری سے جواب دیں - کوئی اور نہیں پڑھ رہا ہے۔ ہر ایک پر نشان لگائیں جو پچھلے یا دو مہینوں میں درست ہوا ہے۔</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> میں نے پیسے ادھار لیے ہیں، کریڈٹ کارڈ استعمال کیا ہے، یا پیسے استعمال کیے ہیں جن کا مقصد بلوں کے لیے تجارت یا نقصان کی وصولی کے لیے ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں نے اپنے نقصانات کو چھپایا ہے، یا ان کے بارے میں جھوٹ بولا ہے، اپنے کسی قریبی سے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں نے اپنے آپ سے جھوٹ بولا ہے کہ میں واقعی کتنا نیچے ہوں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں نے روکنے یا وقفہ لینے کا فیصلہ کیا ہے، اور پھر بہرحال تجارت کی۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں تناؤ، بوریت، تنہائی، اضطراب، یا کم موڈ سے بچنے کے لیے تجارت کرتا ہوں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> ہارنے کے بعد میں اسے فوری طور پر واپس جیتنے کے لیے ایک مضبوط پل محسوس کرتا ہوں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> تجارت کی وجہ سے میری نیند، میرا کام، یا میرے تعلقات متاثر ہوئے ہیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> جب میں تجارت میں نہیں ہوں تو میں بے چین، چڑچڑا یا خالی محسوس کرتا ہوں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں نے پہلے بھی کاٹنے کی کوشش کی ہے اور نہیں کر سکا۔</li>\n</ul>\n<p>اگر آپ نے ایک پر نشان لگایا ہے تو اسے قریب سے دیکھیں۔ اگر آپ نے ٹک کیا۔ <strong>کئی</strong>براہ کرم اسے سنجیدگی سے لیں۔ ایماندارانہ اقدام کوئی بہتر حکمت عملی یا چھوٹی پوزیشن نہیں ہے۔ یہ ایک مکمل وقفہ لینا اور کسی سے رابطہ کرنا ہے۔ یہ زیادہ رد عمل نہیں ہے۔ یہ بالکل صحیح جواب ہے جو یہ جوابات آپ کو بتا رہے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>اگر تجارت آپ کو کنٹرول کر رہی ہے، تو جواب یہ ہے کہ کبھی زیادہ تجارت نہ کریں۔ اقدام مکمل طور پر روکنا ہے، کسی ایسے شخص کو بتائیں جس پر آپ اعتماد کرتے ہیں، اور مدد حاصل کریں۔ رویے کا مسئلہ بہتر سیٹ اپ سے حل نہیں ہوتا۔</p>\n</div></div>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>یہاں سب سے خطرناک غلطی رویے کے مسئلے کو حکمت عملی کے مسئلے کے طور پر سمجھنا ہے۔ آپ ایک اور کورس خریدیں، اشارے بدلیں، نیا نظام آزمائیں، مزید نظم و ضبط کا وعدہ کریں۔ یہ سب آپ کو اسکرین پر رکھتا ہے، جہاں مسئلہ رہتا ہے۔ اگر سرخ جھنڈے درست ہیں، تو درستگی چارٹ کے اندر نہیں ہے۔ اپنی پوزیشن کا سائز کم کرنا بھی کافی نہیں ہے۔ پیٹرن رسائی پر فیڈ کرتا ہے، لہذا جواب ایک مکمل وقفہ ہے، چھوٹی شرط نہیں.</p>\n</div></div>\n<h2 id=\"what-actually-helps\">اصل میں کیا مدد کرتا ہے۔</h2>\n<p>اگر یہ آپ ہیں، تو یہاں ایماندار راستہ ہے۔ اس میں سے کوئی بھی قوت ارادی کے بارے میں نہیں ہے، کیونکہ قوت ارادی وہ آلہ نہیں ہے جو اس کے لیے کام کرے۔</p>\n<p><strong>مکمل طور پر رکیں، جزوی طور پر نہیں۔</strong> طرز عمل کا نمونہ \"میں چھوٹی تجارت کروں گا\" کا جواب نہیں دیتا ہے۔ یہ صاف وقفے کا جواب دیتا ہے۔ ایک حقیقی وقت کے لیے مکمل طور پر دور ہٹ جائیں - ہفتے، ایک دوپہر نہیں۔</p>\n<p><strong>کسی کو بتائیں جس پر آپ اعتماد کرتے ہیں۔</strong> اپنے ساتھی، دوست، یا خاندان کے کسی رکن کو بلند آواز میں صحیح نمبر بتائیں۔ رازداری ایندھن ہے؛ ایمانداری اس پر پانی ہے. یہ واحد گفتگو اکثر سب سے مشکل اور طاقتور قدم ہوتا ہے۔</p>\n<p><strong>پیشہ ورانہ مدد حاصل کریں۔</strong> یہ ایک تسلیم شدہ، قابل علاج نمونہ ہے، اور لوگوں کو اس میں مدد کے لیے تربیت دی جاتی ہے۔ ایک مشیر یا ماہر نفسیات، آپ کا ڈاکٹر، یا ہیلپ لائن سب اچھی پہلی کال ہیں۔ ہندوستان میں، حکومت کی KIRAN ذہنی صحت کی ہیلپ لائن (1800-599-0019) مفت، خفیہ ہے اور دن رات چلتی ہے۔ براہ کرم اپنے علاقے میں موجودہ نمبر اور قریبی مشاورتی خدمات دیکھیں۔ مسئلہ جوا سپورٹ یہاں براہ راست لاگو ہوتا ہے، کیونکہ طریقہ کار ایک جیسا ہے۔</p>\n<p><strong>اپنی رسائی کو ہٹا دیں۔</strong> یہ شکست نہیں ہے - یہ سب سے مضبوط چالوں میں سے ایک ہے جو آپ کر سکتے ہیں۔ ٹریڈنگ اکاؤنٹ کو بند کرنا، اپنے بروکر سے اسے محدود کرنے کے لیے کہنا، ایپ کو ہٹانا، لاگ ان کو کسی بھروسہ مند شخص کے حوالے کرنا، یا اپنی رقم ایسی جگہ ڈالنا جہاں آپ ایک کلک میں نہیں پہنچ سکتے۔ آپ جس عمل کو روکنے کی کوشش کر رہے ہیں اسے کرنا مشکل ہے۔</p>\n<p>اس کے ساتھ مدد مانگنے میں آپ کی کسی بھی تجارت سے زیادہ ہمت درکار ہوتی ہے۔ یہ کمزوری نہیں ہے۔ یہ آپ کے لیے دستیاب سب سے بہادر اور ہوشیار فیصلہ ہے۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>واحد چیز جو یہاں اکثر ناکام ہوتی ہے وہ صرف قوتِ ارادی پر انحصار کرنا ہے۔ \"میں صرف اپنے آپ پر قابو رکھوں گا\" وہ منصوبہ ہے جو پہلے ہی ناکام ہو چکا ہے جب بھی آپ نے باکس پر نشان لگایا جس میں کہا گیا تھا کہ آپ نے رکنے کا فیصلہ کیا اور بہرحال تجارت کی۔ ایک زبردستی پیٹرن کا پورا نکتہ یہ ہے کہ یہ اچھے ارادوں کو زیر کرتا ہے۔ یہ آپ کے کردار میں کوئی خامی نہیں ہے - یہ اس طرح ہے کہ پیٹرن کیسے کام کرتا ہے، اور یہی وجہ ہے کہ رسائی کو ہٹانا اور حقیقی مدد حاصل کرنا سخت کوشش کو شکست دیتا ہے۔</p>\n<p>چھپ کر کرنا بھی ناکام ہو جاتا ہے۔ جب تک نقصانات پوشیدہ رہتے ہیں، شرم آپ کو الگ تھلگ رکھتی ہے اور لوپ موڑتا رہتا ہے۔ پیٹرن خاموشی پر زندہ رہتا ہے، لہذا علاج ایک ایماندار گفتگو کے ساتھ شروع ہوتا ہے.</p>\n<p>اور خاموشی سے رکنے کے بجائے \"سرمایہ کاری\" یا سینڈ باکس ٹریڈنگ (Analyzer mode in OpenAlgo) کی طرف جانا بھی ناکام ہو سکتا ہے، اگر اصل ضرورت بازاروں کے بجائے کارروائی کی تھی۔ اگر آپ شرط لگائے بغیر خاموش نہیں بیٹھ سکتے تو یہ چیز کسی پیشہ ور کے پاس لانے کی ہے، اکیلے انتظام کرنے کی نہیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>اگر آپ نے یہ دور پڑھا ہے اور اپنے آپ کو پہچان لیا ہے تو ایک سانس لیں۔ یہ عام ہے، یہ شرمناک نہیں ہے، اور یہ مدد سے بہتر ہو جاتا ہے۔ کسی ایسے شخص سے رابطہ کرنا - جس پر آپ بھروسہ کرتے ہیں، یا کسی مشیر یا ہیلپ لائن تک - ایک تاجر یا ایک شخص کے طور پر آپ کا انجام نہیں ہے۔ یہ ایک طویل عرصے میں پہلا حقیقی طور پر مضبوط اقدام ہے۔ آپ کو رکنے کی اجازت ہے، اور آپ کو مدد مانگنے کی اجازت ہے۔</p>\n</div></div>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> عام فعال تجارت کو مجبوری کے مسئلے سے کیا الگ کرتا ہے؟</summary><p>یہ ضائع ہونے والی رقم نہیں ہے۔ یہ تجارت کے ساتھ آپ کا رشتہ ہے - چاہے آپ فیصلہ کرتے وقت روک سکتے ہیں، چاہے آپ جذبات سے بچنے کے لیے تجارت کرتے ہیں، اور آیا یہ آپ کے پیسے، نیند اور رشتوں کو نقصان پہنچا رہا ہے۔ سرخ جھنڈے پیٹرن کے بارے میں ہیں، نقصان کے سائز کے نہیں۔</p>\n</details><details>\n<summary><strong>2.</strong> کبھی کبھار بڑی جیت کسی کو نقصانات کے طویل سلسلے میں کیوں جھکائے رکھتی ہے؟</summary><p>کیونکہ دماغ غیر متوقع انعامات سے چلتا ہے، مستحکم نہیں۔ ایک نایاب، حیران کن جیت - نیز قریب کی مس جو \"بہت قریب\" کی طرح محسوس ہوتی ہے - آپ کو نیچے ہوتے وقت بٹن دباتے رہنے کے لیے کافی ہے، ہمیشہ اگلے کا انتظار کرنا۔ یہ ایک سلاٹ مشین کے طور پر ایک ہی طریقہ کار ہے.</p>\n</details><details>\n<summary><strong>3.</strong> اگر کئی سرخ جھنڈے درست ہیں تو بہتر حکمت عملی یا چھوٹی پوزیشن غلط جواب کیوں ہے؟</summary><p>کیونکہ مسئلہ طرز عمل کا ہے، تکنیکی نہیں۔ ایک نیا سسٹم یا اس سے چھوٹا سائز آپ کو اسکرین پر رکھتا ہے، جہاں پیٹرن رہتا ہے۔ صحیح جواب ایک مکمل وقفہ ہے، کسی کو بتانا جس پر آپ بھروسہ کرتے ہیں، اور پیشہ ورانہ مدد - دوسرا سیٹ اپ نہیں۔</p>\n</details><details>\n<summary><strong>4.</strong> آپ کی اپنی رسائی کو ہٹانا - اکاؤنٹ کو بند کرنا یا محدود کرنا - کو شکست کے بجائے طاقت کیوں سمجھا جاتا ہے؟</summary><p>کیونکہ پیٹرن آسان رسائی پر مشتمل ہے، اور صرف قوت ارادی اس کے خلاف پہلے ہی ناکام ہو چکی ہے۔ عمل کو حقیقی طور پر مشکل بنانا - اکاؤنٹ کو بند کرنا، ایپ کو ہٹانا، لاگ ان کے حوالے کرنا - ایک صاف نظر والا، طاقتور اقدام ہے جو وہاں کام کرتا ہے جہاں \"میں اپنے آپ کو کنٹرول کروں گا\" نہیں کرتا۔</p>\n</details><details>\n<summary><strong>5.</strong> کوئی اپنے میں پیٹرن کو پہچانتا ہے اور شرم محسوس کرتا ہے۔ یاد رکھنے والی ایماندار، مہربان چیز کیا ہے؟</summary><p>کہ یہ ایک معروف، عام اور قابل علاج نمونہ ہے، جس طرح مسئلہ جوئے کی طرح وائرڈ ہے - کردار کی خرابی نہیں۔ کسی قابل اعتماد شخص، کسی مشیر یا ہیلپ لائن تک پہنچنا طاقت کی علامت ہے، کمزوری نہیں، اور یہ کنٹرول کی طرف واپسی کا پہلا حقیقی قدم ہے۔</p>\n</details>\n","toc":[{"level":2,"text":"جب عادت بن جاتی ہے۔","id":"when-a-habit-becomes-a-hook"},{"level":2,"text":"وہ لوپ جو آپ کو جوڑتا ہے۔","id":"the-loop-that-hooks-you"},{"level":2,"text":"ایماندار سرخ جھنڈے","id":"the-honest-red-flags"},{"level":2,"text":"ایک سرخ پرچم خود تشخیص","id":"a-red-flags-self-assessment"},{"level":2,"text":"اصل میں کیا مدد کرتا ہے۔","id":"what-actually-helps"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"8":{"html":"<p>مرکزی بجٹ سے ایک سال پہلے، میرا گھبراہٹ کا شکار تھی۔ اس کے پاس تقریباً 5,00,000 روپے مالیت کے اسٹاک کا پورٹ فولیو تھا اور وہ بجٹ کے دن تیزی سے گرنے کے بارے میں سوچ بھی نہیں سکتی تھی۔ اس لیے اس نے تقریباً 4,000 روپے میں ایک انڈیکس پٹ آپشن خریدا - ایک ایسا معاہدہ جس کی قیمت بڑھے گی اگر مارکیٹ گرتی ہے۔ بجٹ کا دن آیا، مارکیٹ بمشکل حرکت میں آئی، اور چند ہفتوں بعد اس کی ڈالی ہوئی میعاد ختم ہوگئی۔ وہ 4000 روپے \"کھو چکی\" تھی۔ لیکن وہ دو ہفتوں تک اچھی طرح سے سوئی تھی، اور تحفظ ہر وقت حقیقی تھا - اسے کبھی بھی اسے استعمال نہیں کرنا پڑا۔ وہ 4000 روپے کوئی بری تجارت نہیں تھی۔ یہ انشورنس پریمیم تھا۔</p>\n<p>یہ باب ہیجنگ ماڈیول کو کھولتا ہے۔ اس سے پہلے کہ ہم اس بارے میں بات کریں کہ کب ہیج کرنا ہے، کب نہیں، اس کی قیمت کیا ہے اور کون سے اوزار استعمال کرنے ہیں، آپ کو ایماندار ذہنی ماڈل کی ضرورت ہے۔ ہیجنگ کے بارے میں تقریباً ہر ابتدائی غلطی اس ایک خیال کو غلط کرنے سے ہوتی ہے۔</p>\n<h2 id=\"a-hedge-is-insurance-not-a-magic-shield\">ہیج انشورنس ہے، جادو کی ڈھال نہیں۔</h2>\n<p>ایک ہیج ایک دوسری پوزیشن ہے جو آپ پہلے سے موجود پوزیشن کے خطرے کو کم کرنے کے لیے لیتے ہیں۔ اگر آپ کے پاس اسٹاک ہے اور آپ گرنے سے ڈرتے ہیں، تو آپ ایسی چیز شامل کرتے ہیں جو مارکیٹ گرنے پر آپ کو ادائیگی کرتی ہے۔ دونوں پوزیشنیں ایک دوسرے کے خلاف دھکیلتی ہیں، لہذا ایک بری حرکت آپ کو کم تکلیف دیتی ہے۔</p>\n<p>یہ ہے وہ حصہ جو ابتدائی طور پر چھوڑتا ہے: وہ تحفظ کبھی بھی مفت نہیں ہوتا، اور یہ کبھی بھی منافع کی ضمانت نہیں دیتا۔ ایک ہیج <strong>لاگت کے لیے ایک خطرے کی تجارت کرتا ہے۔</strong>. آپ کچھ چھوڑ دیتے ہیں - ایک پریمیم، ایک اسپریڈ، آپ کا کچھ الٹا - ایک چھوٹے منفی پہلو کے بدلے میں۔ یہ بالکل ایسا ہی ہے جیسے آپ کی گاڑی کا بیمہ کروانا۔ آپ ہر سال ادائیگی کرتے ہیں، آپ امید کرتے ہیں کہ آپ کو اس کی ضرورت نہیں ہوگی، اور پریمیم صرف رات کو سونے کی قیمت ہے۔</p>\n<p>تو ایک ہیج ایک ساتھ دو کام کرتا ہے۔ یہ آپ کے نقصانات کے نیچے ایک منزل رکھتا ہے۔ اور یہ بھی، تقریباً ہمیشہ، آپ کی حد کو کم کرتا ہے - آپ تحفظ کے لیے ادائیگی کرتے ہیں، اس لیے آپ کا بہترین معاملہ قدرے خراب ہو جاتا ہے۔ آپ کسی بھی چیز کے لئے منفی پہلو کو محدود نہیں کر سکتے ہیں۔ دوسری طرف سے کوئی وہ خطرہ مول لے رہا ہے جو آپ دے رہے ہیں، اور وہ ادا کرنا چاہتے ہیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 330\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"نفع اور نقصان کا خاکہ۔ غیر ہیجڈ پوزیشن ایک سیدھی ترچھی لکیر ہے جس کے بائیں جانب لامحدود نقصان ہے۔ ہیجڈ پوزیشن میں ایک فلیٹ فلور ہے جو بائیں طرف نقصان کو کوپ کرتا ہے، اور دائیں طرف اٹھتا ہے لیکن غیر ہیجڈ لائن کے نیچے بیٹھتا ہے، کم اوپر کی طرف دکھاتا ہے۔\">\n  <defs>\n    <marker id=\"hx\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\" markerUnits=\"strokeWidth\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8b949e\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"330\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"28\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">تنہا پوزیشن بمقابلہ پوزیشن پلس ہیج</text>  <line x1=\"120\" y1=\"60\" x2=\"120\" y2=\"285\" stroke=\"#8b949e\" stroke-width=\"1.5\"/>\n  <line x1=\"120\" y1=\"180\" x2=\"710\" y2=\"180\" stroke=\"#8b949e\" stroke-width=\"1.5\"/>\n  <text x=\"112\" y=\"74\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">منافع</text>\n  <text x=\"112\" y=\"278\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">نقصان</text>\n  <text x=\"700\" y=\"198\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">قیمت میں اضافہ →</text>  <line x1=\"120\" y1=\"258\" x2=\"700\" y2=\"92\" stroke=\"#4c72b0\" stroke-width=\"2.5\" stroke-dasharray=\"6 5\"/>\n  <path d=\"M120,212 L372,212 L700,118\" fill=\"none\" stroke=\"#55a868\" stroke-width=\"3\"/>  <line x1=\"372\" y1=\"180\" x2=\"372\" y2=\"212\" stroke=\"#8b949e\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>  <rect x=\"150\" y=\"222\" width=\"180\" height=\"22\" rx=\"6\" fill=\"#11161d\" stroke=\"#55a868\"/>\n  <text x=\"240\" y=\"237\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">محدود نقصان: فرش</text>  <line x1=\"560\" y1=\"104\" x2=\"560\" y2=\"132\" stroke=\"#dd8452\" stroke-width=\"1.5\" marker-end=\"url(#hx)\"/>\n  <line x1=\"560\" y1=\"132\" x2=\"560\" y2=\"104\" stroke=\"#dd8452\" stroke-width=\"1.5\" marker-end=\"url(#hx)\"/>\n  <rect x=\"500\" y=\"252\" width=\"200\" height=\"22\" rx=\"6\" fill=\"#11161d\" stroke=\"#dd8452\"/>\n  <text x=\"600\" y=\"267\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">فرق آپ کی قیمت ہے۔</text>  <rect x=\"430\" y=\"300\" width=\"20\" height=\"12\" rx=\"2\" fill=\"none\" stroke=\"#4c72b0\" stroke-width=\"2.5\" stroke-dasharray=\"6 5\"/>\n  <text x=\"456\" y=\"310\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">تنہا پوزیشن</text>\n  <rect x=\"580\" y=\"300\" width=\"20\" height=\"12\" rx=\"2\" fill=\"none\" stroke=\"#55a868\" stroke-width=\"3\"/>\n  <text x=\"606\" y=\"310\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">پوزیشن + ہیج</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ہیج بدترین کیس کو فرش میں چپٹا کرتا ہے - لیکن پوری گرین لائن تھوڑی نیچے بیٹھتی ہے۔ یہ فرق وہی ہے جو آپ ادا کرتے ہیں۔</figcaption>\n</figure>\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک ہیج لاگت کو قبول کرکے ایک خطرے کو کم کرتا ہے۔ یہ ایک پریمیم کے ساتھ انشورنس ہے - مفت تحفظ نہیں، اور ضمانت شدہ رقم کمانے کا طریقہ نہیں ہے۔ یہ آپ کے منفی پہلو کو ڈھانپتا ہے، اور بدلے میں یہ عام طور پر آپ کے اوپری حصے کو ٹوپی یا مونڈ دیتا ہے۔</p>\n</div></div>\n<h2 id=\"what-you-pay-for-peace-of-mind\">جو آپ ذہنی سکون کے لیے ادا کرتے ہیں۔</h2>\n<p>ہیج کی قیمت ہمیشہ واضح نہیں ہوتی، کیونکہ یہ ہمیشہ فیس کی طرح نہیں لگتی۔ یہ تین شکلوں میں آتا ہے۔ کبھی کبھی یہ ایک ہوتا ہے۔ <strong>پریمیم</strong> - وہ روپے جو آپ آپشن خریدنے کے لیے دیتے ہیں، جیسے میرا کے 4,000 روپے۔ کبھی کبھی ایسا ہوتا ہے۔ <strong>پھیلاؤ اور چارجز</strong> - ہر بار جب آپ داخل ہوتے ہیں اور باہر جاتے ہیں تو خرید و فروخت کی قیمتوں کے علاوہ بروکریج، ایکسچینج فیس اور ٹیکس کے درمیان فرق۔ اور کبھی کبھی ایسا ہوتا ہے۔ <strong>دیا ہوا الٹا</strong> - وہ فوائد جو آپ ضائع کرتے ہیں کیونکہ جب آپ کی اہم پوزیشن جیت رہی ہوتی ہے تو آپ کا ہیج آپ کے خلاف ہوتا ہے۔</p>\n<p>وہ آخری ڈرپوک قیمت ہے۔ اگر آپ کسی پورٹ فولیو کو ہیج کرتے ہیں اور مارکیٹ پھر بڑھ جاتی ہے، تو آپ کا ہیج پیسہ کھو دیتا ہے حالانکہ آپ کے اسٹاک نے اچھا کام کیا تھا۔ آپ اب بھی مجموعی طور پر آگے ہیں، اس سے کم آگے اگر آپ نے کچھ نہیں کیا ہوتا۔ ایک ہیج آپ کو صرف اس وقت خرچ نہیں کرتا جب آپ اس کے بارے میں غلط ہوتے ہیں۔ جب آپ مارکیٹ کے بارے میں صحیح ہیں تو یہ خاموشی سے آپ کو مہنگا پڑ سکتا ہے۔</p>\n<p>ہیج کو دیکھنے کا ایماندار طریقہ سیدھا تبادلہ ہے۔ تم تھوڑا چھوڑ دو۔ آپ کو دماغی سکون اور ایک معروف ترین صورت حال ملے گی۔ آیا یہ تبادلہ قابل قدر ہے یا نہیں اس کا انحصار پوری طرح سے صورتحال پر ہے - جس کے بارے میں اگلے چند ابواب ہیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 270\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"دو پینلز کے ساتھ ایک تجارتی بند خاکہ۔ بائیں پینل میں آپ جو کچھ چھوڑ دیتے ہیں اس کی فہرست دیتا ہے: ایک پریمیم، اسپریڈز اور چارجز، اور کچھ اوپر۔ دائیں پینل میں آپ کو جو کچھ ملتا ہے اس کی فہرست دی جاتی ہے: نقصانات کے نیچے ایک منزل، ایک معلوم بدترین صورت، اور پکڑنے کے لیے پرسکون۔ ان کے درمیان ایک تیر کا تبادلہ ظاہر ہوتا ہے۔\">\n  <defs>\n    <marker id=\"hy\" markerWidth=\"10\" markerHeight=\"10\" refX=\"7\" refY=\"3\" orient=\"auto\" markerUnits=\"strokeWidth\">\n      <path d=\"M0,0 L7,3 L0,6 Z\" fill=\"#8b949e\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"270\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"28\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ایک ہیج ایک تبادلہ ہے، ایک مفت ڈھال نہیں</text>  <rect x=\"30\" y=\"50\" width=\"300\" height=\"200\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\"/>\n  <rect x=\"30\" y=\"50\" width=\"300\" height=\"36\" rx=\"10\" fill=\"#241c14\" stroke=\"#dd8452\"/>\n  <text x=\"180\" y=\"74\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">جو آپ ترک کر دیتے ہیں۔</text>\n  <circle cx=\"52\" cy=\"116\" r=\"4\" fill=\"#dd8452\"/><text x=\"66\" y=\"121\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">ایک پریمیم (اختیاری قیمت)</text>\n  <circle cx=\"52\" cy=\"156\" r=\"4\" fill=\"#dd8452\"/><text x=\"66\" y=\"161\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">اسپریڈز، بروکریج، ٹیکس</text>\n  <circle cx=\"52\" cy=\"196\" r=\"4\" fill=\"#dd8452\"/><text x=\"66\" y=\"201\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">آپ کے کچھ الٹا</text>  <line x1=\"345\" y1=\"150\" x2=\"415\" y2=\"150\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#hy)\"/>  <rect x=\"430\" y=\"50\" width=\"300\" height=\"200\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\"/>\n  <rect x=\"430\" y=\"50\" width=\"300\" height=\"36\" rx=\"10\" fill=\"#16241b\" stroke=\"#55a868\"/>\n  <text x=\"580\" y=\"74\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">جو آپ کو واپس ملتا ہے۔</text>\n  <circle cx=\"452\" cy=\"116\" r=\"4\" fill=\"#55a868\"/><text x=\"466\" y=\"121\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">آپ کے نقصانات کے نیچے ایک منزل</text>\n  <circle cx=\"452\" cy=\"156\" r=\"4\" fill=\"#55a868\"/><text x=\"466\" y=\"161\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">ایک معروف، فکسڈ بدترین کیس</text>\n  <circle cx=\"452\" cy=\"196\" r=\"4\" fill=\"#55a868\"/><text x=\"466\" y=\"201\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">پکڑنے اور سوچنے کا سکون</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">اگر بائیں جانب آپ کے لیے دائیں جانب سے زیادہ قابل قدر ہے تو ہیج نہ کریں۔ زیادہ تر وقت، یہ ہے.</figcaption>\n</figure><h2 id=\"what-a-hedge-can-and-cannot-do\">ایک ہیج کیا کر سکتا ہے اور کیا نہیں کر سکتا</h2>\n<p>تحفظ خریدنے سے پہلے اس میز کو اپنے سر میں رکھیں۔ تمام ہیجنگ مایوسی کا نصف دائیں ہاتھ کے کالم کی توقع سے آتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ایک ہیج CAN</th>\n<th>ایک ہیج CANNOT</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ایک متعین مدت کے دوران معلوم نقصان کو کیپ کریں۔</td>\n<td>بری پوزیشن کو اچھی میں بدل دیں۔</td>\n</tr>\n<tr>\n<td>آپ کو ایک فکسڈ، معلوم بدترین کیس دیں۔</td>\n<td>مفت میں ہمیشہ کے لیے آپ کی حفاظت کریں۔</td>\n</tr>\n<tr>\n<td>فیصلہ کرنے کے لئے اپنا وقت اور پرسکون خریدیں۔</td>\n<td>آپ کو منافع کی ضمانت دیں۔</td>\n</tr>\n<tr>\n<td>ایک مخصوص، شناخت شدہ خطرے کو کم کریں۔</td>\n<td>ایک ہی وقت میں ہر خطرے کو دور کریں۔</td>\n</tr>\n<tr>\n<td>آپ کو ایک ایونٹ کے ذریعے منعقد کرنے دیں آپ دوسری صورت میں گھبراہٹ میں فروخت کریں گے</td>\n<td>خود کے لئے ادائیگی کریں - اس کی ہمیشہ جاری لاگت ہوتی ہے۔</td>\n</tr>\n</tbody></table>\n<p>دائیں کالم کو دوبارہ پڑھیں۔ ہیج ایسی پوزیشن کو نہیں بچائے گا جسے آپ کو صرف بند کرنا چاہئے۔ یہ آپ کو بار بار ادائیگی کیے بغیر سال بہ سال آپ کی حفاظت نہیں کرے گا۔ اور یہ آپ کو کبھی بھی مفت پیسے نہیں دے گا۔ اگر کوئی ہیج کبھی گارنٹی شدہ منافع کی طرح لگتا ہے، تو آپ نے اسے غلط پڑھا ہے - قیمت ایسی جگہ چھپی ہوئی ہے جسے آپ نے ابھی تک نہیں دیکھا۔</p>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>کلاسک ابتدائی غلطی یہ ہے کہ ہیج مفت میں ہو، یا خود پیسہ کمایا جائے۔ دو ورژن: تحفظ خریدنا اور پھر اس کی میعاد ختم ہونے پر دھوکہ دہی کا احساس کرنا (یعنی بیمہ کام کرنا ہے، ناکام نہیں ہونا - آپ نے کار کو کریش نہیں کیا)، اور ہیج کو منافع کے مرکز کے طور پر پیش کرنا، اس سے \"کمانے\" کی امید میں شامل کرنا۔ ہیج ایک قیمت ہے جسے آپ خطرے کو کم کرنے کے لیے ادا کرتے ہیں۔ اگر آپ چاہتے ہیں کہ یہ پیسہ کمائے، تو آپ نے ہیج نہیں کیا ہے - آپ نے ابھی دوسری شرط کھولی ہے۔</p>\n</div></div>\n<h2 id=\"who-hedges-what\">کون کس چیز کی حفاظت کرتا ہے۔</h2>\n<p>ہیجنگ ایک سرگرمی نہیں ہے۔ مختلف شرکاء کو مختلف خطرات کا سامنا کرنا پڑتا ہے، اس لیے وہ مختلف چیزوں کی حفاظت کرتے ہیں اور مختلف اخراجات قبول کرتے ہیں۔ یہ آگے کے ماڈیول کا نقشہ ہے، کاپی کرنے کا مشورہ نہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>جو وہ عام طور پر ہیج کرتے ہیں۔</th>\n<th>ایک عام ٹول</th>\n<th>قیمت وہ قبول کرتے ہیں۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>کسی معروف واقعہ سے پہلے ایک بڑا پورٹ فولیو، یا گہری حادثے کی پریشانی</td>\n<td>ایک انڈیکس ڈالنا، یا اسٹاک کو کیش میں تراشنا</td>\n<td>اگر کوئی زوال نہیں آتا ہے تو پریمیم، یا منافع چھوڑ دیا جاتا ہے۔</td>\n</tr>\n<tr>\n<td>اسٹاک / انٹرا ڈے ٹریڈر</td>\n<td>ایک واحد مرتکز یا رات بھر کی پوزیشن</td>\n<td>چھوٹا سائز، ایک سٹاپ نقصان، یا ایک مختصر انڈیکس ہیج</td>\n<td>پھیلاؤ اور چارجز؛ کچھ الٹا بند</td>\n</tr>\n<tr>\n<td>F&amp;O (فیوچر) تاجر</td>\n<td>لیوریجڈ پوزیشن پر دشاتمک خطرہ</td>\n<td>ایک آفسیٹنگ مستقبل یا آپشن ٹانگ</td>\n<td>مارجن باندھا گیا، پریمیم، کم منافع</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>ایک مختصر آپشن کے خلاف نایاب، پرتشدد اقدام</td>\n<td>اسپریڈ بنانے کے لیے مزید آپشن خریدنا</td>\n<td>ان کے جمع کردہ پریمیم کا حصہ</td>\n</tr>\n</tbody></table>\n<p>نوٹ کریں کہ سرمایہ کار کے لیے، \"کچھ نہ کریں\" یا \"تھوڑا سا تراشیں\" اکثر سب سے سستا ہیج ہوتا ہے۔ فینسی ٹول بہترین نہیں ہے۔ ہم اس پر واپس آتے رہیں گے۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>انشورنس ماڈل ایماندار ہے، لیکن اس کی بلند آواز سے کہنے کی حدود ہیں۔</p>\n<p>ایک ہیج آپ کو اس وقت ناکام بناتا ہے جب لاگت اس خطرے سے زیادہ ہوتی ہے جو اسے ہٹاتا ہے۔ 20,000 روپے کے چھوٹے پورٹ فولیو پر تحفظ، یا اس کے قریب کوئی واقعہ نہ ہونے والی پرسکون پوزیشن پر، پریمیم اور چارجز میں اس سے زیادہ لاگت آسکتی ہے جس سے آپ ممکنہ طور پر کھو سکتے ہیں۔ آپ اپنے آپ کو غریب خرید انشورنس خرچ کر سکتے ہیں جس کی آپ کو کبھی ضرورت نہیں تھی۔</p>\n<p>یہ ناکام ہوجاتا ہے جب ہیج اصل میں خطرے سے میل نہیں کھاتا ہے۔ اگر آپ کے پاس چھوٹے مڈ کیپ اسٹاکس کی ایک ٹوکری ہے اور بڑے کیپ انڈیکس کے ساتھ ہیج کرتے ہیں، تو دونوں الگ ہوسکتے ہیں - آپ کے اسٹاک گر جاتے ہیں جب کہ آپ کا ہیج بمشکل بجھتا ہے۔ اس مماثلت، جسے بنیاد خطرہ کہا جاتا ہے، کا مطلب ہے کہ ہیج آپ کو بالکل اسی وقت بے نقاب چھوڑ سکتا ہے جب آپ کو ضرورت ہو۔ بعد کے ایک باب میں اس کا تفصیل سے احاطہ کیا گیا ہے۔</p>\n<p>یہ ناکام ہوجاتا ہے جب آپ خالص خوف سے ہیج کرتے ہیں، بار بار۔ ہر ہلچل کو ہیج کرنا ایک مستحکم پورٹ فولیو کو پریمیم کے سست رساو میں بدل دیتا ہے۔ لاگت ہر بار چھوٹی ہوتی ہے اور ایک سال سے زیادہ خراب ہوتی ہے۔</p>\n<p>اور یہ اس وقت ناکام ہو جاتا ہے جب ایک ہیج ایسی پوزیشن پر فائز ہونے کا بہانہ بن جاتا ہے جسے آپ کو بند کرنا چاہیے۔ جلتے ہوئے گھر کی بیمہ کوئی منصوبہ نہیں ہے۔ بعض اوقات صحیح اقدام خطرے سے بچانا نہیں ہوتا بلکہ اسے کاٹنا ہوتا ہے - بیچنا، نقصان اٹھانا، اور چلے جانا۔ فرق جاننا پوری مہارت ہے، اور یہ وہ جگہ ہے جہاں یہ ماڈیول جا رہا ہے۔</p>\n<p>یہ باب تعلیم ہے، سرمایہ کاری کا مشورہ نہیں۔ یہاں کوئی بھی چیز کسی خاص ہیج کو خریدنے یا بیچنے کی سفارش نہیں ہے - یہ وہ ذہنی ماڈل ہے جس کی آپ کو کچھ بھی فیصلہ کرنے سے پہلے درکار ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>اس سے ماڈیول B کھلتا ہے۔ اگلا ہم اس وقت احاطہ کرتے ہیں جب ہیجنگ حقیقی طور پر اپنی لاگت حاصل کرتی ہے (ایونٹ سے پہلے ایک بڑی کتاب، توجہ مرکوز یا راتوں رات نمائش)، جب یہ حد سے زیادہ ہو اور آپ اسے چھوڑ دیں، تحفظ کا مکمل قیمت ٹیگ، اور آسان ٹولز - حفاظتی پوٹس، کالر، انڈیکس ہیجز اور صرف سادہ نقد۔ ان سب میں ایک خیال رکھیں: ہیج انشورنس ہے، پریمیم کے ساتھ۔</p>\n</div></div>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> ایک جملے میں، ایک ہیج اصل میں کیا کرتا ہے؟</summary><p>یہ لاگت کو قبول کر کے ایک مخصوص خطرے کو کم کرتا ہے - ایک پریمیم، ایک اسپریڈ، یا کچھ دیا ہوا الٹا۔ یہ انشورنس ہے، مفت تحفظ نہیں اور منافع کی ضمانت نہیں ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> میرا کا انڈیکس ختم ہو گیا اور وہ 4000 روپے سے محروم ہو گئی۔ کیا اس کا ہیج ناکام ہوگیا؟</summary><p>نہیں، یہ انشورنس ہے جیسا کہ ڈیزائن کیا گیا ہے - اس نے تحفظ کے لیے ایک پریمیم ادا کیا جس کی اسے ضرورت نہیں تھی، جیسے کہ بغیر کسی حادثے کے ایک سال پر کار انشورنس۔ تحفظ پورے وقت حقیقی تھا؛ اسے کبھی بھی دعویٰ نہیں کرنا پڑا۔</p>\n</details><details>\n<summary><strong>3.</strong> ہیج عام طور پر آپ کے اوپری حصے کو کیوں کم کرتا ہے، نہ صرف آپ کا منفی پہلو؟</summary><p>کیونکہ آپ اس کی ادائیگی کرتے ہیں۔ پریمیم، اسپریڈ یا آف سیٹنگ پوزیشن پر آپ کو کچھ لاگت آتی ہے، اس لیے آپ کا بہترین کیس تھوڑا خراب ہو جاتا ہے - اور اگر مارکیٹ بڑھ جاتی ہے، تو ہیج خود پیسے کھو دیتا ہے یہاں تک کہ آپ کی اہم پوزیشن جیت جاتی ہے۔</p>\n</details><details>\n<summary><strong>4.</strong> دو چیزوں کے نام بتائیں جو ہیج نہیں کر سکتا۔</summary><p>یہ بری پوزیشن کو اچھی میں نہیں بدل سکتا، اور یہ آپ کو ہمیشہ کے لیے مفت میں محفوظ نہیں رکھ سکتا۔ یہ منافع کی ضمانت بھی نہیں دے سکتا - اگر ایک ہیج مفت رقم کی طرح لگتا ہے، تو آپ نے قیمت گنوا دی ہے۔</p>\n</details><details>\n<summary><strong>5.</strong> ہیج غلط ٹول کب ہے، اور اس کے بجائے آپ کو کیا کرنا چاہیے؟</summary><p>جب تحفظ کی لاگت اس خطرے سے زیادہ ہوتی ہے جو اسے ہٹاتا ہے، یا جب پوزیشن ایک ہو تو آپ کو بس بند کرنا چاہیے۔ ان صورتوں میں بہتر اقدام خطرے کو کم کرنا ہے - سائز کو کم کرنا یا بیچنا - بجائے اس کے کہ ایسی پوزیشن کو بیمہ کرو جس پر آپ کو فائز نہیں ہونا چاہئے۔</p>\n</details>\n","toc":[{"level":2,"text":"ہیج انشورنس ہے، جادو کی ڈھال نہیں۔","id":"a-hedge-is-insurance-not-a-magic-shield"},{"level":2,"text":"جو آپ ذہنی سکون کے لیے ادا کرتے ہیں۔","id":"what-you-pay-for-peace-of-mind"},{"level":2,"text":"ایک ہیج کیا کر سکتا ہے اور کیا نہیں کر سکتا","id":"what-a-hedge-can-and-cannot-do"},{"level":2,"text":"کون کس چیز کی حفاظت کرتا ہے۔","id":"who-hedges-what"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"9":{"html":"<p>میرا نے بارہ سالوں میں 45 لاکھ روپے کا پورٹ فولیو بنایا ہے - زیادہ تر بڑی، معروف ہندوستانی کمپنیاں جن پر وہ یقین رکھتی ہیں۔ مرکزی بجٹ دو دن باقی ہے۔ وہ بیچنا نہیں چاہتی: کچھ ہولڈنگز میں بڑے غیر حقیقی منافع اور ٹیکس کا بل ہوتا ہے اگر وہ باہر نکلتی ہے، اور اسے طویل عرصے تک ان میں حقیقی یقین ہے۔ لیکن وہ یہ بھی جانتی ہیں کہ بجٹ کا دن ایک ہی سیشن میں مارکیٹ کو 5 سے 7 فیصد تک لے جا سکتا ہے، اور 6 فیصد کی کمی گھنٹوں میں اس کی کتاب سے تقریباً 3 لاکھ روپے کا صفایا کر دے گی۔ اس لیے وہ NIFTY پر چند ہزار روپے خرچ کرتی ہے اگر مارکیٹ سخت گرتی ہے تو اس کی قیمت بڑھ جاتی ہے۔ اگر بجٹ مارکیٹ کو خوفزدہ کرتا ہے، تو پٹ دھچکے کو نرم کرتا ہے۔ اگر کچھ نہیں ہوتا ہے تو، وہ صرف ایک چھوٹا سا پریمیم کھو دیتی ہے - بجٹ رات کے ذریعے سونے کی قیمت۔ یہ ایک ہیج ہے جس طرح اس کا استعمال کیا جانا ہے۔</p>\n<p>آخری باب نے کہا کہ ہیجنگ ایک پریمیم کے ساتھ انشورنس ہے: کبھی بھی مفت، کبھی منافع کی ضمانت نہیں۔ یہ باب واضح اگلے سوال کا جواب دیتا ہے - اس پریمیم کی ادائیگی اصل میں اس کے قابل کب ہے؟</p>\n<h2 id=\"the-one-thread-behind-every-good-hedge\">ہر اچھے ہیج کے پیچھے ایک دھاگہ</h2>\n<p>ایک ہی امتحان ہے، اور ہیج کرنے کی ہر اچھی وجہ اسے پاس کرتی ہے۔ ایک ہیج اپنی قیمت صرف اس وقت کماتا ہے جب آپ جس خطرے کی حفاظت کر رہے ہیں وہ یہ ہے:</p>\n<ol>\n<li><strong>اصلی اور بڑے</strong> - گرنے سے حقیقی طور پر آپ کے پیسے یا آپ کی نیند کو نقصان پہنچے گا، نہ کہ صرف تھوڑا سا ڈنک۔</li>\n<li><strong>وقت کا پابند</strong> - یہ کسی تاریخ، واقعہ، یا آخری تاریخ سے منسلک ہے، مستقل پریشانی سے نہیں۔</li>\n<li><strong>صرف فروخت کرکے ہٹانا مشکل ہے۔</strong> - آپ نہیں کر سکتے، یا نہیں چاہتے، بس سستے میں پوزیشن سے باہر نکلیں اور چلے جائیں۔</li>\n</ol>\n<p>ان میں سے کسی ایک کو یاد کریں اور آپ شاید ہیج کو نہیں دیکھ رہے ہیں۔ اگر خطرہ چھوٹا ہے تو اسے نظر انداز کریں۔ اگر آپ صرف کم قیمت پر پوزیشن بیچ سکتے ہیں، تو فروخت صاف ہے۔ ہیجنگ عجیب و غریب وسط کے لیے ہے: ایک بڑا، تاریخ کا خطرہ جسے آپ پکڑے ہوئے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>جب آپ کو ایک حقیقی، بڑے، وقتی خطرے کا سامنا کرنا پڑتا ہے جسے آپ بیچ کر دور نہیں کر سکتے یا نہیں کرنا چاہتے۔ اگر آپ آسانی سے پوزیشن کو سستے میں بیچ سکتے ہیں اور وہاں سے چلے جاتے ہیں، تو یہ تقریباً ہمیشہ بہتر، آسان اقدام ہوتا ہے۔</p>\n</div></div>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 380\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"فیصلہ کا بہاؤ یہ ظاہر کرتا ہے کہ آپ کو صرف اس وقت ہیج کرنا چاہئے جب خطرہ حقیقی اور بڑا ہو، کسی تاریخ یا تقریب سے منسلک ہو، اور اسے صرف فروخت کرکے ہٹایا نہیں جا سکتا۔\">\n  <defs>\n    <marker id=\"hf1\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\" markerUnits=\"strokeWidth\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8b949e\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"380\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"26\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">کیا مجھے اس سے بچنا چاہئے؟ تین سوالوں کا امتحان</text>  <rect x=\"160\" y=\"44\" width=\"280\" height=\"36\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <text x=\"300\" y=\"67\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">ایک پوزیشن آپ کو پریشان کر رہی ہے۔</text>\n  <line x1=\"300\" y1=\"80\" x2=\"300\" y2=\"98\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#hf1)\"/>  <rect x=\"120\" y=\"100\" width=\"360\" height=\"42\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\"/>\n  <text x=\"300\" y=\"126\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">کیا خطرہ حقیقی اور بڑا ہے؟</text>\n  <line x1=\"480\" y1=\"121\" x2=\"523\" y2=\"121\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#hf1)\"/>\n  <text x=\"500\" y=\"113\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">نہیں</text>\n  <rect x=\"525\" y=\"100\" width=\"215\" height=\"42\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\"/>\n  <text x=\"632\" y=\"126\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12.5\" font-family=\"sans-serif\">صرف اعصاب - کوئی ہیج نہیں</text>\n  <line x1=\"300\" y1=\"142\" x2=\"300\" y2=\"158\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#hf1)\"/>\n  <text x=\"314\" y=\"155\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">جی ہاں</text>  <rect x=\"120\" y=\"160\" width=\"360\" height=\"42\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\"/>\n  <text x=\"300\" y=\"186\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">ایک تاریخ یا تقریب سے منسلک؟</text>\n  <line x1=\"480\" y1=\"181\" x2=\"523\" y2=\"181\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#hf1)\"/>\n  <text x=\"500\" y=\"173\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">نہیں</text>\n  <rect x=\"525\" y=\"160\" width=\"215\" height=\"42\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\"/>\n  <text x=\"632\" y=\"186\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12.5\" font-family=\"sans-serif\">سائز یا اسٹاپ کے ساتھ انتظام کریں۔</text>\n  <line x1=\"300\" y1=\"202\" x2=\"300\" y2=\"218\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#hf1)\"/>\n  <text x=\"314\" y=\"215\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">جی ہاں</text>  <rect x=\"120\" y=\"220\" width=\"360\" height=\"42\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\"/>\n  <text x=\"300\" y=\"246\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">کیا آپ اسے صرف بیچ سکتے ہیں؟</text>\n  <line x1=\"480\" y1=\"241\" x2=\"523\" y2=\"241\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#hf1)\"/>\n  <text x=\"500\" y=\"233\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">جی ہاں</text>\n  <rect x=\"525\" y=\"220\" width=\"215\" height=\"42\" rx=\"10\" fill=\"#11161d\" stroke=\"#37b3a4\"/>\n  <text x=\"632\" y=\"246\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12.5\" font-family=\"sans-serif\">فروخت سستی ہے - فروخت</text>\n  <line x1=\"300\" y1=\"262\" x2=\"300\" y2=\"280\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#hf1)\"/>\n  <text x=\"314\" y=\"276\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">نہیں</text>  <rect x=\"120\" y=\"282\" width=\"360\" height=\"46\" rx=\"10\" fill=\"#16241b\" stroke=\"#55a868\"/>\n  <text x=\"300\" y=\"310\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">اسے ہیج کرنا - یہ وہی ہے جس کے لئے ہیجنگ ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ایک ہیج صرف اپنی قیمت کماتا ہے جب تینوں جوابات ایک ہی طرف اشارہ کرتے ہیں۔</figcaption>\n</figure><p>اب پانچ حالات جہاں یہ امتحان پاس ہوتا ہے، بار بار۔</p>\n<h2 id=\"1-a-big-portfolio-into-a-known-event\">1. ایک معروف واقعہ میں ایک بڑا پورٹ فولیو</h2>\n<p>مرکزی بجٹ۔ عام انتخابات کا نتیجہ۔ ایک RBI پالیسی فیصلہ۔ ایک بڑا عدالتی فیصلہ یا پالیسی کا اعلان۔ یہ وہ تاریخیں ہیں جو ہر کوئی آتے ہوئے دیکھ سکتا ہے، جہاں ایک تیز حرکت کا امکان ہے لیکن سمت کسی کا اندازہ ہے۔</p>\n<p>یہ ہے <strong>واقعہ کا خطرہ</strong>، اور یہ لاتا ہے۔ <strong>فرق کا خطرہ</strong> - وہی خطرہ جس کے بارے میں رسک مینجمنٹ کورس نے خبردار کیا تھا۔ قیمت ایک ہی چھلانگ میں چھلانگ لگا سکتی ہے، جب مارکیٹ بند ہو یا بھرنے کے لیے بہت تیزی سے آگے بڑھ رہی ہو تو سیدھا آپ کے سٹاپ لاس کو چھوڑ کر۔ ایک سٹاپ آپ کی حفاظت نہیں کرتا خلا میں۔ ایک ہیج کر سکتا ہے، کیونکہ یہ قیمت ادا کرتا ہے چاہے قیمت کتنی ہی بڑھ جائے۔</p>\n<p>آپ کی کتاب جتنی بڑی ہوگی، یہ اتنا ہی اہم ہوگا۔ 50,000 روپے کے ہولڈنگ پر 6 فیصد بجٹ ڈے گرنا اور میرا کے 45 لاکھ روپے والے ایک پر 2.7 لاکھ روپے کا ہول ہے۔ جب پوزیشن بڑی ہوتی ہے اور تاریخ طے ہوتی ہے، تو کچھ دنوں کے لیے منفی پہلو کو محدود کرنے کے لیے ایک چھوٹا پریمیم ادا کرنا ایک منصفانہ تجارت ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک ٹائم لائن جس میں ایک معروف ایونٹ کا دن دکھایا جا رہا ہے۔ ایونٹ سے پہلے قیمت کا راستہ مستحکم ہے، اور ایونٹ میں یہ اوپر یا نیچے جا سکتا ہے۔ ایونٹ کے ارد گرد ایک ہیج ونڈو منفی پہلو کی حفاظت کرتی ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"26\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">آگے جانے والا واقعہ: پہلے کی حفاظت کریں، بعد میں ہٹا دیں۔</text>  <rect x=\"352\" y=\"64\" width=\"96\" height=\"172\" rx=\"8\" fill=\"#55a868\" fill-opacity=\"0.12\" stroke=\"#55a868\" stroke-dasharray=\"4 3\"/>\n  <text x=\"400\" y=\"80\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"11\" font-family=\"sans-serif\">ہیج کھڑکی</text>  <line x1=\"400\" y1=\"86\" x2=\"400\" y2=\"244\" stroke=\"#8b949e\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n  <text x=\"400\" y=\"258\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">تقریب کا دن: بجٹ / نتیجہ / RBI پالیسی</text>  <line x1=\"90\" y1=\"170\" x2=\"400\" y2=\"170\" stroke=\"#4c72b0\" stroke-width=\"3\"/>\n  <circle cx=\"90\" cy=\"170\" r=\"4\" fill=\"#4c72b0\"/>\n  <text x=\"84\" y=\"158\" text-anchor=\"start\" fill=\"#8b949e\" font-size=\"11.5\" font-family=\"sans-serif\">اب: آپ کا بڑا عہدہ</text>  <line x1=\"400\" y1=\"170\" x2=\"660\" y2=\"98\" stroke=\"#55a868\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/>\n  <circle cx=\"660\" cy=\"98\" r=\"4\" fill=\"#55a868\"/>\n  <text x=\"650\" y=\"92\" text-anchor=\"end\" fill=\"#55a868\" font-size=\"11.5\" font-family=\"sans-serif\">اوپر کی حرکت: ہیج کی میعاد ختم، چھوٹی قیمت</text>  <line x1=\"400\" y1=\"170\" x2=\"660\" y2=\"244\" stroke=\"#c44e52\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/>\n  <circle cx=\"660\" cy=\"244\" r=\"4\" fill=\"#c44e52\"/>\n  <text x=\"650\" y=\"262\" text-anchor=\"end\" fill=\"#c44e52\" font-size=\"11.5\" font-family=\"sans-serif\">ڈاون گیپ: ہیج ادا کرتا ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">آپ نہیں جان سکتے کہ واقعہ کس راستے سے ٹوٹتا ہے۔ ہیج اس طرف کا احاطہ کرتا ہے جو آپ کو نقصان پہنچا سکتا ہے۔</figcaption>\n</figure><h2 id=\"2-concentrated-stock-exposure-you-cannot-sell\">2. مرتکز اسٹاک ایکسپوژر جو آپ فروخت نہیں کر سکتے</h2>\n<p>تصور کریں کہ آپ کی مجموعی مالیت کا ایک بڑا حصہ ایک کمپنی میں بیٹھا ہے۔ ہو سکتا ہے کہ وہ آپ کے آجر کی طرف سے ESOPs ہوں، جو ایک اور سال کے لیے بند ہیں - آپ انہیں قانونی طور پر ابھی فروخت نہیں کر سکتے۔ ہوسکتا ہے کہ فروخت کرنے سے ٹیکس کا بل شروع ہوجائے جسے آپ موخر کرنا چاہتے ہیں۔ ہوسکتا ہے کہ آپ کو یقین ہو اور آپ اسٹاک کو برقرار رکھنا چاہتے ہیں، لیکن آپ اگلے سہ ماہی کے نتائج کے بارے میں گھبرائے ہوئے ہیں۔</p>\n<p>سنگل اسٹاک کا خطرہ ناقابل معافی ہے - ایک برا نتیجہ یا تھوڑی سی بری خبر اسٹاک کو راتوں رات 15 یا 20 فیصد نیچے لے جا سکتی ہے۔ جب فروخت میز سے باہر ہو تو، ایک ہیج واحد لیور ہے جو آپ نے اس پوزیشن کے نقصان کو محدود کرنے کے لیے چھوڑا ہے جب تک کہ آپ اسے تھامے رہیں۔</p>\n<h2 id=\"3-overnight-or-weekend-f-o-exposure-into-news\">3. راتوں رات یا ہفتے کے آخر میں خبروں میں F&amp;O کی نمائش</h2>\n<p>فیوچرز اور شارٹ آپشنز کا فائدہ اٹھانا ہے، جس کا مطلب ہے کہ چھوٹی حرکتیں آپ کے سرمائے کو سخت متاثر کرتی ہیں۔ انہیں راتوں رات پکڑے رکھیں اور آپ اس فرق کو لے رہے ہیں جو آپ مارکیٹ کے بند ہونے کے دوران سنبھال نہیں سکتے۔</p>\n<p>یہ ایک طویل ویک اینڈ کے ارد گرد تیز تر ہو جاتا ہے، گھنٹوں کے بعد اعلان کیا جانے والا نتیجہ، یا ہفتہ کو بریک ہونے والی عالمی خبریں۔ مارکیٹ دوبارہ کھل جاتی ہے اور قیمت محض کہیں اور ہے - رد عمل کا کوئی موقع نہیں ہے۔ اگر آپ کو اس کے ذریعے لیوریجڈ پوزیشن پر فائز ہونا ضروری ہے تو، ایک ہیج (یا صرف سائز کو بالکل نیچے کاٹنا) اس بات کو ظاہر کرتا ہے کہ پیر کا وقفہ آپ کے ساتھ کیا کر سکتا ہے۔</p>\n<h2 id=\"4-a-real-business-exposure\">4. ایک حقیقی کاروباری نمائش</h2>\n<p>اس کے لیے ہیجنگ ایجاد کی گئی تھی، تاجروں کے وجود سے بہت پہلے۔ ایک درآمد کنندہ جس کو تین مہینوں میں 54X0$ ڈالر میں ادائیگی کرنی ہوگی اسے روپیہ کے کمزور ہونے کا خدشہ ہے۔ ایک برآمد کنندہ جو ڈالر وصول کرے گا اسے اس کے مضبوط ہونے کا خدشہ ہے۔ سونے کا ذخیرہ رکھنے والے ایک زیور کو ٹکڑے فروخت ہونے سے پہلے قیمت گرنے کا خدشہ ہے۔</p>\n<p>یہ شرطیں نہیں ہیں - یہ کاروبار چلانے سے حقیقی نقد بہاؤ کے خطرات ہیں۔ ایک کرنسی یا کموڈٹی ہیج ایک نامعلوم مستقبل کی قیمت کو معلوم قیمت میں بدل دیتا ہے، تاکہ کاروبار منصوبہ بنا سکے۔ بات ہیج سے فائدہ اٹھانا نہیں ہے۔ یہ میز سے ایک بڑی غیر یقینی صورتحال کو دور کرنا ہے۔</p>\n<h2 id=\"5-a-known-future-cash-need\">5. ایک معلوم مستقبل کی نقدی کی ضرورت</h2>\n<p>کہو کہ آپ کو تین مہینوں میں 20 لاکھ روپے کی ضرورت ہے - ایک گھر کی ادائیگی، ایک بچے کے کالج میں داخلہ، ایک آخری تاریخ جسے آپ منتقل نہیں کر سکتے۔ پیسہ ایکویٹی میں کھڑا ہے۔ آپ ضرورت سے پہلے 15 فیصد گراوٹ کا متحمل نہیں ہو سکتے، لیکن آپ یہ بھی نہیں چاہتے کہ آج ہی فروخت کریں اور ممکنہ اضافے سے محروم رہیں یا ابھی ٹیکس ادا کریں۔</p>\n<p>ایک مختصر تاریخ والا ہیج اس رقم کی حفاظت کرتا ہے جس کی آپ کو حقیقی طور پر ضرورت ہوتی ہے، جس تاریخ پر آپ کو اس کی ضرورت ہوتی ہے۔ نقد کی آخری تاریخ جتنی قریب اور زیادہ طے کی جائے گی، تحفظ کا کیس اتنا ہی مضبوط ہوگا۔</p>\n<p><em>یہ تعلیم ہے، ذاتی مشورے نہیں۔ یہاں رقم اور آلات مثالیں ہیں - آپ کے اپنے نمبر اور ٹیکس کی صورتحال مختلف ہوگی۔</em></p>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>کلاسک ابتدائی غلطی ایک چھوٹی پوزیشن کو ہیج کرنا ہے، یا جب کوئی حقیقی واقعہ نہیں ہے تو ہیجنگ ہے - صرف ایک مبہم پریشانی۔ 30,000 روپے کے ہولڈنگ کی حفاظت کے لیے 1,500 روپے پریمیم ادا کرنا، یا ہر ہفتے \"صرف صورت میں\" پوٹس خریدنا خطرے کا انتظام نہیں ہے۔ یہ ایک سست رساو ہے جو خاموشی سے آپ کی واپسی کا خون بہاتی ہے۔ اگر پوزیشن چھوٹی ہے، یا پریشانی صرف اعصاب ہے جس میں کوئی تاریخ نہیں ہے، جواب عام طور پر کوئی ہیج نہیں ہے - سائز کم کریں، یا کچھ نہ کریں۔</p>\n</div></div>\n<h2 id=\"a-checklist-good-reasons-to-hedge\">ایک چیک لسٹ: ہیج کرنے کی اچھی وجوہات</h2>\n<p>کسی بھی تحفظ کے لیے ادائیگی کرنے سے پہلے اس فہرست کو نیچے چلائیں۔ جتنے زیادہ بکس آپ ٹک کریں گے، کیس اتنا ہی بہتر ہوگا۔</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> خطرہ حقیقی اور بڑا ہے - گرنے سے حقیقی طور پر آپ کے مالیات یا آپ کی نیند کو نقصان پہنچے گا۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> ایک تاریخ یا واقعہ منسلک ہے: بجٹ، نتیجہ، پالیسی فیصلہ، یا نقد آخری تاریخ۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> آپ ابھی پوزیشن فروخت نہیں کر سکتے یا نہیں کرنا چاہتے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> تحفظ کی لاگت اس نقصان کے آگے کم ہے جس کے خلاف آپ حفاظت کر رہے ہیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> آپ بالکل جانتے ہیں کہ آپ کس چیز کی حفاظت کر رہے ہیں، اور کب تک۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> ایونٹ گزر جانے کے بعد آپ کے پاس پہلے سے ہیج کو ہٹانے کا منصوبہ ہے۔</li>\n</ul>\n<p>اگر ان میں سے اکثر کو ٹک کیا جاتا ہے تو، ایک ہیج معنی رکھتا ہے۔ اگر وہ نہیں ہیں تو، آسان اقدام پر سختی سے دیکھیں - صرف پوزیشن کو کاٹنا۔</p>\n<h2 id=\"how-the-hedge-situation-differs-by-participant\">ہیج کی صورتحال شرکاء کے لحاظ سے کیسے مختلف ہوتی ہے۔</h2>\n<table>\n<thead>\n<tr>\n<th>حصہ لینے والا</th>\n<th>ہیج کرنے کی عام وجہ</th>\n<th>ایک عام، سادہ ٹول</th>\n<th>اسے کب چھوڑنا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>بجٹ، انتخابی نتائج یا پالیسی کے دن میں جانے والا بڑا پورٹ فولیو</td>\n<td>ایک انڈیکس چند دنوں کے لیے رکھا، یا نمائش کو تراشنا</td>\n<td>ایک چھوٹی SIP کتاب - صرف ڈپ کے ذریعے خریدتے رہیں</td>\n</tr>\n<tr>\n<td>اسٹاک تاجر</td>\n<td>نتائج کی تاریخ کے ذریعے منعقد ہونے والی ایک بڑی جیتنے والی سوئنگ تجارت</td>\n<td>ایک حفاظتی پوٹ، یا محض جزوی منافع لینا</td>\n<td>ایک چھوٹی پوزیشن - ایک عام سٹاپ نقصان کافی ہے</td>\n</tr>\n<tr>\n<td>F&amp;O (فیوچر) تاجر</td>\n<td>ایک لیوریجڈ پوزیشن راتوں رات یا ہفتے کے آخر میں خبروں میں لے جاتی ہے۔</td>\n<td>آفسیٹ کرنے کا آپشن، یا بند ہونے سے پہلے لاٹ کاٹنا</td>\n<td>ایک فلیٹ، صرف انٹرا ڈے کتاب جس میں رات بھر کوئی چیز نہیں رکھی گئی ہے۔</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>ایک مختصر پریمیم کتاب جو کسی ایونٹ یا ایکسپائری کے ارد گرد ایک خلا کو ظاہر کرتی ہے۔</td>\n<td>ٹیل ہیج کے طور پر ایک لمبا آؤٹ آف دی منی ونگ</td>\n<td>چھوٹے، متعین خطرے کے سائز کے ساتھ ایک پرسکون، کم ایونٹ والا ہفتہ</td>\n</tr>\n</tbody></table>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>ہیجنگ ایک آلہ ہے، علاج نہیں. یہ چند پیشین گوئی طریقوں سے غلط ہو جاتا ہے۔</p>\n<p>ایک ہیج خراب پوزیشن کو ٹھیک نہیں کر سکتا۔ اگر آپ کو کسی چیز کو بالکل بھی نہیں رکھنا چاہئے، تو اس کی حفاظت کرنا صرف غلطی کی قیمت میں اضافہ کرتا ہے۔ کبھی کبھی \"ہیج یا نہیں\" غلط سوال ہوتا ہے اور \"میں اس کا مالک کیوں ہوں؟\" صحیح ہے.</p>\n<p>سائز اور آلے کو خطرے سے مماثل ہونا چاہئے۔ ایک ہی سٹاک کو ایک وسیع انڈیکس کے ساتھ ہیج کریں اور ہو سکتا ہے کہ دونوں ایک ساتھ نہ بڑھیں - جب آپ کا سٹاک گرتا ہے تو انڈیکس برقرار رہ سکتا ہے، جس سے آپ کو تحفظ کے لیے ادائیگی کرنی پڑتی ہے جو تحفظ نہیں دیتا۔ اس مماثلت کو بنیادی خطرہ کہا جاتا ہے، اور یہ خاموشی سے سست ہیجز کو شکست دیتا ہے۔</p>\n<p>واقعہ گزر جاتا ہے اور لوگ ہیج اتارنا بھول جاتے ہیں۔ اب یہ انشورنس نہیں رہا ہے - یہ ایک تازہ شرط ہے جو پریمیم کو خون دیتی ہے یا آپ کی نمائش کو کم کرتی ہے۔ ایک ہیج کو باہر نکلنے کے منصوبے کی اتنی ہی ضرورت ہوتی ہے جتنا کہ اندراج۔</p>\n<p>اور چھوٹی کتابوں کے لیے، تحفظ کی لاگت محفوظ ہونے کے خطرے سے زیادہ ہو سکتی ہے۔ کسی پورٹ فولیو کی حفاظت کے لیے ہر ماہ حقیقی رقم خرچ کرنا جسے سٹاپ لوس یا اس سے تھوڑی چھوٹی پوزیشن ہینڈل کرے گی ایک ناقص تجارت ہے۔ اس میں سے کوئی بھی مشورہ نہیں ہے کہ کیا خریدنا یا بیچنا ہے - یہ تحفظ کے لیے ادائیگی کرنے سے پہلے سوچنے کا طریقہ ہے۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> ایک ہیج کی قیمت کے قابل ہونے سے پہلے کون سی تین چیزیں درست ہونی چاہئیں؟</summary><p>خطرہ حقیقی اور بڑا ہونا چاہیے، یہ وقت کا پابند ہونا چاہیے (تاریخ یا تقریب سے منسلک)، اور اسے محض فروخت کرکے ہٹانا مشکل ہونا چاہیے۔ اگر آپ صرف پوزیشن کو سستے میں بیچ سکتے ہیں، تو فروخت کرنا عام طور پر بہتر اقدام ہوتا ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> مرکزی بجٹ جیسا معروف واقعہ سٹاپ لوس کے بجائے ہیج کا مطالبہ کیوں کرتا ہے؟</summary><p>ایونٹس فرق کا خطرہ پیدا کرتے ہیں - قیمت ایک ہی حرکت میں بڑھ سکتی ہے اور سیدھے آپ کے اسٹاپ پر جا سکتی ہے، خاص طور پر راتوں رات یا دوبارہ کھلنے پر۔ ایک ہیج قیمت کے فرق سے قطع نظر ادائیگی کرتا ہے، لہذا یہ چھلانگ کے اس پار حفاظت کرتا ہے جسے کوئی روک نہیں سکتا۔</p>\n</details><details>\n<summary><strong>3.</strong> آپ ESOPs کو ایک اور سال کے لیے بند رکھتے ہیں اور اگلے نتیجہ سے ڈرتے ہیں۔ یہ نصابی کتاب ہیج کی صورتحال کیوں ہے؟</summary><p>آپ کے پاس ایک بڑا، مرتکز واحد اسٹاک کا خطرہ ہے جسے آپ قانونی طور پر فروخت نہیں کرسکتے ہیں۔ فروخت کرنا میز سے باہر ہے، لہذا ایک ہیج واحد لیور بچا ہے جس سے ایک پوزیشن کے منفی پہلو کو محدود کیا جا سکتا ہے جب تک کہ آپ اسے تھامے رہیں۔</p>\n</details><details>\n<summary><strong>4.</strong> 30,000 روپے کی چھوٹی سی غلطی کو بچانے کے لیے ہر ہفتے ایک پٹ کیوں خرید رہا ہے؟</summary><p>پوزیشن بہت چھوٹی ہے اور کوئی حقیقی واقعہ نہیں ہے - یہ مبہم اعصاب سے باہر نکل رہا ہے۔ مستحکم پریمیم لاگت ایک سست رساو ہے جو آپ کے ریٹرن کو خون بہاتی ہے۔ ایک چھوٹی پوزیشن کے لیے، سائز کو کم کرنا یا محض کچھ نہ کرنا بہتر جواب ہے۔</p>\n</details><details>\n<summary><strong>5.</strong> ایک درآمد کنندہ کو تین ماہ میں ڈالر میں ادائیگی کرنی ہوگی۔ کیا اس کرنسی کو ہیج کرنا روپے پر شرط ہے؟</summary><p>نہیں - یہ شرط کے برعکس ہے۔ یہ ایک حقیقی کاروباری کیش فلو رسک ہے، اور ہیج مستقبل کی نامعلوم شرح مبادلہ کو معلوم میں بدل دیتا ہے تاکہ کاروبار منصوبہ بندی کر سکے۔ مقصد یقین ہے، ہیج پر منافع نہیں.</p>\n</details>\n","toc":[{"level":2,"text":"ہر اچھے ہیج کے پیچھے ایک دھاگہ","id":"the-one-thread-behind-every-good-hedge"},{"level":2,"text":"1. ایک معروف واقعہ میں ایک بڑا پورٹ فولیو","id":"1-a-big-portfolio-into-a-known-event"},{"level":2,"text":"2. مرتکز اسٹاک ایکسپوژر جو آپ فروخت نہیں کر سکتے","id":"2-concentrated-stock-exposure-you-cannot-sell"},{"level":2,"text":"3. راتوں رات یا ہفتے کے آخر میں خبروں میں F&O کی نمائش","id":"3-overnight-or-weekend-f-o-exposure-into-news"},{"level":2,"text":"4. ایک حقیقی کاروباری نمائش","id":"4-a-real-business-exposure"},{"level":2,"text":"5. ایک معلوم مستقبل کی نقدی کی ضرورت","id":"5-a-known-future-cash-need"},{"level":2,"text":"ایک چیک لسٹ: ہیج کرنے کی اچھی وجوہات","id":"a-checklist-good-reasons-to-hedge"},{"level":2,"text":"ہیج کی صورتحال شرکاء کے لحاظ سے کیسے مختلف ہوتی ہے۔","id":"how-the-hedge-situation-differs-by-participant"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"10":{"html":"<p>میرا کے پاس مٹھی بھر اسٹاک میں 80,000 روپے تھے اور ایک چل رہا تھا SIP۔ اس نے ہیجنگ کے بارے میں پڑھا، بجٹ کے دن سے پہلے گھبرا گئی، اور ہر چیز کو \"محفوظ\" کرنے کے لیے ایک NIFTY خرید لیا۔ بازار بمشکل منتقل ہوا۔ ڈال کی میعاد ختم ہوگئی اور پریمیم پلس چارجز کی قیمت تقریباً 1,400 روپے ہے۔ اگلے مہینے اس نے دوبارہ، اور دوبارہ کیا. سال کے آخر تک اس نے تحفظ پر زیادہ خرچ کیا تھا جس کی اسے کبھی ضرورت نہیں تھی اس سے زیادہ اس کا پورٹ فولیو بھی گر گیا تھا۔ اس کے پیسے ٹھیک تھے۔ اس کا خوف صرف ایک ہی چیز کا انتظام کیا جا رہا تھا، اور یہ اس کا کرایہ وصول کر رہا تھا۔</p>\n<p>آخری دو ابواب نے ہیجنگ کا معاملہ بنایا۔ یہ ایک ایماندار دوسرا نصف ہے: زیادہ تر وقت، زیادہ تر ابتدائیوں کے لیے، صحیح جواب ہوتا ہے۔ <strong>ہیج نہ کرو</strong>. ایک ہیج ایک قیمت ہے۔ اگر وہ چیز جس سے اس کی حفاظت ہوتی ہے وہ چھوٹی، زندہ رہنے والی، یا مبہم ہے، تو یہ قیمت صرف ایک سست رساو ہے۔</p>\n<h2 id=\"hedging-is-a-tool-not-a-reflex\">ہیجنگ ایک ٹول ہے، اضطراری نہیں۔</h2>\n<p>ایک ہیج پریمیم ادا کر کے ایک خطرے کو خرید لیتا ہے - رقم میں، پیچیدگی میں، الٹا چھوڑ کر۔ یہ تجارت صرف اس وقت قابل ہے جب خطرہ بڑا، حقیقی، اور واضح طور پر نامزد ہو۔ ان تینوں میں سے کسی ایک کو بھی لے لو اور ہیج اپنی کیپ حاصل کرنا بند کر دیتا ہے۔</p>\n<p>پھندا وہ ہیجنگ ہے۔ <em>محسوس کرتا ہے</em> ذمہ دار ایسا محسوس ہوتا ہے کہ ایسا کرنا ہوشیار، بڑے ہو گیا ہے۔ لیکن تحفظ جس کی آپ کو ضرورت نہیں ہے احتیاط نہیں ہے - یہ ایک ٹیکس ہے جسے آپ رضاکارانہ طور پر ادا کرتے ہیں۔ اور آپ کا اکاؤنٹ جتنا چھوٹا ہوگا، ٹیکس اتنا ہی بھاری ہوگا، کیونکہ ہیج کی قیمت صرف اس وجہ سے کم نہیں ہوتی کہ آپ کا پورٹ فولیو چھوٹا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک چارٹ جس میں دکھایا گیا ہے کہ تقریباً مقررہ ہیج لاگت چھوٹے پورٹ فولیو کے ریٹرن کا ایک بہت بڑا ٹکڑا کھاتی ہے لیکن بڑے پورٹ فولیو کے ریٹرن کا صرف ایک چھوٹا ٹکڑا۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ایک ہی ہیج لاگت ایک چھوٹی کتاب کو کہیں زیادہ تکلیف دیتی ہے۔</text>  <rect x=\"70\" y=\"70\" width=\"180\" height=\"170\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <text x=\"160\" y=\"62\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"12\" font-family=\"sans-serif\">80,000 روپے کی کتاب</text>\n  <rect x=\"90\" y=\"100\" width=\"140\" height=\"120\" rx=\"6\" fill=\"#16241b\" stroke=\"#55a868\"/>\n  <rect x=\"90\" y=\"100\" width=\"140\" height=\"78\" rx=\"6\" fill=\"#241619\" stroke=\"#c44e52\"/>\n  <text x=\"160\" y=\"145\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-family=\"sans-serif\">ہیج لاگت</text>\n  <text x=\"160\" y=\"205\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">کیا رہ گیا ہے</text>  <rect x=\"510\" y=\"70\" width=\"180\" height=\"170\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <text x=\"600\" y=\"62\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"12\" font-family=\"sans-serif\">20,00,000 روپے کی کتاب</text>\n  <rect x=\"530\" y=\"100\" width=\"140\" height=\"120\" rx=\"6\" fill=\"#16241b\" stroke=\"#55a868\"/>\n  <rect x=\"530\" y=\"100\" width=\"140\" height=\"14\" rx=\"6\" fill=\"#241619\" stroke=\"#c44e52\"/>\n  <text x=\"600\" y=\"170\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">کیا رہ گیا ہے</text>  <line x1=\"270\" y1=\"155\" x2=\"500\" y2=\"155\" stroke=\"#8b949e\" stroke-width=\"2\" stroke-dasharray=\"5 4\"/>\n  <text x=\"385\" y=\"148\" text-anchor=\"middle\" fill=\"#dd8452\" font-size=\"12\" font-family=\"sans-serif\">تقریباً ایک ہی روپے کی لاگت</text>\n  <text x=\"380\" y=\"270\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"12\" font-family=\"sans-serif\">سرخ ہیج بل ہے۔ ایک چھوٹی سی کتاب پر یہ واپسی کو نگل جاتا ہے۔ ایک بڑے پر یہ ایک گول کرنے کی غلطی ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ہیجز کی تقریباً مقررہ کم از کم قیمت ہوتی ہے۔ چھوٹے اکاؤنٹس محسوس کرتے ہیں کہ اس کی قیمت سب سے زیادہ ہے۔</figcaption>\n</figure><h2 id=\"six-times-the-answer-is-do-not-hedge\">چھ بار جواب ہے \"ہیج نہ کرو\"</h2>\n<p><strong>1. ایک چھوٹا پورٹ فولیو جہاں منفی پہلو زندہ رہنے کے قابل ہے۔</strong> اگر آپ کے پاس 80,000 روپے ہیں اور ایک خراب مہینہ کا مطلب ہے کہ یہ 70,000 روپے تک گر جاتا ہے، تو یہ 10,000 روپے کا پیپر فال ہے جس پر آپ سواری کر سکتے ہیں۔ اس کے خلاف بیمہ کروانے کے لیے ہر ماہ 1,000-1,500 روپے ادا کرنا خود زوال کے مقابلے میں ایک سال سے زیادہ خرچ کر سکتا ہے۔ جب سب سے برا معاملہ غیر آرام دہ ہے لیکن خطرناک نہیں ہے، تو آپ اس کا بیمہ نہیں کراتے ہیں - آپ اس کے ساتھ رہتے ہیں۔</p>\n<p><strong>2. ایک طویل مدتی SIP یا جمع کرنے والا۔</strong> یہ بدیہی کا مخالف ہے۔ اگر آپ منظم طریقے سے ہر ماہ دس سال کے فاصلے پر ایک مقصد کے لیے خرید رہے ہیں، تو مارکیٹ گرنا آپ کا دشمن نہیں ہے - یہ ایک رعایت ہے۔ 30% کمی آپ کے SIP کو کم قیمتوں پر مزید یونٹ خریدنے دیتی ہے۔ SIP کو ہیج کرنے کا مطلب ہے اس چیز کو منسوخ کرنے کے لیے ادائیگی کرنا جس سے SIP کام کرتا ہے۔ فالس جب جمع کرنے والا ہوتا ہے۔ <em>خریدتا ہے</em>، نہیں جب یہ چھپ جاتا ہے۔</p>\n<p><strong>3. چھوٹے عہدے۔</strong> کہو کہ آپ کے پاس کوئی چھوٹی چیز ہے، یا 15,000 روپے کے شیئرز ہیں۔ ایسی پوزیشن کے لیے کلین فکس جو آپ کو پریشان کرتی ہے اس پر ہیج نہیں لگانا ہے - یہ پوزیشن کو چھوٹا کرنا، یا اسے بند کرنا ہے۔ ایک چھوٹی سی ہولڈنگ پر ایک ہیج ایک دوسرا آلہ، چارجز کا دوسرا سیٹ، اور دیکھنے کے لیے ایک دوسری چیز جوڑتا ہے، یہ سب کچھ ایسی رقم کی حفاظت کے لیے ہے جو آپ کو کبھی نقصان نہیں پہنچا سکتی تھی۔</p>\n<p><strong>4. سادہ خوف سے بچنا۔</strong> یہ میرا کی غلطی ہے۔ مارکیٹ خوفناک محسوس کرتی ہے، خبریں بلند ہوتی ہیں، اس لیے آپ تحفظ کے لیے پہنچ جاتے ہیں - اس لیے نہیں کہ آپ نے ایک مخصوص خطرے کی پیمائش کی ہے، بلکہ اس لیے کہ آپ چاہتے ہیں کہ بے چینی کا احساس رک جائے۔ یہ جذباتی ہیجنگ ہے۔ لاگت حقیقی اور بار بار ہوتی ہے۔ \"خطرہ\" ایک موڈ ہے۔ آپ کے اعصاب کو پرسکون کرنے کے لیے خریدا گیا ہیج آپ کے اعصاب کی حفاظت کرتا ہے، آپ کے سرمائے کی نہیں، اور یہ آپ کو ہر بار بل دیتا ہے۔</p>\n<p><strong>5. جب ہیج خطرے کے لیے بہت زیادہ خرچ کرتا ہے۔</strong> کسی بڑے ایونٹ سے پہلے، آپشن پریمیم بڑھ جاتے ہیں کیونکہ ہر کوئی ایک ساتھ تحفظ چاہتا ہے۔ بعض اوقات ایک ماہ کے پوٹ پر اس کی قیمت کا 3-4% خرچ ہو سکتا ہے۔ اگر آپ گرنے سے بچانے کے لیے 4% ادا کر رہے ہیں تو آپ کے خیال میں 5% ہو سکتا ہے، ریاضی بمشکل کام کرتی ہے - اور اگر زوال نہیں آتا ہے، تو آپ نے صرف 4% کھو دیا ہے۔ جب تحفظ کی قیمت کسی آفت کی طرح ہوتی ہے جو شاید نہیں ہو سکتی، تو اسے چھوڑنا (یا سائز کم کرنا) اکثر سستی شرط ہوتی ہے۔</p>\n<p><strong>6. جب آپ خطرے کا نام نہیں لے سکتے۔</strong> ایک ہیج کو کسی خاص چیز کی طرف اشارہ کرنا ہوتا ہے - یہ اسٹاک، یہ واقعہ، یہ راتوں رات کا فرق۔ اگر ایماندارانہ جواب \"میں بالکل کس چیز کے خلاف حفاظت کر رہا ہوں؟\" \"مجھے نہیں معلوم، عام طور پر مارکیٹ،\" پھر آپ صحیح طریقے سے ہیج کا سائز یا انتخاب نہیں کر سکتے۔ مبہم خوف مبہم، مہنگا، بری طرح سے مماثل تحفظ کا باعث بنتا ہے۔ اگر آپ اس کا نام نہیں لے سکتے ہیں، تو آپ اسے اچھی طرح سے ہیج نہیں کر سکتے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک ہیج صرف اس وقت خریدنے کے قابل ہے جب خطرہ بڑا، حقیقی اور واضح طور پر نامزد ہو۔ اگر منفی پہلو زندہ رہنے کے قابل ہے، اگر آپ طویل مدتی خریدار ہیں، اگر پوزیشن چھوٹی ہے، اگر یہ صرف خوف ہے، اگر پریمیم بہت زیادہ ہے، یا اگر آپ یہ نہیں کہہ سکتے کہ آپ کس چیز کے خلاف حفاظت کر رہے ہیں - صحیح اقدام ہے ہیج نہ کرنا۔</p>\n</div></div>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>کلاسک ابتدائی غلطی ایک ہیج کو آرام دہ کمبل کے طور پر علاج کر رہی ہے: خرید انڈیکس ایک چھوٹے اکاؤنٹ پر ہر خوفناک سرخی سے پہلے رکھتا ہے \"صرف صورت میں\"۔ ہر ایک سمجھداری محسوس کرتا ہے۔ وہ مل کر خاموشی سے آپ کے ریٹرن کو فنڈ تحفظ فراہم کرتے ہیں جسے آپ کبھی استعمال نہیں کرتے ہیں۔ بہتر اقدام یہ ہے کہ پہلے یہ پوچھ لیا جائے کہ کیا نقصان زندہ رہنے کے قابل بھی ہے - اور اگر ایسا ہے تو کچھ نہ کریں، یا صرف کم رکھیں۔</p>\n</div></div>\n<h2 id=\"the-cleaner-move-cut-instead-of-hedge\">کلینر اقدام: ہیج کے بجائے کاٹ دیں۔</h2>\n<p>یہاں وہ خیال ہے جو سب سے زیادہ \"کیا مجھے ہیج کرنا چاہئے؟\" سوالات غائب. جب کوئی پوزیشن بہت بڑی ہوتی ہے اور یہ آپ کو خوفزدہ کرتی ہے، تو آپ کے پاس محفوظ محسوس کرنے کے دو طریقے ہوتے ہیں۔ آپ پوری پوزیشن رکھ سکتے ہیں اور سب سے اوپر ہیج کے لیے ادائیگی کر سکتے ہیں۔ یا آپ آسانی سے کم رکھ سکتے ہیں۔</p>\n<p>ایک ابتدائی کے لیے، کم رکھنا تقریباً ہمیشہ صاف ہوتا ہے۔ اس پر کوئی اضافی لاگت نہیں آتی - درحقیقت یہ سرمایہ کو آزاد کرتا ہے۔ کوئی پریمیم نہیں ہے، ٹریک کرنے کی کوئی میعاد نہیں ہے، کوئی دوسرا آلہ نہیں ہے، کوئی بنیادی خطرہ نہیں ہے۔ آپ بالکل وہی چیز کم کرتے ہیں جس نے آپ کو پریشان کیا تھا: آپ کی نمائش۔ ایک ہیج بہت تیز چلنے والی کار پر بریک لگانے کی کوشش کرتا ہے۔ پوزیشن کاٹنا گاڑی کو سست کر دیتا ہے۔ یہ کورس کے شروع سے سیدھے پوزیشن کے سائز کے ساتھ جوڑتا ہے: اگر کوئی پوزیشن اتنی بڑی ہے کہ آپ کو لگتا ہے کہ آپ کو اسے ہیج کرنا ہوگا، تو اصل اشارہ عام طور پر یہ ہوتا ہے کہ پہلے اس کا سائز بہت بڑا تھا۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 320\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"فیصلہ کرنے کا کانٹا: ایک ایسی پوزیشن سے شروع کرنا جو بہت زیادہ خطرہ محسوس کرتا ہے، یہ پوچھنا کہ کیا خطرہ بڑا، حقیقی اور نام کا ہے، جو یا تو پوزیشن کو کم کرنے کا باعث بنتا ہے یا کبھی کبھی، اسے ہیج کرنا۔\">\n  <defs>\n    <marker id=\"afork\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\" markerUnits=\"strokeWidth\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8b949e\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"320\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">جب کوئی پوزیشن بہت خطرناک محسوس ہوتی ہے: کٹ، یا ہیج؟</text>  <rect x=\"270\" y=\"50\" width=\"220\" height=\"44\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\"/>\n  <text x=\"380\" y=\"77\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">یہ پوزیشن مجھے خوفزدہ کرتی ہے۔</text>\n  <line x1=\"380\" y1=\"94\" x2=\"380\" y2=\"112\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#afork)\"/>  <rect x=\"230\" y=\"114\" width=\"300\" height=\"50\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\"/>\n  <text x=\"380\" y=\"135\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">کیا خطرہ بڑا ہے، حقیقی AND</text>\n  <text x=\"380\" y=\"153\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12.5\" font-family=\"sans-serif\">کسی چیز کا میں بالکل ٹھیک نام دے سکتا ہوں؟</text>  <line x1=\"300\" y1=\"164\" x2=\"180\" y2=\"200\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#afork)\"/>\n  <text x=\"205\" y=\"186\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"12\" font-family=\"sans-serif\">نہیں / یقین نہیں۔</text>\n  <line x1=\"460\" y1=\"164\" x2=\"580\" y2=\"200\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#afork)\"/>\n  <text x=\"560\" y=\"186\" text-anchor=\"middle\" fill=\"#dd8452\" font-size=\"12\" font-family=\"sans-serif\">جی ہاں، واضح طور پر</text>  <rect x=\"60\" y=\"204\" width=\"240\" height=\"92\" rx=\"10\" fill=\"#16241b\" stroke=\"#55a868\"/>\n  <text x=\"180\" y=\"232\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">پوزیشن کاٹ دیں۔</text>\n  <text x=\"180\" y=\"256\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">کم پکڑو، یا باہر نکلو۔ کوئی پریمیم نہیں،</text>\n  <text x=\"180\" y=\"274\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">کوئی میعاد ختم نہیں، سرمائے کو آزاد کرتا ہے۔</text>  <rect x=\"460\" y=\"204\" width=\"240\" height=\"92\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\"/>\n  <text x=\"580\" y=\"232\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">ایک ہیج پر غور کریں۔</text>\n  <text x=\"580\" y=\"256\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">صرف اس صورت میں جب آپ کو رکھنا ضروری ہے۔</text>\n  <text x=\"580\" y=\"274\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">پوزیشن اور قیمت منصفانہ ہے.</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">زیادہ تر ابتدائیوں کے لیے بائیں راستہ ہی جواب ہے۔ ہیجنگ ایک تنگ استثناء ہے، طے شدہ نہیں۔</figcaption>\n</figure><h3 id=\"do-not-hedge-if\">NOT ہیج کریں اگر...</h3>\n<p>اس فہرست کو نیچے چلائیں۔ اگر کوئی لائن درست ہے تو، ہیج شاید آج غلط ٹول ہے۔</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> جس نقصان سے آپ ڈرتے ہیں۔ <strong>زندہ رہنے کے قابل</strong> - غیر آرام دہ، لیکن آپ کے مقاصد کے لئے خطرناک نہیں.</li>\n<li><input disabled=\"\" type=\"checkbox\"> آپ ایک ہیں <strong>طویل مدتی SIP خریدار</strong> اور فالس آپ کو سستے یونٹ خریدنے دیتے ہیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> پوزیشن ہے <strong>چھوٹا</strong> - آپ اس کی بجائے سائز کم کر سکتے ہیں یا اسے بند کر سکتے ہیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> اصل ڈرائیور ہے۔ <strong>خوف یا خوفناک سرخی؟</strong>ایک مخصوص، ماپا خطرہ نہیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> دی <strong>پریمیم کھڑی ہے</strong> اس زوال کے نسبت جس کی آپ اصل میں توقع کرتے ہیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> آپ <strong>نام نہیں دے سکتے</strong> بالکل جس کے خلاف آپ حفاظت کر رہے ہیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> پوزیشن کاٹنا پریشانی کو دور کرے گا۔ <strong>زیادہ سستا</strong> اسے ہیج کرنے کے مقابلے میں.</li>\n</ul>\n<p>یہ تعلیم ہے، ذاتی مشورے نہیں - یہ سوچنے کا طریقہ ہے، آپ کے پیسے کے بارے میں کوئی اصول نہیں۔</p>\n<h2 id=\"how-it-differs-by-who-you-are\">یہ کس طرح مختلف ہے کہ آپ کون ہیں۔</h2>\n<p>\"ڈونٹ اوور ہیج\" پیغام آپ کی سیٹ کے لحاظ سے مختلف طریقے سے اترتا ہے۔ ایک طویل مدتی سرمایہ کار اور آپشن بیچنے والا ایک ہی کھیل نہیں کھیل رہے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>عام طور پر NOT کو ہیج کرنا چاہیے جب...</th>\n<th>کلینر متبادل</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار / SIP</td>\n<td>افق برسوں دور ہے۔ زوال مواقع خرید رہے ہیں۔</td>\n<td>ڈپس پر خریدتے رہیں؛ ان کے لیے نقد رقم رکھیں</td>\n</tr>\n<tr>\n<td>اسٹاک تاجر</td>\n<td>پوزیشن چھوٹی ہے اور سٹاپ لاس پہلے ہی نقصان کو پورا کر دیتا ہے۔</td>\n<td>سٹاپ اور سائز نیچے کا استعمال کریں؛ آپشن پریمیم کو چھوڑ دیں۔</td>\n</tr>\n<tr>\n<td>F&amp;O (فیوچر) تاجر</td>\n<td>پریشانی کا مطلب صرف یہ ہے کہ پوزیشن بہت بڑی ہے۔</td>\n<td>بہت کم کریں؛ ایک چھوٹی پوزیشن ہیج ہے</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>خطرے کی وضاحت نہیں کی گئی ہے اور ہیج صحیح معنوں میں دم کو نہیں روک سکتا</td>\n<td>سائز اتنا ہے کہ ایک برا دن آپ کا صفایا نہیں کر سکتا۔ طے شدہ رسک اسپریڈز فروخت کریں۔</td>\n</tr>\n</tbody></table>\n<p>پیٹرن پر توجہ دیں۔ وقف شدہ بیچنے والے کے علاوہ ہر کسی کے لیے، ایماندار \"ہیج\" عام طور پر چھوٹا سائز یا اسٹاپ ہوتا ہے، خریدا ہوا آپشن نہیں۔ ہیجنگ بنیادی طور پر اپنا مقام حاصل کرتا ہے جب آپ کے پاس ایک بڑا، واضح طور پر نام کا خطرہ ہوتا ہے جو آپ کو حقیقی طور پر کتابوں پر رکھنا چاہیے۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>یہ باب اوور ہیجنگ کے خلاف بحث کرتا ہے، لیکن دلیل کی حدود ہوتی ہیں، اور ان کو نظر انداز کرنا اس کی اپنی غلطی ہے۔</p>\n<p>یہ ناکام ہوجاتا ہے جب منفی پہلو ہوتا ہے۔ <em>نہیں</em> زندہ رہنے کے قابل ایک مرتکز پوزیشن، ایک بڑی لیوریجڈ کتاب، یا کسی ایسے ہولڈنگ پر ایک معروف واقعہ جس سے آپ باہر نہیں نکل سکتے - یہ بالکل اسی وقت ہوتے ہیں جب ہیج اس کی قیمت کے قابل ہو۔ \"ہیج نہ کریں\" چھوٹے، زندہ رہنے والے، مبہم خطرات کے لیے مشورہ ہے، نہ کہ حقیقی، سائز والے، ناموں کے لیے۔</p>\n<p>یہ آپشن بیچنے والوں کے لئے ناکام ہوجاتا ہے جو دم کے خطرے کا سامنا کرتے ہیں۔ کسی ننگے بیچنے والے کو \"صرف ہیج نہ کرو\" بتانا خطرناک ہو سکتا ہے، کیونکہ ان کا نایاب برا دن وہ ہوتا ہے جو انہیں مٹا دیتا ہے۔ ان کے لیے، ایک کھڑا دم ہیج یا سختی سے متعین خطرے والے ڈھانچے بقا ہو سکتے ہیں، ضائع نہیں۔</p>\n<p>یہ ناکام ہوجاتا ہے اگر \"پوزیشن کاٹنا\" حقیقت میں دستیاب نہیں ہے - ایک غیر قانونی اسٹاک، ایک لاک ان ہولڈنگ، ایک کاروباری نمائش جسے آپ آسانی سے بند نہیں کرسکتے ہیں۔ جب آپ خطرے کو براہ راست کم نہیں کر سکتے ہیں، تو ہیج کے لیے ادائیگی ہی واحد آپشن رہ سکتا ہے۔</p>\n<p>اور یہ ناکام ہوجاتا ہے اگر آپ \"ہیج نہ کریں\" کو \"خطرے کو نظر انداز کریں\" کے طور پر پڑھتے ہیں۔ بات یہ تھی کہ کبھی لاپرواہ نہ ہو۔ یہ ایک ابتدائی کے لئے ہے، <em>صحیح سائز اور صبر</em> عام طور پر مارو <em>تحفظ خریدنا</em> - اور خوف سے خریدا گیا ہیج بالکل بھی رسک مینجمنٹ نہیں ہے۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> موٹے طور پر طے شدہ ہیج لاگت ایک چھوٹے پورٹ فولیو کو بڑے سے زیادہ کیوں نقصان پہنچاتی ہے؟</summary><p>کیونکہ تحفظ کی لاگت آپ کے اکاؤنٹ سے کم نہیں ہوتی ہے۔ وہی 1,000-1,500 روپے کا پریمیم 20,00,000 روپے کی کتاب کا ایک چھوٹا ٹکڑا ہے لیکن 80,000 روپے کی کتاب کا ایک بڑا ٹکڑا - ایک چھوٹے اکاؤنٹ پر یہ پورے سال کا منافع کھا سکتا ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> طویل مدتی SIP کو ہیج کرنا عام طور پر غلط اقدام کیوں ہے؟</summary><p>A SIP کام کرتا ہے۔ <em>کیونکہ</em> قیمتیں گرنے پر یہ زیادہ یونٹ خریدتا ہے۔ ہیجنگ اس فائدے کو منسوخ کرنے کے لیے ادائیگی کرتی ہے۔ ایک ہدف سالوں کے فاصلے پر، مارکیٹ میں گرنا ایک رعایت ہے، خطرہ نہیں - اس طرح گرنا اس وقت ہوتا ہے جب جمع کرنے والا خریدتا ہے، نہ کہ جب وہ چھپ جاتا ہے۔</p>\n</details><details>\n<summary><strong>3.</strong> \"جذباتی ہیجنگ\" کیا ہے اور یہ ایک جال کیوں ہے؟</summary><p>یہ کسی مخصوص، ناپے گئے خطرے کو پورا کرنے کے بجائے خوفناک احساس کو پرسکون کرنے کے لیے تحفظ خرید رہا ہے۔ پریمیم حقیقی اور بار بار چلنے والا ہے۔ \"خطرہ\" صرف ایک موڈ ہے۔ یہ آپ کے اعصاب کی حفاظت کرتا ہے، آپ کے سرمائے کی نہیں، اور یہ آپ کو ہر بار بل دیتا ہے۔</p>\n</details><details>\n<summary><strong>4.</strong> ایک ابتدائی شخص ایک چھوٹی سی پوزیشن رکھتا ہے جو انہیں پریشان کرتا ہے۔ عام طور پر اسے ہیج کرنے سے زیادہ صاف کیا ہے؟</summary><p>بس کم رکھیں، یا اسے بند کریں۔ پوزیشن کو کم کرنے میں کوئی اضافی لاگت نہیں آتی، سرمائے کو آزاد کرتا ہے، اور بالکل وہی ایکسپوژر ہٹا دیتا ہے جس سے آپ پریشان تھے - بغیر کسی پریمیم کے، نہ ختم ہونے کے، اور نہ ہی ٹریک کرنے کے لیے کوئی دوسرا آلہ۔</p>\n</details><details>\n<summary><strong>5.</strong> اگر آپ بالکل وہی نام نہیں دے سکتے جس کے خلاف آپ حفاظت کر رہے ہیں، تو یہ آپ کو کیا بتاتا ہے؟</summary><p>کہ آپ کو شاید ابھی تک ہیج نہیں کرنا چاہئے۔ ایک ہیج کو ایک مخصوص خطرے کی طرف اشارہ کرنا ہوتا ہے - یہ اسٹاک، یہ واقعہ، یہ فرق - تاکہ آپ اسے سائز اور منتخب کرسکیں۔ مبہم خوف مبہم، مہنگا، بری طرح سے مماثل تحفظ کا باعث بنتا ہے۔</p>\n</details>\n","toc":[{"level":2,"text":"ہیجنگ ایک ٹول ہے، اضطراری نہیں۔","id":"hedging-is-a-tool-not-a-reflex"},{"level":2,"text":"چھ بار جواب ہے \"ہیج نہ کرو\"","id":"six-times-the-answer-is-do-not-hedge"},{"level":2,"text":"کلینر اقدام: ہیج کے بجائے کاٹ دیں۔","id":"the-cleaner-move-cut-instead-of-hedge"},{"level":3,"text":"NOT ہیج کریں اگر...","id":"do-not-hedge-if"},{"level":2,"text":"یہ کس طرح مختلف ہے کہ آپ کون ہیں۔","id":"how-it-differs-by-who-you-are"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"11":{"html":"<p>میرا کے پاس 5,00,000 روپے کا پرسکون، طویل مدتی پورٹ فولیو ہے۔ پچھلے سال کے شروع میں ایک ڈراؤنی سرخی نے اسے جھنجھوڑ دیا، اس لیے اس نے ذمہ دارانہ کام کیا: اس نے \"بہتر نیند\" کے لیے ہر ماہ ایک ماہ کاNIFTYخریدنا شروع کیا۔ مارکیٹ ایک طرف چلی گئی اور سارا سال تھوڑا سا اوپر چلا گیا - کوئی حادثہ، کوئی ڈرامہ نہیں۔ سال کے آخر میں اس نے اپنے ادا کیے گئے ہر پریمیم کو جمع کر لیا اور پیلا ہو گیا۔ اس نے ایک ایسے پورٹ فولیو کی حفاظت کے لیے تقریباً 90,000 روپے خرچ کیے تھے جو کبھی سنگین خطرے میں نہیں تھا۔ انشورنس اصلی تھی۔ بل بھی ایسا ہی تھا - اور اس نے خاموشی سے اس کے زیادہ تر فوائد کھا لیے تھے۔</p>\n<p>یہی اس باب کا سبق ہے۔ ایک ہیج مفت حفاظت نہیں ہے. یہ ایک پروڈکٹ ہے جسے آپ قیمت کے ٹیگ کے ساتھ خریدتے ہیں، اور آپ کو اس کی قیمت ادا کرنے سے پہلے اسے پڑھ لینا چاہیے۔</p>\n<h2 id=\"a-hedge-is-a-product-and-it-has-a-price\">ایک ہیج ایک مصنوعات ہے، اور اس کی ایک قیمت ہے</h2>\n<p>پچھلے دو ابواب میں آپ نے دیکھا کہ ہیجنگ کیا کرتی ہے اور آپ اسے کب چاہیں گے۔ اب ایماندار حصہ: ہر ہیج پر پیسہ خرچ ہوتا ہے، اور لاگت ابتدائی کی توقع سے زیادہ جگہوں پر ظاہر ہوتی ہے۔ آپ کے سکوٹر پر انشورنس کا ایک پریمیم ہے جسے آپ دیکھ سکتے ہیں۔ مارکیٹ کے ہیج میں ایک پریمیم بھی ہوتا ہے، اس کے علاوہ مٹھی بھر چھوٹے چارجز جو کونوں میں چھپ جاتے ہیں۔ انہیں شامل کریں اور ایک \"سستا\" ہیج اکثر سستا نہیں ہوتا ہے۔ نقطہ آپ کو ہیجنگ سے ڈرانا نہیں ہے - یہ آپ کو ایک خریدار بنانا ہے جو کل بل جانتا ہے، لہذا آپ اسے صرف اس وقت ادا کرتے ہیں جب خطرہ حقیقی طور پر بڑا اور حقیقی طور پر حقیقی ہو۔</p>\n<h2 id=\"the-eight-costs-hiding-in-every-hedge\">آٹھ اخراجات ہر ہیج میں چھپے ہوئے ہیں۔</h2>\n<p>ایک حفاظتی پوٹ - سب سے آسان ہیج، ایک آپشن جو آپ کو ادائیگی کرتا ہے اگر مارکیٹ گرتی ہے - تقریباً آٹھ الگ الگ اخراجات اٹھاتی ہے۔ کچھ واضح ہیں۔ زیادہ تر beginners صرف پہلا نوٹس.</p>\n<p><strong>1. آپشن پریمیم۔</strong> ڈال کی پیشگی قیمت۔ یہ بڑا ہے۔ ایک ماہ کا پوٹ جو آج کی سطح کے قریب حفاظت کرتا ہے عام طور پر اس قدر کا تقریباً 1.5% سے 2% خرچ ہوتا ہے جس کی آپ حفاظت کر رہے ہیں۔ 5,00,000 روپے پر جو کہ تقریباً 7,500 سے 10,000 روپے ہے - جس لمحے آپ خریدتے ہیں، بازار کبھی گرتا ہے یا نہیں۔</p>\n<p><strong>2. وقت کی خرابی (تھیٹا)۔</strong> ایک طویل آپشن ہر ایک دن تھوڑی سی قدر کھو دیتا ہے، بس وقت گزرنے سے۔ وہ پریمیم جو آپ نے ادا کیا تھا وہ ختم ہو جاتا ہے جیسے جیسے ختم ہو جاتا ہے۔ اگر کریش کبھی نہیں آتا ہے، تو پوٹ بیکار ختم ہو جاتا ہے اور پورا پریمیم ایک حقیقی نقصان بن جاتا ہے۔ تھیٹا صرف اسی پریمیم کی روزانہ کی ڈرپ ہے۔</p>\n<p><strong>3. بولی پوچھنا پھیل گیا۔</strong> آپ اعلی \"پوچھ\" قیمت پر خریدتے ہیں اور، جب آپ باہر نکلتے ہیں، تو آپ کم \"بولی\" قیمت پر فروخت کرتے ہیں۔ ان کے درمیان فرق ایک قیمت ہے جسے آپ دو بار ادا کرتے ہیں - ایک بار داخل ہونا، ایک بار باہر نکلنا - اور یہ دور کی تاریخ یا کم تجارتی ہڑتالوں پر وسیع ہے۔</p>\n<p><strong>4. بروکریج، STT اور دیگر چارجز۔</strong> ہر ہیج لیگ ایک آرڈر ہے، اور آرڈرز میں بروکریج، ایکسچینج فیس، GST اور سیکیورٹیز ٹرانزیکشن ٹیکس ہوتا ہے۔ انفرادی طور پر چھوٹا، لیکن حقیقی، اور جب بھی آپ ہیج کو نئے مہینے میں رول کرتے ہیں تو وہ دہراتے ہیں۔</p>\n<p><strong>5. پھسلنا۔</strong> جو قیمت آپ دیکھتے ہیں اور جو قیمت آپ کو درحقیقت ملتی ہے وہ ایک جیسی نہیں ہوتی، خاص طور پر تیز یا پتلی مارکیٹ میں - جو بالکل اس وقت ہوتی ہے جب آپ تحفظ خریدنے کا رجحان رکھتے ہیں۔ فرق پھسلن کا ہے، پھیلاؤ کے اوپر ایک پوشیدہ ٹیکس۔</p>\n<p><strong>6. بنیاد اور ٹریکنگ رسک۔</strong> اگر آپ NIFTY انڈیکس کے ساتھ مخصوص اسٹاک کی ایک ٹوکری کو ہیج کرتے ہیں، تو انڈیکس اور آپ کے اسٹاک لاک اسٹپ میں منتقل نہیں ہوتے ہیں۔ آپ کے اسٹاک کے گرنے کے دوران انڈیکس برقرار رہ سکتا ہے - لہذا جب آپ کے پورٹ فولیو میں خون بہہ رہا ہے تو آپ کا ہیج بہت کم ادائیگی کرتا ہے۔ یہ مماثلت بنیادی خطرہ ہے، اور اس کا مطلب ہے کہ آپ نے جس تحفظ کے لیے ادائیگی کی ہے وہ مکمل طور پر ختم نہیں ہو سکتی جب آپ کو ضرورت ہو۔</p>\n<p><strong>7. فیوچر ہیج میں مارجن باندھ دیا گیا ہے۔</strong> اگر آپ پوٹ خریدنے کے بجائے فیوچر کنٹریکٹ کو مختصر کرکے ہیج کرتے ہیں، تو آپ پریمیم ادا نہیں کرتے ہیں - لیکن آپ کو ایکسچینج کے ساتھ مارجن منی پارک کرنی ہوگی، اور وہ سرمایہ بلاک ہوجاتا ہے اور کہیں اور کام نہیں کرسکتا۔ شارٹ کے خلاف ایک تیز اقدام مارجن کال مڈ ہیج کو بھی متحرک کر سکتا ہے۔</p>\n<p><strong>8. الٹا چھوٹ گیا۔</strong> کچھ ہیجز، جیسے کالر یا ڈھکی ہوئی کال، اپنے فوائد کو محدود کرکے اپنی لاگت کو کم کرتے ہیں۔ آپ سستے تحفظ کے بدلے بڑے اپ-ویو کو ترک کر دیتے ہیں۔ اگر مارکیٹ میں تیزی آتی ہے تو \"بچت\" آپ کو اس پریمیم سے کہیں زیادہ خرچ کر سکتی ہے جس سے آپ نے گریز کیا تھا۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک اسٹیک شدہ بار جس میں پریمیم، بِڈ اسک اسپریڈ، بروکریج اور ٹیکسز، اور پھسلن سے ہیج کی کل ماہانہ لاگت ہوتی ہے، جو تقریباً 1.6 فیصد تک پہنچ جاتی ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ہیج بل جمع ہے - ایک ماہ، 5,00,000 روپے محفوظ</text>  <line x1=\"300\" y1=\"60\" x2=\"300\" y2=\"250\" stroke=\"#30363d\" stroke-width=\"1\"/>\n  <line x1=\"300\" y1=\"250\" x2=\"720\" y2=\"250\" stroke=\"#30363d\" stroke-width=\"1\"/>  <rect x=\"320\" y=\"92\" width=\"300\" height=\"34\" rx=\"6\" fill=\"#4c72b0\"/>\n  <text x=\"470\" y=\"114\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12.5\" font-family=\"sans-serif\">آپشن پریمیم 7,500 روپے</text>  <rect x=\"320\" y=\"130\" width=\"60\" height=\"34\" rx=\"6\" fill=\"#dd8452\"/>\n  <text x=\"636\" y=\"152\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">بولی پوچھنے کا پھیلاؤ ~ 400 روپے</text>  <rect x=\"320\" y=\"168\" width=\"40\" height=\"34\" rx=\"6\" fill=\"#8172b3\"/>\n  <text x=\"636\" y=\"190\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">بروکریج + STT ~200 روپے</text>  <rect x=\"320\" y=\"206\" width=\"44\" height=\"34\" rx=\"6\" fill=\"#c44e52\"/>\n  <text x=\"636\" y=\"228\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">سلپیج ~ 200 روپے</text><p>  <text x=\"40\" y=\"78\" fill=\"#8b949e\" font-size=\"12\" font-family=\"sans-serif\">لاگت</text>\n  <text x=\"40\" y=\"262\" fill=\"#8b949e\" font-size=\"12\" font-family=\"sans-serif\">ڈھیر</text>\n  <rect x=\"40\" y=\"92\" width=\"230\" height=\"148\" rx=\"8\" fill=\"#11161d\" stroke=\"#37b3a4\"/>\n  <text x=\"155\" y=\"150\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">تمام میں</text>\n  <text x=\"155\" y=\"178\" text-anchor=\"middle\" fill=\"#37b3a4\" font-size=\"22\" font-weight=\"700\" font-family=\"sans-serif\">~ 8,300 روپے</text>\n  <text x=\"155\" y=\"206\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">تقریبا 1.6٪ / مہینہ</text>\n</svg></p>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">پریمیم صرف سرخی ہے۔ چھوٹے چارجز سب سے اوپر ہیں - اور ہر رول کو دہرائیں۔</figcaption>\n</figure><p>پریمیم اور تھیٹا ایک ہی رقم کے دو خیالات ہیں: تھیٹا وہ رفتار ہے جس پر آپ نے خاموشی سے ادا کیا ہوا پریمیم غائب ہو جاتا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 230\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک منحنی خطوط جس میں ایک طویل آپشن کی قدر کو ایک ماہ کے دوران پورے پریمیم سے صفر تک سلائیڈ کرتے ہوئے دکھایا گیا ہے کیونکہ وقت کے خاتمے میں تیزی آتی ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"230\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"28\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"15\" font-family=\"sans-serif\">وقت کا خاتمہ: اگر حادثہ کبھی نہیں آتا ہے تو پریمیم پگھل جاتا ہے۔</text>\n  <line x1=\"70\" y1=\"50\" x2=\"70\" y2=\"185\" stroke=\"#30363d\" stroke-width=\"1\"/>\n  <line x1=\"70\" y1=\"185\" x2=\"710\" y2=\"185\" stroke=\"#30363d\" stroke-width=\"1\"/>\n  <path d=\"M70,62 C 300,80 480,120 710,182\" fill=\"none\" stroke=\"#dd8452\" stroke-width=\"3\"/>\n  <circle cx=\"70\" cy=\"62\" r=\"4\" fill=\"#dd8452\"/>\n  <circle cx=\"710\" cy=\"182\" r=\"4\" fill=\"#c44e52\"/>\n  <text x=\"80\" y=\"58\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">پریمیم ادا کیا گیا: 7,500 روپے</text>\n  <text x=\"540\" y=\"174\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">میعاد ختم ہونے کی تاریخ: 0 روپے</text>\n  <text x=\"90\" y=\"205\" fill=\"#8b949e\" font-size=\"11.5\" font-family=\"sans-serif\">خریدیں۔</text>\n  <text x=\"640\" y=\"205\" fill=\"#8b949e\" font-size=\"11.5\" font-family=\"sans-serif\">میعاد ختم ہونے کا دن</text>\n  <text x=\"350\" y=\"205\" fill=\"#8b949e\" font-size=\"11.5\" font-family=\"sans-serif\">اختتام کے قریب زوال کی رفتار بڑھ جاتی ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">اگر مارکیٹ ساکت رہتی ہے تو، ایک طویل آپشن ہیج صفر پر بہہ جاتا ہے - اپنے آخری دنوں میں تیزی سے۔</figcaption>\n</figure><h2 id=\"a-worked-example-insuring-rs-5-00-000-for-a-month\">ایک کام کی مثال: ایک ماہ کے لیے 5,00,000 روپے کا بیمہ کرنا</h2>\n<p>کہتے ہیں کہ آپ انڈیکس پٹ کا استعمال کرتے ہوئے ایک ماہ کے لیے 5,00,000 روپے کے ایکویٹی پورٹ فولیو کی حفاظت کرنا چاہتے ہیں۔ یہ ہے مکمل بل، گول، مثالی نمبروں کے ساتھ - آپ کے حقیقی اعداد و شمار مارکیٹ اور آپ کی ہڑتال کے ساتھ مختلف ہوں گے۔</p>\n<table>\n<thead>\n<tr>\n<th>لاگت کی چیز</th>\n<th>یہ کیا ہے</th>\n<th>ایک ماہ کا روپیہ خرچ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>آپشن پریمیم (~1.5%)</td>\n<td>پوٹ خود - وہ تحفظ جو آپ خریدتے ہیں۔</td>\n<td>7,500 روپے</td>\n</tr>\n<tr>\n<td>بولی پوچھنا پھیل گیا۔</td>\n<td>داخلے پر اور دوبارہ باہر نکلنے پر ادائیگی کی گئی۔</td>\n<td>~ 400 روپے</td>\n</tr>\n<tr>\n<td>بروکریج + ایکسچینج + GST</td>\n<td>ہیج آرڈر ٹانگوں پر چارجز</td>\n<td>150 روپے</td>\n</tr>\n<tr>\n<td>STT اور دیگر قانونی فیس</td>\n<td>آپشن لین دین پر ٹیکس</td>\n<td>~ 100 روپے</td>\n</tr>\n<tr>\n<td>پھسلنا</td>\n<td>اسکرین کی قیمت اور بھرنے کے درمیان فرق</td>\n<td>~200 روپے</td>\n</tr>\n<tr>\n<td><strong>ایک مہینے کے لیے سب</strong></td>\n<td><strong>تحفظ کی کل لاگت</strong></td>\n<td><strong>~8,350 روپے (تقریباً 1.7%)</strong></td>\n</tr>\n</tbody></table>\n<p>لہذا ایک مہینے کے کور کی حقیقی قیمت 1.7% کے قریب ہے جو کہ اکیلے پریمیم نے تجویز کی ہے۔ کسی معروف، خوفناک واقعے سے پہلے اسے ایک بار ادا کریں اور یہ معقول انشورنس ہے۔ لیکن دیکھیں کہ کیا ہوتا ہے اگر آپ اسے ہر ماہ کرتے ہیں، میرا کی طرح: تقریباً 1.7% ایک مہینے میں، بارہ بار رول کیا جاتا ہے، سال میں 18% سے 20% کے آرڈر پر ہوتا ہے - یہاں تک کہ ایک سال میں جہاں کچھ برا نہیں ہوتا ہے۔ آپ اپنے پورٹ فولیو کی قیمت کا پانچواں حصہ اس زوال کے خلاف بیمہ کر سکتے ہیں جو کبھی نہیں آتا۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ہر ہیج کا ایک بل ہوتا ہے، اور پریمیم صرف ٹاپ لائن ہے۔ تمام لاگت - پریمیم، ٹائم ڈیکی، اسپریڈ، چارجز، سلپیج، بیس رسک، مسدود مارجن اور کیپ اپ سائڈ - وہی ہے جو آپ اصل میں ادا کرتے ہیں۔ تحفظ خریدنے سے پہلے پورا بل پڑھیں۔</p>\n</div></div>\n<h2 id=\"protection-versus-cost-when-the-bill-is-worth-paying\">تحفظ بمقابلہ لاگت: جب بل ادا کرنے کے قابل ہو۔</h2>\n<p>ایک ہیج کی قیمت صرف اس وقت ہوتی ہے جب آپ جو خطرہ ہٹا رہے ہیں وہ اس لاگت کے مقابلے میں حقیقی اور بڑا دونوں ہوتا ہے۔ کسی بڑے پورٹ فولیو کو حقیقی، قریب المدت خطرے سے بچانے کے لیے 1.7% ادا کرنا ہوشیار ہو سکتا ہے۔ مبہم پریشانی کی وجہ سے ہر ماہ اسی 1.7% کی ادائیگی، جب کوئی خاص خطرہ نظر نہیں آتا ہے، بس آہستہ آہستہ آپ کے فوائد کو دور کرنا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 250\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک بیلنس پیمانہ جس کا وزن ہٹائے جانے والے خطرے کے سائز کے مقابلے میں ایک چھوٹی مخصوص ہیج لاگت کا ہوتا ہے، خطرے کے بڑے ہونے پر اس کے قابل ہونے کی طرف اشارہ کرتا ہے اور خطرہ چھوٹا ہونے پر اس کے قابل نہیں ہوتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"250\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"28\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"15\" font-family=\"sans-serif\">جب ہیج اس کی قیمت کے قابل ہے۔</text>  <rect x=\"40\" y=\"60\" width=\"330\" height=\"160\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\"/>\n  <text x=\"205\" y=\"84\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13.5\" font-weight=\"700\" font-family=\"sans-serif\">اس کے قابل</text>\n  <rect x=\"70\" y=\"100\" width=\"90\" height=\"80\" rx=\"6\" fill=\"#4c72b0\"/>\n  <text x=\"115\" y=\"146\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-family=\"sans-serif\">لاگت</text>\n  <rect x=\"230\" y=\"104\" width=\"110\" height=\"92\" rx=\"6\" fill=\"#c44e52\"/>\n  <text x=\"285\" y=\"146\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-family=\"sans-serif\">بڑا، حقیقی</text>\n  <text x=\"285\" y=\"164\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-family=\"sans-serif\">خطرہ</text>\n  <text x=\"205\" y=\"208\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11.5\" font-family=\"sans-serif\">چھوٹا بل ایک بڑا، قریبی مدت کے خطرے کو دور کر دیتا ہے۔</text>  <rect x=\"390\" y=\"60\" width=\"330\" height=\"160\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\"/>\n  <text x=\"555\" y=\"84\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13.5\" font-weight=\"700\" font-family=\"sans-serif\">اس کے قابل نہیں۔</text>\n  <rect x=\"420\" y=\"100\" width=\"90\" height=\"80\" rx=\"6\" fill=\"#4c72b0\"/>\n  <text x=\"465\" y=\"146\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-family=\"sans-serif\">لاگت</text>\n  <rect x=\"585\" y=\"150\" width=\"95\" height=\"40\" rx=\"6\" fill=\"#dd8452\"/>\n  <text x=\"632\" y=\"174\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-family=\"sans-serif\">مبہم فکر</text>\n  <text x=\"555\" y=\"208\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11.5\" font-family=\"sans-serif\">ایک ہی بل، بار بار ادا کیا، بغیر کسی خطرے کے</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ایک ہی قیمت کا ٹیگ۔ پیمانے کے دوسری طرف خطرہ وہی ہے جو فیصلہ کرتا ہے کہ آیا یہ ادائیگی کے قابل ہے۔</figcaption>\n</figure>\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>دو کلاسک غلطیاں ہمیشہ کے لیے ہیجز کو رولنگ کر رہی ہیں اور تمام لاگت کو نظر انداز کر رہی ہیں۔ مہینہ بہ مہینہ \"صرف اس صورت میں\" رول کرنے سے تھیٹا خون بہہ جاتا ہے اور ہر سائیکل کو چارج کیا جاتا ہے، لہذا ایک پرسکون، بڑھتا ہوا سال اب بھی ایک بڑے سوراخ کے ساتھ ختم ہوتا ہے - بالکل میرا کا 90,000 روپے۔ اور صرف پریمیم (\"یہ صرف 1.5% ہے\") کا حوالہ دینا اسپریڈ، سلپیج، ٹیکسز اور کیپ اپ سائڈ کو چھپاتا ہے جو حقیقی لاگت کو زیادہ کرتا ہے۔ بہتر اقدام: مخصوص خطرے اور اس کی کھڑکی کو نام دیں، پورے بل کی قیمت لگائیں، اور صرف تب ہی ہیج کریں جب خطرہ حقیقی اور بڑا ہو - بصورت دیگر اس کے بجائے صرف پوزیشن کو تراشنے پر غور کریں۔</p>\n</div></div>\n<p>یہ تعلیم ہے، کسی مخصوص تجارت کے بارے میں مشورہ نہیں۔ یہاں کے نمبر لاگت کی شکل سکھانے کے لیے مثالیں ہیں، نہ کہ کسی خاص ہیج کو خریدنے یا چھوڑنے کی سفارش۔</p>\n<h2 id=\"how-the-cost-of-hedging-differs-by-seat\">ہیجنگ کی قیمت سیٹ کے لحاظ سے کیسے مختلف ہوتی ہے۔</h2>\n<p>آپ جس سیٹ پر بیٹھتے ہیں اس کے لحاظ سے ایک ہی قیمت مختلف ہوتی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>جہاں قیمت سب سے زیادہ کاٹتی ہے۔</th>\n<th>دیانتدار کال</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>پریمیم اور بار بار رولز مستحکم SIP فوائد کو ختم کرتے ہیں۔</td>\n<td>عام طور پر لمبے افق کو ہیج نہ کریں۔ فالس کی سواری کریں، یا صرف کسی معروف بڑے ایونٹ کے ارد گرد ہیج کریں۔</td>\n</tr>\n<tr>\n<td>فعال (نقد) تاجر</td>\n<td>ہر حفاظتی ٹانگ پر پھیلاؤ، پھسلنا اور دلالی</td>\n<td>پوٹ خریدنے کے مقابلے میں پوزیشن کو کاٹنا یا سائز کم کرنا اکثر سستا ہوتا ہے۔</td>\n</tr>\n<tr>\n<td>F&amp;O (فیوچر) تاجر</td>\n<td>ہیج ٹانگ اور بنیاد کے خطرے پر مارجن کو روک دیا گیا ہے۔</td>\n<td>اس اقدام کے خلاف سرمایہ باندھنے کا وزن کریں جس کا آپ کو خوف ہے۔ ایک تنگ سٹاپ سستا ہو سکتا ہے</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>تحفظ خریدنا ان کے جمع کردہ پریمیم کو کھا جاتا ہے۔</td>\n<td>ایک حفاظتی بازو آمدنی کو کم کرتا ہے لیکن دم کے نقصان کو محدود کرتا ہے - قیمت فروخت کرنے سے پہلے دونوں طرف</td>\n</tr>\n</tbody></table>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>ہیج کی لاگت کو پڑھنا ضروری ہے، لیکن صرف لاگت کی گنتی آپ کو گمراہ کر سکتی ہے۔</p>\n<p>یہ اس وقت ناکام ہو جاتا ہے جب آپ بل کو آپ کے تحفظ کے بارے میں بات کرنے دیتے ہیں جس کی آپ کو واقعی ضرورت ہے۔ ایک بڑے پورٹ فولیو کے لیے ایک حقیقی، بڑا، قریب المدت خطرہ ادائیگی کا جواز پیش کر سکتا ہے۔ ایک قابل قدر ہیج کو چھوڑنا صرف اس لیے کہ \"1.7% بہت زیادہ محسوس ہوتا ہے\" یہ ہے کہ کس طرح ایک چھوٹا پریمیم تباہ کن نقصان میں بدل جاتا ہے۔</p>\n<p>جب نمبروں کا اندازہ لگایا جاتا ہے تو یہ ناکام ہوجاتا ہے۔ حقیقی پریمیم اتار چڑھاؤ کے ساتھ آگے بڑھتے ہیں - تحفظ ڈرامائی طور پر زیادہ مہنگا ہو جاتا ہے جب خوف زیادہ ہوتا ہے اور حادثے کا امکان ہوتا ہے۔ پُرسکون اوقات میں 1.5% گھبراہٹ میں 4% یا 5% ہو سکتا ہے، اس لیے ان حالات کے لیے ہیج کی قیمت لگائیں جن میں آپ واقعی ہیں۔</p>\n<p>یہ اس وقت ناکام ہو جاتا ہے جب بنیاد کا خطرہ آپ کے اندازے سے زیادہ ہوتا ہے۔ چھوٹے یا مڈ کیپ اسٹاکس کے پورٹ فولیو پر ایک انڈیکس ہیج تقریباً کچھ نہیں دے سکتا جب کہ آپ کی ہولڈنگز سخت گرتی ہیں۔ ایک سستا ہیج جو فائر نہیں کرتا ہے وہ بچت نہیں ہے - یہ دو بار ضائع ہونے والی رقم ہے۔</p>\n<p>اور یہ sizing کے متبادل کے طور پر ناکام ہو جاتا ہے۔ اگر کوئی پوزیشن اتنی بڑی ہے کہ سونے کا واحد طریقہ ہر ماہ اسے ہیج کرنا ہے، تو گہرا مسئلہ پوزیشن کے سائز کا ہے، نہ کہ گم شدہ ہیج - اور سب سے سستا، صاف ترین تحفظ اکثر پہلے جگہ پر کم ہوتا ہے۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> آپشن پریمیم کے علاوہ، حفاظتی پوٹ میں چھپے تین دیگر اخراجات کا نام دیں۔</summary><p>ان میں سے کوئی بھی تین: ٹائم ڈیک (تھیٹا)، داخلے اور باہر نکلنے پر بولی کا پھیلاؤ، بروکریج اور ایکسچینج چارجز، STT اور قانونی فیس، پھسلن، بنیاد یا ٹریکنگ رسک، فیوچر ہیج پر مارجن مسدود، اور کیپ سے الٹا کھو جانا۔ پریمیم صرف سرخی کی قیمت ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> میرا کے پورٹ فولیو میں سارا سال تھوڑا سا اضافہ ہوا، پھر بھی ہیجنگ پر اسے تقریباً 90,000 روپے کا خرچہ آیا۔ کیسے؟</summary><p>اس نے 5,00,000 روپے کے پورٹ فولیو کے تقریباً 1.5% سے 1.7% کے حساب سے ہر ماہ ایک ماہ کا تازہ پوٹ خریدا۔ ادائیگی کے لیے بغیر کسی حادثے کے بارہ بار رول کیا گیا، پریمیم اور چارجز پورٹ فولیو کی قیمت کے تقریباً پانچویں حصے تک شامل کیے گئے - تھیٹا اس کے لیے کچھ بھی نہیں دکھایا گیا۔</p>\n</details><details>\n<summary><strong>3.</strong> بنیادی خطرہ کیا ہے، اور اس سے ہیج کی قیمت اس سے زیادہ کیوں ہوتی ہے؟</summary><p>بنیادی خطرہ آپ کے ہیج اور جو آپ کے پاس ہے اس کے درمیان مماثلت نہیں ہے - مثال کے طور پر، مخصوص اسٹاک کی ٹوکری کے مقابلے میں ایک NIFTY انڈیکس۔ آپ کے اسٹاک کے گرنے کے دوران انڈیکس برقرار رہ سکتا ہے، لہذا جب آپ کو اس کی سب سے زیادہ ضرورت ہو تو ہیج بہت کم ادائیگی کرتا ہے۔ آپ نے تحفظ کے لیے ادائیگی کی جو مکمل طور پر فائر نہیں ہوئی۔</p>\n</details><details>\n<summary><strong>4.</strong> ایک ماہ کے تحفظ کے لیے تقریباً 1.7% ادائیگی کب ایک معقول قیمت ہے؟</summary><p>جب خطرے کو ہٹایا جا رہا ہے تو اس لاگت کے مقابلے میں حقیقی اور بڑا دونوں طرح کا ہوتا ہے - مثال کے طور پر، ایک معروف، قریب المدت واقعہ جو ایک بڑے پورٹ فولیو کو بری طرح نقصان پہنچا سکتا ہے۔ مبہم پریشانی کے باعث ہر ماہ اتنی ہی رقم ادا کرنا، جس میں کوئی خاص خطرہ نظر نہیں آتا، آہستہ آہستہ اپنے فائدے ختم کر دیں۔</p>\n</details><details>\n<summary><strong>5.</strong> ایک ابتدائی کا کہنا ہے کہ \"ہیج سستا ہے، یہ صرف 1.5% پریمیم ہے۔\" اس میں کیا حرج ہے؟</summary><p>پریمیم صرف ٹاپ لائن ہے۔ تمام لاگت میں بولی پوچھنے کا اسپریڈ، بروکریج، STT، سلپیج، کوئی بھی بنیادی خطرہ، مسدود مارجن اور کیپ اپ سائڈ بھی شامل ہے۔ صرف پریمیم کی گنتی اصلی بل کو کم کرتی ہے - اور وہ بل ہر بار جب ہیج رول ہوتا ہے دہرایا جاتا ہے۔</p>\n</details>\n","toc":[{"level":2,"text":"ایک ہیج ایک مصنوعات ہے، اور اس کی ایک قیمت ہے","id":"a-hedge-is-a-product-and-it-has-a-price"},{"level":2,"text":"آٹھ اخراجات ہر ہیج میں چھپے ہوئے ہیں۔","id":"the-eight-costs-hiding-in-every-hedge"},{"level":2,"text":"ایک کام کی مثال: ایک ماہ کے لیے 5,00,000 روپے کا بیمہ کرنا","id":"a-worked-example-insuring-rs-5-00-000-for-a-month"},{"level":2,"text":"تحفظ بمقابلہ لاگت: جب بل ادا کرنے کے قابل ہو۔","id":"protection-versus-cost-when-the-bill-is-worth-paying"},{"level":2,"text":"ہیجنگ کی قیمت سیٹ کے لحاظ سے کیسے مختلف ہوتی ہے۔","id":"how-the-cost-of-hedging-differs-by-seat"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"12":{"html":"<p>میرا کے پاس ایک ہیITسٹاک کے 6 لاکھ روپے ہیں۔ اس نے اسے تین سال تک برقرار رکھا اور اب بھی اس کاروبار پر یقین رکھتی ہے۔ لیکن کمپنی جمعرات کو کمائی کی اطلاع دیتی ہے، مارکیٹ پریشان ہے، اور ایک برا نمبر ایک ہی دن میں 15 فیصد کم کر سکتا ہے۔ ایک دوست اس سے کہتی ہے کہ \"بس اسے اختیارات کے ساتھ ہیج کریں\"۔ وہ آپشن چین کھولتی ہے، ہڑتالوں اور یونانی خطوط کی دیوار دیکھتی ہے جس سے وہ کبھی نہیں ملی، اور جم جاتی ہے۔ آخر میں وہ سب سے آسان کام کرتی ہے: وہ اپنی ہولڈنگ کا ایک تہائی حصہ بیچتی ہے اور ایونٹ پر نقد رقم جمع کرتی ہے۔ اس رات اس کی نیند لوٹ آئی۔ میرا نے جو کیا وہ ایک ہیج تھا - وہاں سب سے صاف ستھرا میں سے ایک ہے۔</p>\n<p>آخری چند ابواب میں اس بات کا احاطہ کیا گیا تھا کہ ہیج واقعی کیا کرتا ہے، کب اس کی ادائیگی کے قابل ہے، اور کب نہیں ہے۔ یہ باب ٹول باکس ہے۔ ہم سب سے زیادہ ملوث افراد تک خطرے کو کم کرنے کے آسان ترین، سستے طریقوں سے چلتے ہیں، ہر ایک کے لیے تصویر اور تجارت کے ساتھ۔ قیمتوں کا کوئی فارمولہ نہیں۔ بس ٹول کیا کرتا ہے اور کس کے لیے مناسب ہے۔</p>\n<h2 id=\"a-ladder-of-hedges-simplest-first\">ہیجز کی ایک سیڑھی، پہلے سب سے آسان</h2>\n<p>ان آلات کا ایک فطری حکم ہے۔ نیچے والے کی قیمت نہیں ہے اور نہ ہی کسی خاص اکاؤنٹ کی ضرورت ہے۔ سب سے اوپر کی قیمت پریمیم یا مارجن پر ہے اور آپ سے کچھ اور سمجھنے کو کہتے ہیں۔ صرف اتنی ہی اونچی چڑھیں جتنی نوکری کی ضرورت ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 360\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"چھ ہیجنگ ٹولز کی ایک سیڑھی جس میں سب سے نیچے سے سب سے اوپر تک شامل ہوتا ہے: نقدی کو تراشنا یا ہولڈ کرنا، متنوع کرنا، حفاظتی پوٹ، کورڈ کال، کالر، اور انڈیکس-فیوچر ہیج۔\">\n  <defs>\n    <marker id=\"ar-lad\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\" markerUnits=\"strokeWidth\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8b949e\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"360\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"395\" y=\"28\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">خطرے کو کم کرنے کے چھ طریقے، پہلے سب سے آسان</text>  <line x1=\"100\" y1=\"320\" x2=\"100\" y2=\"55\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar-lad)\"/>\n  <text transform=\"rotate(-90 60 190)\" x=\"60\" y=\"190\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"12\" font-family=\"sans-serif\">بڑھتی ہوئی لاگت اور پیچیدگی</text>  <rect x=\"135\" y=\"282\" width=\"500\" height=\"38\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\"/>\n  <text x=\"385\" y=\"306\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">1. پوزیشن کو تراشیں یا نقد رقم رکھیں</text>\n  <rect x=\"135\" y=\"236\" width=\"500\" height=\"38\" rx=\"10\" fill=\"#11161d\" stroke=\"#37b3a4\"/>\n  <text x=\"385\" y=\"260\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">2. اسٹاکس اور سیکٹرز میں تنوع پیدا کریں۔</text>\n  <rect x=\"135\" y=\"190\" width=\"500\" height=\"38\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\"/>\n  <text x=\"385\" y=\"214\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">3. حفاظتی پوٹ (بیمہ خریدیں)</text>\n  <rect x=\"135\" y=\"144\" width=\"500\" height=\"38\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\"/>\n  <text x=\"385\" y=\"168\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">4. کورڈ کال (آمدنی، اوپر کی حد)</text>\n  <rect x=\"135\" y=\"98\" width=\"500\" height=\"38\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\"/>\n  <text x=\"385\" y=\"122\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">5. کالر (ایک کال کے ذریعے ادائیگی کی جاتی ہے)</text>\n  <rect x=\"135\" y=\"52\" width=\"500\" height=\"38\" rx=\"10\" fill=\"#11161d\" stroke=\"#8172b3\"/>\n  <text x=\"385\" y=\"76\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-family=\"sans-serif\">6. انڈیکس-مستقبل کا ہیج (پورا پورٹ فولیو)</text><p>  <text x=\"650\" y=\"305\" fill=\"#55a868\" font-size=\"11\" font-family=\"sans-serif\">مفت، آسان</text>\n  <text x=\"648\" y=\"75\" fill=\"#8172b3\" font-size=\"11\" font-family=\"sans-serif\">سب سے زیادہ ملوث</text>\n</svg></p>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">نچلے حصے سے شروع کریں۔ زیادہ تر مبتدیوں کو کبھی بھی تیسرے نمبر پر چڑھنے کی ضرورت نہیں ہوتی ہے۔</figcaption>\n</figure>\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>سب سے سستا، سب سے آسان ہیج تقریبا ہمیشہ ہی کم چیز کا مالک ہوتا ہے۔ کسی اختیار یا مستقبل کے لیے تبھی پہنچیں جب پوزیشن کو تراشنا آپ کو وہ چیز نہیں دے سکتا جس کی آپ کو ضرورت ہے۔</p>\n</div></div>\n<h2 id=\"1-trim-the-position-or-hold-cash\">1. پوزیشن کو تراشیں یا نقد رقم رکھیں</h2>\n<p>سب سے آسان ہیج کم رکھنا ہے۔ پوزیشن کا ایک ٹکڑا بیچیں اور آمدنی کو نقد میں رکھیں۔ جب مارکیٹ گرتی ہے تو کیش نہیں گرتا۔ اگر آپ کسی تقریب سے پہلے انعقاد کے بارے میں گھبراتے ہیں، تو اس کا ایک تہائی فروخت کرنے سے آپ کا خطرہ ایک تہائی کم ہوجاتا ہے - فوری طور پر، بغیر کسی اضافی قیمت کے، بغیر کسی نئی مہارت کے۔</p>\n<p>ٹریڈ آف ایماندار ہے: آپ نے جو حصہ بیچا ہے، اگر خبر اچھی ہے تو آپ منافع چھوڑ دیتے ہیں۔ یہ پوری قیمت ہے۔ لیکن کوئی پریمیم نہیں ہے، کوئی مارجن نہیں، ٹریک کرنے کی کوئی میعاد نہیں ہے، اور کچھ بھی غلط نہیں ہے۔ ایک ہی پوزیشن کے بارے میں فکر مند زیادہ تر ابتدائیوں کے لیے، یہ بورنگ جواب نہیں ہے - یہ صحیح ہے۔</p>\n<h2 id=\"2-diversification-the-built-in-hedge\">2. تنوع - بلٹ ان ہیج</h2>\n<p>تنوع کا مطلب ہر چیز کو ایک اسٹاک، ایک شعبے، یا ایک اثاثہ میں نہیں ڈالنا ہے۔ پھیلاؤ کو پکڑو - کئی اسٹاک، کچھ سیکٹرز میں، شاید کچھ نقد یا سونا - اور وہ سب ایک ہی وجہ سے ایک ہی دن نہیں گریں گے۔ ایک نام کا برا نتیجہ بمشکل پندرہ کی ٹوکری کو ڈینٹ دیتا ہے۔</p>\n<p>یہ ایک ہیج ہے جس میں بنایا گیا ہے کہ آپ کس طرح رکھتے ہیں، نہ کہ آپ کی تجارت۔ اس کی کوئی قیمت نہیں ہے اور ہمیشہ کام کرتا ہے۔ ٹریڈ آف: یہ آپ کے جیتنے والوں کو اتنا ہی نرم کرتا ہے جتنا آپ کے ہارنے والوں کو، اور یہ آپ کو کسی بڑے حادثے میں نہیں بچاتا۔ مارچ 2020 میں، جب NIFTY ہفتوں میں تقریباً 38% گر گیا، تقریباً سب کچھ ایک ساتھ گر گیا۔ تنوع روزمرہ کے جھٹکوں کو کم کرتا ہے، دہائی میں ایک بار نہیں۔</p>\n<h2 id=\"3-protective-put-buying-insurance\">3. حفاظتی پوٹ - انشورنس خریدنا</h2>\n<p>حفاظتی پوٹ پہلا آلہ ہے جس پر پیسہ خرچ ہوتا ہے۔ آپ اسٹاک کے مالک ہیں؛ آپ اس پر ایک پوٹ آپشن خریدتے ہیں۔ اسٹاک کے گرنے کے ساتھ ہی پوٹ کی قیمت بڑھ جاتی ہے، اس لیے منتخب کردہ قیمت سے نیچے - ہڑتال - پوٹ کا فائدہ آپ کے اسٹاک کے نقصانات کو پورا کرتا ہے۔ آپ کا منفی پہلو اس منزل پر رک جاتا ہے جسے آپ پہلے سے چنتے ہیں۔</p>\n<p>اس کے بارے میں بالکل انشورنس کی طرح سوچیں۔ آپ پریمیم ادا کرتے ہیں۔ اگر کچھ برا نہیں ہوتا ہے تو، پریمیم ختم ہوجاتا ہے اور آپ کندھے اچکاتے ہیں۔ اگر اسٹاک کریش ہو جاتا ہے، تو ادائیگی آپ کو فرش کے نیچے ڈھانپ لیتی ہے۔ اسٹرائیک کے اوپر، آپ اپنا پورا الٹا رکھتے ہیں، مائنس پریمیم جو آپ نے ادا کیا تھا۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 330\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"اسٹاک کی ادائیگی کے علاوہ حفاظتی پوٹ: نقصانات ایک معلوم منزل پر پٹ اسٹرائیک کے نیچے فلیٹ ہوتے ہیں، جبکہ فائدہ اسٹرائیک سے اوپر ہوتا ہے، اس کے مقابلے میں اسٹاک کو اکیلے رکھنے کے لامحدود نقصان کے مقابلے میں۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"330\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"26\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">حفاظتی پوٹ: نقصانات ایک منزل پر رک جاتے ہیں۔</text>  <line x1=\"110\" y1=\"60\" x2=\"110\" y2=\"290\" stroke=\"#8b949e\" stroke-width=\"1.5\"/>\n  <line x1=\"110\" y1=\"180\" x2=\"710\" y2=\"180\" stroke=\"#8b949e\" stroke-width=\"1.5\"/>\n  <text x=\"120\" y=\"74\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">منافع</text>\n  <text x=\"120\" y=\"284\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">نقصان</text>\n  <text x=\"700\" y=\"170\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">ختم ہونے پر اسٹاک کی قیمت</text>  <line x1=\"300\" y1=\"60\" x2=\"300\" y2=\"290\" stroke=\"#6e7681\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <text x=\"300\" y=\"306\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">ہڑتال کرو</text>  <line x1=\"110\" y1=\"228\" x2=\"300\" y2=\"228\" stroke=\"#6e7681\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <text x=\"116\" y=\"222\" fill=\"#c44e52\" font-size=\"11\" font-family=\"sans-serif\">فرش (بدترین صورت)</text>  <polyline points=\"110,275 700,85\" fill=\"none\" stroke=\"#8b949e\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>\n  <polyline points=\"110,228 300,228 700,99\" fill=\"none\" stroke=\"#55a868\" stroke-width=\"3\"/>  <rect x=\"470\" y=\"70\" width=\"14\" height=\"3\" fill=\"#8b949e\"/>\n  <text x=\"492\" y=\"75\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">اکیلے اسٹاک</text>\n  <rect x=\"470\" y=\"92\" width=\"14\" height=\"4\" fill=\"#55a868\"/>\n  <text x=\"492\" y=\"97\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">اسٹاک + حفاظتی ڈال</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">متعین قیمت (پریمیم)، طے شدہ منزل۔ ہڑتال کے نیچے، آپ کا نقصان بس رک جاتا ہے۔</figcaption>\n</figure><p>قیمت حقیقی ہے اور اس سے خون بہہ رہا ہے۔ اگر ایونٹ خاموشی سے گزر جاتا ہے تو، پریمیم کچھ بھی نہیں ہوتا ہے اور آپ نے اس تحفظ کے لیے ادائیگی کی ہے جسے آپ نے استعمال نہیں کیا تھا۔ یہ ٹھیک ہے جب آپ اسٹاک کو فروخت نہیں کر سکتے یا نہیں کریں گے - ایک طویل مدتی ہولڈنگ، باہر نکلنے پر ٹیکس کے بڑے بل والی پوزیشن، یا ایک معروف ایونٹ جس میں آپ سوار ہونا چاہتے ہیں۔ یہ ایک مستقل آرام دہ کمبل کے طور پر بیکار ہے۔</p>\n<h2 id=\"4-covered-call-income-with-a-ceiling\">4. کورڈ کال - آمدنی، چھت کے ساتھ</h2>\n<p>ایک کورڈ کال آپشن کو پلٹ دیتی ہے۔ آپ اسٹاک کے مالک ہیں اور آپ اس کے خلاف کال کا آپشن بیچتے ہیں۔ کال بیچنے سے آج آپ کو ایک پریمیم ادا ہوتا ہے۔ اگر اسٹاک فلیٹ رہتا ہے یا تھوڑا سا نیچے جاتا ہے، تو آپ اس پریمیم کو برقرار رکھتے ہیں - نقصانات کے خلاف ایک چھوٹا سا کشن۔</p>\n<p>کیچ چھت ہے. اگر اسٹاک کال کی ہڑتال سے گزر جاتا ہے، تو آپ کو اس سطح سے اوپر کے فوائد کے حوالے کرنا چاہیے۔ آپ کا الٹا بند ہے۔ اور کشن صرف اتنا ہی بڑا ہے جتنا آپ نے جمع کیا ہے، اس لیے ڈھکی ہوئی کال حقیقی منفی تحفظ نہیں ہے - یہ ایک چھوٹے سے زوال کو نرم کرتا ہے، کریش نہیں۔ یہ تجارت کے ساتھ آمدنی ہے، انشورنس نہیں.</p>\n<h2 id=\"5-collar-cheap-protection-capped-both-ways\">5. کالر - سستا تحفظ، دونوں طریقوں سے کیپڈ</h2>\n<p>ایک کالر آخری دو کو جوڑتا ہے۔ آپ ڈاون سائڈ کور کے لیے ایک حفاظتی پوٹ خریدتے ہیں، اور آپ اس کی ادائیگی کے لیے کورڈ کال بیچتے ہیں۔ کال فنڈز سے آپ جو پریمیم جمع کرتے ہیں وہ پریمیم آپ ڈال پر خرچ کرتے ہیں۔ اچھی طرح سے، تحفظ سستا یا تقریباً مفت ہو جاتا ہے۔</p>\n<p>\"تقریباً مفت\" کی قیمت یہ ہے کہ اب آپ کو دونوں طرف سے باکس کیا گیا ہے۔ آپ کے منفی پہلو پٹ ہڑتال پر فرش ہے; کال ہڑتال پر آپ کا الٹا محدود ہے۔ آپ نے انشورنس کی ادائیگی کو روکنے کے لیے بڑی ریلی کا سودا کیا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 330\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"کالر کی ادائیگی: پوٹ اسٹرائیک کے نیچے فرش پر فلیٹ، درمیان میں بڑھتا ہوا، اور کال اسٹرائیک کے اوپر کیپ پر فلیٹ، اس لیے نقصان اور فائدہ دونوں محدود ہیں۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"330\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"26\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">کالر: نیچے فرش، اوپر بند</text>  <line x1=\"110\" y1=\"60\" x2=\"110\" y2=\"290\" stroke=\"#8b949e\" stroke-width=\"1.5\"/>\n  <line x1=\"110\" y1=\"180\" x2=\"710\" y2=\"180\" stroke=\"#8b949e\" stroke-width=\"1.5\"/>\n  <text x=\"120\" y=\"74\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">منافع</text>\n  <text x=\"120\" y=\"284\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">نقصان</text>\n  <text x=\"700\" y=\"170\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">ختم ہونے پر اسٹاک کی قیمت</text>  <line x1=\"300\" y1=\"60\" x2=\"300\" y2=\"290\" stroke=\"#6e7681\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <text x=\"300\" y=\"306\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">ہڑتال کرو</text>\n  <line x1=\"560\" y1=\"60\" x2=\"560\" y2=\"290\" stroke=\"#6e7681\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <text x=\"560\" y=\"306\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">ہڑتال کال کریں۔</text>  <line x1=\"110\" y1=\"220\" x2=\"300\" y2=\"220\" stroke=\"#6e7681\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <text x=\"116\" y=\"214\" fill=\"#c44e52\" font-size=\"11\" font-family=\"sans-serif\">فرش</text>\n  <line x1=\"560\" y1=\"136\" x2=\"700\" y2=\"136\" stroke=\"#6e7681\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <text x=\"700\" y=\"130\" text-anchor=\"end\" fill=\"#55a868\" font-size=\"11\" font-family=\"sans-serif\">ٹوپی</text>  <polyline points=\"110,275 700,85\" fill=\"none\" stroke=\"#8b949e\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>\n  <polyline points=\"110,220 300,220 560,136 700,136\" fill=\"none\" stroke=\"#dd8452\" stroke-width=\"3\"/>  <rect x=\"470\" y=\"262\" width=\"14\" height=\"3\" fill=\"#8b949e\"/>\n  <text x=\"492\" y=\"267\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">اکیلے اسٹاک</text>\n  <rect x=\"470\" y=\"282\" width=\"14\" height=\"4\" fill=\"#dd8452\"/>\n  <text x=\"492\" y=\"287\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">کالر</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">دونوں سرے بند ہیں۔ آپ تحفظ کو سستا کرنے کے لیے بڑی ریلی ترک کر دیں۔</figcaption>\n</figure><p>ایک کالر چمکتا ہے جب آپ کسی خوفناک کھڑکی سے ہولڈنگ کو زیادہ ادائیگی کیے بغیر لے جانا چاہتے ہیں، اور آپ بدلے میں چاند کی تصویر چھوڑ کر خوش ہوتے ہیں۔ یہ کلاسک \"ایونٹ کے ذریعے فائدہ کی حفاظت کریں\" کا ڈھانچہ ہے۔</p>\n<h2 id=\"6-index-future-hedge-covering-the-whole-book\">6. انڈیکس-مستقبل کا ہیج - پوری کتاب کا احاطہ کرتا ہے۔</h2>\n<p>آخری مرحلہ پورے پورٹ فولیو کے لیے ہے۔ اپنی ملکیت کے ہر اسٹاک پر پوٹ خریدنے کے بجائے، آپ مستقبل میں ایک انڈیکس مختصر کریں - NIFTY یا BANKNIFTY۔ اگر مارکیٹ گرتی ہے تو، آپ کی ٹوکری میں زوال کو پورا کرتے ہوئے، مختصر مستقبل کے فوائد۔ ایک تجارت، وسیع احاطہ۔</p>\n<p>یہ سب سے زیادہ ملوث ٹول ہے۔ اسے مارجن اکاؤنٹ کی ضرورت ہے اور روزانہ مارک ٹو مارکیٹ کے جھولوں کے لیے رقم کی ضرورت ہے۔ اس کا سائز آپ کے پورٹ فولیو کے مطابق ہونا چاہیے - یہ سائز کرنا، بیٹا اور تصوراتی قدر کا استعمال کرتے ہوئے، اگلے باب کا پورا موضوع ہے۔ اور یہ دونوں طریقوں کو کاٹتا ہے: جب ہیج آن ہوتا ہے، تو آپ بھی فائدہ اٹھانا بند کر دیتے ہیں اگر مارکیٹ بڑھ جاتی ہے۔ یہ مارکیٹ کو بے اثر کر دیتا ہے، فل سٹاپ۔ یہ ایک چھوٹی، خوفناک ونڈو پر ایک بڑی، متنوع کتاب کے لیے اپنی جگہ بناتا ہے - روزمرہ کی عادت کے طور پر نہیں۔</p>\n<h2 id=\"the-tools-at-a-glance\">ٹولز ایک نظر میں</h2>\n<table>\n<thead>\n<tr>\n<th>ٹول</th>\n<th>لاگت</th>\n<th>سادگی</th>\n<th>اہم تجارت بند</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>تراشنا / نقد روکنا</td>\n<td>کوئی نہیں۔</td>\n<td>سب سے آسان</td>\n<td>آپ نے جو حصہ بیچا اس پر حاصل ہونے والے منافع کو ترک کر دیں۔</td>\n</tr>\n<tr>\n<td>تنوع</td>\n<td>کوئی نہیں۔</td>\n<td>آسان</td>\n<td>ایک وسیع حادثے میں کوئی مدد نہیں؛ جیتنے والوں کو کم کرتا ہے۔</td>\n</tr>\n<tr>\n<td>حفاظتی ڈال</td>\n<td>پریمیم (ایک حقیقی، بار بار چلنے والا بل)</td>\n<td>سادہ، ایک ٹانگ</td>\n<td>اگر کچھ نہیں ہوتا ہے تو پریمیم خون بہتا ہے۔</td>\n</tr>\n<tr>\n<td>احاطہ کال</td>\n<td>پریمیم کماتا ہے۔</td>\n<td>سادہ، ایک ٹانگ</td>\n<td>کیپس الٹا؛ صرف ایک چھوٹا سا زوال تکیا</td>\n</tr>\n<tr>\n<td>کالر</td>\n<td>سستا یا قریب مفت</td>\n<td>اعتدال پسند، دو ٹانگیں۔</td>\n<td>اوپر کی طرف ڈھکی ہوئی اور نیچے کی طرف فرش</td>\n</tr>\n<tr>\n<td>انڈیکس مستقبل</td>\n<td>مارجن + روزانہ جھولے۔</td>\n<td>سب سے زیادہ ملوث</td>\n<td>دونوں سمتوں کو بے اثر کرتا ہے۔ سائز کی ضرورت ہے</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>کلاسک ابتدائی غلطی سب سے پہلے بہترین ٹول تک پہنچ رہی ہے۔ پوزیشن خوفناک محسوس ہوتی ہے، اس لیے وہ سیدھے ملٹی ٹانگ آپشن ڈھانچے کی طرف جاتے ہیں جنہیں وہ صرف نصف سمجھتے ہیں، اسپریڈز اور پریمیم ادا کرتے ہیں، اور غلط ہونے کے نئے طریقے بناتے ہیں۔ دس میں سے نو بار، پوزیشن کو صرف نصف میں کاٹ دینے سے صفر لاگت اور صفر پیچیدگی پر وہی خوف دور ہو جاتا۔ سیڑھی چڑھنا؛ سب سے اوپر نہ چھلانگ لگائیں.</p>\n</div></div>\n<h2 id=\"which-tool-suits-whom\">کون سا ٹول کس کے لیے موزوں ہے۔</h2>\n<p>دائیں ہاتھ کا انحصار اس سیٹ پر ہے جس پر آپ بیٹھتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>عام طور پر پہنچ جاتا ہے۔</th>\n<th>کیوں</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>ٹرم/ہولڈ کیش، تنوع</td>\n<td>سب سے کم قیمت؛ ایک لمبا افق پریمیم ادا کیے بغیر جھٹکے لگاتا ہے۔</td>\n</tr>\n<tr>\n<td>اسٹاک (جھولے) کا تاجر</td>\n<td>پوزیشن، حفاظتی ڈال ٹرم</td>\n<td>کسی واقعہ کے ذریعے منعقد ہونے والے ایک ہی یقین پر ایک متعین منزل</td>\n</tr>\n<tr>\n<td>ایف اینڈ او / فیوچر ٹریڈر</td>\n<td>انڈیکس-مستقبل کا ہیج</td>\n<td>پہلے سے ہی مشتق دنیا میں؛ لیوریجڈ کتاب کو تیزی سے غیر جانبدار کرتا ہے۔</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>کالر طرز اور متعین خطرے والے ڈھانچے</td>\n<td>کھلی ہوئی پونچھ کو لپیٹ دیتا ہے جو فروخت کرنے سے بے نقاب ہوجاتا ہے۔</td>\n</tr>\n</tbody></table>\n<p>یہ تعلیم ہے، ذاتی مشورے نہیں۔ آپ کے لیے کون سا ٹول فٹ بیٹھتا ہے اس کا انحصار آپ کے ہولڈنگز، آپ کے ٹیکس، آپ کے اکاؤنٹ اور آپ کے اعصاب پر ہے - اس کا فیصلہ پرسکون طریقے سے کریں، پہلے سے، نہ کہ کسی خوفناک دن کے درمیان۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>یہ اوزار کم خطرہ؛ ان میں سے کوئی بھی اسے حذف نہیں کرتا، اور ہر ایک اپنے طریقے سے ناکام ہوتا ہے۔</p>\n<p>تراشنا اور کیش آپ کو الٹا نقصان پہنچاتے ہیں: اگر آپ اچھی خبر سے پہلے فروخت کرتے ہیں، تو آپ کم کماتے ہیں۔ یہ اچھی طرح سے سونے کی قیمت ہے، اور کبھی کبھی یہ ڈنک دیتا ہے.</p>\n<p>تنوع ایک حقیقی حادثے میں ناکام ہو جاتا ہے، جب ارتباط ایک میں جاتا ہے اور سب کچھ ایک ساتھ گر جاتا ہے۔ یہ عام ہفتوں کے لیے بنایا گیا ہے، 2008 یا مارچ 2020 کے لیے نہیں۔</p>\n<p>اختیارات لاگت کے ذریعے خاموشی سے ناکام ہوجاتے ہیں۔ ایک حفاظتی پوٹ بار بار خریدا جاتا ہے، ایسی ہولڈنگ پر جو کبھی کریش نہیں ہوتا، اس حادثے سے زیادہ خون بہا سکتا ہے جس کا آپ کو خدشہ تھا۔ سادہ پریشانی سے تحفظ خریدنا، جس کا احاطہ کرنے کے لیے کوئی متعین خطرہ نہیں، صرف ایک سست عطیہ ہے۔</p>\n<p>کالر اور انڈیکس کا مستقبل آپ کے اچھے نتائج کو محدود کرکے ناکام ہوجاتا ہے۔ دونوں آپ کے اوپری حصے کو پن کرتے ہیں، لہذا ایک مضبوط ریلی میں ایک ہیجڈ کتاب غیر ہیجڈ کتاب کو کم کارکردگی کا مظاہرہ کرتی ہے - اور زیادہ سائز یا غلط سائز کا انڈیکس ہیج خود ہی پیسہ کھو سکتا ہے۔ ہیج ایک قیمت ہے جسے آپ جان بوجھ کر ادا کرتے ہیں۔ اگر آپ اس خطرے کا نام نہیں دے سکتے ہیں جو اسے ہٹاتا ہے اور اس سے جو بل وصول ہوتا ہے، تو آپ ہیجنگ نہیں کر رہے ہیں - آپ دوسری شرط لگا رہے ہیں۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> سب سے آسان، سب سے سستا ہیج کیا ہے، اور یہ بہترین انتخاب کب ہے؟</summary><p>کم مالک ہونا - پوزیشن کو تراشنا یا نقد رقم رکھنا۔ اس کی کوئی قیمت نہیں ہے، اسے کسی خاص اکاؤنٹ کی ضرورت نہیں ہے، اور فوری طور پر کام کرتا ہے۔ ایک ابتدائی کے لیے جو ایک ہی انعقاد کے بارے میں فکر مند ہے، یہ عام طور پر صحیح جواب ہوتا ہے۔ آپشنز یا فیوچر تک پہنچیں تبھی جب تراشنا کام نہیں کر سکتا۔</p>\n</details><details>\n<summary><strong>2.</strong> حفاظتی الفاظ میں، پہلے سے کیا وضاحت کی جاتی ہے - اور اس کی قیمت آپ کو کیا ہوتی ہے؟</summary><p>آپ کا زیادہ سے زیادہ نقصان (پوٹ ہڑتال پر منزل) اور آپ کی لاگت (پریمیم) دونوں سامنے معلوم ہیں۔ ہڑتال کے اوپر آپ اپنا اوپری حصہ رکھیں، پریمیم کو کم کریں۔ اگر کچھ برا نہیں ہوتا ہے، تو وہ پریمیم اس تحفظ کے لیے خرچ کیا جاتا ہے جس کی آپ کو ضرورت نہیں تھی۔</p>\n</details><details>\n<summary><strong>3.</strong> ڈھکی ہوئی کال حقیقی منفی تحفظ سے کیسے مختلف ہے؟</summary><p>ایک کورڈ کال صرف ایک پریمیم اکٹھا کرتی ہے، جو اس رقم سے ایک چھوٹی سی کمی کو کم کرتی ہے - یہ حادثے کے خلاف کچھ نہیں کرتی۔ اس کے بدلے میں آپ کال اسٹرائیک کے اوپر اپنے اوپری حصے کو کیپ کرتے ہیں۔ یہ ایک حد کے ساتھ آمدنی ہے، انشورنس نہیں.</p>\n</details><details>\n<summary><strong>4.</strong> کالر کو \"دونوں طریقوں سے کیپ\" کیوں کہا جاتا ہے؟</summary><p>آپ ایک پوٹ (نیچے ایک منزل) خریدتے ہیں اور اس کی ادائیگی کے لیے کال بیچتے ہیں (اوپر کیپ)۔ نتیجہ سستا یا تقریباً مفت تحفظ ہے، لیکن آپ کا منفی پہلو پوٹ اسٹرائیک پر محدود ہے اور کال اسٹرائیک پر آپ کا الٹا سائیڈ محدود ہے۔ آپ سستے کور کے لیے بڑی ریلی کی تجارت کرتے ہیں۔</p>\n</details><details>\n<summary><strong>5.</strong> انڈیکس فیوچر ہیج سیڑھی پر سب سے زیادہ ملوث ٹول کیوں ہے؟</summary><p>اس کے لیے مارجن اکاؤنٹ کی ضرورت ہے، روزانہ مارک ٹو مارکیٹ کے جھولوں کے لیے رقم رکھی گئی ہے، اور بیٹا اور تصوراتی قدر کا استعمال کرتے ہوئے اپنے پورٹ فولیو میں محتاط سائز کی ضرورت ہے۔ یہ دونوں سمتوں کو بھی غیرجانبدار بنا دیتا ہے - جب یہ آن ہوتا ہے، اگر مارکیٹ بڑھ جاتی ہے تو آپ فائدہ اٹھانا بند کر دیتے ہیں۔ یہ ایک چھوٹی، خوفناک ونڈو پر ایک بڑی، متنوع کتاب کے مطابق ہے، روزمرہ کے استعمال میں نہیں۔</p>\n</details>\n","toc":[{"level":2,"text":"ہیجز کی ایک سیڑھی، پہلے سب سے آسان","id":"a-ladder-of-hedges-simplest-first"},{"level":2,"text":"1. پوزیشن کو تراشیں یا نقد رقم رکھیں","id":"1-trim-the-position-or-hold-cash"},{"level":2,"text":"2. تنوع - بلٹ ان ہیج","id":"2-diversification-the-built-in-hedge"},{"level":2,"text":"3. حفاظتی پوٹ - انشورنس خریدنا","id":"3-protective-put-buying-insurance"},{"level":2,"text":"4. کورڈ کال - آمدنی، چھت کے ساتھ","id":"4-covered-call-income-with-a-ceiling"},{"level":2,"text":"5. کالر - سستا تحفظ، دونوں طریقوں سے کیپڈ","id":"5-collar-cheap-protection-capped-both-ways"},{"level":2,"text":"6. انڈیکس-مستقبل کا ہیج - پوری کتاب کا احاطہ کرتا ہے۔","id":"6-index-future-hedge-covering-the-whole-book"},{"level":2,"text":"ٹولز ایک نظر میں","id":"the-tools-at-a-glance"},{"level":2,"text":"کون سا ٹول کس کے لیے موزوں ہے۔","id":"which-tool-suits-whom"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"13":{"html":"<p>روی کے پاس تقریباً 12,00,000 روپے کا اسٹاک تھا - زیادہ تر مڈ کیپس جس پر اسے یقین تھا۔ ایک بڑا ایونٹ آنے والا تھا، اس لیے اس نے ہیج کرنے کا فیصلہ کیا۔ اس نے انڈیکس فیوچرز کو شارٹ کیا جس کی مالیت تقریباً اسی روپے کی تھی جو اس کی کتاب تھی: بارہ لاکھ اسٹاک، بارہ لاکھ آف NIFTY مختصر۔ \"روپے کے بدلے روپیہ، میں احاطہ کرتا ہوں،\" اس نے خود سے کہا۔ مارکیٹ گر گئی۔ NIFTY تقریباً 10% گرا، اور اس کے شارٹ نے اسے 1,20,000 روپے کے قریب کمایا۔ اس نے ہوشیار محسوس کیا - جب تک اس نے اپنا پورٹ فولیو کھولا اور دیکھا کہ یہ 14% گر گیا ہے، 1,68,000 روپے کا نقصان ہے۔ وہ \"مکمل طور پر ہیجڈ\" تھا اور اب بھی 48,000 روپے نیچے تھا۔ اس کے ہیج کے ساتھ کچھ بھی غلط نہیں ہوا تھا۔ اس نے صرف ایک نمبر کو نظر انداز کر دیا تھا جو فیصلہ کرتا ہے کہ ہیج کو کتنا بڑا ہونا چاہیے۔</p>\n<p>وہ نمبر بیٹا ہے۔ یہ باب ایک پورٹ فولیو ہیج کو صحیح طریقے سے سائز کرنے کے بارے میں ہے - اور ایماندار ہونے کے بارے میں کہ ایک مناسب سائز کا ہیج کبھی بھی کامل نہیں ہوتا ہے۔</p>\n<h2 id=\"two-numbers-that-size-every-hedge\">دو نمبر جو ہر ہیج کا سائز کرتے ہیں۔</h2>\n<p>ایک ہیج کا سائز بنانے کے لیے آپ کو صرف دو خیالات کی ضرورت ہے۔ انہیں سیکھیں اور زیادہ تر الجھنیں ختم ہو جاتی ہیں۔</p>\n<p><strong>بیٹا</strong> یہ ہے کہ آپ کا پورٹ فولیو انڈیکس کے مقابلے میں کتنا حرکت کرتا ہے۔ 1.0 کے بیٹا کا مطلب ہے کہ آپ کا اسٹاک تقریباً NIFTY جیسا ہی منتقل ہوتا ہے۔ 1.2 کے بیٹا کا مطلب ہے کہ وہ تقریباً 20 فیصد حرکت کرتے ہیں <em>مزید</em> - جب NIFTY 10% گرتا ہے، تو آپ کی کتاب تقریباً 12% گر جاتی ہے۔ مڈ اور سمال کیپس کا بیٹا اکثر 1 سے اوپر ہوتا ہے۔ بڑے، مستحکم نام 1 کے قریب یا نیچے بیٹھتے ہیں۔ بیٹا ماضی کی اوسط ہے، کوئی وعدہ نہیں، لیکن یہ آپ کا بہترین واحد اندازہ ہے کہ آپ کا پورٹ فولیو مارکیٹ کے ساتھ کتنی مشکل سے بدلتا ہے۔</p>\n<p><strong>تصوراتی قدر</strong> روپیہ کی پوری قیمت ہے جو ایک پوزیشن کی نمائندگی کرتی ہے - وہ مارجن نہیں جو آپ نے لگایا ہے، <em>پوری</em> ایکسپوژر۔ ایک NIFTY فیوچر لاٹ انڈیکس لیول لاٹ سائز سے گنا زیادہ ہے۔ تقریباً 24,000 کی انڈیکس کی سطح پر اور 65 کے قریب لاٹ سائز پر (ایکسچینج کے ذریعے وقتاً فوقتاً لاٹ سائزز پر نظر ثانی کی جاتی ہے - ہمیشہ موجودہ معاہدے کی تفصیلات کو چیک کریں)، ایک لاٹ کا تصور 24,000 x 65 = ہوتا ہے۔ <strong>15,60,000 روپے</strong>. آپ مارجن کے لحاظ سے بہت کم پوسٹ کر سکتے ہیں، لیکن آپ کو تقریباً ساڑھے پندرہ لاکھ انڈیکس کی نقل و حرکت کا سامنا ہے۔ ہیجنگ تصوراتی قدر کے ملاپ کے بارے میں ہے، مارجن نہیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"دو قطاروں کا بہاؤ: پورٹ فولیو ویلیو ٹائمز بیٹا ہیج تصوراتی کو مختصر سے برابر کرتا ہے، پھر اس ہیج تصور کو ایک لاٹ کے تصور سے تقسیم کرنے سے لاٹوں کی تعداد ملتی ہے۔\">\n  <defs>\n    <marker id=\"hf\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\" markerUnits=\"strokeWidth\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8b949e\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ایک ہیج کا سائز: قدر x بیٹا، پھر لاٹ میں تبدیل کریں۔</text>  <rect x=\"30\" y=\"62\" width=\"200\" height=\"58\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\"/>\n  <text x=\"130\" y=\"86\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">پورٹ فولیو ویلیو</text>\n  <text x=\"130\" y=\"106\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">10,00,000 روپے</text>\n  <text x=\"246\" y=\"97\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"20\" font-family=\"sans-serif\">x</text>\n  <rect x=\"262\" y=\"62\" width=\"150\" height=\"58\" rx=\"10\" fill=\"#11161d\" stroke=\"#8172b3\"/>\n  <text x=\"337\" y=\"86\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">بیٹا</text>\n  <text x=\"337\" y=\"106\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">1.2</text>\n  <text x=\"428\" y=\"97\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"20\" font-family=\"sans-serif\">=</text>\n  <rect x=\"444\" y=\"62\" width=\"286\" height=\"58\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\"/>\n  <text x=\"587\" y=\"86\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">مختصر سے تصوراتی ہیج</text>\n  <text x=\"587\" y=\"106\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">12,00,000 روپے</text>  <line x1=\"587\" y1=\"120\" x2=\"587\" y2=\"150\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#hf)\"/>\n  <line x1=\"587\" y1=\"150\" x2=\"160\" y2=\"150\" stroke=\"#8b949e\" stroke-width=\"2\"/>\n  <line x1=\"160\" y1=\"150\" x2=\"160\" y2=\"186\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#hf)\"/>  <rect x=\"30\" y=\"190\" width=\"230\" height=\"58\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\"/>\n  <text x=\"145\" y=\"214\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">ہیج تصوراتی</text>\n  <text x=\"145\" y=\"234\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">12,00,000 روپے</text>\n  <text x=\"276\" y=\"225\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"20\" font-family=\"sans-serif\">/</text>\n  <rect x=\"292\" y=\"190\" width=\"270\" height=\"58\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\"/>\n  <text x=\"427\" y=\"212\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">ایک NIFTY لاٹ</text>\n  <text x=\"427\" y=\"232\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">24,000 x 65 = 15,60,000 روپے</text>\n  <text x=\"578\" y=\"225\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"20\" font-family=\"sans-serif\">=</text>\n  <rect x=\"594\" y=\"190\" width=\"136\" height=\"58\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\"/>\n  <text x=\"662\" y=\"214\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">کے بارے میں</text>\n  <text x=\"662\" y=\"234\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">0.77 لاٹ</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">آپ کی حقیقی مارکیٹ کی نمائش ویلیو x بیٹا ہے۔ یہ، آپ کے پورٹ فولیو کی قیمت نہیں، وہی ہے جسے آپ ہیج کرتے ہیں۔</figcaption>\n</figure><h2 id=\"sizing-an-index-hedge-step-by-step\">ایک انڈیکس ہیج کا سائز، قدم بہ قدم</h2>\n<p>یہ ہے سادہ روپے میں سارا حساب۔ کہتے ہیں کہ آپ کے پاس 10,00,000 روپے کا پورٹ فولیو ہے اور آپ نے اس کا بیٹا تقریباً 1.2 ہے۔</p>\n<ol>\n<li><strong>اپنی حقیقی نمائش تلاش کریں۔</strong> پورٹ فولیو ویلیو x بیٹا = 10,00,000 x 1.2 = <strong>12,00,000 روپے</strong>. آپ کی بارہ لاکھ کی کتاب بازار کی نظروں میں بارہ لاکھ انڈیکس کی طرح چلتی ہے۔ یہی وجہ ہے کہ راوی کا روپے کے بدلے ہیج کم پڑ گیا - اس کی حقیقی نمائش اس کی نقد قیمت سے زیادہ تھی۔</li>\n<li><strong>اس کو انڈیکس تصور کے ساتھ ملائیں۔</strong> آپ زوال کو پورا کرنے کے لیے 12,00,000 روپے NIFTY کم کرنا چاہتے ہیں۔</li>\n<li><strong>لاٹ میں تبدیل کریں۔</strong> ایک لاٹ کے تصور سے تقسیم کریں: 12,00,000 / 15,60,000 = <strong>0.77 لاٹ</strong>. آپ تین چوتھائی لاٹ کی تجارت نہیں کر سکتے، اس لیے آپ ایک لاٹ (ایک چھوٹا اوور ہیج) پر پہنچ جاتے ہیں یا اسے چھوڑ دیتے ہیں۔</li>\n</ol>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>انڈیکس ہیج کا سائز آپ کے پورٹ فولیو کی قیمت ہے جسے اس کے بیٹا سے ضرب دیا جاتا ہے - پورٹ فولیو کی روپے کی قدر نہیں۔ اپنے ہیج <em>ایکسپوژر</em>، پھر لاٹ کی تعداد حاصل کرنے کے لیے ایک لاٹ کے تصوراتی سے تقسیم کریں۔ یہ مشورہ نہیں ہے کہ ہیج کرنا ہے یا نہیں۔ اگر آپ انتخاب کرتے ہیں تو صرف ایک کا سائز کیسے بنانا ہے۔</p>\n</div></div>\n<h2 id=\"full-partial-over-and-under\">مکمل، جزوی، اوپر اور نیچے</h2>\n<p>آپ کو تمام خطرہ مول لینے کی ضرورت نہیں ہے۔ ہیجنگ ایک ڈائل ہے، سوئچ نہیں۔</p>\n<p>اے <strong>جزوی ہیج</strong> جان بوجھ کر خطرے کا صرف ایک حصہ ہٹاتا ہے۔ اگر آپ کچھ اوپر رکھنا چاہتے ہیں اور صرف گرنے کو نرم کرنا چاہتے ہیں تو نصف کو ہیج کریں: اپنے ہیج کو تصوراتی طور پر لیں اور 0.5 سے ضرب دیں۔ مذکورہ کتاب کے لیے، 50% ہیج انڈیکس کے چھ لاکھ ہے، بارہ نہیں۔ آپ آدھی کمی محسوس کریں گے اور آدھا اچھال رکھیں گے۔ یہ اکثر سمجھدار وسط ہوتا ہے: آپ گھبرائے ہوئے ہیں لیکن یقینی نہیں، اس لیے آپ ان سب کے بجائے کچھ خطرہ مول لیتے ہیں۔ ایک مکمل ہیج سب سے زیادہ حفاظت کرتا ہے لیکن سب سے زیادہ الٹا دیتا ہے۔ ایک جزوی ہیج جان بوجھ کر \"میں کھیل میں تھوڑا سا رہنا چاہتا ہوں\" کا انتخاب ہے۔</p>\n<p>اسے غلط کرنے کے دو طریقے خاموش ہیں۔ <strong>انڈر ہیجنگ</strong> اس کا مطلب ہے کہ آپ کا شارٹ آپ کے حقیقی نمائش سے چھوٹا ہے - آپ ابھی بھی جزوی طور پر بے نقاب ہیں، اور گرنے سے تکلیف ہوتی ہے (یہ راوی تھا)۔ <strong>اوور ہیجنگ</strong> مطلب آپ کا مختصر ہے <em>بڑا</em> آپ کی نمائش سے زیادہ - اور اب آپ پلٹ گئے ہیں۔ آپ مارکیٹ میں مختصر ہیں۔ اگر یہ گرتا رہتا ہے تو آپ کا منافع، لیکن اگر یہ بڑھتا ہے تو آپ پیسے کھو دیتے ہیں حالانکہ آپ کے اسٹاک بڑھ گئے ہیں۔ اوور ہیج انشورنس ہونا بند کر دیتا ہے اور دوسری سمت میں ایک نئی شرط بن جاتا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 320\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"انڈر ہیجڈ، دائیں سائز کے اور زیادہ ہیجڈ کا موازنہ کرنے والے تین پینل۔ نیلے رنگ کا لانگ اسٹاک بار ایک ہی لمبائی میں رہتا ہے جبکہ شارٹ ہیج بار اس سے چھوٹا، برابر یا لمبا ہوتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"320\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">نیچے، دائیں، اور اوپر: ہیج کو آپ کی نمائش سے ملانا</text>  <rect x=\"20\" y=\"52\" width=\"226\" height=\"246\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\"/>\n  <text x=\"133\" y=\"78\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">انڈر ہیجڈ</text>\n  <text x=\"38\" y=\"112\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">طویل اسٹاک (نمائش)</text>\n  <rect x=\"38\" y=\"120\" width=\"170\" height=\"20\" rx=\"4\" fill=\"#4c72b0\"/>\n  <text x=\"38\" y=\"166\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">مختصر ہیج</text>\n  <rect x=\"38\" y=\"174\" width=\"105\" height=\"20\" rx=\"4\" fill=\"#dd8452\"/>\n  <text x=\"133\" y=\"252\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">ہیج بہت چھوٹا۔</text>\n  <text x=\"133\" y=\"270\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">گرنا اب بھی آپ کو تکلیف دیتا ہے۔</text>  <rect x=\"267\" y=\"52\" width=\"226\" height=\"246\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\"/>\n  <text x=\"380\" y=\"78\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">دائیں سائز کا</text>\n  <text x=\"285\" y=\"112\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">طویل اسٹاک (نمائش)</text>\n  <rect x=\"285\" y=\"120\" width=\"170\" height=\"20\" rx=\"4\" fill=\"#4c72b0\"/>\n  <text x=\"285\" y=\"166\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">مختصر ہیج</text>\n  <rect x=\"285\" y=\"174\" width=\"170\" height=\"20\" rx=\"4\" fill=\"#55a868\"/>\n  <text x=\"380\" y=\"252\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">ہیج = قدر x بیٹا۔</text>\n  <text x=\"380\" y=\"270\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">زوال زیادہ تر آفسیٹ ہوتا ہے۔</text>  <rect x=\"514\" y=\"52\" width=\"226\" height=\"246\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\"/>\n  <text x=\"627\" y=\"78\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">اوور ہیجڈ</text>\n  <text x=\"532\" y=\"112\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">طویل اسٹاک (نمائش)</text>\n  <rect x=\"532\" y=\"120\" width=\"170\" height=\"20\" rx=\"4\" fill=\"#4c72b0\"/>\n  <text x=\"532\" y=\"166\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">مختصر ہیج</text>\n  <rect x=\"532\" y=\"174\" width=\"186\" height=\"20\" rx=\"4\" fill=\"#c44e52\"/>\n  <text x=\"627\" y=\"252\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">اب آپ نیٹ شارٹ ہیں۔</text>\n  <text x=\"627\" y=\"270\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">اضافہ آپ کے پیسے کھو دیتا ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">نیلی بار آپ کی حقیقی نمائش ہے۔ ہیج کو اس سے مماثل ہونا چاہئے، نہ کہ آپ کی نقد قیمت۔</figcaption>\n</figure>\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>یہاں دو ابتدائی پھندے بیٹھے ہیں۔ پہلا ہیجنگ ہے۔ <strong>روپیہ کے بدلے روپیہ</strong> - بیٹا کو نظر انداز کرتے ہوئے آپ کے پورٹ فولیو کی نقد قیمت کے برابر انڈیکس مختصر کرنا۔ ایک ہائی بیٹا کتاب انڈر ہیجڈ رہتی ہے اور پھر بھی سخت گرتی ہے، بالکل راوی کی طرح۔ دوسرا ہے۔ <strong>زیادہ ہیجنگ</strong> \"محفوظ رہنا\" - اتنا تحفظ خریدنا کہ آپ اب خالص کم ہو گئے ہیں، اس لیے ریکوری ریلی آپ کو اسی دن خرچ کرتی ہے جس دن آپ کا اسٹاک بالآخر اچھالتا ہے۔ x بیٹا کی قدر کے لیے سائز، پھر رکیں۔</p>\n</div></div>\n<h2 id=\"a-worked-portfolio-hedge-sizing-table\">ایک کام شدہ پورٹ فولیو ہیج سائزنگ ٹیبل</h2>\n<p>ایک ہی طریقہ، مختلف کتابیں۔ انڈیکس لیول 24,000 کے آس پاس، 65 کے قریب لاٹ، تو ایک لاٹ تقریباً 15,60,000 روپے کا تصور ہے۔ دیکھیں کہ کس طرح لاٹ شاذ و نادر ہی پوری نکلتی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>پورٹ فولیو</th>\n<th>بیٹا</th>\n<th>حفاظت کرنا</th>\n<th>ہیج تصوراتی (قدر x بیٹا x %)</th>\n<th>لاٹ (خیالی / 15,60,000)</th>\n<th>عملی انتخاب</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>10,00,000 روپے</td>\n<td>1.2</td>\n<td>تمام (100%)</td>\n<td>12,00,000</td>\n<td>0.77</td>\n<td>1 لاٹ - قدرے زیادہ ہیجڈ</td>\n</tr>\n<tr>\n<td>30,00,000 روپے</td>\n<td>1.2</td>\n<td>تمام (100%)</td>\n<td>36,00,000</td>\n<td>2.31</td>\n<td>2 لاٹ - ہلکا سا انڈر ہیج</td>\n</tr>\n<tr>\n<td>30,00,000 روپے</td>\n<td>1.2</td>\n<td>نصف (50%)</td>\n<td>18,00,000</td>\n<td>1.15</td>\n<td>1 لاٹ - ہلکا سا انڈر ہیج</td>\n</tr>\n<tr>\n<td>50,00,000 روپے</td>\n<td>0.9</td>\n<td>تمام (100%)</td>\n<td>45,00,000</td>\n<td>2.88</td>\n<td>3 لاٹ - چھوٹا اوور ہیج</td>\n</tr>\n</tbody></table>\n<p>آخری کالم کا سبق: چھوٹی کتابیں اور عجیب بیٹا تقریباً کبھی پوری لاٹوں میں تقسیم نہیں ہوتے۔ آپ کو گول کرنے پر مجبور کیا جاتا ہے، اور ہر بار گول کرنا ایک چھوٹا سا اوور یا انڈر ہیج ہوتا ہے۔ یہ عام بات ہے۔ مقصد یہ ہے۔ <em>کافی قریب</em>، کامل نہیں۔</p>\n<h2 id=\"how-this-differs-by-who-you-are\">آپ کون ہیں اس سے یہ کیسے مختلف ہے۔</h2>\n<p>ایک ہی ریاضی ہر ایک پر لاگو ہوتی ہے، لیکن یہ آپ کی نشست کے ساتھ کتنا اہم ہے.</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>کیا ایک پورٹ فولیو ہیج فٹ ہے؟</th>\n<th>کیا دیکھنا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>شاذ و نادر ہی ضرورت ہے؛ ایک لاٹ ایک چھوٹی SIP کتاب کو بونا کر سکتا ہے۔</td>\n<td>ایک NIFTY لاٹ ~15.6 لاکھ تصوراتی ہے - چند لاکھ کے پورٹ فولیو کو صاف ستھرا ہیج کرنے کے لیے بہت بڑا</td>\n</tr>\n<tr>\n<td>فعال تاجر</td>\n<td>کبھی کبھی، ایک معروف واقعہ میں</td>\n<td>آپ کی اصل ہولڈنگز کا بیٹا، اندازہ نہیں؛ بہت احتیاط سے گول کریں</td>\n</tr>\n<tr>\n<td>F&amp;O (فیوچر) تاجر</td>\n<td>ہاں، یہ دیسی ٹول ہے۔</td>\n<td>شارٹ لاٹ پر مارجن، اور اوور ہیجنگ کے ذریعے نیٹ شارٹ بیٹ میں نہ جانا</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>اکثر انڈیکس آپشنز کے ساتھ ہیجز کرتے ہیں، فیوچر نہیں۔</td>\n<td>ایک مختصر پوٹ پہلے سے ہی مارکیٹ کی نمائش میں اضافہ کرتا ہے؛ ہیج کا سائز خالص بیٹا میں کریں، مجموعی نہیں۔</td>\n</tr>\n</tbody></table>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>یہاں تک کہ بالکل سائز کا، ایک پورٹ فولیو ہیج ایک تخمینہ ہے۔ کیوں کے بارے میں ایماندار ہو.</p>\n<p><strong>بنیاد اور ٹریکنگ رسک - آپ کے اسٹاک انڈیکس نہیں ہیں۔</strong> آپ NIFTY کے ساتھ ہیج کرتے ہیں، لیکن آپ NIFTY کے مالک نہیں ہیں۔ آپ ایک مخصوص ٹوکری کے مالک ہیں۔ اگر انڈیکس برقرار رہنے کے دوران آپ کے اسٹاک گر جاتے ہیں (ایک شعبے کا مسئلہ، ایک برا نتیجہ)، آپ کا ہیج بمشکل حرکت کرتا ہے اور آپ بہرحال ہار جاتے ہیں۔ انڈیکس صرف آپ کے زوال کے اس حصے سے بچا سکتا ہے جو کہ ہے۔ <em>مارکیٹ وسیع</em>. اسٹاک کے لیے مخصوص حصہ بے نقاب ہے۔</p>\n<p><strong>بیٹا بہہ جاتا ہے۔</strong> آپ نے جس 1.2 کا حساب لگایا ہے وہ پسماندہ نظر آنے والی اوسط ہے۔ ایک شدید حادثے میں، باہمی رابطے اچھلتے ہیں اور بہت سے اسٹاک ان کے پرسکون دن کے بیٹا کی تجویز سے کہیں زیادہ مشکل سے اکٹھے ہو جاتے ہیں - لہذا عام اوقات کے لیے ایک ہیج بالکل اسی وقت کم ہو سکتا ہے جب آپ کو اس کی سب سے زیادہ ضرورت ہو۔ بیٹا ایک رہنما ہے، ضمانت نہیں ہے۔</p>\n<p><strong>لاٹ یکساں طور پر تقسیم نہیں ہوتے ہیں۔</strong> جیسا کہ ٹیبل نے دکھایا ہے، آپ کو تقریباً ہمیشہ ہی مکمل طور پر گول کرنے پر مجبور کیا جاتا ہے، شروع سے ہی ایک چھوٹا سا اوور یا کم ہیج بنا ہوا چھوڑ دیا جاتا ہے۔</p>\n<p>ایک پرفیکٹ ہیج - جو آپ کے روپے کے نقصان کو منسوخ کرتا ہے - ایک نصابی کتاب کا خیال ہے، مارکیٹ کی حقیقت نہیں۔ ایمانداری کا مقصد لینا ہے۔ <em>زیادہ تر</em> ایک معلوم قیمت پر مارکیٹ کے خطرے کو ختم کرنا، اور یہ جاننے کے لیے کہ آپ اب بھی کون سے خطرات کو اٹھا رہے ہیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>یہ ماڈیول B کو بند کر دیتا ہے۔ اب آپ کے پاس ہیجنگ کی مکمل ایماندارانہ تصویر ہے: یہ واقعی کیا کرتا ہے، کب یہ اس کے قابل ہے، کب نہیں ہے، اس کی قیمت کیا ہے، سادہ ٹولز، اور بیٹا اور تصوراتی قدر کے ساتھ کس طرح سائز کرنا ہے۔ اس میں سے کوئی بھی مفت نہیں ہے، اور اس میں سے کوئی بھی کامل نہیں ہے - لیکن صاف آنکھوں کے ساتھ استعمال کیا جاتا ہے، ایک ہیج آپ کو گھبراہٹ کے نیچے بیچنے کے بجائے طوفان سے گزرنے کے لئے پرسکون خریدتا ہے۔ اس کے بعد کورس براہ راست سرمائے کی حفاظت کی طرف موڑتا ہے۔</p>\n</div></div>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> آپ کا پورٹ فولیو 1.3 کے بیٹا کے ساتھ 20,00,000 روپے کا ہے۔ ایک مکمل ہیج کتنا انڈیکس تصوراتی ہونا چاہئے؟</summary><p>ویلیو ٹائم بیٹا: 20,00,000 x 1.3 = 26,00,000 روپے انڈیکس تصوراتی۔ آپ اپنے حقیقی نمائش کو روکتے ہیں، نہ کہ پورٹ فولیو کی نقد قیمت۔</p>\n</details><details>\n<summary><strong>2.</strong> روی نے پھر بھی پیسہ کیوں کھویا حالانکہ وہ روپیہ کے بدلے \"مکمل طور پر ہیجڈ\" تھا؟</summary><p>اس نے بیٹا نظر انداز کیا۔ اس کی مڈ کیپ بک کا بیٹا تقریباً 1.4 تھا، اس لیے یہ 14% گر گئی جب NIFTY 10% گر گیا۔ روپے کے بدلے روپے کی شارٹ نے صرف 10% مارکیٹ کی حرکت کا احاطہ کیا، جس سے اضافی گراوٹ کا پردہ فاش نہیں ہوا۔ اس کا احساس کیے بغیر وہ انڈر ہیجڈ تھا۔</p>\n</details><details>\n<summary><strong>3.</strong> زیادہ ہیجڈ ہونے کا کیا مطلب ہے، اور یہ خطرناک کیوں ہے؟</summary><p>آپ کا شارٹ آپ کے حقیقی نمائش سے بڑا ہے، اس لیے آپ اب مارکیٹ میں مختصر ہیں۔ اگر یہ مزید گرتا ہے تو آپ پیسہ کماتے ہیں، لیکن اگر یہ بڑھتا ہے تو آپ پیسہ کھو دیتے ہیں - اگرچہ آپ کے اسٹاک بڑھ گئے ہیں۔ ہیج ایک تازہ دشاتمک شرط میں بدل گیا ہے۔</p>\n</details><details>\n<summary><strong>4.</strong> ایک NIFTY لاٹ تقریباً 15,60,000 روپے کا تصوراتی ہے۔ 5,00,000 روپے کے پورٹ فولیو کے لیے یہ مسئلہ کیوں ہے؟</summary><p>ایک لاٹ پوری کتاب سے کہیں زیادہ بڑا ہوتا ہے، اس لیے ایک لاٹ بھی بڑے پیمانے پر اسے زیادہ ہیج کرتا ہے۔ چھوٹے پورٹ فولیوز عام طور پر انڈیکس فیوچر کے ساتھ صاف طور پر ہیج نہیں کر سکتے ہیں - پوزیشن کا سائز کم کرنا یا نقد رقم رکھنا اکثر آسان اقدام ہوتا ہے۔</p>\n</details><details>\n<summary><strong>5.</strong> ایک کامل ہیج کیوں نایاب ہے یہاں تک کہ جب آپ اسے صحیح طریقے سے سائز دیتے ہیں؟</summary><p>آپ کے اسٹاک انڈیکس نہیں ہیں (بنیاد اور ٹریکنگ رسک)، بیٹا بڑھتا ہے اور اکثر حادثے میں بڑھ جاتا ہے، اور لاٹ سائزز آپ کو گول کرنے پر مجبور کرتے ہیں۔ ایک ہیج قیمت پر مارکیٹ کے زیادہ تر خطرے کو دور کرتا ہے - یہ روپے کو آپ کے نقصان کو منسوخ نہیں کرتا ہے۔</p>\n</details>\n","toc":[{"level":2,"text":"دو نمبر جو ہر ہیج کا سائز کرتے ہیں۔","id":"two-numbers-that-size-every-hedge"},{"level":2,"text":"ایک انڈیکس ہیج کا سائز، قدم بہ قدم","id":"sizing-an-index-hedge-step-by-step"},{"level":2,"text":"مکمل، جزوی، اوپر اور نیچے","id":"full-partial-over-and-under"},{"level":2,"text":"ایک کام شدہ پورٹ فولیو ہیج سائزنگ ٹیبل","id":"a-worked-portfolio-hedge-sizing-table"},{"level":2,"text":"آپ کون ہیں اس سے یہ کیسے مختلف ہے۔","id":"how-this-differs-by-who-you-are"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"14":{"html":"<p>میرا کو کچھ ایسا ملا جو مفت پیسے کی طرح محسوس ہوا۔ ہر ہفتے اس نے مارکیٹ سے تھوڑا اوپر ایک NIFTY کال آپشن فروخت کیا اور پریمیم جیب میں ڈالا - چھوٹا، مستحکم، آسان۔ یہاں 5200 روپے، وہاں 5000 روپے۔ پانچ ماہ تک اس نے کام کیا، اور اس نے اسے آمدنی کے طور پر سوچنا شروع کیا۔ پھر صبح انتخابی نتیجہ آیا۔ NIFTY نے اپنی اسکرین کو چھونے سے پہلے تقریباً 1,200 پوائنٹس کا فاصلہ طے کیا۔ اس نے جو کال 5,200 روپے میں فروخت کی تھی اس کی قیمت اچانک تقریباً 78,000 روپے تھی۔ ایک وقفے نے پانچ ماہ کے پریمیم کو مٹا دیا اور پھر کچھ۔ ارجن، دو میزوں کے فاصلے پر بیٹھا تھا، اس ہفتے بالکل وہی نظارہ تھا - لیکن اس نے ایک بیچ دیا تھا۔ <em>پھیلاؤ</em>. اس صبح اسے 15,600 روپے کا نقصان ہوا اور ایک روپیہ بھی زیادہ نہیں، کیونکہ اس کے نقصان میں داخل ہونے سے پہلے ایک فرش بنا ہوا تھا۔</p>\n<p>یہ واحد فرق - فرش یا چٹان - وہی ہے جس کے بارے میں یہ باب ہے۔ یہ آپشن سیلر پلے بک کو ایک اصول کے ساتھ کھولتا ہے جسے ایک ابتدائی بیچنے والا نہیں چھوڑ سکتا: صرف متعین خطرے کے ساتھ فروخت کریں۔</p>\n<h2 id=\"the-two-trades-in-one-minute\">دونوں تجارت، ایک منٹ میں</h2>\n<p>آپشن بیچنے کا مطلب ہے کہ آپ آج ہی ایک پریمیم جمع کرتے ہیں اور ایک ذمہ داری قبول کرتے ہیں۔ اگر مارکیٹ آپ کے خلاف چلتی ہے، تو آپ ادائیگی کرتے ہیں۔ اس ذمہ داری کو ادا کرنے کے دو طریقے ہیں۔</p>\n<p>اے <strong>ننگے مختصر</strong> کال یا پوٹ بیچ رہا ہے جس کے پیچھے کچھ بھی نہیں ہے۔ آپ پریمیم جمع کرتے ہیں اور مارکیٹ جو کچھ بھی کرتی ہے اس کے سامنے کھڑے ہوتے ہیں۔ ایک کال بیچیں، اور ریلی آپ کو خرچ کرے گی۔ ایک پوٹ بیچیں، اور کریش آپ کو مہنگا پڑے گا۔ آپ کی حفاظت کرنے والی کوئی دوسری ٹانگ نہیں ہے - \"ننگے\" کا مطلب بالکل وہی ہے۔</p>\n<p>اے <strong>ہیجڈ مختصر</strong>عام طور پر کہا جاتا ہے a <strong>پھیلاؤ</strong>، ایک آپشن فروخت کر رہا ہے اور <em>خریدنا</em> انشورنس کے طور پر مزید دور کا اختیار۔ آپ 24,000 کال بیچتے ہیں اور 24,300 کال خریدتے ہیں۔ آپ جو آپشن خریدتے ہیں وہ آپ کو تھوڑا سا پریمیم خرچ کرتا ہے، لہذا آپ کم جمع کرتے ہیں۔ بدلے میں، وہ خریدا ہوا آپشن آپ کے نقصان کو پورا کرتا ہے۔ اس بات سے کوئی فرق نہیں پڑتا ہے کہ مارکیٹ کتنی دور تک چلتی ہے، لمبی ٹانگ آپ کو اس کی ہڑتال سے اوپر ادا کرتی ہے۔ آپ کے داخل ہوتے ہی آپ کا بدترین معاملہ طے ہو جاتا ہے۔</p>\n<p>بازار کا ایک ہی منظر۔ دو بالکل مختلف خطرے کی شکلیں۔</p>\n<h2 id=\"the-cliff-why-a-naked-short-is-open-ended\">چٹان: ایک ننگا شارٹ کھلا کیوں ہوتا ہے۔</h2>\n<p>میرا کی ننگی مختصر کال کی ادائیگی کی تصویر بنائیں۔ جب تک NIFTY اپنی ہڑتال سے نیچے رہتی ہے، وہ پورا پریمیم رکھتی ہے - ایک چھوٹا، فلیٹ منافع۔ اسٹرائیک کے اوپر، مارکیٹ میں جو بھی پوائنٹ بڑھتا ہے وہ ایک نقطہ ہے جسے وہ کھو دیتی ہے، اور اسے روکنے کے لیے کچھ بھی نہیں ہے۔ لائن صرف چارٹ کے نیچے سے گرتی ہے، اور گرتی ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 320\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک ننگی مختصر کال کی ادائیگی۔ پریمیم کے برابر ایک چھوٹا فلیٹ منافع جب قیمت اسٹرائیک سے نیچے ہوتی ہے، پھر ایک لائن جو صفر سے گزر جاتی ہے اور بغیر کسی منزل کے چارٹ سے گرتی رہتی ہے۔\">\n  <defs>\n    <marker id=\"dn\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\" markerUnits=\"strokeWidth\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#c44e52\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"320\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ننگی مختصر کال: ایک چھوٹا پریمیم، پھر ایک پہاڑ</text>\n  <line x1=\"70\" y1=\"60\" x2=\"70\" y2=\"290\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <line x1=\"70\" y1=\"175\" x2=\"720\" y2=\"175\" stroke=\"#30363d\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\"/>\n  <text x=\"60\" y=\"100\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">منافع</text>\n  <text x=\"60\" y=\"260\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">نقصان</text>\n  <text x=\"78\" y=\"170\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">0</text>\n  <line x1=\"320\" y1=\"70\" x2=\"320\" y2=\"290\" stroke=\"#8b949e\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <text x=\"320\" y=\"305\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">ہڑتال 24,000</text>\n  <line x1=\"70\" y1=\"135\" x2=\"320\" y2=\"135\" stroke=\"#55a868\" stroke-width=\"3\"/>\n  <line x1=\"320\" y1=\"135\" x2=\"710\" y2=\"300\" stroke=\"#c44e52\" stroke-width=\"3\" marker-end=\"url(#dn)\"/>\n  <circle cx=\"404\" cy=\"175\" r=\"4\" fill=\"#e6edf3\"/>\n  <text x=\"404\" y=\"160\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">وقفہ بھی</text>\n  <text x=\"195\" y=\"123\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"11.5\" font-family=\"sans-serif\">رکھا ہوا پریمیم: 5,200 روپے</text>\n  <text x=\"600\" y=\"250\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">نقصان بڑھتا رہتا ہے</text>\n  <text x=\"600\" y=\"268\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"11\" font-family=\"sans-serif\">نیچے کوئی منزل نہیں۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">سب سے زیادہ جو آپ بنا سکتے ہیں وہ پریمیم ہے۔ آپ جس سے زیادہ کھو سکتے ہیں اس کی کوئی حد نہیں ہے۔</figcaption>\n</figure><p>میرا کی صبح نمبر چلائیں۔ اس نے 80 روپے فی یونٹ میں 24,000 کال فروخت کی۔ ایک NIFTY لاٹ لگ بھگ 65 یونٹس ہے، اس لیے اس نے 80 x 65 = جمع کیے <strong>5,200 روپے</strong>. NIFTY تقریباً 25,200 تک - 1,200 پوائنٹس تک بڑھ گیا۔ اس کی کال اب کم از کم اس کی اندرونی قیمت کے قابل تھی: 1,200 x 65 = <strong>78,000 روپے</strong>. وہ ایک تجارت پر تقریباً 78 ہزار کا مقروض تھا جس سے اسے تقریباً پانچ ہزار ادا ہوئے۔ یہ تقریباً نقصان ہے۔ <strong>72,800 روپے</strong> - چودہ گنا پریمیم اس نے جمع کیا - اور اگر فرق زیادہ ہوتا تو نقصان ہوتا۔ وہ پہاڑ ہے: چھوٹا انعام، بے حد خطرہ۔</p>\n<h2 id=\"the-floor-how-a-spread-caps-your-loss\">فرش: اسپریڈ آپ کے نقصان کو کیسے روکتا ہے۔</h2>\n<p>اب ارجن کا ورژن۔ اسی 24000 کال کو اس نے 80 روپے میں بیچا، لیکن وہ بھی <em>خریدا</em> 20 روپے میں 24,300 کال۔ اس نے کم جمع کیا - 80 مائنس 20 = 60 روپے فی یونٹ، یا <strong>3,900 روپے</strong> بہت کے لئے. ٹریڈ آف وہ سب کچھ ہے جو اہم ہے: 24,300 سے اوپر، اس کی خریدی ہوئی کال اس کی فروخت کردہ کال کے ساتھ پوائنٹ فی پوائنٹ بڑھ جاتی ہے، اس لیے دونوں منسوخ کر دیتے ہیں۔ اس کا نقصان مرنا بند ہو جاتا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 320\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ہیجڈ شارٹ کال اسپریڈ کی ادائیگی۔ نچلی سٹرائیک کے نیچے ایک چھوٹا فلیٹ منافع، سٹرائیکس کے درمیان ڈھلوان نقصان، پھر ایک فلیٹ ریڈ فلور جہاں زیادہ سے زیادہ نقصان محدود ہو اور مزید بڑھ نہ سکے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"320\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ہیجڈ شارٹ (پھیلاؤ): ایک چھوٹا پریمیم، لیکن ایک منزل</text>\n  <line x1=\"70\" y1=\"60\" x2=\"70\" y2=\"290\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <line x1=\"70\" y1=\"160\" x2=\"720\" y2=\"160\" stroke=\"#30363d\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\"/>\n  <text x=\"60\" y=\"105\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">منافع</text>\n  <text x=\"60\" y=\"255\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">نقصان</text>\n  <text x=\"78\" y=\"155\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">0</text>\n  <line x1=\"300\" y1=\"70\" x2=\"300\" y2=\"290\" stroke=\"#8b949e\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <text x=\"300\" y=\"305\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10.5\" font-family=\"sans-serif\">24000 میں فروخت کریں۔</text>\n  <line x1=\"500\" y1=\"70\" x2=\"500\" y2=\"290\" stroke=\"#8b949e\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <text x=\"500\" y=\"305\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10.5\" font-family=\"sans-serif\">24,300 خریدیں۔</text>\n  <line x1=\"70\" y1=\"128\" x2=\"300\" y2=\"128\" stroke=\"#55a868\" stroke-width=\"3\"/>\n  <line x1=\"300\" y1=\"128\" x2=\"500\" y2=\"245\" stroke=\"#dd8452\" stroke-width=\"3\"/>\n  <line x1=\"500\" y1=\"245\" x2=\"710\" y2=\"245\" stroke=\"#c44e52\" stroke-width=\"3\"/>\n  <circle cx=\"360\" cy=\"160\" r=\"4\" fill=\"#e6edf3\"/>\n  <text x=\"360\" y=\"146\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">وقفہ بھی</text>\n  <text x=\"185\" y=\"116\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"11.5\" font-family=\"sans-serif\">رکھا ہوا پریمیم: 3,900 روپے</text>\n  <text x=\"605\" y=\"232\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">زیادہ سے زیادہ نقصان: 15,600 روپے</text>\n  <text x=\"605\" y=\"266\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"11\" font-family=\"sans-serif\">منزل - نقصان یہاں رک جاتا ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">خریدا ہوا آپشن بے اتھاہ چٹان کو ایک فلیٹ، معلوم منزل میں بدل دیتا ہے۔</figcaption>\n</figure><p>یہاں سب سے خراب صورت حال ہے، پہلے سے طے شدہ۔ اس کے دو حملوں کے درمیان فرق 300 پوائنٹس ہے۔ اس نے 60 جمع کیے۔ تو اس کا زیادہ سے زیادہ نقصان ہے (300 - 60) x 65 = 240 x 65 = <strong>15,600 روپے</strong>. NIFTY کا فرق 25,200، 26,000، کہیں بھی ہوسکتا ہے - ارجن اب بھی بالکل 15,600 روپے کھوتا ہے اور ایک روپیہ زیادہ نہیں۔ وہ منزل ہے۔ اس نے ایک نامعلوم، ممکنہ طور پر تباہ کن نقصان کو ایک نمبر میں تبدیل کرنے کے لیے تقریباً 1,300 روپے پریمیم چھوڑ دیے جسے اس نے خرید پر کلک کرنے سے پہلے لکھا تھا۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک ابتدائی کے لئے، صرف کے ساتھ اختیارات فروخت <strong>خطرے کی وضاحت</strong> - ایک پھیلاؤ، جہاں آپ نے پہلے ہی وہ تحفظ خرید لیا ہے جو آپ کے نقصان کو پورا کرتا ہے۔ ایک ننگا مختصر آپ کو ایک چھوٹا سا پریمیم اور ایک کھلا نقصان۔ ہیج کے لیے آپ جو پریمیم چھوڑ دیتے ہیں وہ سب سے سستا انشورنس ہے جو آپ کبھی خریدیں گے۔ یہ تعلیم ہے، کسی مخصوص تجارت کے بارے میں مشورہ نہیں۔</p>\n</div></div>\n<h2 id=\"naked-vs-spread-side-by-side\">ننگے بمقابلہ پھیلاؤ، پہلو بہ پہلو</h2>\n<table>\n<thead>\n<tr>\n<th>کیا فرق پڑتا ہے۔</th>\n<th>ننگا مختصر</th>\n<th>ہیجڈ مختصر (پھیلاؤ)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>پریمیم جمع کیا گیا۔</td>\n<td>بڑا - 5,200 روپے</td>\n<td>چھوٹا - 3,900 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>کھلا ہوا، غیر متعینہ</td>\n<td>متعین - 15,600 روپے</td>\n</tr>\n<tr>\n<td>ایک خلا پر بدترین معاملہ</td>\n<td>مارکیٹ جو کچھ بھی کرے (72,800+ روپے)</td>\n<td>اب بھی 15,600 روپے</td>\n</tr>\n<tr>\n<td>مارجن بلاک کر دیا گیا۔</td>\n<td>بڑا اور غبارہ آپ کے خلاف حرکت کرتے ہی اُڑ سکتا ہے۔</td>\n<td>بہت چھوٹی - لمبی ٹانگ مارجن کا فائدہ کماتی ہے۔</td>\n</tr>\n<tr>\n<td>کیا آپ اسے صحیح طریقے سے سائز کر سکتے ہیں؟</td>\n<td>نہیں - بدترین کیس نامعلوم ہے۔</td>\n<td>ہاں - آپ جانتے ہیں کہ سامنے کا سب سے برا معاملہ ہے۔</td>\n</tr>\n<tr>\n<td>نتیجہ کی رات سوتے ہیں؟</td>\n<td>واقعی نہیں۔</td>\n<td>جی ہاں</td>\n</tr>\n</tbody></table>\n<p>وہ قطار جو خاموشی سے ہر چیز کا فیصلہ کرتی ہے وہ حاشیہ ہے۔ ایک ننگا شارٹ ایک بڑے مارجن کو روکتا ہے، اور جب تجارت آپ کے خلاف ہوتی ہے، تو آپ کا بروکر مطالبہ کرتا ہے۔ <em>مزید</em> - بالکل جب آپ اسے کم سے کم برداشت کر سکتے ہیں۔ ایک پھیلاؤ بہت کم روکتا ہے کیونکہ ایکسچینج دیکھ سکتا ہے کہ آپ کا نقصان ختم ہو گیا ہے، لہذا اسے کسی آفت کے لیے کشن کی ضرورت نہیں ہے جو نہیں ہو سکتی۔</p>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>کلاسک بیگنر ٹریپ \"اضافی پریمیم کے عوض\" ننگا فروخت کر رہا ہے۔ جی ہاں، ننگا شارٹ 5,200 روپے جمع کرتا ہے بمقابلہ اسپریڈ کے 3,900 روپے - تقریباً 33 فیصد زیادہ۔ ایسا لگتا ہے جیسے ہیج خریدنے کے لئے میز پر پیسہ چھوڑ دیا جائے۔ لیکن آپ اضافی پریمیم جمع نہیں کر رہے ہیں۔ لامحدود نقصان کو انڈر رائٹ کرنے کے لیے آپ کو ایک چھوٹی سی رقم مل رہی ہے۔ ایک وقفہ اور \"اضافی\" 1,300 روپے جو آپ نے کئی ہفتوں میں بچائے تھے وہ 72,800 روپے کے ایک ہٹ کے نیچے غائب ہو جاتے ہیں۔ ہیج کوئی قیمت نہیں ہے - یہ واحد چیز ہے جو آپ کے اکاؤنٹ کو ختم کرنے سے ایک برا دن روکتی ہے۔</p>\n</div></div>\n<h2 id=\"why-defined-risk-lets-you-size-and-sleep\">کیوں متعین خطرہ آپ کو سائز اور سونے دیتا ہے۔</h2>\n<p>یہ فرش کی اہمیت کی گہری وجہ ہے۔ <strong>آپ کسی ایسی پوزیشن کو سائز نہیں دے سکتے جس کی بدترین صورت آپ کو معلوم نہیں ہے۔</strong> پوزیشن کا سائز صرف ایک سوال ہے: \"اگر یہ زیادہ سے زیادہ غلط ہو جاتا ہے، تو میں کتنا کھو سکتا ہوں، اور کیا میں اس سے بچ سکتا ہوں؟\" اسپریڈ کے لیے، جواب ایک نمبر ہے - 15,600 روپے - تاکہ آپ فیصلہ کر سکیں کہ آپ کے خطرے کے بجٹ میں کتنی لاٹیں فٹ ہیں۔ اگر آپ کا قاعدہ یہ ہے کہ 5,00,000 روپے کے اکاؤنٹ کے 2% سے زیادہ خطرہ نہ ہو، یعنی 10,000 روپے، تو یہ اسپریڈ پہلے ہی بہت بڑا ہے اور آپ اس سے زیادہ تنگ تجارت کرتے ہیں۔ ریاضی <em>کام کرتا ہے</em>.</p>\n<p>ایک ننگے شارٹ کے لیے، بدترین صورت \"نامعلوم، ممکنہ طور پر تباہ کن\" ہے اور آپ لامحدودیت کے خلاف سائز نہیں کر سکتے۔ لہذا بیچنے والے اس کے بجائے خطرناک کام کرتے ہیں: وہ سائز سے دور ہوتے ہیں۔ <em>مارجن</em> یا یہ کتنا محفوظ محسوس ہوتا ہے، دونوں ہی دم کے بارے میں کچھ نہیں کہتے ہیں۔ اس طرح ایک خاموش آمدنی کی حکمت عملی ایک ہی صفایا میں ختم ہوتی ہے۔</p>\n<p>فروخت کرنے سے پہلے ایک کام شدہ چیک لسٹ:</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> زیادہ سے زیادہ نقصان روپے میں لکھیں۔ اگر آپ نہیں کر سکتے ہیں، تو تجارت ننگی ہے - اسے مت رکھو.</li>\n<li><input disabled=\"\" type=\"checkbox\"> چیک کریں کہ آپ کے خطرے کی فی تجارت کی حد (مثلاً 1-2% سرمایہ) کے خلاف زیادہ سے زیادہ نقصان۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> تصدیق کریں کہ ایک خریدی ہوئی ٹانگ ہے، حقیقی ہڑتال کے ساتھ، اصل میں بھری ہوئی ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> مارجن کو نوٹ کریں، اور یہ کہ یہ چھوٹا ہیجڈ مارجن ہے، ننگا نہیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> اس کے بعد ہی، لاٹوں کی تعداد کو سائز دیں تاکہ بیان کردہ نقصان آپ کے بجٹ کے مطابق ہو۔</li>\n</ul>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 230\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"دو بدترین کیس بار۔ برہنہ شارٹ بار لمبا اور سرخ ہے اور فریم کے اوپری حصے سے چلتا ہے، جس پر نامعلوم لیبل لگا ہوا ہے۔ اسپریڈ بار مختصر اور محدود ہے، جس پر 15,600 روپے کا لیبل لگایا گیا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"230\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"28\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"15\" font-family=\"sans-serif\">بدترین صورت آپ انڈر رائٹنگ کر رہے ہیں۔</text>\n  <line x1=\"70\" y1=\"195\" x2=\"700\" y2=\"195\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <rect x=\"180\" y=\"50\" width=\"120\" height=\"145\" rx=\"4\" fill=\"#c44e52\"/>\n  <text x=\"240\" y=\"42\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">چارٹ سے دور چلتا ہے</text>\n  <text x=\"240\" y=\"215\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">ننگا: نامعلوم</text>\n  <rect x=\"470\" y=\"158\" width=\"120\" height=\"37\" rx=\"4\" fill=\"#55a868\"/>\n  <text x=\"530\" y=\"150\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">بند</text>\n  <text x=\"530\" y=\"215\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">پھیلاؤ: 15,600 روپے</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">آپ صرف ایک نمبر کو سائز دے سکتے ہیں۔ ننگی بار کا سائز کا کوئی اوپری کنارہ نہیں ہے۔</figcaption>\n</figure><h2 id=\"how-this-differs-by-who-you-are\">آپ کون ہیں اس سے یہ کیسے مختلف ہے۔</h2>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>ننگا یا ہیجڈ؟</th>\n<th>آپ کے لیے اس کا کیا مطلب ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>نہ ہی - ننگے بیچنا سرمایہ کاری نہیں ہے۔</td>\n<td>اگر آپ بالکل بھی فروخت کرتے ہیں، تو آپ کے زیر ملکیت حصص کے خلاف صرف ایک احاطہ کال ہے۔</td>\n</tr>\n<tr>\n<td>فعال تاجر</td>\n<td>صرف ہیجڈ</td>\n<td>داخلے سے پہلے روپے میں زیادہ سے زیادہ نقصان کی وضاحت کریں؛ پھیلتا ہے، کبھی ننگا نہیں ہوتا</td>\n</tr>\n<tr>\n<td>ایف اینڈ او تاجر</td>\n<td>بطور ڈیفالٹ ہیجڈ</td>\n<td>چھوٹا مارجن، ڈھکی ہوئی دم؛ برہنہ فروخت کو ایک اعلی درجے کی، نایاب رعایت سمجھیں۔</td>\n</tr>\n<tr>\n<td>اختیار بیچنے والا (آمدنی)</td>\n<td>طے شدہ خطرے کے ڈھانچے</td>\n<td>آپ کا پریمیم ایج صرف اس صورت میں زندہ رہتا ہے جب کوئی ایک ٹیل ایونٹ اس کے مہینوں کو ختم نہ کر سکے۔</td>\n</tr>\n</tbody></table>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>متعین خطرہ ایک مسئلہ کو مکمل طور پر حل کرتا ہے - کھلی ہوئی دم - لیکن یہ جادو کی ڈھال نہیں ہے۔ اس کی حدود کے بارے میں ایماندار رہو.</p>\n<p><strong>ایک پھیلاؤ اب بھی اپنی پوری متعین رقم کھو سکتا ہے، اور یہ حقیقی رقم ہے۔</strong> 15,600 روپے محدود ہے، چھوٹا نہیں۔ اسے لگاتار تین تجارتوں پر کھو دیں اور آپ 46,800 روپے نیچے ہیں۔ Defined کا مطلب محفوظ نہیں ہے۔ اس کا مطلب ہے زندہ رہنے کے قابل اور قابل قدر۔</p>\n<p><strong>تحفظ کے اپنے اخراجات ہوتے ہیں۔</strong> دو ٹانگوں کا مطلب ہے بروکریج اور چارجز کے دو سیٹ، اور ایک وسیع بولی-کراس کرنے کے لیے پوچھنا۔ چھوٹے پریمیم پر وہ رگڑ پہلے سے ہی پتلی کنارے کا اصلی ٹکڑا کھاتے ہیں۔ چھوٹے اسپریڈز کو اکثر کافی بیچیں اور اکیلے اخراجات ہی جیتنے والے خیال کو ہارنے والے خیال میں بدل سکتے ہیں۔</p>\n<p><strong>تصفیہ اور خلاء اب بھی پھیلاؤ کے اندر کاٹتے ہیں۔</strong> ہندوستانی انڈیکس کے اختیارات کے لیے، ایکسپائری نقد سے طے شدہ ہے، اس لیے ڈرنے کے لیے کوئی US طرز کی ابتدائی تفویض نہیں ہے - اصل خطرہ وہی ہے جو ایکسپائری سیٹلمنٹ پر ہوتا ہے۔ ایکسپائری کے قریب ایک پرتشدد فرق آپ کو ادائیگی کے بدترین موڑ پر کھڑا کر سکتا ہے، اور اگر آپ ان کو ایکسپائری میں رکھتے ہیں تو سٹاک آپشنز یا سٹاک فیوچرز فزیکل ڈیلیوری کی ذمہ داری لے سکتے ہیں۔ نقصان اب بھی محدود ہے - لیکن آپ کیپ کو تیزی سے اور بغیر وارننگ کے مار سکتے ہیں۔ اگر آپ پوری طرح سے نہیں سمجھتے کہ پوزیشن کیسے طے ہوتی ہے تو اسے ختم ہونے سے پہلے بند کر دیں۔</p>\n<p><strong>پریمیم کنارے حقیقی طور پر پتلا ہے۔</strong> زیادہ تر ہفتوں میں بیچنے والا تھوڑا سا جمع کرتا ہے۔ پورا کھیل اس بات کو یقینی بنا رہا ہے کہ نایاب برا ہفتہ بہت سی اچھی چیزوں کو نہیں مٹا سکتا۔ یہ بالکل وہی ہے جو ہیج آپ کو خریدتا ہے - اور خاص طور پر اس کو چھوڑنا اتنا پرکشش اور اتنا خطرناک کیوں ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>یہ وہی چربی کا نقصان ہے جو آپ نے رسک مینجمنٹ کورس کے آپشن سیلر رسک باب میں دیکھا تھا: ایک آپشن سیلر کی واپسی کا وکر بہت سی چھوٹی جیت اور کچھ نایاب، بہت بڑے نقصانات ہیں۔ ایک ننگا چھوٹا چھوڑتا ہے جو پوری طرح سے بے نقاب ہوتا ہے - ایک ایونٹ ہر جیت سے بڑا ہوسکتا ہے۔ ایک اسپریڈ ایک معروف مقام پر دم کو کاٹ دیتا ہے۔ متعین شدہ رسک بیچنے والا اب بھی کبھی کبھی کھو دیتا ہے، لیکن اس سے زیادہ نہیں جو اس نے پہلے لکھا تھا۔</p>\n</div></div>\n<p>یہ باب تعلیم ہے، سرمایہ کاری کا مشورہ نہیں، اور ہڑتال اور روپے کے اعداد و شمار مثالی مثالیں ہیں - کسی خاص آپشن کو فروخت کرنے کی سفارش نہیں ہے۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> ننگے مختصر آپشن کا واحد سب سے بڑا خطرہ کیا ہے؟</summary><p>نقصان کھلا ہوا ہے۔ آپ ایک چھوٹا پریمیم اکٹھا کرتے ہیں، لیکن اگر مارکیٹ آپ کے خلاف سخت حرکت کرتی ہے تو کوئی منزل نہیں ہے - ایک فرق آپ کے جمع کردہ سے کئی گنا زیادہ کھو سکتا ہے، جیسا کہ پریمیم شوز کے 5,200 روپے پر میرا کا تقریباً 72,800 روپے کا نقصان ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> اسپریڈ آپ کے نقصان کو کیسے روکتا ہے؟</summary><p>آپ تحفظ کے طور پر مزید دور کا اختیار خریدتے ہیں۔ اس کے اسٹرائیک سے آگے، جو خریدا گیا ٹانگ آپ کے بیچے گئے آپشن کے ساتھ پوائنٹ فی پوائنٹ حاصل کرتا ہے، اس لیے دونوں منسوخ ہو جاتے ہیں اور آپ کا نقصان رک جاتا ہے۔ آپ کا زیادہ سے زیادہ نقصان سٹرائیکس مائنس کے درمیان کا فرق ہے جمع شدہ پریمیم - ایک مقررہ نمبر جو آپ کے داخل ہونے سے پہلے معلوم ہوتا ہے۔</p>\n</details><details>\n<summary><strong>3.</strong> ارجن نے ایک 24,000 کال فروخت کی اور 24,300 کی کال 60 روپے کے کریڈیٹ میں خریدی، لاٹ سائز 65۔ اس کا زیادہ سے زیادہ نقصان کیا ہے؟</summary><p>سٹرائیکس 300 پوائنٹس کے علاوہ ہیں، اور اس نے 60 اکٹھے کیے، اس لیے وہ سب سے زیادہ کھو سکتا ہے (300 - 60) x 65 = 240 x 65 = Rs 15,600 - چاہے وہ کتنی ہی دور کیوں نہ چلا جائے۔</p>\n</details><details>\n<summary><strong>4.</strong> جب برہنہ خطرہ نہیں ہوتا ہے تو متعین خطرہ آپ کو پوزیشن کا سائز کیوں دیتا ہے؟</summary><p>سائزنگ پوچھتی ہے \"اگر یہ زیادہ سے زیادہ غلط ہو جائے تو کیا میں اس سے بچ سکتا ہوں؟\" اسپریڈ کا روپوں میں سب سے زیادہ خراب معاملہ ہے، لہذا آپ اسے خطرے والے بجٹ میں فٹ کر سکتے ہیں۔ ایک ننگے شارٹ کا سب سے برا معاملہ نامعلوم اور ممکنہ طور پر تباہ کن ہے، لہذا اس کے مقابلے میں سائز کا کوئی نمبر نہیں ہے - بیچنے والے اس کے بجائے مارجن یا گٹ محسوس کو ختم کرتے ہیں۔</p>\n</details><details>\n<summary><strong>5.</strong> اگر کوئی اسپریڈ آپ کے نقصان کو محدود کرتا ہے، تو یہ صرف \"محفوظ\" کیوں نہیں ہے؟</summary><p>آپ اب بھی پوری متعین رقم کھو سکتے ہیں، کئی بار۔ بروکریج اور پھیلاؤ میں دو ٹانگیں زیادہ لاگت آتی ہیں، سیٹلمنٹ اور گیپس آپ کو ایکسپائری کے قریب پہنچ سکتے ہیں، اور بیچنے والے کا کنارہ پتلا ہے۔ متعین خطرہ نقصان کو زندہ اور قابل قدر بناتا ہے - یہ اسے چھوٹا یا ضمانت نہیں دیتا ہے۔</p>\n</details>\n","toc":[{"level":2,"text":"دونوں تجارت، ایک منٹ میں","id":"the-two-trades-in-one-minute"},{"level":2,"text":"چٹان: ایک ننگا شارٹ کھلا کیوں ہوتا ہے۔","id":"the-cliff-why-a-naked-short-is-open-ended"},{"level":2,"text":"فرش: اسپریڈ آپ کے نقصان کو کیسے روکتا ہے۔","id":"the-floor-how-a-spread-caps-your-loss"},{"level":2,"text":"ننگے بمقابلہ پھیلاؤ، پہلو بہ پہلو","id":"naked-vs-spread-side-by-side"},{"level":2,"text":"کیوں متعین خطرہ آپ کو سائز اور سونے دیتا ہے۔","id":"why-defined-risk-lets-you-size-and-sleep"},{"level":2,"text":"آپ کون ہیں اس سے یہ کیسے مختلف ہے۔","id":"how-this-differs-by-who-you-are"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"15":{"html":"<p>میرا نے تقریباً ہر ہفتے NIFTY پر آئرن کنڈور بیچنا شروع کیا۔ خیال تقریباً بہت اچھا لگا۔ جب تک انڈیکس وسیع رینج کے اندر رہا، اس نے پریمیم برقرار رکھا۔ چار ماہ تک یہ کام کرتا رہا۔ چھوٹی جیت، چھوٹی جیت، چھوٹی جیت - تقریباً 4,000 روپے زیادہ تر ہفتے۔ اس کا کھاتہ مسلسل چڑھتا گیا اور وہ سوچنے لگی کہ اسے کوئی مشین مل گئی ہے۔ اس کے بعد بجٹ ہفتہ ریلی آئی۔ NIFTY نے تین سیشنز کے لیے ایک ہی سمت میں سخت ٹرینڈ کیا اور اپنی کال اسٹرائیک سے سیدھا بھاگا۔ اس ایک ہفتے میں اس کی تقریباً 28,000 روپے کی لاگت آئی - پچھلی چھ جیتوں کا تقریباً ہر ایک روپیہ۔ حکمت عملی نہیں ٹوٹی تھی۔ وہ صرف اس نقصان کو پورا کر چکی تھی جس کی وہ ہمیشہ قابل تھی۔</p>\n<p>پچھلے باب میں آپ نے دیکھا کہ پھیلاؤ ننگے شارٹ سے زیادہ محفوظ کیوں ہے: یہ آپ کے نقصان کو سامنے رکھتا ہے۔ یہ باب ان تین ڈھانچے کو لے جاتا ہے جن سے ایک ابتدائی شخص اصل میں ملتا ہے - کریڈٹ اسپریڈ، آئرن کنڈور اور آئرن فلائی - اور سادہ تصویروں میں ان کی ادائیگی کی شکلیں دکھاتا ہے۔ قیمتوں کا کوئی ریاضی نہیں۔ جہاں آپ پیسہ کماتے ہیں، جہاں آپ اسے کھو دیتے ہیں، اور ایک نمبر جو ہر چیز کا فیصلہ کرتا ہے۔</p>\n<h2 id=\"the-credit-spread-sell-one-buy-a-cheaper-one-further-out\">کریڈٹ اسپریڈ: ایک بیچیں، مزید سستا خریدیں۔</h2>\n<p>کریڈٹ اسپریڈ ایک ہی قسم کے دو اختیارات ہیں، جو ایک ساتھ فروخت اور خریدے جاتے ہیں۔ آپ ایک ایسا آپشن بیچتے ہیں جس کی قیمت زیادہ ہو اور مزید سستا خریدیں۔ ان کی قیمتوں میں فرق خالص کریڈٹ کے طور پر آپ کے اکاؤنٹ میں آتا ہے - اور یہ کریڈٹ آپ کے لیے زیادہ سے زیادہ ہے۔ آپ نے جو آپشن خریدا ہے وہ آپ کی سیٹ بیلٹ ہے: یہ بتاتا ہے کہ ایک بڑا اقدام آپ کو کتنا خرچ کر سکتا ہے۔</p>\n<p>آئینے کے دو ورژن ہیں۔ اے <strong>بیل ڈال پھیل گیا</strong> مارکیٹ کے نیچے فروخت کیا جاتا ہے: آپ ایک پوٹ بیچتے ہیں اور سستا پوٹ خریدتے ہیں۔ آپ اس وقت تک کریڈٹ رکھتے ہیں جب تک انڈیکس آپ کے شارٹ پٹ سے اوپر رہتا ہے۔ اے <strong>ریچھ کال پھیل گئی</strong> مارکیٹ کے اوپر بھی یہی خیال ہے: آپ کال بیچتے ہیں اور سستی کال خریدتے ہیں، اور آپ اس وقت تک کریڈٹ برقرار رکھتے ہیں جب تک کہ انڈیکس آپ کی مختصر کال سے نیچے رہتا ہے۔ ایک جھکا ہوا تیزی، ایک جھکاؤ مندی کا۔ دونوں جیت جاتے ہیں اگر انڈیکس آپ کے خلاف زیادہ آگے نہیں بڑھتا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"بیل پوٹ اسپریڈ کی ادائیگی کی شکل: بائیں منزل پر محدود نقصان، صفر کو عبور کرنے والی ڈھلوان لائن، پھر دائیں جانب کریڈٹ کے برابر فلیٹ کیپڈ منافع۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">کریڈٹ اسپریڈ (بیل ڈال): محدود منافع، محدود نقصان</text>\n  <line x1=\"50\" y1=\"190\" x2=\"720\" y2=\"190\" stroke=\"#8b949e\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <text x=\"40\" y=\"194\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">0</text>\n  <line x1=\"200\" y1=\"100\" x2=\"200\" y2=\"270\" stroke=\"#30363d\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <line x1=\"400\" y1=\"100\" x2=\"400\" y2=\"270\" stroke=\"#30363d\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <polyline points=\"60,250 200,250 300,190\" fill=\"none\" stroke=\"#c44e52\" stroke-width=\"3\"/>\n  <polyline points=\"300,190 400,130 720,130\" fill=\"none\" stroke=\"#55a868\" stroke-width=\"3\"/>\n  <text x=\"200\" y=\"288\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">لمبی پوٹ (خریدنا، کم)</text>\n  <text x=\"400\" y=\"288\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">شارٹ پٹ (بیچنا، زیادہ)</text>\n  <text x=\"120\" y=\"240\" fill=\"#c44e52\" font-size=\"11.5\" font-family=\"sans-serif\">زیادہ سے زیادہ نقصان (کیپڈ)</text>\n  <text x=\"560\" y=\"122\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"11.5\" font-family=\"sans-serif\">زیادہ سے زیادہ منافع = کریڈٹ</text>\n  <text x=\"690\" y=\"160\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">انڈیکس کی سطح →</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">اگر انڈیکس آپ کے شارٹ پٹ سے اوپر رہتا ہے تو آپ چھوٹا سا کریڈٹ رکھتے ہیں۔ اگر خریدا گیا تو نقصان کو ختم کر دے گا۔</figcaption>\n</figure><h2 id=\"the-iron-condor-two-spreads-one-range\">آئرن کنڈور: دو اسپریڈز، ایک رینج</h2>\n<p>مارکیٹ کے نیچے ایک بیل ڈال دیں اور ایک ہی وقت میں اس کے اوپر ایک ریچھ کی کال پھیلائیں، اور آپ کے پاس ایک ہے۔ <strong>لوہے کا کنڈور</strong>. آپ نے ایک رینج بیچی ہے۔ جب تک آپ کی دو مختصر ہڑتالوں کے درمیان انڈیکس ختم ہو جاتا ہے، دونوں اسپریڈز بے کار ہو جائیں گے اور آپ دونوں کریڈٹ اپنے پاس رکھیں گے۔ وہ فلیٹ سبز درمیانی حصہ آپ کا منافع کا علاقہ ہے۔ اس کے باہر دونوں طرف قدم رکھیں اور ایک اسپریڈ کھونا شروع ہو جائے گا، جب تک کہ آپ کے نقصان کو اس طرف سے خریدا ہوا بازو روک نہیں دیتا۔</p>\n<p>کنڈور کی اپیل واضح ہے: مارکیٹیں کہیں جانے میں کافی وقت صرف کرتی ہیں، اور ایک کنڈور آپ کو بالکل اسی کے لیے ادائیگی کرتا ہے۔ اس کا جال بھی اتنا ہی حقیقی ہے۔ منافع کا علاقہ وسیع اور آرام دہ ہے، جس کی وجہ سے تجارت محفوظ محسوس ہوتی ہے - لیکن \"محفوظ محسوس ہوتا ہے\" اور \"محفوظ ہے\" مختلف چیزیں ہیں، کیونکہ نقصان کا دم آپ کو یاد دلائے گا۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 320\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"آئرن کنڈور پے آف: شارٹ پٹ اور شارٹ کال کے درمیان درمیان میں ایک فلیٹ منافع کی سطح مرتفع، دونوں پروں پر محدود نقصانات تک نیچے کی طرف ڈھلوان۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"320\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">آئرن کنڈور: درمیان میں ایک فلیٹ منافع بخش زون، پروں پر نقصانات محدود</text>\n  <rect x=\"250\" y=\"150\" width=\"270\" height=\"55\" fill=\"#55a868\" opacity=\"0.14\"/>\n  <line x1=\"50\" y1=\"205\" x2=\"720\" y2=\"205\" stroke=\"#8b949e\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <text x=\"40\" y=\"209\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">0</text>\n  <line x1=\"140\" y1=\"120\" x2=\"140\" y2=\"285\" stroke=\"#30363d\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <line x1=\"250\" y1=\"120\" x2=\"250\" y2=\"285\" stroke=\"#30363d\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <line x1=\"520\" y1=\"120\" x2=\"520\" y2=\"285\" stroke=\"#30363d\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <line x1=\"630\" y1=\"120\" x2=\"630\" y2=\"285\" stroke=\"#30363d\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <polyline points=\"60,260 140,260 195,205\" fill=\"none\" stroke=\"#c44e52\" stroke-width=\"3\"/>\n  <polyline points=\"195,205 250,150 520,150 575,205\" fill=\"none\" stroke=\"#55a868\" stroke-width=\"3\"/>\n  <polyline points=\"575,205 630,260 700,260\" fill=\"none\" stroke=\"#c44e52\" stroke-width=\"3\"/>\n  <text x=\"140\" y=\"302\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"10.5\" font-family=\"sans-serif\">لمبا ڈالنا</text>\n  <text x=\"250\" y=\"302\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"10.5\" font-family=\"sans-serif\">شارٹ پٹ</text>\n  <text x=\"520\" y=\"302\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"10.5\" font-family=\"sans-serif\">مختصر کال</text>\n  <text x=\"630\" y=\"302\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"10.5\" font-family=\"sans-serif\">لمبی کال</text>\n  <text x=\"385\" y=\"143\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"11.5\" font-family=\"sans-serif\">زیادہ سے زیادہ منافع (دونوں کریڈٹ)</text>\n  <text x=\"385\" y=\"182\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">منافع کا زون: انڈیکس یہاں رہتا ہے۔</text>\n  <text x=\"95\" y=\"250\" fill=\"#c44e52\" font-size=\"11\" font-family=\"sans-serif\">زیادہ سے زیادہ نقصان</text>\n  <text x=\"665\" y=\"250\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"11\" font-family=\"sans-serif\">زیادہ سے زیادہ نقصان</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ایک کنڈور جیت جاتا ہے اگر انڈیکس صرف درمیانی رینج کے اندر رہتا ہے - اور دونوں بازو پر محدود رقم کھو دیتا ہے۔</figcaption>\n</figure><h2 id=\"the-iron-fly-same-idea-tighter\">لوہے کی مکھی: ایک ہی خیال، سخت</h2>\n<p>ایک <strong>لوہے کی مکھی</strong> (آئرن بٹر فلائی) ایک کنڈور ہے جسے بیچ میں کھینچا جاتا ہے۔ ان کے درمیان وقفے کے ساتھ دو الگ الگ شارٹ سٹرائیکس کے بجائے، آپ پوٹ اور کال کو پر فروخت کرتے ہیں۔ <em>ایک ہی</em> ہڑتال - عام طور پر موجودہ قیمت کے بالکل قریب - اور تحفظ کے لیے ہر طرف ایک بازو خریدیں۔ چونکہ آپ پیسے کے اختیارات فروخت کر رہے ہیں، آپ ایک بہت بڑا کریڈٹ جمع کرتے ہیں۔ لیکن منافع کا زون اس ایک ہڑتال کے ارد گرد ایک تنگ خیمے میں سکڑ جاتا ہے۔ آپ زیادہ کماتے ہیں اگر انڈیکس جہاں سے شروع ہوتا ہے اس کے قریب ہوتا ہے، اور اگر یہ اعتدال سے بھی بڑھ جاتا ہے تو آپ اسے واپس دیتے ہیں۔ ایک کنڈور ایک رینج پر شرط لگاتا ہے؛ خاموشی پر ایک مکھی شرط لگاتی ہے۔</p>\n<h2 id=\"the-structures-side-by-side\">ڈھانچے، ساتھ ساتھ</h2>\n<table>\n<thead>\n<tr>\n<th>ساخت</th>\n<th>جو آپ بیچتے/خریدتے ہیں۔</th>\n<th>منافع کا علاقہ</th>\n<th>زیادہ سے زیادہ منافع بمقابلہ زیادہ سے زیادہ نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>بیل ڈال پھیل گیا</td>\n<td>اونچی پوٹ بیچیں، سستا لوئر پوٹ خریدیں۔</td>\n<td>انڈیکس برقرار ہے۔ <strong>اوپر</strong> مختصر پوٹ</td>\n<td>چھوٹے کیپڈ کریڈٹ بمقابلہ بڑے کیپڈ نقصان</td>\n</tr>\n<tr>\n<td>ریچھ کی کال پھیل گئی۔</td>\n<td>کم کال بیچیں، سستی اونچی کال خریدیں۔</td>\n<td>انڈیکس برقرار ہے۔ <strong>نیچے</strong> مختصر کال</td>\n<td>چھوٹے کیپڈ کریڈٹ بمقابلہ بڑے کیپڈ نقصان</td>\n</tr>\n<tr>\n<td>آئرن کنڈور</td>\n<td>ایک بیل ڈال پھیل گیا <strong>پلس</strong> ریچھ کی کال پھیل گئی۔</td>\n<td>انڈیکس برقرار ہے۔ <strong>کے درمیان</strong> دو مختصر حملے</td>\n<td>دو چھوٹے کریڈٹ بمقابلہ دونوں طرف سے ایک بڑا محدود نقصان</td>\n</tr>\n<tr>\n<td>لوہے کی مکھی</td>\n<td>پوٹ بیچیں اور پر کال کریں۔ <strong>ایک ہی</strong> ہڑتال، ہر طرف ایک بازو خریدیں</td>\n<td>انڈیکس <strong>قریب پن</strong> وہ ایک ہڑتال</td>\n<td>بڑا کریڈٹ بمقابلہ ایک تنگ، رکھنے کے لیے مشکل زون</td>\n</tr>\n</tbody></table>\n<p>آخری کالم میں پیٹرن پر توجہ دیں۔ ان میں سے ہر ایک میں، آپ جو کریڈٹ جمع کرتے ہیں وہ اس نقصان سے چھوٹا ہوتا ہے جو آپ لے سکتے ہیں۔ یہ کوئی خامی نہیں ہے جس سے آپ خریداری کر سکتے ہیں - یہ اکثر جیتنے کی قیمت ہے۔</p>\n<h2 id=\"the-one-number-that-matters-max-loss-not-max-profit\">ایک نمبر جو اہمیت رکھتا ہے: زیادہ سے زیادہ نقصان، زیادہ سے زیادہ منافع نہیں۔</h2>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"بیس لائن کے اوپر چھ چھوٹے سبز وِن بار اور اس کے نیچے ایک لمبا سرخ ہار بار، یہ ظاہر کرتا ہے کہ ایک ہی ہار چھ جیت کو مٹا سکتا ہے اور خالص نقصان چھوڑ سکتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">چھوٹی جیت، اکثر. بڑا کھونا، شاذ و نادر ہی۔</text>\n  <line x1=\"50\" y1=\"150\" x2=\"710\" y2=\"150\" stroke=\"#8b949e\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <rect x=\"70\" y=\"110\" width=\"40\" height=\"40\" rx=\"3\" fill=\"#55a868\"/>\n  <rect x=\"125\" y=\"110\" width=\"40\" height=\"40\" rx=\"3\" fill=\"#55a868\"/>\n  <rect x=\"180\" y=\"110\" width=\"40\" height=\"40\" rx=\"3\" fill=\"#55a868\"/>\n  <rect x=\"235\" y=\"110\" width=\"40\" height=\"40\" rx=\"3\" fill=\"#55a868\"/>\n  <rect x=\"290\" y=\"110\" width=\"40\" height=\"40\" rx=\"3\" fill=\"#55a868\"/>\n  <rect x=\"345\" y=\"110\" width=\"40\" height=\"40\" rx=\"3\" fill=\"#55a868\"/>\n  <text x=\"227\" y=\"98\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"12\" font-family=\"sans-serif\">چھ جیت x تقریباً 4,000 روپے = +24,000 روپے</text>\n  <rect x=\"470\" y=\"150\" width=\"80\" height=\"120\" rx=\"3\" fill=\"#c44e52\"/>\n  <text x=\"510\" y=\"288\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"12\" font-family=\"sans-serif\">ایک نقصان: تقریباً 28,000 روپے</text>\n  <text x=\"640\" y=\"120\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">خالص نتیجہ</text>\n  <text x=\"640\" y=\"142\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"15\" font-weight=\"700\" font-family=\"sans-serif\">-4000 روپے</text>\n  <text x=\"640\" y=\"170\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">ایک جیتنے کے بعد</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">زیادہ جیت کی شرح پیسہ کمانے کے مترادف نہیں ہے: ایک مکمل نقصان چھ جیتوں کو ختم کر سکتا ہے۔</figcaption>\n</figure><p>یہاں اس کا دل ہے۔ یہ ڈھانچے اکثر جیتنے کے لیے بنائے جاتے ہیں۔ انڈیکس زیادہ تر ہفتوں تک آپ کی حد میں رہتا ہے، اس لیے آپ اپنا چھوٹا سا کریڈٹ بار بار جمع کرتے ہیں، اور جیت معمول کے مطابق محسوس ہونے لگتی ہے۔ لیکن دیکھو <em>سائز</em> ہر ایک کے نتیجے میں. ایک عام کنڈور 4000 روپے بنانے کے لیے 28,000 روپے کا خطرہ مول لے سکتا ہے۔ آپ چھ یا سات بار صحیح ہو سکتے ہیں اور ایک ہی نقصان لاٹ کو مٹا دیتا ہے۔ ایک اعلی جیت کی شرح پیسہ کمانے کے مترادف نہیں ہے۔ جو چیز آپ کو سالوینٹ رکھتی ہے وہ یہ ہے کہ آیا نایاب نقصان زندہ رہتا ہے - اور یہ مکمل طور پر آپ کے زیادہ سے زیادہ نقصان سے طے ہوتا ہے، ایک ایسی تعداد جسے آپ اس وقت جانتے ہیں جب آپ تجارت کرتے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک متعین خطرے والے بیچنے والے کے لیے، زیادہ سے زیادہ نقصان زیادہ سے زیادہ منافع سے کہیں زیادہ اہمیت رکھتا ہے۔ یہ تجارتیں عام طور پر جیت جاتی ہیں، لیکن ایک مکمل نقصان کئی جیتوں کو ختم کر سکتا ہے - اس لیے پوزیشن کا سائز اس حساب سے بنائیں کہ آپ کیا کھوتے ہیں جب آپ غلط ہوتے ہیں، اس سے کبھی نہیں جو آپ جمع کرتے ہیں جب آپ صحیح ہوتے ہیں۔ (تعلیم، مشورہ نہیں۔)</p>\n</div></div>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>کلاسک ابتدائی اقدام جیت کی شرح کو بلند کرنے کے لیے کنڈور کے حملوں کو وسیع کرنا ہے - \"انڈیکس کبھی بھی وہاں سے باہر نہیں آئے گا۔\" یہ سچ ہے کہ ایک وسیع رینج زیادہ کثرت سے جیتتا ہے۔ لیکن ایک ہی پنکھوں کو رکھتے ہوئے شارٹ سٹرائیکس کو چوڑا کرنا <em>نقصان</em> بڑا بھی، اس لیے اب آپ اسی چھوٹے کریڈٹ کو جمع کرنے کے لیے اور بھی زیادہ خطرہ مول لے رہے ہیں۔ اپنے زیادہ سے زیادہ نقصان کو خاموشی سے بڑھا کر 90% جیت کی شرح کا پیچھا کرنا بالکل اسی طرح ہے جس طرح ایک سرخ ہفتے میں سبز ہفتوں کا سلسلہ ختم ہوتا ہے جو اسے واپس لے جاتا ہے۔ ایک کنڈور کو اس کے بدترین کیس سے پرکھیں، نہ کہ اس کی ہٹ ریٹ سے۔</p>\n</div></div>\n<h2 id=\"how-this-differs-by-who-you-are\">آپ کون ہیں اس سے یہ کیسے مختلف ہے۔</h2>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>کیا یہ ڈھانچے فٹ ہیں؟</th>\n<th>کیا دیکھنا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>شاذ و نادر ہی - یہ تاجر کا آلہ ہے، سرمایہ کاری کرنے والا نہیں۔</td>\n<td>وقت اور توجہ؛ ایک کنڈور کو انتظام کرنے کی ضرورت ہے، ایک SIP کو نہیں ہے۔</td>\n</tr>\n<tr>\n<td>فعال (دشاتمک) تاجر</td>\n<td>کبھی کبھی، ایک \"رینج میں رہتا ہے\" نقطہ نظر کا اظہار کرنے کے لئے</td>\n<td>اب آپ کوئی حرکت نہ کرنے پر شرط لگا رہے ہیں - رجحان تجارت کے برعکس</td>\n</tr>\n<tr>\n<td>F&amp;O (فیوچر) تاجر</td>\n<td>مستقبل سے طے شدہ خطرے کے اختیارات میں ایک قدرتی قدم</td>\n<td>چار ٹانگوں کا مطلب ہے چارجز کے چار سیٹ اور چھوٹا سا کریڈٹ کھا جانا</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>روٹی اور مکھن کے ڈھانچے</td>\n<td>فی تجارت زیادہ سے زیادہ نقصان، اور ایک ساتھ تمام کھلے کنڈورس میں کل خطرہ</td>\n</tr>\n</tbody></table>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>دو طریقے، بنیادی طور پر - اور یہ دونوں کے بارے میں ایماندار ہونے کے قابل ہے۔</p>\n<p><strong>ایک بڑی، تیز رفتار حرکت آپ کے تحفظ سے گزر جاتی ہے۔</strong> آپ کا خریدا ہوا بازو نقصان کو پورا کرتا ہے، لیکن یہ اسے نہیں مٹاتا - اور وہ ٹوپی آپ کے کریڈٹ سے کئی گنا زیادہ ہے۔ نتیجہ کے دن کا وقفہ یا بجٹ سرپرائز آپ کے رد عمل کا اظہار کرنے سے پہلے آپ کی مختصر اور طویل ہڑتال دونوں کے ذریعے انڈیکس کو صاف کر سکتا ہے۔ آپ پوری، محدود رقم کھو دیتے ہیں۔ وہ میرا تھا: ایک ٹرینڈنگ ہفتہ، ایک زیادہ سے زیادہ نقصان، چھ جیت گئیں۔</p>\n<p><strong>انڈیکس آپ کی مختصر ہڑتال کی میعاد ختم ہونے پر بالکل ٹھیک پن کرتا ہے۔</strong> یہ خاموش ڈراؤنا خواب ہے۔ ہندوستانی انڈیکس کے اختیارات نقد سے طے شدہ ہیں، لہذا فکر کرنے کی کوئی US طرز کی ابتدائی تفویض نہیں ہے - خطرہ خود ختم ہونے والی تصفیہ ہے۔ اگر NIFTY آپ کی شارٹ اسٹرائیک پر یا اس کے بالکل قریب بند ہو جاتا ہے، تو آپ \"پن رسک\" میں پھنس جاتے ہیں: آپ اس بات کا یقین نہیں کر سکتے کہ یہ کس طرف طے پائے گا، آپ کی حفاظتی لمبی ٹانگ بیکار ختم ہو سکتی ہے جب کہ شارٹ آپ کے خلاف نقد رقم میں طے ہو جائے گا، اور نتیجہ اگلے سیشن میں سرپرائز ہو سکتا ہے۔ اسٹاک آپشنز اور اسٹاک فیوچرز پر یہ اب بھی تیز ہے، کیونکہ ایکسپائری کا مطلب شیئرز کی فزیکل ڈیلیوری ہو سکتی ہے۔ مدت ختم ہونے سے پہلے پوزیشن کو بند کر دینا، بجائے اس کے کہ اسے ہڑتال پر بیٹھنے دیں، اس سے زیادہ تر گریز کرتے ہیں۔</p>\n<p>اور پھر سست رساو۔ ہر کنڈور کی چار ٹانگیں ہوتی ہیں۔ چار ٹانگوں کا مطلب ہے بروکریج کے چار سیٹ، STT اور ایکسچینج چارجز، نیز راستے میں پھسلنا اور باہر نکلنا۔ ایک ایسی تجارت پر جس کا پورا کنارہ 4,000 روپے کا کریڈٹ ہے، رگڑ کوئی گول کرنے والی غلطی نہیں ہے - یہ ہر جیت سے ایک حقیقی کاٹتی ہے، جبکہ نقصان پورے سائز میں رہتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>متعین خطرے کا مطلب ہے کہ آپ کا نقصان ہے۔ <em>معلوم اور بند</em> - اس کا مطلب چھوٹا نہیں ہے۔ \"زیادہ سے زیادہ نقصان 28,000 روپے\" اب بھی خطرے کی وضاحت ہے۔ اس بات کو یقینی بنائیں کہ کیپڈ نمبر وہ ہے جو آپ کا اکاؤنٹ لگاتار کئی بار جذب کر سکتا ہے، کیونکہ کافی زیادہ تجارت ہو جائے گی۔</p>\n</div></div>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> ایک لائن میں کریڈٹ اسپریڈ کیا ہے؟</summary><p>ایک ہی قسم کے دو اختیارات: آپ ایک مہنگا فروخت کرتے ہیں اور خالص کریڈٹ کو برقرار رکھتے ہوئے مزید سستا خریدتے ہیں، اور آپ کے خریدے گئے آپشن سے آپ کے نقصان کی حد ہوتی ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> لوہے کا کنڈور کیسے بنایا جاتا ہے، اور اس کا زیادہ سے زیادہ منافع کب ہوتا ہے؟</summary><p>یہ ایک بیل ہے جو مارکیٹ کے نیچے پھیلا ہوا ہے اور اس کے اوپر ریچھ کی کال پھیلی ہوئی ہے۔ جب انڈیکس دو شارٹ سٹرائیکس کے درمیان ختم ہو جاتا ہے تو یہ اپنا پورا منافع کماتا ہے، اس لیے دونوں اسپریڈز بے کار ہو جاتے ہیں اور آپ دونوں کریڈٹ اپنے پاس رکھتے ہیں۔</p>\n</details><details>\n<summary><strong>3.</strong> آئرن کنڈور اور آئرن فلائی میں بنیادی فرق کیا ہے؟</summary><p>ایک کنڈور ایک وقفے کے ساتھ دو الگ الگ سٹرائیکس فروخت کرتا ہے، جس سے منافع کا وسیع علاقہ ہوتا ہے لیکن ایک چھوٹا سا کریڈٹ۔ ایک مکھی ایک ہی سٹرائیک پر دونوں آپشنز بیچتی ہے، جس سے بڑا کریڈٹ ملتا ہے لیکن منافع کا ایک تنگ زون - اسے تقریباً ساکت بیٹھنے کے لیے انڈیکس کی ضرورت ہوتی ہے۔</p>\n</details><details>\n<summary><strong>4.</strong> 90% جیتنے کی شرح اب بھی پیسے کیوں کھو سکتی ہے؟</summary><p>کیونکہ زیادہ سے زیادہ نقصان عام طور پر زیادہ سے زیادہ منافع سے کئی گنا ہوتا ہے۔ بہت سی چھوٹی جیتیں ایک مکمل نقصان سے مٹائی جا سکتی ہیں، لہذا جیت کی شرح اکیلے آپ کو اس بارے میں کچھ نہیں بتاتی ہے کہ آیا حکمت عملی پیسہ کماتی ہے - نقصان کا حجم۔</p>\n</details><details>\n<summary><strong>5.</strong> یہ ڈھانچہ ناکام ہونے کے دو اہم طریقوں کے نام بتائیں۔</summary><p>ایک بڑا، تیز اقدام آپ کے تحفظ سے گزرتا ہے اور آپ کو مکمل نقصان پہنچاتا ہے۔ یا انڈیکس میعاد ختم ہونے پر ایک مختصر ہڑتال پر ٹھیک ہوجاتا ہے، پن اور سیٹلمنٹ کا خطرہ پیدا کرتا ہے۔ دونوں کے سب سے اوپر، چار ٹانگوں پر الزامات خاموشی سے چھوٹی جیت کو ختم کر دیتے ہیں۔</p>\n</details>\n","toc":[{"level":2,"text":"کریڈٹ اسپریڈ: ایک بیچیں، مزید سستا خریدیں۔","id":"the-credit-spread-sell-one-buy-a-cheaper-one-further-out"},{"level":2,"text":"آئرن کنڈور: دو اسپریڈز، ایک رینج","id":"the-iron-condor-two-spreads-one-range"},{"level":2,"text":"لوہے کی مکھی: ایک ہی خیال، سخت","id":"the-iron-fly-same-idea-tighter"},{"level":2,"text":"ڈھانچے، ساتھ ساتھ","id":"the-structures-side-by-side"},{"level":2,"text":"ایک نمبر جو اہمیت رکھتا ہے: زیادہ سے زیادہ نقصان، زیادہ سے زیادہ منافع نہیں۔","id":"the-one-number-that-matters-max-loss-not-max-profit"},{"level":2,"text":"آپ کون ہیں اس سے یہ کیسے مختلف ہے۔","id":"how-this-differs-by-who-you-are"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"16":{"html":"<p>ارجن نے ایک NIFTY پوٹ اسپریڈ فروخت کیا - ایک متعین خطرے والی تجارت۔ اس نے تقریباً 5,000 روپے کا پریمیم جمع کیا، اور اس کا زیادہ سے زیادہ نقصان 15,000 روپے تک محدود تھا۔ اس نے آخری باب پڑھا تھا۔ وہ داخل ہونے سے پہلے ہی اپنے بدترین حالات کو جانتا تھا۔ پھر مارکیٹ اس کی مختصر ہڑتال کی طرف گرنا شروع ہوئی۔ چھوٹے، معلوم نقصان کو لینے کے بجائے، اس نے وقت خریدنے کے لیے اگلے ہفتے تک پھیلاؤ کو \"رول\" کیا۔ رول کی ادائیگی کے لیے اس نے اپنی حفاظتی لمبی ٹانگ ہٹا دی - اب پوزیشن ننگی تھی۔ مارکیٹ گرتی رہی، لہذا اس نے اپنی قیمت کو \"اوسط نیچے\" کرنے کے لیے لاٹ کو دگنا کردیا۔ تیسرے ہفتے تک اس کا 15,000 روپے کا خطرہ خاموشی سے کھلا ہوا خطرہ بن گیا۔ ایک کمزور عالمی سیشن نے اوپن میں NIFTY کو گرا دیا، اور ارجن کو اس تجارت میں تقریباً 1,40,000 روپے کا نقصان ہوا جس پر اسے زیادہ سے زیادہ پندرہ ہزار لاگت آنی تھی۔ بازار کی کسی چیز نے اسے حیران نہیں کیا۔ اس کی ایڈجسٹمنٹ ہوئی۔</p>\n<p>آخری دو ابواب نے طے شدہ خطرے کی فروخت کو بنایا: پہلے نقصان کو محدود کریں، ساخت کا احترام کریں۔ یہ باب اس لمحے کے بارے میں ہے جو خاموشی سے اس سب کو کالعدم کر دیتا ہے - ایڈجسٹمنٹ۔ پوزیشن کو ایڈجسٹ کرنا غلط نہیں ہے۔ آپ کے غلط ہونے کا اعتراف کرنے سے بچنے کے لیے ایڈجسٹ کرنا وہ جگہ ہے جہاں اکاؤنٹس مر جاتے ہیں۔</p>\n<h2 id=\"what-adjusting-actually-means\">\"ایڈجسٹ\" کا اصل مطلب کیا ہے۔</h2>\n<p>جب کوئی تجارت آپ کے خلاف ہوتی ہے، تو آپ کے پاس صرف اسے بند کرنے کے علاوہ چار وسیع اقدامات ہوتے ہیں۔</p>\n<ul>\n<li><strong>رولنگ</strong> - موجودہ پوزیشن کو بند کریں اور اسی طرح کی پوزیشن کو بعد میں ایکسپائری میں دوبارہ کھولیں، تاکہ تجارت واپس آنے کے لیے \"وقت خریدیں\"۔</li>\n<li><strong>شفٹنگ ہڑتالیں۔</strong> - قیمت کا پیچھا کرنے کے لیے اپنی ہڑتالوں کو اوپر یا نیچے منتقل کریں۔</li>\n<li><strong>ٹانگیں شامل کرنا</strong> - ادائیگی کی شکل کو تبدیل کرنے کے لیے ایک اور آپشن پر بولٹ (یا موجودہ کو ہٹا دیں)۔</li>\n<li><strong>دوگنا نیچے</strong> - بدتر قیمت پر مزید لاٹ شامل کریں، تاکہ آپ کا اوسط اندراج بہتر نظر آئے۔</li>\n</ul>\n<p>ان میں سے ہر ایک سمجھدار، خطرے کو کم کرنے والا اقدام ہو سکتا ہے۔ ہر ایک ایک چیز کا بھیس بن سکتا ہے: نقصان کی بکنگ نہیں کرنا۔ میکانکس باہر سے ایک جیسے نظر آتے ہیں۔ فرق مکمل طور پر ہے۔ <em>کیوں</em> آپ یہ کر رہے ہیں اور <em>جب آپ نے فیصلہ کیا۔</em> کو</p>\n<h2 id=\"the-one-honest-test\">ایک ایماندارانہ امتحان</h2>\n<p>کسی بھی ایڈجسٹمنٹ سے پہلے، ایک سوال پوچھیں: <strong>کیا یہ میرے خطرے کو کم کرتا ہے یا اس کی وضاحت کرتا ہے، یا نقصان سے بچنے کے لیے یہ میرے خطرے کو بڑھاتا ہے؟</strong></p>\n<p>ایک اچھی ایڈجسٹمنٹ آپ کے بدترین کیس کو چھوٹا یا بڑا بناتی ہے، اور آپ نے داخل ہونے سے پہلے اس کی منصوبہ بندی کی تھی۔ وقت میں ایک ٹیسٹ شدہ اسپریڈ کو رول کرنا <em>کریڈٹ کے لیے</em>, اس اصول کے مطابق جو آپ نے پہلے سے لکھ دیا ہے، بغیر کسی خطرے کے حقیقی طور پر کمرہ خرید سکتے ہیں۔ اپنے کھوئے ہوئے شارٹ کو بند کرنا اور اسے ایک چھوٹی، مزید آؤٹ پوزیشن سے تبدیل کرنا نمائش کو کم کرتا ہے۔ یہ انتظامیہ ہیں۔</p>\n<p>ایک خراب ایڈجسٹمنٹ آپ کا بدترین کیس بناتی ہے۔ <em>بڑا</em>. حفاظتی ٹانگ کو ہٹانا، لاٹیں شامل کرنا، پھیلاؤ کو چوڑا کرنا، یا پیسے کے قریب ننگے شارٹ کو رول کرنا یہ سب کچھ بڑھاتا ہے جو آپ کھو سکتے ہیں۔ وہ نتیجہ خیز محسوس کرتے ہیں کیونکہ آپ \"کچھ کر رہے ہیں\"۔ آپ اصل میں کیا کر رہے ہیں ہارنے والی شرط کو زندہ رکھنے کے لیے زیادہ ادائیگی کر رہے ہیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 320\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک ہاری ہوئی تجارت دو راستوں میں بٹ جاتی ہے۔ اچھا راستہ پہلے سے طے شدہ اصول کے مطابق چلتا ہے اور خطرے کی وضاحت رکھتا ہے، جس کا اختتام چھوٹے معلوم نقصان پر ہوتا ہے۔ خراب راستہ دوگنا ہو جاتا ہے اور ہیجز کو ہٹاتا ہے، جس سے خطرہ بڑھتا ہے ممکنہ دھماکے میں۔\">\n  <defs>\n    <marker id=\"aw\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\" markerUnits=\"strokeWidth\">\n      <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8b949e\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"320\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ایک ہی کھونے والی تجارت سے دو راستے</text>  <rect x=\"300\" y=\"48\" width=\"160\" height=\"50\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\"/>\n  <text x=\"380\" y=\"70\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">تجارت کو نقصان ہو رہا ہے۔</text>\n  <text x=\"380\" y=\"88\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">ایک چھوٹا، متعین نقصان</text>  <line x1=\"340\" y1=\"98\" x2=\"190\" y2=\"128\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#aw)\"/>\n  <line x1=\"420\" y1=\"98\" x2=\"570\" y2=\"128\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#aw)\"/>  <rect x=\"30\" y=\"132\" width=\"320\" height=\"158\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\"/>\n  <text x=\"190\" y=\"156\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">اچھی ایڈجسٹمنٹ (منصوبہ بند)</text>\n  <text x=\"46\" y=\"182\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">کریڈٹ کے لیے پہلے سے طے شدہ اصول کے مطابق رول آؤٹ کریں۔</text>\n  <text x=\"46\" y=\"204\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">خطرہ متعین رہتا ہے یا چھوٹا ہو جاتا ہے۔</text>\n  <text x=\"46\" y=\"226\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">یا صرف اپنے اسٹاپ پوائنٹ پر بند کریں۔</text>\n  <rect x=\"46\" y=\"244\" width=\"288\" height=\"32\" rx=\"6\" fill=\"#0d1117\" stroke=\"#55a868\"/>\n  <text x=\"190\" y=\"265\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">بدترین صورت: چھوٹا، معلوم نقصان</text>  <rect x=\"410\" y=\"132\" width=\"320\" height=\"158\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\"/>\n  <text x=\"570\" y=\"156\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">خراب ایڈجسٹمنٹ (گھبراہٹ)</text>\n  <text x=\"426\" y=\"182\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">لاٹ کو دوگنا کریں، ہیج کو ہٹا دیں۔</text>\n  <text x=\"426\" y=\"204\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">خطرہ بڑھتا ہے؛ نقصان کھلا ختم ہو جاتا ہے</text>\n  <text x=\"426\" y=\"226\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">نقصان کی بکنگ سے بچنے کے لیے کچھ بھی</text>\n  <rect x=\"426\" y=\"244\" width=\"288\" height=\"32\" rx=\"6\" fill=\"#0d1117\" stroke=\"#c44e52\"/>\n  <text x=\"570\" y=\"265\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">بدترین صورت: ایک دھماکے</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ایک ہی ہارنے والی تجارت، ایک ہی لفظ \"ایڈجسٹ\" - لیکن ایک راستہ خطرے کو چھوٹا رکھتا ہے اور ایک راستہ اسے بڑھاتا ہے۔</figcaption>\n</figure>\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>خطرے کو منظم کرنے یا اس کی وضاحت کرنے کے لیے پوزیشن کو ایڈجسٹ کریں - نقصان کی بکنگ سے کبھی بھی گریز کریں۔ اگر کوئی ایڈجسٹمنٹ آپ کے بدترین کیس کو بڑا بناتا ہے، تو یہ ٹھیک نہیں ہے۔ یہ اسی ہارنے والے خیال پر ایک بڑی شرط ہے۔</p>\n</div></div>\n<h2 id=\"this-is-loss-aversion-wearing-a-costume\">یہ ایک لباس پہننے کے نقصان سے بچنے والا ہے</h2>\n<p>ماڈیول اے نے سکھایا کہ نقصان سے تقریباً دوگنا نقصان ہوتا ہے جتنا ایک ہی فائدہ اچھا لگتا ہے، اور یہ کہ دماغ تجارت کو غلط تسلیم کرنے کے درد سے بچنے کے لیے تقریباً کچھ بھی کرے گا۔ ایڈجسٹمنٹ وہ جگہ ہے جہاں وہ جبلت ہوشیار ہوجاتی ہے۔ \"میں ہار نہیں رہا ہوں - میں رول کر رہا ہوں۔\" \"میں غلط نہیں ہوں - میں ابھی جلدی ہوں۔\" \"میں یہاں شامل کروں گا اور اوسط نیچے آجائے گا۔\" ان جملوں میں سے ہر ایک لباس میں نقصان سے بچنے والا ہے، اور لباس مہارت کی زبان ہے۔</p>\n<p>بتانا آسان ہے۔ ایک حقیقی رسک مینجمنٹ ایڈجسٹمنٹ پرسکون ہے اور اس کا پہلے سے فیصلہ کیا گیا تھا۔ نقصان سے بچنے کی ایڈجسٹمنٹ فوری ہے، اصلاحی، اور ہمیشہ پوزیشن کو بڑھاتی ہے۔ اگر آپ نے صرف ایڈجسٹمنٹ کے بارے میں سوچا ہے۔ <em>کے بعد</em> تجارت سرخ ہو گئی، اس کے بارے میں بہت مشکوک ہو.</p>\n<h2 id=\"rolling-a-loser-how-the-risk-grows\">ہارنے والے کو رول کرنا: خطرہ کیسے بڑھتا ہے۔</h2>\n<p>دیکھیں اصل میں ارجن کے ساتھ کیا ہوا۔ ہر \"ایڈجسٹ\" کو ایک چھوٹے، معقول قدم کی طرح محسوس ہوا۔ اکٹھے ہو کر انہوں نے پندرہ ہزار روپے کے مسئلے کو ڈیڑھ لاکھ کی تباہی میں بدل دیا۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"سرخ سلاخوں کی ایک بڑھتی ہوئی سیڑھی۔ اصل بیان کردہ خطرہ چھوٹا ہے، پھر ہر رول، ٹانگوں کو ہٹانا اور لاٹ کو دوگنا کرنے سے زیادہ سے زیادہ نقصان کا بار لمبا ہو جاتا ہے، جس کا اختتام اوپن اینڈڈ بلو اپ پر ہوتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ہر \"ایڈجسٹمنٹ\" زیادہ سے زیادہ نقصان کو بڑھاتا ہے۔</text>  <line x1=\"60\" y1=\"250\" x2=\"730\" y2=\"250\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <text x=\"50\" y=\"150\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\" transform=\"rotate(-90 50 150)\">زیادہ سے زیادہ نقصان</text>  <rect x=\"80\" y=\"214\" width=\"120\" height=\"36\" rx=\"4\" fill=\"#55a868\"/>\n  <text x=\"140\" y=\"237\" text-anchor=\"middle\" fill=\"#0d1117\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">15 ہزار روپے</text>\n  <text x=\"140\" y=\"270\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"10.5\" font-family=\"sans-serif\">اصل پھیلاؤ</text>  <rect x=\"240\" y=\"178\" width=\"120\" height=\"72\" rx=\"4\" fill=\"#dd8452\"/>\n  <text x=\"300\" y=\"219\" text-anchor=\"middle\" fill=\"#0d1117\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">30 ہزار روپے</text>\n  <text x=\"300\" y=\"270\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"10.5\" font-family=\"sans-serif\">رول آؤٹ + وسیع تر</text>  <rect x=\"400\" y=\"120\" width=\"120\" height=\"130\" rx=\"4\" fill=\"#c44e52\"/>\n  <text x=\"460\" y=\"190\" text-anchor=\"middle\" fill=\"#0d1117\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">60 ہزار روپے</text>\n  <text x=\"460\" y=\"270\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"10.5\" font-family=\"sans-serif\">ہیج کو ہٹا دیں۔</text>  <rect x=\"560\" y=\"58\" width=\"120\" height=\"192\" rx=\"4\" fill=\"#c44e52\"/>\n  <text x=\"620\" y=\"120\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">کھلا ہوا</text>\n  <text x=\"620\" y=\"270\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"10.5\" font-family=\"sans-serif\">لاٹ کو دوگنا کریں۔</text><p>  <text x=\"380\" y=\"294\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10.5\" font-family=\"sans-serif\">وقت اور گھبراہٹ بائیں سے دائیں حرکت کرتی ہے - جس نقصان سے آپ گریز کر رہے تھے وہ بڑھتا ہی جاتا ہے۔</text>\n</svg></p>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ہارنے والے کو رول کرنے اور دوگنا کرنے سے نقصان نہیں مٹتا ہے - یہ ایک بڑے کو ملتوی کر دیتا ہے۔</figcaption>\n</figure><p>ظالمانہ حصہ یہ ہے کہ رولنگ اکثر چند بار \"کام\" کرتی ہے۔ مارکیٹ اچھالتی ہے، رولڈ ٹریڈ اچھی آتی ہے، اور جو سبق آپ سیکھتے ہیں وہ غلط ہے: جس سے آپ ہمیشہ باہر نکل سکتے ہیں۔ تو آپ کا سائز بڑھ جاتا ہے۔ پھر ایک حرکت واپس نہیں آتی، اور جو مقام آپ نے بڑھایا ہے وہ اب جذب کرنے کے لیے بہت بڑا ہے۔ وہ حکمت عملی جس نے آپ کو ایک ہی سیشن میں پریمیم کے ایک سال پیچھے مہینوں کے لیے چھوٹی جیت ادا کی۔</p>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>کلاسک ٹریپ: ایک مختصر آپشن آپ کے خلاف جاتا ہے، لہذا آپ زیادہ فروخت کرکے \"اوسط نیچے\" جاتے ہیں، یا آپ اسے قریب تر کرتے ہیں اور رول کو فنڈ دینے کے لیے حفاظتی ونگ کو ہٹا دیتے ہیں۔ آپ تجارت کو بہتر نہیں کر رہے ہیں - آپ وہی چیز حذف کر رہے ہیں جس نے اسے زندہ رکھا۔ نقصان کی بکنگ سے بچنے کے لیے شارٹ پر دوگنا کرنا یہ ہے کہ کس طرح ایک طے شدہ خطرے کا تاجر غیر متعینہ خطرہ بن جاتا ہے۔ اس کے بجائے چھوٹے نقصان کو بک کرو۔</p>\n</div></div>\n<h2 id=\"good-vs-bad-adjustment-the-checklist\">اچھا بمقابلہ برا ایڈجسٹمنٹ: چیک لسٹ</h2>\n<p>آرڈر دینے سے پہلے اس کے ذریعے کوئی بھی ایڈجسٹمنٹ کریں۔ اگر یہ زیادہ تر دائیں کالم میں اترتا ہے تو اس کے بجائے رکیں اور بند کریں۔</p>\n<table>\n<thead>\n<tr>\n<th>سوال</th>\n<th>اچھی ایڈجسٹمنٹ</th>\n<th>خراب ایڈجسٹمنٹ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>کیا میں نے داخل ہونے سے پہلے اس کی منصوبہ بندی کی تھی؟</td>\n<td>ہاں - یہ میرے اصولوں میں تھا۔</td>\n<td>نہیں - میں نے ابھی اس کے بارے میں سوچا۔</td>\n</tr>\n<tr>\n<td>میرے زیادہ سے زیادہ نقصان کا کیا ہوتا ہے؟</td>\n<td>وہی رہتا ہے یا سکڑ جاتا ہے۔</td>\n<td>بڑھتا ہے۔</td>\n</tr>\n<tr>\n<td>کیا میں یہ کریڈٹ کے لیے کر رہا ہوں؟</td>\n<td>ہاں، یا خطرے سے پاک</td>\n<td>میں اندر رہنے کے لیے مارجن کی ادائیگی / اضافہ کر رہا ہوں۔</td>\n</tr>\n<tr>\n<td>کیا پوزیشن چھوٹی ہو رہی ہے؟</td>\n<td>ایک ہی سائز یا اس سے چھوٹا</td>\n<td>بڑا - زیادہ لاٹ</td>\n</tr>\n<tr>\n<td>میں واقعی یہ کیوں کر رہا ہوں؟</td>\n<td>متعین خطرے کا انتظام کرنے کے لیے</td>\n<td>بکنگ نقصان سے بچنے کے لیے</td>\n</tr>\n<tr>\n<td>کیا میں اسے یہاں بند کر سکتا ہوں؟</td>\n<td>ہاں، اور میں نہ کرنے کا انتخاب کر رہا ہوں۔</td>\n<td>نہیں - بند کرنا ناقابل برداشت محسوس ہوتا ہے۔</td>\n</tr>\n</tbody></table>\n<p>ایک سادہ پری ٹریڈ اصول ان سب کو مات دیتا ہے: داخل ہونے سے پہلے، لکھ لیں۔ <em>دونوں</em> آپ کی ایڈجسٹمنٹ (اگر کوئی ہے) اور آپ کا \"صرف اسے بند کریں\" پوائنٹ - قیمت یا نقصان جس پر آپ باہر نکلتے ہیں اس سے کوئی فرق نہیں پڑتا ہے۔ اگر آپ اس مقام تک پہنچ جاتے ہیں، تو آپ خود سے بات چیت نہیں کرتے۔</p>\n<h2 id=\"how-this-differs-by-who-you-are\">آپ کون ہیں اس سے یہ کیسے مختلف ہے۔</h2>\n<p>\"ایڈجسٹ\" کا مطلب ہے مختلف چیزیں اور آپ کی سیٹ کے لحاظ سے مختلف خطرہ ہوتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>\"ایڈجسٹ\" کیسا لگتا ہے۔</th>\n<th>حقیقی خطرہ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>سزا سنانے والے اسٹاک پر اوسط نیچے</td>\n<td>ٹھیک ہے اگر منصوبہ بندی کی گئی ہے اور مقالہ برقرار ہے۔ خطرناک ہے اگر یہ صرف غلطی تسلیم کرنے سے انکار کر رہا ہے۔</td>\n</tr>\n<tr>\n<td>اسٹاک / سوئنگ ٹریڈر</td>\n<td>ایک سٹاپ کو منتقل کرنا \"اسے جگہ دینے کے لیے\"</td>\n<td>نقصان سے بچنے کے لیے اسٹاپ کو وسیع کرنا چھوٹے نقصان کو بڑے نقصان میں بدل دیتا ہے۔</td>\n</tr>\n<tr>\n<td>F&amp;O (فیوچر) تاجر</td>\n<td>کھوتے ہوئے مستقبل میں بہت کچھ شامل کرنا</td>\n<td>لیوریج کا مطلب ہے کہ دگنی پوزیشن مارجن سے آپ کو تیزی سے کال کر سکتی ہے۔</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>رولنگ، پنکھوں کو ہٹانا، شارٹس کو دوگنا کرنا</td>\n<td>سب سے زیادہ خطرہ - ایڈجسٹمنٹ خاموشی سے متعین خطرے کو کھلے خطرے میں بدل دیتے ہیں۔</td>\n</tr>\n</tbody></table>\n<p>پیٹرن ہر جگہ یکساں ہے: ایک ایڈجسٹمنٹ جو منصوبہ بند ہے اور خطرے کو کم کرتی ہے وہ انتظام ہے۔ ایک ایڈجسٹمنٹ جو اصلاح شدہ ہے اور خطرہ بڑھتا ہے انکار ہے۔ آپشن بیچنے والے کے پاس اپنے آپ کو بے وقوف بنانے کے لیے سب سے زیادہ ٹولز ہیں۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>یہ باب آپ کو کبھی ایڈجسٹ کرنے کا نہیں کہہ رہا ہے۔ یہ اس کی اپنی غلطی ہوگی۔</p>\n<p><strong>کچھ ایڈجسٹمنٹ حقیقی طور پر اچھی ہیں اور ان کا استعمال کیا جانا چاہیے۔</strong> کریڈٹ کے لیے وقت پر ٹیسٹ شدہ اسپریڈ آؤٹ کو رول کرنا، خطرے سے دوچار سائیڈ کو بند کر کے خطرہ مول لینا، یا چھوٹی، مزید تاریخ والی پوزیشن میں تبدیل کرنا یہ سب خطرے کو کم کر سکتے ہیں۔ \"کبھی ایڈجسٹ نہ کریں\" کا قاعدہ آپ کو وہ نقصان اٹھانے پر مجبور کرے گا جس کا آپ نے انتظام کیا تھا۔ بات یہ نہیں ہے۔ <em>نہیں</em> ایڈجسٹمنٹ - یہ کوئی ایڈجسٹمنٹ نہیں ہے جو نقصان سے بچنے کے لیے خطرہ بڑھاتا ہے۔</p>\n<p><strong>ایک پہلے سے طے شدہ اصول ہر صورت میں زندہ نہیں رہتا۔</strong> بازاروں کا فرق۔ بعض اوقات آپ کا \"صرف اسے بند کریں\" پوائنٹ ایک ہی پرنٹ میں چھلانگ لگا دیتا ہے اور آپ اپنی منصوبہ بند قیمت پر باہر نہیں نکل سکتے - یہ دم کا خطرہ ہے، اور اگلا باب بالکل اسی کے بارے میں ہے۔ ایک منصوبہ نقصان کو کم کرتا ہے؛ یہ ہر بار آپ سے بچنے کا وعدہ نہیں کرتا۔</p>\n<p><strong>\"تعریف شدہ\" کی وضاحت صرف اس صورت میں کی جاتی ہے جب آپ اس کی وضاحت کرتے رہیں۔</strong> آپ کا زیادہ سے زیادہ نقصان صرف اس وقت ہوتا ہے جب ڈھانچہ برقرار رہے۔ جس لمحے آپ بازو کو ہٹاتے ہیں یا کسی برہنہ حالت میں رول کرتے ہیں، ٹوپی ختم ہو جاتی ہے، اور جو بھی سکون آپ نے \"تعین شدہ خطرے\" سے لیا وہ اس کے ساتھ جاتا ہے۔</p>\n<p>یہ تعلیم ہے، کسی مخصوص عہدے پر مشورہ نہیں۔ ایماندارانہ ٹیک وے چھوٹا اور مضبوط ہے: داخل ہونے سے پہلے اپنی ایڈجسٹمنٹ اور باہر نکلنے کا فیصلہ کریں، اور صرف اس لیے ایڈجسٹ نہ کریں کہ بکنگ نقصان پہنچاتی ہے۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> وہ کونسا واحد ٹیسٹ ہے جو اچھے ایڈجسٹمنٹ کو برے سے الگ کرتا ہے؟</summary><p>چاہے یہ آپ کے خطرے کو کم کرتا ہے یا بڑھاتا ہے۔ ایک اچھی ایڈجسٹمنٹ آپ کے زیادہ سے زیادہ نقصان کو یکساں یا کم رکھتی ہے اور اس کی پہلے سے منصوبہ بندی کی گئی تھی۔ نقصان کی بکنگ سے بچنے کے لیے ایک خراب ایڈجسٹمنٹ آپ کے بدترین کیس کو بڑھا دیتی ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> کھونے والے مختصر آپشن پر دوگنا ہونا اتنا خطرناک کیوں ہے؟</summary><p>یہ پہلی تجارت کے غلط ہونے کو تسلیم کرنے سے بچنے کے لیے بدتر قیمت پر مزید کھلے خطرے کا اضافہ کرتا ہے۔ آپ اس پوزیشن کو بڑا کرتے ہیں جو آپ کو تکلیف دے رہا ہے، لہذا ایک مسلسل حرکت ایک چھوٹے، قابل انتظام نقصان کو بڑے نقصان میں بدل دیتی ہے - اور ایک ننگے شارٹ پر، ایک کھلا ہوا نقصان۔</p>\n</details><details>\n<summary><strong>3.</strong> ایڈجسٹمنٹ نقصان سے بچنے سے کیسے منسلک ہے؟</summary><p>نقصان سے بچنا نقصان کی بکنگ کو تقریباً دوگنا تکلیف دہ بناتا ہے جتنا کہ مساوی فائدہ اچھا لگتا ہے۔ ایڈجسٹ کرنے سے آپ اپنے آپ کو یہ بتا کر اس تکلیف سے بچ سکتے ہیں کہ آپ ہارنے کی بجائے \"منظم\" کر رہے ہیں۔ اصلاحی، فوری ایڈجسٹمنٹ مہارت کا لباس پہن کر نقصان سے بچنا ہے۔</p>\n</details><details>\n<summary><strong>4.</strong> تجارت میں داخل ہونے سے پہلے آپ کو کن دو چیزوں کا فیصلہ کرنا چاہیے؟</summary><p>آپ کا ایڈجسٹمنٹ پلان (اگر کوئی ہے) اور آپ کا \"صرف اسے بند کریں\" پوائنٹ - قیمت یا نقصان جہاں سے آپ باہر نکلتے ہیں اس سے کوئی فرق نہیں پڑتا ہے۔ دونوں کا پیشگی فیصلہ کرنا آپ کو جذباتی لمحے میں خود سے بات چیت کرنے سے روکتا ہے۔</p>\n</details><details>\n<summary><strong>5.</strong> کیا یہ باب کہتا ہے کہ آپ کو کبھی بھی پوزیشن کو ایڈجسٹ نہیں کرنا چاہئے؟</summary><p>نہیں، کچھ ایڈجسٹمنٹ حقیقی طور پر خطرے کو کم کرتی ہیں، جیسے کہ کریڈٹ کے لیے ٹیسٹ شدہ اسپریڈ آؤٹ کو رول کرنا یا خطرے والی طرف کو بند کرنا۔ اصول زیادہ تنگ ہے: کبھی بھی ایسی ایڈجسٹمنٹ نہ کریں جس سے آپ کا خطرہ بڑھ جائے صرف نقصان کی بکنگ سے بچنے کے لیے۔</p>\n</details>\n","toc":[{"level":2,"text":"\"ایڈجسٹ\" کا اصل مطلب کیا ہے۔","id":"what-adjusting-actually-means"},{"level":2,"text":"ایک ایماندارانہ امتحان","id":"the-one-honest-test"},{"level":2,"text":"یہ ایک لباس پہننے کے نقصان سے بچنے والا ہے","id":"this-is-loss-aversion-wearing-a-costume"},{"level":2,"text":"ہارنے والے کو رول کرنا: خطرہ کیسے بڑھتا ہے۔","id":"rolling-a-loser-how-the-risk-grows"},{"level":2,"text":"اچھا بمقابلہ برا ایڈجسٹمنٹ: چیک لسٹ","id":"good-vs-bad-adjustment-the-checklist"},{"level":2,"text":"آپ کون ہیں اس سے یہ کیسے مختلف ہے۔","id":"how-this-differs-by-who-you-are"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"17":{"html":"<p>میرا نے آمدنی کے لیے آپشنز بیچ دیے۔ ہر ہفتے اس نے NIFTY پر ایک گلا فروخت کیا - ایک کال مارکیٹ سے بہت اوپر اور ایک بہت نیچے - اور پریمیم کو اس کے اکاؤنٹ میں آنے دیں۔ چھوٹا، مستحکم، تقریباً بورنگ۔ دس مہینوں تک اس نے کام کیا: تقریباً 8,000 سے 12,000 روپے فی ہفتہ، تقریباً 4,00,000 روپے 6,00,000 روپے کے اکاؤنٹ پر بنک ہوئے۔ وہ اسے اپنی \"تنخواہ\" کہنے لگی۔ پھر ایک صبح مارکیٹ ایک عالمی جھٹکے سے نیچے گر گئی۔ اس نے جو پوٹ 40 روپے میں بیچا تھا وہ 520 روپے میں کھلا۔ اس سے پہلے کہ وہ سوچ بھی پاتی، ایک دن ان احتیاط سے ہفتہ وار منافع کے نو ماہ کے قریب ختم ہو گیا۔ اس کے طریقہ کار کے بارے میں کچھ بھی نہیں بدلا تھا۔ بازار نے اسے بس اپنی دم دکھائی تھی۔</p>\n<p>یہ باب اس دم کے بارے میں ہے - وہ نایاب، پرتشدد دن جو آپشن بیچنے والے کے مہینوں کے پریمیم کو مٹا دیتا ہے - اور بیچنے والے کس طرح تیاری کرتے ہیں تاکہ وہ دن مہلک کے بجائے زندہ رہے۔ یہ آپشن سیلر پلے بک کو بند کر دیتا ہے۔</p>\n<h2 id=\"the-shape-of-a-seller-s-risk\">بیچنے والے کے خطرے کی شکل</h2>\n<p>اختیارات فروخت کرنا ان کو خریدنے کے برعکس تجارت ہے۔ آپ تھوڑی سی رقم اکٹھا کرتے ہیں، اکثر، ایک نایاب، بڑا نقصان اٹھانے کے بدلے میں۔ زیادہ تر ہفتوں میں آپ کے بیچے گئے اختیارات کی میعاد ختم ہوجاتی ہے اور آپ پریمیم رکھتے ہیں۔ یہ فرش سے سکے اٹھانے کی طرح محسوس ہوتا ہے۔ کیچ سکوں کی طرف لپکنے والی چیز ہے۔</p>\n<p>آپ کا انعام ختم ہو گیا ہے - آپ نے جو پریمیم اکٹھا کیا ہے وہ سب سے زیادہ ہے جو آپ اس تجارت پر کما سکتے ہیں۔ آپ کا نقصان اسی طرح سے محدود نہیں ہے۔ ایک مختصر آپشن آپ کو کئی گنا خرچ کر سکتا ہے جو آپ نے لیا ہے۔ یہ چھوٹی چھوٹی جیتوں کا ایک لمبا ڈھیر ہے اور، ہارنے والے پہلو سے بہت دور، چند دن جو آپ کی اب تک کی ہر جیت سے بڑے ہیں۔ وہ موٹا، غیر متوقع لیکن تباہ کن خطہ ہے۔ <strong>دم کا خطرہ</strong> - تقسیم کی دم میں رہنے والا نقصان۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"بیچنے والے کے روزمرہ کے نتائج کی ترچھی تقسیم: صفر سے بالکل اوپر چھوٹے فوائد کا ایک لمبا تنگ کوبڑ، اور ایک لمبی موٹی دم جو بڑے نقصانات میں رہ گئی، سایہ دار سرخ اور دم پر لیبل لگا ہوا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">بیچنے والے کے روزانہ کے نتائج: اکثر چھوٹے فوائد، شاذ و نادر ہی بہت بڑا نقصان</text>\n  <line x1=\"50\" y1=\"250\" x2=\"720\" y2=\"250\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <text x=\"60\" y=\"272\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">بڑے نقصانات</text>\n  <text x=\"640\" y=\"272\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">چھوٹا فائدہ</text>\n  <line x1=\"560\" y1=\"60\" x2=\"560\" y2=\"250\" stroke=\"#8b949e\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <text x=\"560\" y=\"290\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">صفر</text>\n  <path d=\"M70,248 C 240,246 360,242 440,232 C 500,224 540,150 560,78 C 580,150 610,236 660,247 L 700,249 L 700,250 L 70,250 Z\" fill=\"#11161d\" stroke=\"#55a868\" stroke-width=\"2\"/>\n  <path d=\"M70,248 C 240,246 360,242 440,232 C 470,228 490,210 510,184 L 510,250 L 70,250 Z\" fill=\"#c44e52\" fill-opacity=\"0.35\" stroke=\"none\"/>\n  <text x=\"250\" y=\"210\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">دم</text>\n  <text x=\"250\" y=\"228\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">ایک نایاب دن، بہت بڑا نقصان</text>\n  <text x=\"588\" y=\"120\" fill=\"#55a868\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">زیادہ تر دن</text>\n  <text x=\"588\" y=\"138\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">پریمیم رکھیں</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">بیچنے والا چھوٹا جیتتا ہے، اکثر - اور بڑا ہارتا ہے، شاذ و نادر ہی۔ سارا خطرہ بائیں دم میں رہتا ہے۔</figcaption>\n</figure>\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک دم کا دن ایک سال کو مٹا سکتا ہے۔ چونکہ بیچنے والے کی جیت چھوٹی اور محدود ہوتی ہے جبکہ نایاب نقصان زیادہ ہوتا ہے، ریاضی سفاک ہے: ایک برا فرق دس ماہ کے پریمیم سے بڑا ہو سکتا ہے۔ بقا زیادہ بار جیتنے کے بارے میں نہیں ہے - آپ پہلے ہی کرتے ہیں۔ یہ اس بات کو یقینی بنانے کے بارے میں ہے کہ جس دن آپ ہار گئے وہ آپ کو ختم نہیں کر سکتا۔</p>\n</div></div>\n<h2 id=\"three-things-that-build-the-tail\">تین چیزیں جو دم بناتی ہیں۔</h2>\n<p>ایک دم کا دن شاذ و نادر ہی صرف قیمت کا اقدام ہوتا ہے۔ تین قوتیں عام طور پر ایک ساتھ آتی ہیں، اور ہر ایک دوسرے کو بدتر بناتی ہے۔</p>\n<p><strong>ایک رات کا وقفہ۔</strong> بازار جہاں سے بند ہوا وہاں سے کھلتا ہے - ایک عالمی جھٹکا، حیرت انگیز انتخاب یا پالیسی کا نتیجہ، جنگ کی سرخی۔ نقصان ہوتا ہے۔ <em>کے درمیان</em> سیشنز، جب آپ تجارت نہیں کر سکتے۔ آپ پہلے ہی سوراخ میں گہری جاگتے ہیں۔ ایک سٹاپ نقصان مدد نہیں کرتا، کیونکہ قیمت کبھی بھی آپ کے سٹاپ سے نہیں گزری تھی - یہ اس پر چھلانگ لگا دیتا ہے۔</p>\n<p><strong>اتار چڑھاؤ کا دھماکہ۔</strong> جب خوف بڑھتا ہے، مضمر اتار چڑھاؤ - خوف کے لیے مارکیٹ کی قیمت - اس کے ساتھ چھلانگ لگاتی ہے، اور ہر آپشن اوپر کی طرف بڑھتا ہے۔ ایک آپشن جو آپ نے 40 روپے میں بیچا ہے اس کی قیمت 300 روپے یا 500 روپے ہو سکتی ہے یہاں تک کہ جب صرف انڈیکس کی منتقلی اس کی وضاحت نہیں کرے گی، کیونکہ پوری <em>ڈر پریمیم</em> غبارے والا آپ سمت میں تقریباً درست ہوسکتے ہیں اور پھر بھی اتار چڑھاؤ میں دھماکے سے کچل سکتے ہیں۔</p>\n<p><strong>لیکویڈیٹی خشک ہو رہی ہے۔</strong> بالکل اسی وقت جب آپ کو باہر نکلنے کی ضرورت ہوتی ہے، خریدار غائب ہو جاتے ہیں۔ خلاء کو وسیع کرتا ہے، آرڈر بک پتلی ہوتی ہے، اور آپ کو بچ جانے کے لیے منعقد کرنے اور نماز پڑھنے یا ایک وحشی پھیلاؤ کی ادائیگی کے درمیان انتخاب کرنا چھوڑ دیا جاتا ہے۔ لیکویڈیٹی پُرسکون دنوں میں فراخ دلی سے ہوتی ہے اور اس دن جاتی ہے جب آپ کو درحقیقت اس کی ضرورت ہوتی ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک ایکویٹی وکر دس مہینوں میں چھوٹے مستحکم قدموں میں چڑھتا ہے، پھر ایک دن میں عمودی چٹان سے نیچے گرتا ہے جہاں سے یہ شروع ہوا تھا۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">دس مہینے پریمیم، ایک دم دن</text>\n  <line x1=\"60\" y1=\"60\" x2=\"60\" y2=\"250\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <line x1=\"60\" y1=\"250\" x2=\"720\" y2=\"250\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <text x=\"30\" y=\"120\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\" transform=\"rotate(-90 30 120)\">اکاؤنٹ کی قیمت</text>\n  <polyline points=\"60,210 120,202 180,196 240,186 300,178 360,168 420,158 480,148 540,138 580,128\" fill=\"none\" stroke=\"#55a868\" stroke-width=\"3\"/>\n  <text x=\"250\" y=\"150\" fill=\"#55a868\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">مستحکم ہفتہ وار پریمیم</text>\n  <line x1=\"580\" y1=\"128\" x2=\"592\" y2=\"240\" stroke=\"#c44e52\" stroke-width=\"3\"/>\n  <line x1=\"60\" y1=\"210\" x2=\"720\" y2=\"210\" stroke=\"#8b949e\" stroke-width=\"1\" stroke-dasharray=\"4 4\"/>\n  <text x=\"640\" y=\"206\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">جہاں آپ نے شروع کیا</text>\n  <text x=\"600\" y=\"200\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">ایک دم دن</text>\n  <text x=\"600\" y=\"218\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">یہ سب صاف کرتا ہے</text>\n  <text x=\"120\" y=\"270\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">مہینہ 1</text>\n  <text x=\"520\" y=\"270\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">مہینہ 10</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">چڑھائی سست ہے اور زوال عمودی ہے۔ وہ عدم توازن فروخت کا سارا مسئلہ ہے۔</figcaption>\n</figure><h2 id=\"this-has-really-happened-here\">یہ واقعی یہاں ہوا ہے۔</h2>\n<p>یہ سوچے سمجھے تجربات نہیں ہیں۔ مارچ 2020 میں، COVID حادثے نے ایک لوئر سرکٹ کو نشانہ بنایا جس سے ٹریڈنگ مکمل طور پر رک گئی، اور ان دنوں میں سے ایک دن انڈیکس تقریباً 13% گر گیا - شارٹ پوٹس جو جمعہ کو محفوظ نظر آتے تھے، پیر کے کھلنے سے تباہ کن تھے۔ جون 2024 کے انتخابی نتائج کی صبح، NIFTY صحت یاب ہونے سے پہلے انٹرا ڈے میں تقریباً 6% گر گیا، ایک ایسا اقدام جس نے عام دن کے لیے چھوٹی پوزیشنوں کو کٹا دیا۔ بجٹ کی صبحوں اور مرکزی بینک کے حیران کن فیصلوں نے اس کے چھوٹے ورژن کیے ہیں۔ سبق دہرایا جاتا ہے: بدترین دن راتوں رات آتے ہیں، بغیر کسی انتباہ کے، ایک طویل سکون کے بعد۔</p>\n<p>یہ وہی فرق اور ایونٹ کا خطرہ ہے جو رسک مینجمنٹ کورس ہر شریک کے لیے احاطہ کرتا ہے۔ آپشن بیچنے والے کے لیے یہ سب سے مشکل کاٹتا ہے، کیونکہ آپ کا نقصان وہ حصہ ہے جو محدود نہیں ہے۔</p>\n<h2 id=\"how-sellers-survive-the-tail\">بیچنے والے دم سے کیسے بچتے ہیں۔</h2>\n<p>آپ دم کے دن کی پیش گوئی نہیں کر سکتے۔ آپ صرف اس لیے تعمیر کر سکتے ہیں کہ دم کا دن آپ کو برباد نہ کرے۔ پانچ عادتیں زیادہ تر کام کرتی ہیں۔</p>\n<ul>\n<li><strong>کبھی بھی ننگا نہ بیچیں۔</strong> ایک ننگا مختصر آپشن - اس کے ساتھ کوئی حفاظتی لمبا نہیں - ایک نقصان ہے جو آپ کے پریمیم سے بہت آگے ہے۔ ہمیشہ ایک ہی طرف ایک سستا، مزید آؤٹ آپشن کا مالک ہے تاکہ آپ کے بدترین کیس کی وضاحت اور معلوم ہو <em>پہلے</em> آپ داخل کریں. طے شدہ خطرہ ہر چیز کے نیچے فرش ہے۔</li>\n<li><strong>مارجن بفر رکھیں۔</strong> ایک اتار چڑھاؤ اسپائک مارجن کو بڑھاتا ہے جو آپ کے بروکر کا مطالبہ بدترین ممکنہ لمحے پر ہوتا ہے۔ اگر آپ اپنا تقریباً سارا مارجن استعمال کر رہے ہیں، تو وہ اسپائک بدصورت قیمت پر ایک مربع بند کو مجبور کر سکتا ہے۔ فالتو مارجن کے ساتھ چلائیں - جو کچھ آپ کے پاس ہے اس کا نصف سے دو تہائی استعمال کریں، نہ کہ تمام۔</li>\n<li><strong>ایک کھڑے دم ہیج کو پکڑو.</strong> ہر وقت سستے، پیسے سے باہر طویل اختیارات میں ایک چھوٹی پوزیشن رکھیں۔ وہ ہر مہینے تھوڑا سا خرچ کرتے ہیں اور عام طور پر بیکار ختم ہو جاتے ہیں - یہ نقطہ ہے. بلیک سوان ڈے پر وہ قیمت میں پھٹ جاتے ہیں اور تباہی کی ادائیگی کرتے ہیں۔ اس کو انشورنس کے طور پر سمجھیں آپ ان سالوں میں بھی رکھیں جب گھر نہیں جلتا۔</li>\n<li><strong>دم کے لیے سائز، پرسکون نہیں۔</strong> اس سے پہلے کہ آپ کوئی تجارت کریں، پوچھیں: اگر یہ کل اپنے مقررہ خطرے کے زیادہ سے زیادہ حد تک پہنچ جاتا ہے، تو روپے کا کیا نقصان ہے - اور کیا میرا اکاؤنٹ اسے بغیر توڑے لے سکتا ہے؟ اگر ایماندارانہ جواب نفی میں ہے تو پوزیشن بہت بڑی ہے، فل سٹاپ۔</li>\n<li><strong>سکون کا احترام کریں۔</strong> \"یہ مہینوں میں نہیں ہوا\" حفاظت نہیں ہے۔ یہ وہ سکون ہے جس میں خطرہ خاموشی سے پیدا ہوتا ہے۔ جتنا لمبا خاموش ہو گا، بیچنے والوں کا اتنا ہی زیادہ ہجوم ہیجز پر کم سائز میں ہوتا ہے - اور حتمی تصویر اتنی ہی خراب ہوتی ہے۔</li>\n</ul>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 280\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"مارکیٹ گرنے کے ساتھ ہی دو نقصان کی لکیریں: ایک ننگا شارٹ جس کا نقصان بغیر کسی حد کے گہرا ہوتا رہتا ہے، اور ایک ہیجڈ شارٹ جس کا نقصان ایک معلوم منزل تک چپٹا ہوتا ہے جہاں ٹیل کا ہیج ہوتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"280\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ایک ہی فرق نیچے: ننگا بمقابلہ ہیجڈ</text>\n  <line x1=\"70\" y1=\"70\" x2=\"70\" y2=\"230\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <line x1=\"70\" y1=\"150\" x2=\"720\" y2=\"150\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <text x=\"690\" y=\"168\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">قیمت گرتی ہے</text>\n  <text x=\"80\" y=\"86\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">منافع / نقصان</text>\n  <polyline points=\"70,228 200,200 360,150 720,135\" fill=\"none\" stroke=\"#c44e52\" stroke-width=\"3\"/>\n  <text x=\"150\" y=\"216\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">naked: نقصان گہرا ہوتا رہتا ہے۔</text>\n  <polyline points=\"70,188 230,188 360,150 720,135\" fill=\"none\" stroke=\"#55a868\" stroke-width=\"3\"/>\n  <text x=\"95\" y=\"180\" fill=\"#55a868\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">hedged : یہاں فرش ۔</text>\n  <line x1=\"230\" y1=\"188\" x2=\"230\" y2=\"150\" stroke=\"#8b949e\" stroke-width=\"1\" stroke-dasharray=\"3 3\"/>\n  <text x=\"300\" y=\"125\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">بازو سنبھال لیتا ہے - نقصان بڑھنا بند ہو جاتا ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ایک بہت طویل آپشن کھلے عام نقصان کو ایک معروف، زندہ رہنے والے نقصان میں بدل دیتا ہے۔</figcaption>\n</figure>\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>دو کلاسک بیچنے والے کی غلطیاں دونوں دم کو نظر انداز کرتے ہیں۔ پہلا ہے۔ <strong>کوئی دم ہیج نہیں</strong>: برہنہ فروخت کرنا یا اپنے حفاظتی پروں کو بہت دور جانے دینا کیونکہ ہیجز \"صرف پیسے کا خون بہاتے ہیں\" - 95 فیصد دنوں پر درست ہے جو پرسکون ہیں، اور جو نہیں ہے اس پر تباہ کن ہے۔ دوسرا ہے۔ <strong>سائز تبدیل کرنا گویا سکون ہمیشہ کے لیے رہتا ہے۔</strong>: طویل جیتنے کے بعد پوزیشن کے سائز کو بڑھانا، لہذا آپ کی سب سے بڑی شرط میز پر عین اس وقت ہوتی ہے جب دم سب سے زیادہ واجب الادا ہو۔ ہیج کو آن رکھیں، اور اس خلا کا سائز رکھیں جسے آپ آتے ہوئے نہیں دیکھ سکتے۔</p>\n</div></div>\n<h2 id=\"a-tail-survival-checklist\">ایک دم بقا کی چیک لسٹ</h2>\n<p>ہر سیلنگ سائیکل سے پہلے اسے چلائیں۔ اگر کسی بھی باکس پر نشان نہیں لگایا گیا ہے، تو تجارت بہت خطرناک ہے جیسا کہ یہ کھڑا ہے۔</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> ہر مختصر آپشن کے پاس ایک طے شدہ خطرہ ہوتا ہے (کچھ بھی ننگا نہیں)۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں جانتا ہوں کہ اس پوزیشن کے لیے میرے سب سے زیادہ نقصان کا روپیہ ہے، اور میرا اکاؤنٹ اس سے بچ جاتا ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں اپنے مارجن کا صرف ایک حصہ استعمال کر رہا ہوں، اتار چڑھاؤ میں اضافے کے لیے بفر چھوڑ کر۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> ایک کھڑا دور - OTM ٹیل ہیج اس وقت موجود ہے، \"بعد میں شامل نہیں کیا جائے گا۔\"</li>\n<li><input disabled=\"\" type=\"checkbox\"> پوزیشن کا سائز ایک وقفے والے دن کے لیے سیٹ کیا جاتا ہے، اوسط دن کے لیے نہیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں نے نتائج، بجٹ، پالیسی میٹنگز اور انتخابات کے لیے کیلنڈر چیک کیا ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں آج بڑا نہیں ہوں صرف اس لیے کہ پچھلے کچھ مہینے آسان تھے۔</li>\n</ul>\n<h2 id=\"how-the-tail-hits-each-participant\">کس طرح دم ہر شریک کو مارتی ہے۔</h2>\n<p>دم سب کو چھوتی ہے، لیکن اس کا وزن ان پر برابر نہیں ہوتا۔ بیچنے والے سب سے زیادہ لے جاتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>ایک دم کے دن کی نمائش</th>\n<th>جو ان کی حفاظت کرتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>حقیقی لیکن سست - ایک حادثہ کاغذ پر درد کرتا ہے، وقت اور SIPs اسے ٹھیک کر دیتے ہیں۔</td>\n<td>تنوع، کوئی فائدہ نہیں، ایک طویل افق</td>\n</tr>\n<tr>\n<td>اسٹاک تاجر</td>\n<td>ایک وقفہ ایک سٹاپ کو چھلانگ لگا سکتا ہے، لیکن نقصان اسٹاک میں موجود سرمائے سے ہوتا ہے۔</td>\n<td>پوزیشن کا سائز، راتوں رات کوئی فائدہ نہیں۔</td>\n</tr>\n<tr>\n<td>فیوچر تاجر</td>\n<td>شارپ - لیوریج دونوں طریقوں سے فرق کو بڑھاتا ہے۔</td>\n<td>رک جاتا ہے، چھوٹے سائز، واقعات میں ہیجز</td>\n</tr>\n<tr>\n<td>آپشن خریدار</td>\n<td>محدود نقصان (ادا کردہ پریمیم) - ایک فرق ایک طویل آپشن میں بھی مدد کر سکتا ہے۔</td>\n<td>خطرہ ڈیزائن کے ذریعہ محدود ہے۔</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا</td>\n<td>سب سے زیادہ بے نقاب - محدود فائدہ، بڑا غیر محدود نقصان، ایک ہی وقت میں فرق، حجم اور لیکویڈیٹی سے متاثر</td>\n<td>متعین خطرہ، مارجن بفر، ایک کھڑا دم ہیج</td>\n</tr>\n</tbody></table>\n<p>پیٹرن سادہ ہے: آپشن سیلر ہر کالم کے غلط سرے پر بیٹھتا ہے۔ یہ کبھی فروخت نہ کرنے کی وجہ نہیں ہے - یہی وجہ ہے کہ بیچنے والے کا رسک پلان سب سے سخت ہونا چاہیے۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>اس باب میں دفاع دم کو کم کرتا ہے۔ وہ اسے حذف نہیں کرتے۔ خلا کے بارے میں ایماندار رہو.</p>\n<p><strong>ایک ہیج کی ایک قیمت ہے، اور قیمت حقیقی ہے۔</strong> ٹیل ہیجز سے ہر مہینے تھوڑا سا خون بہتا ہے اور عام طور پر بیکار ختم ہو جاتا ہے۔ ایک پرسکون سال کے دوران جو ڈریگ آپ کی پریمیم آمدنی کا ایک حصہ نگل سکتا ہے۔ یہ بقا کی قیمت ہے، کوئی خامی نہیں ہے - لیکن یہ ایک حقیقی قیمت ہے جو بیک ٹیسٹ کی تجویز کے مقابلے میں فروخت کو کم منافع بخش بناتی ہے۔</p>\n<p><strong>متعین خطرہ اب بھی ایک بڑی تعداد ہوسکتا ہے۔</strong> ایک اسپریڈ آپ کے نقصان کو پورا کرتا ہے، لیکن کیپ آپ کے جمع کردہ پریمیم سے کئی گنا زیادہ ہو سکتی ہے۔ \"تعریف شدہ\" کا مطلب ہے۔ <em>جانا جاتا ہے</em>، نہیں <em>چھوٹا</em>. سائز کو اب بھی متعین زیادہ سے زیادہ کا احترام کرنا ہوگا، یا منزل صرف وہ سطح ہے جس پر آپ امکان کے بجائے یقین کے ساتھ ٹوٹ جاتے ہیں۔</p>\n<p><strong>فرق آپ کے ہیج سے تجاوز کر سکتا ہے۔</strong> واقعی انتہائی سخت دن، حتیٰ کہ ایک دور OTM بھی مکمل طور پر اس اقدام کا احاطہ نہیں کر سکتا، مارجن کو وسط گھبراہٹ کہا جا سکتا ہے، اور لیکویڈیٹی اتنی پتلی ہو سکتی ہے کہ آپ اپنے ہیج کو مناسب قیمت پر تجارت نہیں کر سکتے۔ کوئی ڈھانچہ سیاہ ہنس کو بے درد نہیں بناتا۔ مقصد بقا ہے - اگلے مہینے تجارت کے لیے جینا - بغیر کسی نقصان کے باہر نہیں آنا۔</p>\n<p>یہ کسی خاص طریقے سے بیچنے یا ہیج کرنے کا مشورہ نہیں ہے۔ یہ ایک نقشہ ہے جہاں خطرہ رہتا ہے تاکہ آپ اس کے لیے تعمیر کر سکیں۔</p>\n<p>یہ آپشن سیلر اور ہیجر پلے بک کو بند کر دیتا ہے۔ آپ نے ننگے بمقابلہ ہیجڈ سیلنگ، ڈیفائنڈ رسک ڈھانچے، ایڈجسٹمنٹ کے اندر خطرہ، اور اب وہ دم دیکھا ہے جو اس سب کے نیچے بیٹھی ہے۔ اس کے بعد، حتمی ماڈیول اس کورس کے ہر آئیڈیا کو ہر قسم کے شرکاء کے لیے ایک مکمل، ایک صفحے کے رسک پلان میں بدل دیتا ہے - بشمول بیچنے والے کا اپنا بقا کا منصوبہ، کیونکہ بیچنا کم سے کم معاف کرتا ہے۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> آپشن بیچنے والے کے لیے دم کے خطرے کا کیا مطلب ہے؟</summary><p>نتائج کی تقسیم کے دور میں یہ نایاب، پرتشدد نقصان ہے۔ ایک بیچنے والا چھوٹا اور اکثر جیتتا ہے لیکن، ایک بار، بڑا ہار جاتا ہے - اور وہ واحد نقصان کئی مہینوں کے جمع کیے گئے پریمیم سے زیادہ ہو سکتا ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> ان تین قوتوں کے نام بتائیں جو عام طور پر دم کا دن بناتے ہیں۔</summary><p>راتوں کا وقفہ (مارکیٹ اپنے پہلے کے قریب سے بہت دور کھلتی ہے)، اتار چڑھاؤ کا دھماکہ (ڈر اسپائکس اور پریمیم کا غبارہ، اس لیے مختصر آپشنز ملٹیز کھو دیتے ہیں)، اور لیکویڈیٹی خشک ہو جاتی ہے (خرابی پھیل جاتی ہے اور خریدار اسی وقت غائب ہو جاتے ہیں جب آپ کو باہر نکلنے کی ضرورت ہوتی ہے)۔</p>\n</details><details>\n<summary><strong>3.</strong> وقفے والے دن بیچنے والے کی حفاظت کرنے میں سٹاپ لاس اکثر کیوں ناکام ہو جاتا ہے؟</summary><p>کیونکہ قیمت اس سے گزرنے کے بجائے آپ کے اسٹاپ پر چھلانگ لگاتی ہے۔ نقصان دہ اقدام راتوں رات ہوتا ہے جب آپ تجارت نہیں کر سکتے، اس لیے آپ پہلے ہی نقصان میں گہرے ہوتے ہیں اس سے پہلے کہ کوئی بھی سٹاپ متحرک ہو۔</p>\n</details><details>\n<summary><strong>4.</strong> اسٹینڈ ٹیل ہیج کیا ہے، اور اسے پرسکون مہینوں میں بھی کیوں رکھا جائے؟</summary><p>یہ سستے، پیسے سے باہر کے طویل اختیارات میں ایک چھوٹی پوزیشن ہے جو ہر وقت منعقد ہوتی ہے۔ اس سے تھوڑا خون بہتا ہے اور عام طور پر بیکار ختم ہو جاتا ہے، لیکن بلیک سوان کے دن یہ قیمتی طور پر پھٹ جاتا ہے اور تباہی کی قیمت ادا کرتا ہے۔ آپ اسے بالکل ٹھیک رکھتے ہیں کیونکہ آپ اس دن کا اندازہ نہیں لگا سکتے جس دن آپ کو اس کی ضرورت ہوگی۔</p>\n</details><details>\n<summary><strong>5.</strong> \"یہ مہینوں میں نہیں ہوا\" کیوں محفوظ محسوس کرنے کی ایک خطرناک وجہ ہے؟</summary><p>ایک لمبا پر سکون اس وقت ہوتا ہے جب خطرہ خاموشی سے بناتا ہے اور بیچنے والے ہیجز پر کم سائز میں ہجوم کرتے ہیں۔ خاموشی تحفظ نہیں ہے - یہ سیٹ اپ ہے۔ یہ جتنی دیر تک چلتا ہے، حتمی تصویر اتنی ہی خراب ہوتی ہے۔</p>\n</details>\n","toc":[{"level":2,"text":"بیچنے والے کے خطرے کی شکل","id":"the-shape-of-a-seller-s-risk"},{"level":2,"text":"تین چیزیں جو دم بناتی ہیں۔","id":"three-things-that-build-the-tail"},{"level":2,"text":"یہ واقعی یہاں ہوا ہے۔","id":"this-has-really-happened-here"},{"level":2,"text":"بیچنے والے دم سے کیسے بچتے ہیں۔","id":"how-sellers-survive-the-tail"},{"level":2,"text":"ایک دم بقا کی چیک لسٹ","id":"a-tail-survival-checklist"},{"level":2,"text":"کس طرح دم ہر شریک کو مارتی ہے۔","id":"how-the-tail-hits-each-participant"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"18":{"html":"<p>مارچ 2020 میں ارجن نے اپنے میوچل فنڈز کو تقریباً پانچ ہفتوں میں تقریباً 40 فیصد گرتے دیکھا۔ ہر صبح سرخ کا ایک نیا سایہ تھا۔ اس نے پڑھا تھا کہ آپ کو \"سرمایہ کاری میں رہنا چاہیے\"، لیکن پیر کو نیچے کے قریب وہ اسے مزید نہیں لے سکتا تھا - اس نے سب کچھ بیچ دیا اور رقم ایک فکسڈ ڈپازٹ میں کھڑی کر دی، خود سے کہا کہ وہ واپس خرید لے گا \"ایک بار جب یہ واضح ہو جائے گا۔\" یہ کبھی واضح محسوس نہیں ہوا۔ اگلے سال کے دوران مارکیٹ تقریباً 70 فیصد تک چڑھ گئی، اور اس نے اسے کنارے سے دیکھا۔ اس کی ساتھی میرا نے کچھ نہیں کیا۔ اس نے اپنے SIP کو پورے موسم خزاں میں خریدتے رہنے دیا، ہفتوں تک لاگ ان نہیں کیا، اور ایک سال بعد آرام سے آگے تھا۔ ایک ہی حادثہ۔ دو مکمل طور پر مختلف نتائج - مکمل طور پر رویے سے فیصلہ کیا گیا ہے۔</p>\n<p>یہ باب حتمی ماڈیول کو کھولتا ہے: ہر قسم کے شریک کے لیے ایک مکمل، ایک صفحے کا رسک پلان۔ ہم طویل مدتی سرمایہ کار کے ساتھ شروع کرتے ہیں، کیونکہ سرمایہ کار کا منصوبہ لکھنے میں سب سے آسان اور اس پر عمل کرنا سب سے مشکل ہے۔ ایک سرمایہ کار کا تقریباً تمام خطرہ مارکیٹ میں نہیں ہوتا ہے۔ یہ آئینے میں ہے۔</p>\n<h2 id=\"why-an-investor-s-risk-is-different\">کیوں سرمایہ کار کا خطرہ مختلف ہوتا ہے۔</h2>\n<p>ایک تاجر کا خطرہ ہر پوزیشن میں رہتا ہے - اسٹاپ، سائز، لیوریج۔ ایک سرمایہ کار کا خطرہ وقت اور مزاج میں رہتا ہے۔ اگر آپ کے پاس دس یا بیس سالوں سے اچھے کاروبار ہیں، تو آپ کے پیسے کے لیے واحد سب سے بڑا خطرہ حادثہ نہیں ہے۔ کریشز ٹھیک ہو جاتے ہیں۔ خطرہ ہے۔ <em>آپ</em> حادثے کے دوران بیچنا اور کبھی واپس نہیں آنا۔ ارجن بازار سے نہیں ہارا۔ وہ اپنے ہی خوف سے ہار گیا۔</p>\n<p>لہذا ایک سرمایہ کار کا منصوبہ زیادہ تر قوانین کا ایک مجموعہ ہوتا ہے جو آپ کو طوفانی موسم میں اپنے آپ سے بچانے کے لیے پرسکون موسم میں لکھا جاتا ہے۔ ایک بار ضرور لکھیں۔ جو آپ کر سکتے ہیں خودکار بنائیں۔ پھر زیادہ تر اسے تنہا چھوڑ دیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 250\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"تین سرمائے کی بالٹیاں: ایک ہنگامی فنڈ جو مارکیٹ سے باہر نقد میں رکھا جاتا ہے، ایک طویل مدتی پورٹ فولیو ایکویٹی، قرض اور سونے میں تقسیم ہوتا ہے، اور یہ اصول جس کی آپ کو پانچ سال کے اندر ضرورت ہوتی ہے وہ ایکویٹی سے باہر رہتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"250\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">جہاں سرمایہ کار کا پیسہ بیٹھتا ہے۔</text>\n  <rect x=\"40\" y=\"60\" width=\"180\" height=\"150\" rx=\"10\" fill=\"#11161d\" stroke=\"#37b3a4\" stroke-width=\"2\"/>\n  <text x=\"130\" y=\"88\" text-anchor=\"middle\" fill=\"#37b3a4\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">ایمرجنسی فنڈ</text>\n  <text x=\"130\" y=\"110\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">OUTSIDE مارکیٹ</text>\n  <text x=\"130\" y=\"132\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">نقد / FD / مائع</text>\n  <text x=\"130\" y=\"158\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">6-12 ماہ</text>\n  <text x=\"130\" y=\"176\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">اخراجات کی</text>\n  <rect x=\"260\" y=\"60\" width=\"320\" height=\"150\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\" stroke-width=\"2\"/>\n  <text x=\"420\" y=\"88\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">طویل مدتی پورٹ فولیو</text>\n  <rect x=\"280\" y=\"105\" width=\"170\" height=\"34\" rx=\"6\" fill=\"#4c72b0\"/>\n  <text x=\"365\" y=\"127\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">ایکویٹی 60%</text>\n  <rect x=\"280\" y=\"147\" width=\"85\" height=\"34\" rx=\"6\" fill=\"#55a868\"/>\n  <text x=\"322\" y=\"169\" text-anchor=\"middle\" fill=\"#0d1117\" font-size=\"11\" font-weight=\"700\" font-family=\"sans-serif\">قرض 30%</text>\n  <rect x=\"370\" y=\"147\" width=\"80\" height=\"34\" rx=\"6\" fill=\"#dd8452\"/>\n  <text x=\"410\" y=\"169\" text-anchor=\"middle\" fill=\"#0d1117\" font-size=\"11\" font-weight=\"700\" font-family=\"sans-serif\">سونا 10%</text>\n  <text x=\"465\" y=\"124\" fill=\"#8b949e\" font-size=\"10\" font-family=\"sans-serif\">بڑھتا ہے</text>\n  <text x=\"465\" y=\"138\" fill=\"#8b949e\" font-size=\"10\" font-family=\"sans-serif\">10-20 سال</text>\n  <rect x=\"600\" y=\"60\" width=\"120\" height=\"150\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\" stroke-width=\"2\"/>\n  <text x=\"660\" y=\"92\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">اس کی ضرورت ہے۔</text>\n  <text x=\"660\" y=\"110\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">&lt;5 سال میں؟</text>\n  <text x=\"660\" y=\"140\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">اسے OUT رکھیں</text>\n  <text x=\"660\" y=\"158\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">مساوات کی</text>\n  <text x=\"660\" y=\"184\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\" font-family=\"sans-serif\">اسکول کی فیس،</text>\n  <text x=\"660\" y=\"198\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\" font-family=\"sans-serif\">نیچے ادائیگی</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ایمرجنسی فنڈ اور کوئی بھی قریب المدت گول رقم ایکوئٹی سے باہر بیٹھتی ہے۔ صرف طویل افق کی رقم سامنے آتی ہے۔</figcaption>\n</figure><h2 id=\"the-one-page-plan\">ایک صفحے کا منصوبہ</h2>\n<p>یہ باب کا دل ہے۔ باقی سب کچھ صرف اس کی وضاحت کرتا ہے۔ نیچے دیئے گئے نمبر ایک ہیں۔ <em>مثال کا مرکب</em> ایک لمبے افق کے ساتھ ایک ابتدائی کے لیے، ذاتی مشورے نہیں - آپ کی اپنی تقسیم آپ کی عمر، آمدنی اور نیند کو کھونے کے بغیر آپ کتنا لال پیٹ کر سکتے ہیں پر منحصر ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 330\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک صفحے کا سرمایہ کار رسک پلان کارڈ جس میں پانچ اصول درج ہیں: ایک مختص کریں، SIPs کو خودکار بنائیں، سال میں ایک بار یا بڑھنے پر دوبارہ توازن رکھیں، ایمرجنسی فنڈ کو مارکیٹ سے باہر رکھیں، اور کچھ نہ کریں یا حادثے میں خریدتے رہیں۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"330\" rx=\"12\" fill=\"#0d1117\"/>\n  <rect x=\"20\" y=\"20\" width=\"720\" height=\"290\" rx=\"12\" fill=\"#11161d\" stroke=\"#4c72b0\" stroke-width=\"2\"/>\n  <text x=\"380\" y=\"52\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"17\" font-family=\"sans-serif\">طویل مدتی سرمایہ کار کا ایک صفحہ کا منصوبہ</text>\n  <line x1=\"50\" y1=\"66\" x2=\"710\" y2=\"66\" stroke=\"#30363d\" stroke-width=\"1\"/>\n  <text x=\"55\" y=\"100\" fill=\"#4c72b0\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">1</text>\n  <text x=\"80\" y=\"100\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">مختص کریں۔</text>\n  <text x=\"80\" y=\"118\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">ایک مقررہ مرکب، جیسے 60% ایکویٹی/30% قرض/10% سونا۔ اسے لکھ دیں۔</text>\n  <text x=\"55\" y=\"148\" fill=\"#55a868\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">2</text>\n  <text x=\"80\" y=\"148\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">SIP کو خودکار بنائیں</text>\n  <text x=\"80\" y=\"166\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">ایک ہی رقم، ایک ہی تاریخ، ہر ماہ۔ موسم خزاں میں اسے کبھی نہ روکیں۔</text>\n  <text x=\"55\" y=\"196\" fill=\"#dd8452\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">3</text>\n  <text x=\"80\" y=\"196\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">توازن</text>\n  <text x=\"80\" y=\"214\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">سال میں ایک بار، یا جب کوئی بھی ٹکڑا ہدف سے 5-10% تک بڑھ جاتا ہے۔</text>\n  <text x=\"55\" y=\"244\" fill=\"#37b3a4\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">4</text>\n  <text x=\"80\" y=\"244\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">ایمرجنسی فنڈ</text>\n  <text x=\"80\" y=\"262\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">نقد میں 6-12 ماہ کے اخراجات، OUTSIDE کو مارکیٹ میں رکھا۔</text>\n  <text x=\"55\" y=\"292\" fill=\"#c44e52\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">5</text>\n  <text x=\"80\" y=\"292\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">حادثے میں</text>\n  <text x=\"200\" y=\"292\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">کچھ نہ کریں یا خریدتے رہیں۔ کبھی گھبرائیں نہیں - نیچے بیچیں۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">طوفانی موسم میں آپ کی حفاظت کے لیے پرسکون موسم میں لکھے گئے پانچ اصول۔</figcaption>\n</figure><p>یہاں ایک کاپی کرنے کے قابل چیک لسٹ کے طور پر ایک ہی منصوبہ ہے. اسے پرنٹ کریں۔ اسے وہاں رکھو جہاں آپ اسے برے دن دیکھیں گے۔</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>مختص کیا گیا اور لکھا گیا۔</strong> ایک ٹارگٹ مکس جسے آپ کسی بھی چیز سے روک سکتے ہیں - مثال کے طور پر ابتدائی تقسیم 60% ایکویٹی، 30% قرض، 10% سونا ہے۔ اگر آپ آگے کئی دہائیوں کے ساتھ جوان ہیں تو اعلی مساوات؛ ایک مقصد کے طور پر زیادہ قرض قریب ہو جاتا ہے.</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>SIP خودکار۔</strong> ہر مہینے کی ایک مقررہ تاریخ پر ایک مقررہ روپیہ، جو آپ خرچ کرنے سے پہلے لیا جاتا ہے یا دوسرا اندازہ لگا سکتے ہیں۔ 10,000 روپے ماہانہ، ایک بار مقرر کریں، چلانے کے لیے چھوڑ دیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>ری بیلنس کا اصول منتخب کیا گیا۔</strong> سال میں ایک بار ایک مقررہ تاریخ پر، یا جب بھی کوئی ٹکڑا اپنے ہدف سے 5-10% سے زیادہ بڑھ جاتا ہے۔ جو کچھ بڑھا اس میں سے تھوڑا بیچیں، جو پیچھے رہ گیا ہے اس میں سے تھوڑا خریدیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>ایمرجنسی فنڈ مارکیٹ کے باہر کھڑا ہے۔</strong> نقد رقم، فکسڈ ڈپازٹ یا مائع فنڈ میں چھ سے بارہ ماہ کے اخراجات - لہذا حادثہ آپ کو بل ادا کرنے کے لیے اسٹاک بیچنے پر مجبور نہیں کرتا ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>پانچ سال کے اندر درکار رقم ایکوئٹی میں نہیں ہے۔</strong> اسکول کی فیس، کم ادائیگی، شادی - محفوظ اثاثوں میں قریبی مدت کے اہداف رکھیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>کریش اصول پہلے سے طے شدہ:</strong> کچھ نہ کریں، یا خریدتے رہیں۔ فروخت مینو میں نہیں ہے۔</li>\n</ul>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>پورا منصوبہ ایک جملے تک کم ہو جاتا ہے: خریداری کو خودکار بنائیں، مارکیٹ سے باہر ایمرجنسی فنڈ رکھیں، اور پہلے سے فیصلہ کریں کہ آپ حادثے میں فروخت نہیں کریں گے۔ زیادہ تر سرمایہ کاری میں ناکامی کوئی برا فنڈ نہیں ہے - یہ ایک اچھا منصوبہ ہے جو بدترین لمحے میں ترک کر دیا جاتا ہے۔</p>\n</div></div>\n<h2 id=\"how-to-behave-in-a-crash\">حادثے میں کیسے برتاؤ کرنا ہے۔</h2>\n<p>کریش وہ واحد امتحان ہے جو یہ منصوبہ کبھی طے کرتا ہے، اور یہ پاس یا فیل ہوتا ہے۔ ری بیلنسنگ اور ایلوکیشن اہم ہے، لیکن وہ نرم ہیں۔ حادثہ وہ ہوتا ہے جہاں قسمت خاموشی سے بنائی جاتی ہے یا پھینک دی جاتی ہے - اور صحیح اقدام تقریبا ہمیشہ ہی بورنگ ہوتا ہے۔</p>\n<p>جب مارکیٹ 30% یا 40% نیچے ہے، تو آپ کا SIP اب وہی یونٹ بہت سستا خرید رہا ہے۔ یہ نظام کام کرتا ہے، ٹوٹنے والا نہیں۔ سرمایہ کار جو زوال کے دوران خریدتا رہتا ہے وہ ڈسکاؤنٹ پر لوڈ ہو رہا ہے۔ وہ جو SIP کو روکتا ہے یا بیچتا ہے وہ نقصان میں رہتا ہے اور ریباؤنڈ سے محروم رہتا ہے، جو اکثر تیزی سے اور بغیر وارننگ کے آتا ہے۔ مارچ 2020 میں COVID کم ہونے کے بعد، زیادہ تر بحالی پہلے چند مہینوں میں ہوئی ہے - اگر آپ \"یہ واضح ہونے تک\" انتظار کرتے ہیں، تو آپ اسے پہلے ہی کھو چکے تھے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 290\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"وی کے سائز کا کریش اور ریکوری وکر۔ ایک سرمایہ کار گھبراہٹ میں سب سے نیچے فروخت کرتا ہے اور نقد میں رہتا ہے، صحت مندی لوٹنے سے محروم رہتا ہے۔ دوسرا SIP کو چلتا رہتا ہے اور مکمل طور پر اور اس سے آگے ٹھیک ہوجاتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"290\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ایک ہی حادثہ، دو رویے</text>\n  <line x1=\"60\" y1=\"60\" x2=\"60\" y2=\"240\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <line x1=\"60\" y1=\"240\" x2=\"720\" y2=\"240\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <polyline points=\"60,110 180,150 300,215 360,225\" fill=\"none\" stroke=\"#8b949e\" stroke-width=\"3\"/>\n  <polyline points=\"360,225 480,170 600,110 700,80\" fill=\"none\" stroke=\"#55a868\" stroke-width=\"3\"/>\n  <text x=\"430\" y=\"150\" fill=\"#55a868\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">SIP کو رکھا: بازیافت اور اس سے آگے</text>\n  <polyline points=\"360,225 480,225 600,224 700,224\" fill=\"none\" stroke=\"#c44e52\" stroke-width=\"3\" stroke-dasharray=\"6 5\"/>\n  <text x=\"470\" y=\"262\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">گھبراہٹ میں فروخت: نقد میں پھنس گیا، صحت مندی لوٹنے کی کمی محسوس کرتا ہے۔</text>\n  <circle cx=\"360\" cy=\"225\" r=\"6\" fill=\"#c44e52\"/>\n  <text x=\"300\" y=\"205\" fill=\"#c44e52\" font-size=\"11\" font-family=\"sans-serif\">یہاں فروخت کرتا ہے</text>\n  <text x=\"95\" y=\"100\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">پورٹ فولیو کی قیمت</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">زوال مشترک ہے۔ نتیجہ مکمل طور پر اس بات سے طے ہوتا ہے کہ آپ نیچے کیا کرتے ہیں۔</figcaption>\n</figure><p>کرنے اور نہ کرنے کے تین آسان اصول آپ کو لے کر جاتے ہیں:</p>\n<ul>\n<li><strong>کرو</strong> روزانہ ایپ چیکنگ کو بند کریں۔ آپ کسی ایسے نمبر کے بارے میں گھبراہٹ نہیں کر سکتے جس کی طرف آپ نہیں گھور رہے ہیں۔</li>\n<li><strong>کرو</strong> SIP کو چلتے رہیں - یا، اگر آپ کے پاس اپنے ایمرجنسی فنڈ سے زیادہ فالتو نقد رقم ہے، تو تھوڑا سا اضافہ کریں۔</li>\n<li><strong>مت کرو</strong> پر فروخت کریں \"انتظار کریں جب تک یہ واضح نہ ہو جائے۔\" یہ نچلے حصے میں کبھی واضح نہیں ہوتا ہے۔ یہ وہی ہے جو نیچے کی طرح محسوس ہوتا ہے۔</li>\n</ul>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>سرمایہ کار کی دو کلاسک غلطیاں وہی خوف ہیں جن کے دو چہرے ہیں: <strong>SIP کو روکنا</strong> کیونکہ \"کیوں خریدتے رہیں جب یہ گر رہا ہو،\" اور <strong>نیچے کے قریب گھبراہٹ فروخت</strong> درد کو روکنے کے لئے. دونوں ذمہ دار محسوس کرتے ہیں اور دونوں غلط ہیں۔ SIP کو روکنے سے آپ کی رعایت بالکل اس وقت منسوخ ہوجاتی ہے جب یہ سب سے بڑا ہوتا ہے۔ فروخت کرنا کاغذ کے عارضی نقصان کو مستقل حقیقی میں بدل دیتا ہے اور پھر آپ کو دوبارہ داخلے کا وقت دینے کی ہمت کرتا ہے، جو تقریباً کوئی بھی اچھا نہیں کرتا۔ بہتر اقدام یہ ہے کہ کچھ نہ کریں، یا شیڈول کے مطابق خریداری جاری رکھیں۔</p>\n</div></div>\n<h2 id=\"how-this-differs-from-a-trader-s-plan\">یہ تاجر کے منصوبے سے کیسے مختلف ہے۔</h2>\n<p>ایک سرمایہ کار اور ایک تاجر مختلف کھیل کھیل رہے ہیں، اس لیے ان کے خطرے کے منصوبے تقریباً مخالف نظر آتے ہیں۔ ایک تاجر ہر پوزیشن کا انتظام کرتا ہے۔ ایک سرمایہ کار زندگی بھر کا انتظام کرتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>طویل مدتی سرمایہ کار</th>\n<th>فعال تاجر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>اہم خطرہ</td>\n<td>حادثے میں اپنا رویہ</td>\n<td>ہر پوزیشن کا نقصان</td>\n</tr>\n<tr>\n<td>بنیادی ٹول</td>\n<td>مختص + آٹومیشن</td>\n<td>سٹاپ لوس + پوزیشن سائزنگ</td>\n</tr>\n<tr>\n<td>وقت کا افق</td>\n<td>10-20 سال</td>\n<td>منٹ سے ہفتوں تک</td>\n</tr>\n<tr>\n<td>حادثے پر ردعمل</td>\n<td>کچھ نہ کریں / خریدتے رہیں</td>\n<td>پوزیشن کو تیزی سے کاٹ دیں۔</td>\n</tr>\n<tr>\n<td>فائدہ اٹھانا</td>\n<td>کوئی نہیں۔</td>\n<td>اکثر، اور احتیاط سے کیپ</td>\n</tr>\n<tr>\n<td>کتنی بار عمل کرنا ہے۔</td>\n<td>سال میں چند بار</td>\n<td>روزانہ، فی تجارت</td>\n</tr>\n</tbody></table>\n<p>دیکھیں کہ کریش قطار مکمل طور پر پلٹ جاتی ہے۔ ایک تاجر کے لیے، ہارنے والے کو کاٹنے سے انکار کرنا یہ ہے کہ اکاؤنٹس کیسے مر جاتے ہیں۔ ایک سرمایہ کار کے لیے، ایک حادثے میں کاٹنا ہے کہ دولت کیسے مر جاتی ہے۔ ایک ہی لفظ، مخالف اصول - یہی وجہ ہے کہ آپ کو عمل کرنے سے پہلے یہ جان لینا چاہیے کہ آپ کون سا کھیل کھیل رہے ہیں۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>یہ منصوبہ مضبوط ہے، لیکن یہ جادو نہیں ہے۔ اس کی حدود کے بارے میں ایماندار رہو.</p>\n<p><strong>یہ فرض کرتا ہے کہ آپ کو جلد ہی رقم کی ضرورت نہیں ہے۔</strong> \"حادثے میں کچھ نہ کریں\" صرف اس صورت میں کام کرتا ہے جب رقم حقیقی طور پر طویل مدتی ہو۔ اگر اسی حادثے کے دوران ملازمت کا نقصان ہوتا ہے اور آپ کا ایمرجنسی فنڈ بہت پتلا ہے، تو آپ کو بدترین وقت پر فروخت کرنے پر مجبور کیا جا سکتا ہے - یہی وجہ ہے کہ فنڈ مارکیٹ سے باہر بیٹھتا ہے اور پہلے آتا ہے۔</p>\n<p><strong>تنوع ایک حادثے کو نرم کرتا ہے۔ یہ اسے منسوخ نہیں کرتا.</strong> 2008 یا مارچ 2020 جیسی گہری گھبراہٹ میں، ایکویٹی، بہت سے بانڈز اور یہاں تک کہ سونا بھی تھوڑی دیر کے لیے ایک ساتھ گر سکتا ہے۔ یہ مرکب دھچکے کو کم کرتا ہے اور بحالی کو تیز کرتا ہے - یہ ہر سال گرین اسکرین کا وعدہ نہیں کرتا ہے۔</p>\n<p><strong>\"سرمایہ کاری کریں\" ایک وسیع، سمجھدار پورٹ فولیو کو فرض کرتا ہے۔</strong> یہ اصول متنوع انڈیکس یا کوالٹی فنڈ ہولڈنگز پر لاگو ہوتا ہے جو معیشت کے ساتھ بحال ہوتے ہیں۔ یہ ایک واحد شرط یا فضول اسٹاک کو صفر پر رکھنے کی کوئی وجہ نہیں ہے۔ ایک مارکیٹ کی بحالی؛ ایک بری کمپنی کی ضرورت نہیں ہے۔</p>\n<p>یہ تعلیم ہے، سرمایہ کاری کا مشورہ نہیں۔ یہاں کی فیصدی مثالی مثالیں ہیں - آپ کی اپنی مختص رقم، SIP کی رقم اور ہنگامی فنڈ کا سائز آپ کی صورت حال پر منحصر ہے، اور آپ حقیقی رقم کا ارتکاب کرنے سے پہلے احتیاط سے یا رجسٹرڈ مشیر کے ساتھ سوچنے کے قابل ہیں۔</p>\n<p>اگلے ابواب اسٹاک ٹریڈر، انٹرا ڈے ٹریڈر اور آپشن سیلر کے لیے ایک ہی کام کرتے ہیں - ایک ہی خیال، ہر ایک صفحہ، بہت مختلف اصول۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> طویل مدتی سرمایہ کار کے پیسے کا واحد سب سے بڑا خطرہ کیا ہے؟</summary><p>حادثے میں ان کا اپنا برتاؤ - بنیادی طور پر نیچے کے قریب گھبراہٹ بیچنا یا SIP کو روکنا۔ کریشوں کی بحالی؛ ایک سرمایہ کار جو فروخت کرتا ہے اور اکثر باہر رہتا ہے۔ خطرہ آئینے میں ہے، بازار میں نہیں۔</p>\n</details><details>\n<summary><strong>2.</strong> ایمرجنسی فنڈ مارکیٹ سے باہر کیوں رکھا جاتا ہے؟</summary><p>تاکہ کوئی حادثہ، نوکری کا نقصان یا اچانک بل آپ کو اپنی سرمایہ کاری کو بری قیمت پر بیچنے پر مجبور نہیں کرتا ہے۔ چھ سے بارہ ماہ کے اخراجات نقد یا فکسڈ ڈپازٹ کے ساتھ، آپ پورٹ فولیو کو بالکل اسی وقت چھوڑ سکتے ہیں جب اسے تنہا چھوڑنا سب سے اہم ہے۔</p>\n</details><details>\n<summary><strong>3.</strong> دوبارہ توازن کا اصل مطلب کیا ہے، اور کتنی بار؟</summary><p>اس کا مطلب ہے کہ جو بھی ٹکڑا اپنے ہدف سے بڑھ گیا ہے اسے تراشنا اور جو کچھ بھی پیچھے رہ گیا ہے اسے اوپر کرنا، اپنے منتخب کردہ مکس پر واپس جانے کے لیے - مثال کے طور پر 60A121X0 پر اسے سال میں ایک بار ایک مقررہ تاریخ پر کریں، یا جب بھی کوئی ٹکڑا ہدف سے تقریباً 5-10% سے زیادہ بڑھ جائے۔</p>\n</details><details>\n<summary><strong>4.</strong> کیا آپ کو اپنے SIP کو روکنا چاہیے جب مارکیٹ سخت گر رہی ہے؟</summary><p>نہیں، گرتی ہوئی مارکیٹ کا مطلب ہے کہ اسی SIP کی رقم زیادہ یونٹس سستی خرید رہی ہے، لہذا روکنے سے آپ کی سب سے بڑی رعایت منسوخ ہوجاتی ہے۔ اسے شیڈول کے مطابق جاری رکھیں؛ اگر کچھ بھی ہے، اور صرف اپنے ایمرجنسی فنڈ سے زیادہ اضافی نقدی کے ساتھ، آپ تھوڑا سا اضافہ کر سکتے ہیں۔</p>\n</details><details>\n<summary><strong>5.</strong> ایک سرمایہ کار اور تاجر کے درمیان \"کریش رول\" کیوں پلٹ جاتا ہے؟</summary><p>کیونکہ وہ مختلف کھیل کھیلتے ہیں۔ ایک تاجر کو سرمائے کی حفاظت کے لیے ہارنے والی پوزیشن کو تیزی سے کم کرنا چاہیے۔ متنوع، طویل افق کے پورٹ فولیو کے حامل سرمایہ کار کو کچھ نہیں کرنا چاہیے اور نہ ہی خریدتے رہنا چاہیے، کیونکہ حادثے میں فروخت ہونے والے کاغذ کے عارضی نقصان کو مستقل میں بدل دیتے ہیں۔</p>\n</details>\n","toc":[{"level":2,"text":"کیوں سرمایہ کار کا خطرہ مختلف ہوتا ہے۔","id":"why-an-investor-s-risk-is-different"},{"level":2,"text":"ایک صفحے کا منصوبہ","id":"the-one-page-plan"},{"level":2,"text":"حادثے میں کیسے برتاؤ کرنا ہے۔","id":"how-to-behave-in-a-crash"},{"level":2,"text":"یہ تاجر کے منصوبے سے کیسے مختلف ہے۔","id":"how-this-differs-from-a-trader-s-plan"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"19":{"html":"<p>ارجن نے اپنی ملازمت کے پہلو میں اسٹاک کی تجارت کی۔ وہ ایک مہذب چارٹ ریڈر تھا - اس نے اچھے بریک آؤٹ پکڑے، انہیں کچھ دن روکے رکھا، اچھے منافع بک گئے۔ لیکن اس نے ہر تجارت کو احساس کے مطابق بنایا۔ ایک سیٹ اپ جس کو وہ \"پسند\" کرتا تھا اسے بڑا عہدہ مل گیا۔ جس کے بارے میں اسے یقین نہیں تھا کہ اسے ایک چھوٹا سا مل گیا ہے۔ کوئی مقررہ اسٹاپ، کوئی روزانہ کی حد نہیں۔ مہینوں تک یہ ٹھیک لگ رہا تھا۔ پھر ایک سٹاک جسے وہ پسند کرتا تھا خراب نتائج پر گرا، اس کا کوئی رکنا نہیں تھا، اور واحد نقصان اس کی آخری گیارہ جیتوں کی مشترکہ جیت سے بڑا تھا۔ اس کا کنارہ حقیقی تھا۔ اس کا منصوبہ غائب تھا۔</p>\n<p>یہ باب وہ منصوبہ بناتا ہے جو ارجن کے پاس کبھی نہیں تھا: جھولے یا پوزیشنل اسٹاک ٹریڈر کے لیے ایک مکمل، ایک صفحے کا رسک پلان۔ حکمت عملی نہیں - ایک ایسی حکمت عملی کے گرد ریل جو ایک بری تجارت کو اچھے مہینے کھانے سے روکتی ہے۔</p>\n<h2 id=\"the-six-rails\">چھ ریل</h2>\n<p>اسٹاک ٹریڈر کا رسک پلان چھ آسان اصول ہے۔ کوئی بھی ہوشیار نہیں ہے۔ وہ مل کر فیصلہ کرتے ہیں کہ آیا آپ کا اکاؤنٹ آپ کے کنارے کے ظاہر ہونے کے لیے کافی دیر تک زندہ رہتا ہے۔</p>\n<ol>\n<li><strong>سیٹ اپ اصول</strong> - صرف اپنے ایک متعین سیٹ اپ کی تجارت کریں۔</li>\n<li><strong>سٹاپ نقصان</strong> - ہمیشہ پہلے سے رکھا ہوا، اس سے پہلے کہ آپ تجارت میں ہوں۔</li>\n<li><strong>پوزیشن کا سائز</strong> - نقصان کو فی تجارت کے تقریباً 1% پر طے کریں۔</li>\n<li><strong>روزانہ نقصان کی حد</strong> - ایک مقررہ نقصان یا ہارنے والوں کی تعداد کے بعد تجارت بند کر دیں۔</li>\n<li><strong>فرق کا اصول</strong> - رات بھر کی چھلانگ کا سائز آپ نہیں روک سکتے۔</li>\n<li><strong>جرنل اور ہفتہ وار جائزہ</strong> - ہر تجارت کو لکھیں، اتوار کو ان کا مطالعہ کریں۔</li>\n</ol>\n<p>پورے باب میں ہم تاجر کی ایک مثال استعمال کریں گے: <strong>تجارتی سرمایہ کے 2,00,000 روپے</strong>. گول، سادہ، آپ کے اپنے نمبر تک پیمانہ کرنے میں آسان۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آپ کا کنارہ فیصلہ کرتا ہے کہ آیا آپ سو سے زیادہ تجارت جیتتے ہیں۔ آپ کا رسک پلان یہ فیصلہ کرتا ہے کہ آیا آپ ابھی بھی ٹریڈ سو کے حساب سے تجارت کر رہے ہیں۔ زیادہ تر ابتدائیوں کے پاس پہلا ہوتا ہے اور دوسرا چھوڑ دیتا ہے - اور گمشدہ ریل، کوئی بری حکمت عملی نہیں ہے، جو ان کا خاتمہ کرتی ہے۔</p>\n</div></div>\n<h2 id=\"rule-1-and-2-one-setup-stop-placed-first\">قاعدہ 1 اور 2: ایک سیٹ اپ، پہلے سٹاپ رکھیں</h2>\n<p><strong>صرف اپنے سیٹ اپ کی تجارت کریں۔</strong> ایک ایسا نمونہ منتخب کریں جسے آپ جملے میں بیان کر سکتے ہیں - ایک بنیاد کے اوپر بریک آؤٹ، موونگ ایوریج پر پل بیک، جو بھی آپ نے حقیقت میں پڑھا ہے۔ اگر آپ کے سامنے والا چارٹ ایسا نہیں ہے تو آپ کچھ نہیں کرتے۔ بوریت ایک سیٹ اپ نہیں ہے۔ ٹپ سیٹ اپ نہیں ہے۔ یہ واحد قاعدہ زیادہ تر تجارتوں کو ہٹا دیتا ہے جو خاموشی سے پیسے کھو دیتے ہیں۔</p>\n<p><strong>اسٹاپ پہلے آتا ہے۔</strong> خریدنے سے پہلے، آپ کو اس قیمت کا پتہ ہونا چاہیے جس پر آپ غلط ہیں - اور جس وقت آپ داخل ہوں گے اس وقت اسے سٹاپ لوس آرڈر دیں، نہ کہ \"اسے دستی طور پر دیکھیں\"۔ ایک سٹاپ جسے آپ اپنے سر میں عزت دینے کا ارادہ رکھتے ہیں وہ رکنا نہیں ہے۔ یہ ایک امید ہے. اسے پہلے سے رکھنا مستقبل کے جذباتی فیصلے کو ایک مکمل فیصلے میں بدل دیتا ہے۔</p>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>تینوں اکاؤنٹ کلرز، ترتیب میں۔ <strong>کوئی روک نہیں:</strong> ایک تجارت جس کے بارے میں آپ کو \"معلوم تھا\" واپس آجائے گا وہ گرتا رہتا ہے اور 1% منصوبہ نقصان کو 10% تباہی میں لے جاتا ہے۔ <strong>روزانہ کی کوئی حد نہیں:</strong> ایک بری صبح بدلے کی تجارت کے بعد بدلے کی تجارت بن جاتی ہے جب تک کہ دن ایک گڑھا نہ ہو۔ <strong>گٹ کے ذریعہ سائز:</strong> یقین پر بڑا، شک پر چھوٹا - لہذا آپ کا سب سے بڑا نقصان اس تجارت پر ہوگا جس کے بارے میں آپ کو یقین تھا۔ تینوں کو درست کریں اور آپ سب سے زیادہ خوردہ تاجروں سے آگے ہیں، چاہے آپ کی حکمت عملی کچھ بھی ہو۔</p>\n</div></div>\n<h2 id=\"rule-3-size-so-one-loss-costs-1\">قاعدہ 3: سائز تو ایک نقصان ~1%</h2>\n<p>یہ پورے منصوبے کا انجن ہے، سیدھے رسک مینجمنٹ کورس سے۔ آپ اس بات سے کوئی مقدار نہیں چنتے کہ آپ کو تجارت کتنی پسند ہے۔ آپ اسے اس طرح چنیں۔ <em>اگر سٹاپ ہٹ جاتا ہے، تو آپ تقریباً 1% سرمایہ کھو دیتے ہیں۔</em> - مزید نہیں اس سے سب کچھ پیچھے کی طرف بہتا ہے۔</p>\n<p>ہمارے 2,00,000 روپے کے تاجر کے لیے، 1% ہے۔ <strong>2,000 روپے</strong>. یہ سب سے زیادہ قیمت ہے جو ایک ہی تجارت پر ہو سکتی ہے۔ اب ریاضی:</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 230\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"پوزیشن کے سائز کا بہاؤ: دو لاکھ کا سرمایہ دو ہزار روپے کے ایک فیصد خطرے کا باعث بنتا ہے، جسے بیس روپے فی حصص کے اسٹاپ فاصلے سے تقسیم کیا جاتا ہے، سو شیئر دیتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"230\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"32\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">خطرے سے سائز، گٹ سے نہیں</text>\n  <defs>\n    <marker id=\"ar18a\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L7,3 L0,6 Z\" fill=\"#8b949e\"/></marker>\n  </defs>\n  <rect x=\"30\" y=\"70\" width=\"150\" height=\"80\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\" stroke-width=\"2\"/>\n  <text x=\"105\" y=\"100\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">سرمایہ</text>\n  <text x=\"105\" y=\"122\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"15\" font-weight=\"700\" font-family=\"sans-serif\">2,00,000 روپے</text>\n  <line x1=\"182\" y1=\"110\" x2=\"212\" y2=\"110\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar18a)\"/>\n  <rect x=\"214\" y=\"70\" width=\"160\" height=\"80\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\" stroke-width=\"2\"/>\n  <text x=\"294\" y=\"96\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">خطرہ فی تجارت 1%</text>\n  <text x=\"294\" y=\"120\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"15\" font-weight=\"700\" font-family=\"sans-serif\">2,000 روپے</text>\n  <text x=\"294\" y=\"140\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">زیادہ تر آپ کھو سکتے ہیں۔</text>\n  <line x1=\"376\" y1=\"110\" x2=\"406\" y2=\"110\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar18a)\"/>\n  <rect x=\"408\" y=\"70\" width=\"160\" height=\"80\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\" stroke-width=\"2\"/>\n  <text x=\"488\" y=\"96\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">داخلہ 500، سٹاپ 480</text>\n  <text x=\"488\" y=\"120\" text-anchor=\"middle\" fill=\"#dd8452\" font-size=\"15\" font-weight=\"700\" font-family=\"sans-serif\">20 روپے/حصص</text>\n  <text x=\"488\" y=\"140\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">فاصلہ بند کرو</text>\n  <line x1=\"570\" y1=\"110\" x2=\"600\" y2=\"110\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar18a)\"/>\n  <rect x=\"602\" y=\"70\" width=\"130\" height=\"80\" rx=\"10\" fill=\"#11161d\" stroke=\"#8172b3\" stroke-width=\"2\"/>\n  <text x=\"667\" y=\"96\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">2000 / 20 =</text>\n  <text x=\"667\" y=\"122\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"16\" font-weight=\"700\" font-family=\"sans-serif\">100 شیئرز</text>\n  <text x=\"380\" y=\"195\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"12\" font-family=\"sans-serif\">100 شیئرز x 500 روپے = 50,000 روپے پوزیشن (سرمایہ کا ایک چوتھائی) - لیکن اگر روک دیا جائے تو نقصان صرف 2,000 روپے ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">مقدار = (سرمایہ کا 1%) تقسیم (فی حصص کا فاصلہ روکنا)۔ اسٹاپ سائز کا تعین کرتا ہے۔</figcaption>\n</figure><p>نوٹ کریں کہ پوزیشن 50,000 روپے ہے - اکاؤنٹ کا ایک چوتھائی - ابھی تک <em>خطرہ</em> صرف 2000 روپے ہے۔ ایک سخت سٹاپ آپ کو اسی خطرے کے لیے مزید حصص خریدنے دیتا ہے۔ ایک وسیع اسٹاپ کم زور دیتا ہے۔ روپے کا نقصان کسی بھی طرح سے 1% پر ہی رہتا ہے۔ یہ پوری چال ہے: اسٹاپ فاصلہ، آپ کا اعتماد نہیں، مقدار کا انتخاب کرتا ہے۔ یہ ایک تعلیمی مثال ہے، آپ کے لیے مخصوص تجارتی سائز کے بارے میں مشورہ نہیں۔</p>\n<h2 id=\"rule-4-a-daily-loss-limit\">قاعدہ 4: روزانہ نقصان کی حد</h2>\n<p>سائز ایک تجارت پر آپ کی حفاظت کرتا ہے۔ روزانہ نقصان کی حد آپ کو برے دن پر خود سے بچاتی ہے۔ دو نمبر مقرر کریں اور جو بھی پہلے آئے اسے مانیں: <strong>سرمائے کا 3% کم، یا 3 کھوئے ہوئے تجارت۔</strong> ہمارے تاجر کے لیے یہ ہے۔ <strong>6,000 روپے</strong> یا تین ہارے ہوئے - اور تین مکمل 1% نقصان <em>ہے</em> 6,000 روپے، تو وہ قطار میں لگ جاتے ہیں۔ یا تو مارو، اور آپ کا دن ہو گیا۔ اسکرین آف۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 250\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"روزانہ کی حد کا بہاؤ: ایک سیٹ اپ ٹریڈ لیں، دن کا حساب لگائیں۔ اگر تین فیصد یا تین ہارے ہوئے ہیں، تو دن کے لیے رک جائیں۔ بصورت دیگر آپ اگلا درست سیٹ اپ لے سکتے ہیں۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"250\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">روزانہ سرکٹ بریکر</text>\n  <defs>\n    <marker id=\"ar18b\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L7,3 L0,6 Z\" fill=\"#8b949e\"/></marker>\n  </defs>\n  <rect x=\"30\" y=\"95\" width=\"140\" height=\"60\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\" stroke-width=\"2\"/>\n  <text x=\"100\" y=\"122\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">ایک درست لے لو</text>\n  <text x=\"100\" y=\"140\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">سیٹ اپ تجارت</text>\n  <line x1=\"172\" y1=\"125\" x2=\"205\" y2=\"125\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar18b)\"/>\n  <polygon points=\"305,80 400,125 305,170 210,125\" fill=\"#11161d\" stroke=\"#dd8452\" stroke-width=\"2\"/>\n  <text x=\"305\" y=\"118\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-family=\"sans-serif\">3% نیچے</text>\n  <text x=\"305\" y=\"135\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12\" font-family=\"sans-serif\">یا 3 ہارے ہوئے؟</text>\n  <line x1=\"305\" y1=\"170\" x2=\"305\" y2=\"200\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar18b)\"/>\n  <text x=\"335\" y=\"190\" fill=\"#55a868\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">نہیں</text>\n  <rect x=\"225\" y=\"200\" width=\"160\" height=\"40\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\" stroke-width=\"2\"/>\n  <text x=\"305\" y=\"225\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"12\" font-family=\"sans-serif\">اگلا درست سیٹ اپ ٹھیک ہے۔</text>\n  <line x1=\"400\" y1=\"125\" x2=\"470\" y2=\"125\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#ar18b)\"/>\n  <text x=\"425\" y=\"113\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">جی ہاں</text>\n  <rect x=\"475\" y=\"95\" width=\"255\" height=\"60\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\" stroke-width=\"2\"/>\n  <text x=\"602\" y=\"120\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">STOP دن کے لیے</text>\n  <text x=\"602\" y=\"140\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\" font-family=\"sans-serif\">کوئی نئی تجارت نہیں، کوئی بدلہ نہیں۔</text>\n  <path d=\"M305,240 C 130,250 60,210 90,160\" fill=\"none\" stroke=\"#55a868\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\" marker-end=\"url(#ar18b)\"/>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">برے دن کی ایک منزل ہوتی ہے۔ حد کے بعد، سب سے زیادہ منافع بخش چیز جو آپ کر سکتے ہیں وہ کچھ بھی نہیں ہے۔</figcaption>\n</figure><p>نقطہ صحیح نمبر نہیں ہے۔ یہ ہے کہ فرش موجود ہے <em>پہلے</em> جذبات آتا ہے. 3% دن پریشان کن ہے۔ بدلے کی تجارت کا دن بغیر کسی حد کے یہ ہے کہ کس طرح 3% 20% بن جاتا ہے۔</p>\n<h2 id=\"rule-5-size-for-the-gap\">قاعدہ 5: خلا کے لیے سائز</h2>\n<p>یہاں وہ چیز ہے جو اسٹاک ٹریڈنگ کو انٹرا ڈے سے مختلف بناتی ہے۔ آپ کو راتوں رات پکڑ، اور ایک اسٹاک کر سکتے ہیں <strong>خلا</strong> - اگلی صبح کھولیں جہاں سے یہ بند ہوا تھا، نتائج یا خبروں پر، سیدھے اپنے اسٹاپ پر چھلانگ لگاتے ہوئے۔ آپ کا سٹاپ 480 روپے تھا۔ اسٹاک 460 روپے پر کھلتا ہے۔ آپ کا 40 روپے فی شیئر کا نقصان ہوتا ہے، 20 روپے کا نہیں۔</p>\n<p>تو اپنے سٹاپ کے طور پر علاج کریں <em>بہترین کیس</em>، بدترین نہیں۔ ان پوزیشنوں کے لیے جو آپ راتوں رات لے جاتے ہیں، خاص طور پر نتائج کی تاریخ میں، سائز چھوٹا ہوتا ہے - اپنے سٹاپ کے فاصلے پر ڈیڑھ سے دو گنا کا حقیقت پسندانہ فرق فرض کریں اور چیک کریں کہ نقصان اب بھی آپ کی برداشت کے مطابق ہے۔ سب سے آسان ورژن: کبھی بھی کسی معروف ایونٹ میں راتوں رات بڑی پوزیشن نہ رکھیں۔</p>\n<h2 id=\"rule-6-journal-and-weekly-review\">قاعدہ 6: جرنل اور ہفتہ وار جائزہ</h2>\n<p>آپ اسے بہتر نہیں کر سکتے جو آپ ریکارڈ نہیں کرتے ہیں۔ ہر تجارت کے بعد، چار چیزیں لکھیں: سیٹ اپ، آپ کا منصوبہ بند خطرہ، اصل نتیجہ، اور ایک ایماندار نوٹ کہ آیا آپ نے پلان پر عمل کیا۔ پھر ہفتے میں ایک بار - اتوار کا ایک پرسکون گھنٹہ - انہیں ایک بیچ کے طور پر پڑھیں۔ آپ کسی نئی حکمت عملی کا شکار نہیں ہیں۔ آپ ایک سوال کی جانچ کر رہے ہیں: <strong>کیا میں نے اپنی ریل کی پیروی کی؟</strong> وہ تجارت جہاں آپ نے ایک اصول توڑا ہے وہ آپ کی اصل ٹیوشن ہیں۔ زیادہ تر کنارے مارکیٹ میں نہیں بلکہ پلان اور آپ نے اصل میں کیا کیا اس کے درمیان خلا میں کھو جاتے ہیں۔</p>\n<h2 id=\"the-one-page-plan\">ایک صفحے کا منصوبہ</h2>\n<p>یہ ہے، ایک کارڈ پر پوری چیز آپ ایک چپچپا نوٹ پر کاپی کر سکتے ہیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 360\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک صفحے کا اسٹاک ٹریڈر رسک پلان کارڈ جس میں دو لاکھ روپے کے اکاؤنٹ کے لیے مثال کے نمبروں کے ساتھ چھ ریلوں کی فہرست ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"360\" rx=\"12\" fill=\"#0d1117\"/>\n  <rect x=\"20\" y=\"20\" width=\"720\" height=\"320\" rx=\"12\" fill=\"#11161d\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <text x=\"380\" y=\"52\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"17\" font-family=\"sans-serif\">ایک صفحے کا اسٹاک ٹریڈر رسک پلان</text>\n  <text x=\"380\" y=\"72\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"12\" font-family=\"sans-serif\">مثال کے طور پر اکاؤنٹ: 2,00,000 روپے</text>\n  <line x1=\"40\" y1=\"84\" x2=\"720\" y2=\"84\" stroke=\"#30363d\" stroke-width=\"1\"/>\n  <text x=\"50\" y=\"116\" fill=\"#55a868\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">1. سیٹ اپ</text>\n  <text x=\"250\" y=\"116\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">صرف میرا ایک متعین نمونہ۔ کوئی سیٹ اپ، کوئی تجارت نہیں۔</text>\n  <text x=\"50\" y=\"152\" fill=\"#55a868\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">2. روکنا</text>\n  <text x=\"250\" y=\"152\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">جس لمحے میں داخل ہوں اسے پہلے سے رکھا ہوا ہے۔ کبھی دستی نہیں۔</text>\n  <text x=\"50\" y=\"188\" fill=\"#55a868\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">3. سائز</text>\n  <text x=\"250\" y=\"188\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">رسک 1% = 2,000 روپے۔ مقدار = 2,000 / اسٹاپ فاصلہ۔</text>\n  <text x=\"50\" y=\"224\" fill=\"#55a868\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">4. روزانہ کی حد</text>\n  <text x=\"250\" y=\"224\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">-3% (6,000 روپے) یا 3 ہارے ہوئے پر رکیں۔ اسکرین آف۔</text>\n  <text x=\"50\" y=\"260\" fill=\"#55a868\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">5. فرق</text>\n  <text x=\"250\" y=\"260\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">2x سٹاپ کے لیے رات بھر سائز۔ واقعات میں کوئی بڑا سائز نہیں۔</text>\n  <text x=\"50\" y=\"296\" fill=\"#55a868\" font-size=\"14\" font-weight=\"700\" font-family=\"sans-serif\">6. جرنل</text>\n  <text x=\"250\" y=\"296\" fill=\"#cdd9e5\" font-size=\"13\" font-family=\"sans-serif\">ہر تجارت کو لاگ ان کریں۔ ہر اتوار کو ہفتے کا جائزہ لیں۔</text>\n  <line x1=\"40\" y1=\"312\" x2=\"720\" y2=\"312\" stroke=\"#30363d\" stroke-width=\"1\"/>\n  <text x=\"380\" y=\"330\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11.5\" font-family=\"sans-serif\">ایک خراب تجارت کی قیمت 1% ہے۔ ایک برے دن کی قیمت 3% ہے۔ نہ ہی اکاؤنٹ ختم کر سکتا ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ایک کارڈ پر مکمل منصوبہ۔ ہر روپیہ کے اعداد و شمار کو اپنے کیپیٹل تک پیمانہ کریں۔</figcaption>\n</figure><p>تجارت سے پہلے کی چیک لسٹ کے طور پر، ترتیب میں:</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> یہ چارٹ میرا طے شدہ سیٹ اپ ہے - بوریت نہیں، کوئی ٹپ نہیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> مجھے اپنی سٹاپ کی قیمت معلوم ہے، اور میں داخل ہوتے ہی اسے رکھ دوں گا۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> مقدار = 2,000 روپے فی شیئر اسٹاپ فاصلے سے تقسیم۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> آج کا چل رہا نقصان ابھی تک -3% یا 3 ہارے ہوئے نہیں ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> اگر میں اسے رات بھر رکھتا ہوں، یہاں تک کہ 2x فرق کا نقصان بھی قابل برداشت ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں آج رات اس تجارت کو لاگ کروں گا اور اتوار کو اس کا جائزہ لوں گا۔</li>\n</ul>\n<h2 id=\"how-it-differs-for-the-investor-and-the-intraday-trader\">یہ سرمایہ کار اور انٹرا ڈے ٹریڈر کے لیے کیسے مختلف ہے۔</h2>\n<p>ایک ہی چھ خیالات، تین مختلف ڈائلز۔</p>\n<table>\n<thead>\n<tr>\n<th>ریل</th>\n<th>طویل مدتی سرمایہ کار</th>\n<th>سوئنگ / پوزیشنل ٹریڈر</th>\n<th>انٹرا ڈے تاجر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>فی شرط خطرہ</td>\n<td>مختص، کوئی فی ٹریڈ اسٹاپ نہیں۔</td>\n<td>~1% فی تجارت، ہارڈ اسٹاپ</td>\n<td>~0.5-1% فی تجارت، ہارڈ اسٹاپ</td>\n</tr>\n<tr>\n<td>روزانہ کی حد</td>\n<td>متعلقہ نہیں</td>\n<td>-3% یا 3 ہارنے والے</td>\n<td>سخت، نیز بدلہ نہ لینے کا اصول</td>\n</tr>\n<tr>\n<td>رات کا وقفہ</td>\n<td>گلے لگا ہوا - لمبا افق</td>\n<td>خلا کے لئے سائز</td>\n<td>قریب سے فلیٹ، تقریباً کوئی نہیں۔</td>\n</tr>\n<tr>\n<td>جائزہ لیں</td>\n<td>سہ ماہی توازن</td>\n<td>ہفتہ وار جریدہ</td>\n<td>روزانہ اور ہفتہ وار</td>\n</tr>\n</tbody></table>\n<p>سرمایہ کار بمشکل اسٹاپ کا استعمال کرتا ہے کیونکہ وقت کشن ہے۔ انٹرا ڈے ٹریڈر چلاتا ہے۔ <em>ایک ہی</em> ریلز لیکن سخت اور تیز، اور ایک سخت بغیر انتقامی اصول کا اضافہ کرتا ہے - اگلا باب۔ جھولنے والا تاجر درمیان میں بیٹھتا ہے: اصلی سٹاپ، حقیقی سائز، اور دن کا تاجر فرار ہونے کا خطرہ - راتوں کا فرق۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>یہ ریل تباہی کو کم کرتے ہیں۔ وہ ایک کنارے تیار نہیں کرتے ہیں، اور ان کے پاس ایماندارانہ فرق ہے۔</p>\n<p><strong>ایک منصوبہ جس کا کوئی کنارہ نہیں ہے بس آہستہ آہستہ کھو جاتا ہے۔</strong> کام نہ کرنے والی حکمت عملی پر کامل 1% سائز کا مطلب ہے کہ آپ ایک بار میں 10% کے بجائے ایک وقت میں 1% کھو دیتے ہیں - صاف ستھرا، اب بھی نیچے کی طرف۔ ریل آپ کو بقا اور ایک کنارے تلاش کرنے کا وقت خریدتی ہے۔ وہ کنارے نہیں ہیں.</p>\n<p><strong>فرق کسی بھی اسٹاپ کو شکست دے سکتا ہے۔</strong> ایک 2x فرق کے لیے سائز اور مارکیٹ اب بھی آپ کو صدمے کے نتیجے میں 4x صبح دے سکتی ہے۔ فرق کے لیے سائز سکڑتا ہے کہ دھچکا؛ یہ وعدہ نہیں کر سکتا کہ نقصان کبھی بھی 1% سے زیادہ نہ ہو۔ شاذ و نادر ہی دنوں میں ایسا ہوگا۔</p>\n<p><strong>منصوبہ صرف اس صورت میں کام کرتا ہے جب آپ اس کی اطاعت کریں۔</strong> جریدہ موجود ہے کیونکہ سب سے مشکل حصہ قواعد کو نہیں لکھ رہا ہے - یہ ان کی پیروی کر رہا ہے جس دن آپ بور، نیچے، یا یقین رکھتے ہیں۔ ایک منصوبہ جسے آپ دباؤ میں اوور رائیڈ کرتے ہیں وہ سجاوٹ ہے۔ یہ باب تعلیم ہے، ذاتی مشورے نہیں؛ ہر نمبر کو اپنانے کے لیے مثال کے طور پر پیش کریں، نقل کرنے کی سفارش نہیں۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> 2,00,000 روپے کے اکاؤنٹ کے لیے 20 روپے کے اسٹاپ فاصلے کے ساتھ فی تجارت 1% کا خطرہ ہے، کتنے شیئرز؟</summary><p>2,00,000 روپے کا 1% 2,000 روپے ہے۔ فی شیئر 20 روپے سٹاپ فاصلے سے تقسیم کریں: 2,000/20 = 100 شیئرز۔ اگر سٹاپ ہٹ جاتا ہے، تو آپ کا 2,000 روپے کا نقصان ہوتا ہے - بالکل 1%۔</p>\n</details><details>\n<summary><strong>2.</strong> مثال میں کون سے دو نمبر روزانہ نقصان کی حد کو متعین کرتے ہیں، اور جب کسی کو مارا جاتا ہے تو آپ کیا کرتے ہیں؟</summary><p>سرمائے میں 3% کمی (6,000 روپے) یا 3 کھونے والی تجارت، جو بھی پہلے آئے۔ جب دونوں میں سے کوئی ایک تک پہنچ جاتا ہے تو آپ دن کے لیے تجارت بند کر دیتے ہیں - کوئی نئی تجارت نہیں، کوئی بدلہ نہیں - اور اسکرین کو بند کر دیں۔</p>\n</details><details>\n<summary><strong>3.</strong> جب انٹرا ڈے ٹریڈر کو ضرورت نہیں ہے تو فرق کے لیے سوئنگ ٹریڈر کا سائز کیوں ہونا چاہیے؟</summary><p>سوئنگ ٹریڈر راتوں رات ہولڈ کرتا ہے، لہذا ایک اسٹاک خبروں پر اسٹاپ سے نیچے جا سکتا ہے اور نقصان کا احساس منصوبہ بندی سے کہیں زیادہ ہو سکتا ہے۔ انٹرا ڈے ٹریڈر قریب قریب فلیٹ ہے، اس لیے وہ راتوں رات وقفے کا کوئی خطرہ نہیں رکھتے۔</p>\n</details><details>\n<summary><strong>4.</strong> \"گٹ کے ذریعہ سائز\" میں کیا غلط ہے - یقین پر بڑا، شک پر چھوٹا؟</summary><p>یہ اس تجارت پر آپ کی سب سے بڑی پوزیشن رکھتا ہے جس کے بارے میں آپ کو سب سے زیادہ یقین ہے، اور یقین برے نتیجے سے کوئی تحفظ نہیں ہے۔ آپ کا سب سے بڑا نقصان پھر آپ کی سب سے بڑی شرط پر اترتا ہے۔ فکسڈ 1% سائزنگ ہر نقصان کو ایک ہی چھوٹے سائز میں رکھتی ہے، چاہے آپ کا اعتماد کچھ بھی ہو۔</p>\n</details><details>\n<summary><strong>5.</strong> ہفتہ وار جائزہ دراصل کس چیز کی جانچ کر رہا ہے؟</summary><p>کوئی نئی حکمت عملی نہیں ہے - چاہے آپ نے اپنی ریل کی پیروی کی ہو۔ وہ تجارت جہاں آپ نے ایک اصول کو توڑا ہے (اسٹاپ کو چھوڑ دیا ہے، بڑے پیمانے پر، بدلے کی تجارت کی گئی ہے) اصل اسباق ہیں، کیونکہ زیادہ تر کنارے منصوبے اور آپ نے جو کچھ کیا اس کے درمیان فرق میں کھو جاتا ہے۔</p>\n</details>\n","toc":[{"level":2,"text":"چھ ریل","id":"the-six-rails"},{"level":2,"text":"قاعدہ 1 اور 2: ایک سیٹ اپ، پہلے سٹاپ رکھیں","id":"rule-1-and-2-one-setup-stop-placed-first"},{"level":2,"text":"قاعدہ 3: سائز تو ایک نقصان ~1%","id":"rule-3-size-so-one-loss-costs-1"},{"level":2,"text":"قاعدہ 4: روزانہ نقصان کی حد","id":"rule-4-a-daily-loss-limit"},{"level":2,"text":"قاعدہ 5: خلا کے لیے سائز","id":"rule-5-size-for-the-gap"},{"level":2,"text":"قاعدہ 6: جرنل اور ہفتہ وار جائزہ","id":"rule-6-journal-and-weekly-review"},{"level":2,"text":"ایک صفحے کا منصوبہ","id":"the-one-page-plan"},{"level":2,"text":"یہ سرمایہ کار اور انٹرا ڈے ٹریڈر کے لیے کیسے مختلف ہے۔","id":"how-it-differs-for-the-investor-and-the-intraday-trader"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"20":{"html":"<p>روہت نے منگل کو ایک واضح سر اور چھوٹے منصوبے کے ساتھ شروع کیا: دو تجارتیں، اندر اور باہر، دوپہر کے کھانے کے ذریعے کی گئیں۔ اس کی پہلی تجارت پہلے دس منٹ میں مائنس 1,200 روپے کے نقصان پر رک گئی۔ وہ ڈنک ہی اس نے لیا تھا۔ اس نے اسے واپس جیتنے کے لیے سیدھا پیچھے سے چھلانگ لگائی، پھر دوبارہ، پھر سائز بڑھا کیونکہ \"یہ واضح ہے۔\" 12:30 تک اس نے گیارہ تجارتیں کیں، اس کا انگوٹھا اس کی سوچ سے زیادہ تیز تھا، اور 1,00,000 روپے کا اکاؤنٹ 9,400 روپے نیچے تھا - اس نقصان سے تقریباً پانچ گنا جس کا اس نے منصوبہ بنایا تھا۔ اس دن بازار میں کچھ بھی خاص طور پر غلط نہیں ہوا تھا۔ روہت نے اپنے منصوبے کے بجائے محض اپنے جذبات کا سودا کیا تھا، اور انٹرا ڈے اکاؤنٹ کسی بھی دوسری قسم سے زیادہ تیزی سے سزا دیتا ہے۔</p>\n<p>انٹرا ڈے ٹریڈنگ مارکیٹ میں سب سے زیادہ ناقابل معافی سیٹ ہے۔ آپ کے پاس سوچنے کا وقت نہیں ہے، راتوں رات ٹھنڈا ہونے کا کوئی وقفہ نہیں ہے، اور ہر بار کلک کرنے پر آپ کے پاس لاگت آتی ہے۔ یہ باب آپ کو ایک ایسی چیز فراہم کرتا ہے جو انٹرا ڈے اکاؤنٹ کو زندہ رکھتا ہے: سخت قوانین کا ایک چھوٹا سا مجموعہ، جو مارکیٹ کھلنے سے پہلے لکھا جاتا ہے، کہ جب آپ ہار رہے ہوں تو آپ کو دوبارہ مذاکرات کرنے کی ضرورت نہیں ہے۔</p>\n<h2 id=\"why-intraday-breaks-people-fastest\">انٹرا ڈے لوگوں کو سب سے تیزی سے کیوں توڑ دیتا ہے۔</h2>\n<p>ایک طویل مدتی سرمایہ کار مہینوں تک غلط ہوسکتا ہے اور پھر بھی ٹھیک ہوسکتا ہے۔ ایک انٹرا ڈے تاجر ایک صبح کے لیے غلط ہو سکتا ہے اور اڑا سکتا ہے۔ فرق رفتار اور تعدد میں ہے۔ آپ چند گھنٹوں میں بہت ساری تجارتیں لیتے ہیں، ہر ایک کی لاگت ہوتی ہے - بروکریج، ایکسچینج فیس، STT، سلپیج - اور حقیقی وقت میں خراب موڈ مرکبات۔ اس پر کوئی \"نیند\" نہیں ہے۔ بدلہ لینے کا فیصلہ تجارت اور تباہی دونوں دوپہر کے کھانے سے پہلے ہوتے ہیں۔</p>\n<p>لہذا انٹرا ڈے ڈسپلن قوت ارادی نہیں ہو سکتی۔ یہ ایک ایسا نظام ہونا چاہیے جو آپ پرسکون رہتے ہوئے ترتیب دیں اور جذباتی ہو کر اطاعت کریں۔ پورا منصوبہ مقصد کے مطابق ایک صفحے پر فٹ بیٹھتا ہے - لہذا جب آپ کا فیصلہ ختم ہوجائے تو آپ اسے پانچ سیکنڈ میں پڑھ سکتے ہیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 380\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک صفحے پر مشتمل انٹرا ڈے رسک پلان کارڈ جس میں چھ قواعد درج ہیں: زیادہ سے زیادہ تین سے پانچ تجارت، دو فیصد کا سخت روزانہ نقصان یا دو ہارنے والی تجارت پھر سوئچ آف، بغیر بدلے کے کول ڈاؤن، ایک لیکویڈیٹی فلٹر، کھلے اور دیر سے مایوسی کی تجارت سے گریز کرنے والے وقت کے قواعد، اور حد کے احکامات کا استعمال کرتے ہوئے عمل درآمد کا نظم و ضبط۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"380\" rx=\"12\" fill=\"#0d1117\"/>\n  <rect x=\"20\" y=\"20\" width=\"720\" height=\"340\" rx=\"12\" fill=\"#11161d\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <text x=\"380\" y=\"50\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"17\" font-family=\"sans-serif\">ایک صفحے کا انٹرا ڈے رسک پلان</text>\n  <line x1=\"40\" y1=\"64\" x2=\"720\" y2=\"64\" stroke=\"#30363d\" stroke-width=\"1\"/>\n  <g font-family=\"sans-serif\">\n    <circle cx=\"58\" cy=\"98\" r=\"13\" fill=\"#4c72b0\"/><text x=\"58\" y=\"103\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"13\" font-weight=\"700\">1</text>\n    <text x=\"82\" y=\"95\" fill=\"#e6edf3\" font-size=\"13\" font-weight=\"700\">ایک دن میں زیادہ سے زیادہ 3 سے 5 تجارت</text>\n    <text x=\"82\" y=\"111\" fill=\"#8b949e\" font-size=\"11\">جب گنتی ختم ہو جاتی ہے، آپ کا کام ہو جاتا ہے - چاہے جیتنے کے باوجود۔</text><div class=\"code-wrap\"><button class=\"ex-copy\" type=\"button\" aria-label=\"کوڈ کاپی کریں۔\">کاپی</button><pre><code>&lt;circle cx=&quot;58&quot; cy=&quot;148&quot; r=&quot;13&quot; fill=&quot;#c44e52&quot;/&gt;&lt;text x=&quot;58&quot; y=&quot;153&quot; text-anchor=&quot;middle&quot; fill=&quot;#fff&quot; font-size=&quot;13&quot; font-weight=&quot;700&quot;&gt;2&lt;/text&gt;\n&lt;text x=&quot;82&quot; y=&quot;145&quot; fill=&quot;#e6edf3&quot; font-size=&quot;13&quot; font-weight=&quot;700&quot;&gt;Hard daily loss: minus 2% or 2 losers, then switch off&lt;/text&gt;\n&lt;text x=&quot;82&quot; y=&quot;161&quot; fill=&quot;#8b949e&quot; font-size=&quot;11&quot;&gt;On a Rs 1,00,000 account that is Rs 2,000. No exceptions, no &quot;one more.&quot;&lt;/text&gt;\n\n&lt;circle cx=&quot;58&quot; cy=&quot;198&quot; r=&quot;13&quot; fill=&quot;#dd8452&quot;/&gt;&lt;text x=&quot;58&quot; y=&quot;203&quot; text-anchor=&quot;middle&quot; fill=&quot;#fff&quot; font-size=&quot;13&quot; font-weight=&quot;700&quot;&gt;3&lt;/text&gt;\n&lt;text x=&quot;82&quot; y=&quot;195&quot; fill=&quot;#e6edf3&quot; font-size=&quot;13&quot; font-weight=&quot;700&quot;&gt;No-revenge rule: cool down after a loss&lt;/text&gt;\n&lt;text x=&quot;82&quot; y=&quot;211&quot; fill=&quot;#8b949e&quot; font-size=&quot;11&quot;&gt;Stand up for 15 to 30 minutes before the next trade. Never size up to recover.&lt;/text&gt;\n\n&lt;circle cx=&quot;58&quot; cy=&quot;248&quot; r=&quot;13&quot; fill=&quot;#37b3a4&quot;/&gt;&lt;text x=&quot;58&quot; y=&quot;253&quot; text-anchor=&quot;middle&quot; fill=&quot;#fff&quot; font-size=&quot;13&quot; font-weight=&quot;700&quot;&gt;4&lt;/text&gt;\n&lt;text x=&quot;82&quot; y=&quot;245&quot; fill=&quot;#e6edf3&quot; font-size=&quot;13&quot; font-weight=&quot;700&quot;&gt;Liquidity filter: only liquid names&lt;/text&gt;\n&lt;text x=&quot;82&quot; y=&quot;261&quot; fill=&quot;#8b949e&quot; font-size=&quot;11&quot;&gt;High-volume large-caps or index options. Thin stocks bleed you on slippage.&lt;/text&gt;\n\n&lt;circle cx=&quot;58&quot; cy=&quot;298&quot; r=&quot;13&quot; fill=&quot;#8172b3&quot;/&gt;&lt;text x=&quot;58&quot; y=&quot;303&quot; text-anchor=&quot;middle&quot; fill=&quot;#fff&quot; font-size=&quot;13&quot; font-weight=&quot;700&quot;&gt;5&lt;/text&gt;\n&lt;text x=&quot;82&quot; y=&quot;295&quot; fill=&quot;#e6edf3&quot; font-size=&quot;13&quot; font-weight=&quot;700&quot;&gt;Time-of-day: skip the first 15 min, no new trades late&lt;/text&gt;\n&lt;text x=&quot;82&quot; y=&quot;311&quot; fill=&quot;#8b949e&quot; font-size=&quot;11&quot;&gt;The open is fast and dangerous. Do not carry a desperation trade into the close.&lt;/text&gt;\n\n&lt;circle cx=&quot;58&quot; cy=&quot;340&quot; r=&quot;13&quot; fill=&quot;#55a868&quot;/&gt;&lt;text x=&quot;58&quot; y=&quot;345&quot; text-anchor=&quot;middle&quot; fill=&quot;#fff&quot; font-size=&quot;13&quot; font-weight=&quot;700&quot;&gt;6&lt;/text&gt;\n&lt;text x=&quot;82&quot; y=&quot;337&quot; fill=&quot;#e6edf3&quot; font-size=&quot;13&quot; font-weight=&quot;700&quot;&gt;Execution: limit orders, no chasing&lt;/text&gt;\n&lt;text x=&quot;82&quot; y=&quot;353&quot; fill=&quot;#8b949e&quot; font-size=&quot;11&quot;&gt;Entry, stop and target set before you click. If price ran away, let it go.&lt;/text&gt;\n</code></pre></div>  </g>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ایک کارڈ پر پورا منصوبہ۔ جب آپ کا فیصلہ پھسل رہا ہو تو اسے پانچ سیکنڈ میں پڑھیں۔</figcaption>\n</figure><h2 id=\"the-six-guardrails-one-at-a-time\">چھ گارڈریلز، ایک وقت میں ایک</h2>\n<p><strong>فی دن زیادہ سے زیادہ تجارت (اوور ٹریڈنگ سے بچیں)۔</strong> ایک مشکل گنتی سیٹ کریں - 3 سے 5 بولیں - اور جب یہ ختم ہوجائے، جیت جائے یا ہار جائے تو رک جائیں۔ روہت کی صبح کا نقصان کوئی ایک تجارت نہیں تھا۔ یہ گیارہویں تجارت تھی۔ زیادہ کلکس کا مطلب ہے زیادہ اخراجات اور جذبات کو آگے بڑھانے کے زیادہ مواقع۔ منصوبہ بند تجارت کی ایک چھوٹی سی تعداد ہر بار رد عمل کی لہر کو ہرا دیتی ہے۔</p>\n<p><strong>ایک مشکل زیادہ سے زیادہ روزانہ نقصان.</strong> ایک ایسا نمبر منتخب کریں جسے آپ اپنی زندگی یا آپ کی اگلی صبح کو نقصان پہنچائے بغیر کھو سکتے ہیں - ایک مشترکہ نقطہ آغاز سرمایہ کا 2%، یا دو ہارنے والی تجارت ہے، جو بھی پہلے آئے۔ 1,00,000 روپے کے اکاؤنٹ پر جو کہ تقریباً 2,000 روپے ہے۔ جس لمحے آپ اسے مارتے ہیں، آپ اسکرین کو بند کر دیتے ہیں اور دن کے لیے چلے جاتے ہیں۔ کوئی استثنا نہیں ہے۔ کھونے والے دن وہ ہوتے ہیں جہاں اکاؤنٹس مر جاتے ہیں، لہذا نقصان کو کیپ کرنا صفحہ پر سب سے اہم لائن ہے۔</p>\n<p><strong>ایک بغیر انتقام کا اصول۔</strong> نقصان سے تقریباً دوگنا نقصان ہوتا ہے جتنا ایک ہی سائز کا فائدہ اچھا لگتا ہے - یہ عدم توازن اسے واپس جیتنے کی خواہش کو بھڑکاتا ہے <em>ابھی</em>. نقصان سے بچنے اور بدلے کی تجارت کے باب نے دکھایا کہ کس طرح دوسری تجارت عام طور پر پہلی سے بدتر ہوتی ہے۔ حل مکینیکل ہے: کسی بھی نقصان کے بعد، کھڑے ہو جائیں اور 15 سے 30 منٹ کے لیے اس سے پہلے کہ آپ کو دوبارہ تجارت کرنے کی اجازت دی جائے، اور \"اسے واپس کرنے\" کے لیے اپنے سائز میں کبھی اضافہ نہ کریں۔ بدلہ اس وقت لڑنے کے لیے کردار کی خامی نہیں ہے۔ یہ ایک ایسی تجارت ہے جس پر آپ نے پرسکون رہتے ہوئے پہلے سے پابندی لگا دی تھی۔</p>\n<p><strong>ایک لیکویڈیٹی فلٹر۔</strong> صرف ان ناموں کی تجارت کریں جن کی بہت سے لوگ خرید و فروخت کر رہے ہیں - ہائی والیوم لارج کیپس یا اہم انڈیکس کے اختیارات۔ مائع نام میں خرید و فروخت کی قیمت کے درمیان فرق بہت کم ہوتا ہے، اس لیے آنے اور جانے سے آپ کو تقریباً کچھ بھی نہیں پڑتا۔ ایک پتلی، غیر مائع اسٹاک میں جو خلا وسیع ہے؛ آپ کا اسٹاپ بہت نیچے بھر جاتا ہے جہاں آپ چاہتے تھے، اور پھسلن خاموشی سے تجارت کے بعد تجارت کو کھا جاتی ہے۔ ابتدائی افراد کو مائع ناموں کی ایک مختصر واچ لسٹ رکھنی چاہیے اور باقی سب چیزوں کو نظر انداز کرنا چاہیے۔</p>\n<p><strong>دن کے وقت کا خطرہ۔</strong> 9:15 کے بعد کے پہلے چند منٹ دن کے تیز ترین اور سب سے زیادہ پرتشدد ہوتے ہیں - رات بھر کے آرڈرز ایک ساتھ ملتے ہیں، قیمتیں تیزی سے بڑھ جاتی ہیں، اور پھیلاؤ وسیع ہوتا ہے۔ اسے بسنے دو۔ پہلے 15 منٹ چھوڑ دیں۔ دوپہر کی خاموشی پرسکون ہے۔ آخری سلسلہ پھر سے سخت ہو جاتا ہے، اور یہ وہ جگہ ہے جہاں مایوسی رہتی ہے: دن کے نیچے، لوگ ایک حتمی تجارت کو بند ہونے سے پہلے \"فلیٹ پر واپس جانے\" پر مجبور کرتے ہیں۔ مت کرو. دوپہر کے اوائل تک نئی تجارتیں کھولنا بند کر دیں اور سیشن ختم ہونے سے پہلے ہر چیز کو اچھی طرح ہموار کر لیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"پورے تجارتی دن میں 9:15 سے 3:30 تک خطرے کا وکر۔ خطرہ کھلی جگہ پر سب سے زیادہ ہوتا ہے، ایک پرسکون دوپہر کم پر گرتا ہے، پھر قریب میں دوبارہ بڑھ جاتا ہے۔ پہلے پندرہ منٹ پرہیز کے طور پر سایہ دار ہیں، اور دوپہر کے آخر میں کوئی نئی تجارت نہ ہونے کی وجہ سے سایہ دار ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">جب دن کے وقت خطرہ سب سے زیادہ ہوتا ہے۔</text>\n  <line x1=\"70\" y1=\"60\" x2=\"70\" y2=\"240\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <line x1=\"70\" y1=\"240\" x2=\"720\" y2=\"240\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <text x=\"40\" y=\"150\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\" transform=\"rotate(-90 40 150)\">خطرہ / رفتار</text>\n  <rect x=\"70\" y=\"60\" width=\"70\" height=\"180\" fill=\"#c44e52\" fill-opacity=\"0.16\"/>\n  <rect x=\"610\" y=\"60\" width=\"110\" height=\"180\" fill=\"#dd8452\" fill-opacity=\"0.16\"/>\n  <path d=\"M70,90 C 110,80 130,150 200,185 C 320,235 430,235 540,205 C 600,188 660,120 720,95\" fill=\"none\" stroke=\"#4c72b0\" stroke-width=\"3\"/>\n  <circle cx=\"80\" cy=\"86\" r=\"5\" fill=\"#c44e52\"/>\n  <circle cx=\"370\" cy=\"232\" r=\"5\" fill=\"#55a868\"/>\n  <circle cx=\"710\" cy=\"98\" r=\"5\" fill=\"#dd8452\"/>\n  <text x=\"78\" y=\"78\" fill=\"#c44e52\" font-size=\"11\" font-weight=\"700\" font-family=\"sans-serif\">کھلا: تیز ترین</text>\n  <text x=\"330\" y=\"225\" fill=\"#55a868\" font-size=\"11\" font-weight=\"700\" font-family=\"sans-serif\">midday : پرسکون</text>\n  <text x=\"600\" y=\"86\" fill=\"#dd8452\" font-size=\"11\" font-weight=\"700\" font-family=\"sans-serif\">close : تنگ کرتا ہے۔</text>\n  <text x=\"105\" y=\"258\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\" font-family=\"sans-serif\">9:15</text>\n  <text x=\"105\" y=\"270\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"10\" font-family=\"sans-serif\">پہلے 15 منٹ سے بچیں</text>\n  <text x=\"380\" y=\"258\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\" font-family=\"sans-serif\">12:30</text>\n  <text x=\"665\" y=\"258\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\" font-family=\"sans-serif\">3:30</text>\n  <text x=\"665\" y=\"270\" text-anchor=\"middle\" fill=\"#dd8452\" font-size=\"10\" font-family=\"sans-serif\">کوئی نئی تجارت نہیں</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">کھلا تیز اور خطرناک ہے؛ دیر سے سیشن وہ ہے جہاں مایوسی تجارت کرتی ہے۔ پرسکون درمیانی تجارت کریں۔</figcaption>\n</figure><p><strong>عملدرآمد کا نظم و ضبط۔</strong> داخلے، رکنے اور ہدف کا فیصلہ کریں۔ <em>پہلے</em> آپ کلک کریں - پھر ایک حد کا آرڈر استعمال کریں تاکہ آپ اپنی ادا کردہ قیمت کو کنٹرول کریں۔ اگر اقدام پہلے ہی آپ کی سطح سے بھاگ گیا ہے، تو اسے جانے دو۔ ہمیشہ ایک اور تجارت ہے. مارکیٹ آرڈر کے ساتھ تیز قیمت کا پیچھا کرنا یہ ہے کہ آپ کس طرح اسپائک کے اوپری حصے کو خریدتے ہیں اور اپنے کنارے کو پھسلنے کے حوالے کرتے ہیں۔ آرڈر پیڈ پر پرسکون ہاتھ کسی بھی اشارے سے زیادہ پیسے بچاتے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>انٹرا ڈے پلان ان سوئچز کا ایک سیٹ ہے جسے آپ پرسکون رہتے ہوئے پلٹتے ہیں تاکہ جذباتی ہو کر آپ انہیں پلٹ نہ سکیں۔ دو نمبر زیادہ سے زیادہ وزن اٹھاتے ہیں: تجارت کی زیادہ سے زیادہ تعداد، اور ایک مشکل روزانہ نقصان جس کے بعد آپ دن کے لیے سوئچ آف کر دیتے ہیں - کوئی استثنا نہیں۔</p>\n</div></div>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>کلاسک انٹرا ڈے بلو اپ تین غلطیوں پر مشتمل ہے: روزانہ نقصان کی کوئی حد نہیں، لہذا خراب آغاز کی کوئی منزل نہیں ہوتی۔ بدلے کی تجارت، اس لیے ہر نقصان ایک بڑی، غصے والی تجارت کو متحرک کرتا ہے۔ اور اوور ٹریڈنگ، لہذا کلکس کی سراسر تعداد لاگت اور نقصان دونوں کو کئی گنا بڑھا دیتی ہے۔ بہتر اقدام جان بوجھ کر بورنگ ہے - ایک چھوٹی تجارتی گنتی، ایک مشکل روپیہ روک، اور کسی بھی نقصان کے بعد زبردستی وقفہ۔ بورنگ آپ کو کھیل میں رکھتا ہے۔</p>\n</div></div>\n<h2 id=\"the-one-page-plan-copy-this\">ایک صفحے کا منصوبہ (اسے کاپی کریں)</h2>\n<p>ان کو ایک چپچپا نوٹ پر لکھیں اور اپنی اسکرین پر رکھیں۔ نمبرز 1,00,000 روپے کے اکاؤنٹ کی مثالیں ہیں - انہیں اپنے سرمائے اور خطرے کی برداشت کے مطابق ایڈجسٹ کریں۔</p>\n<ol>\n<li><strong>سرمایہ اور خطرہ فی تجارت:</strong> خطرہ 0.5% سے 1% فی تجارت - یہاں، 500 سے 1,000 روپے۔</li>\n<li><strong>آج کی زیادہ سے زیادہ تجارت:</strong> 3 سے 5۔ جب وہ چلے جاتے ہیں، میرا کام ہو جاتا ہے۔</li>\n<li><strong>مشکل روزانہ سٹاپ:</strong> مائنس 2% (2,000 روپے) <em>یا</em> 2 ہارنے والی تجارت، جو بھی پہلے آئے - پھر سوئچ آف کریں۔</li>\n<li><strong>کسی بھی نقصان کے بعد:</strong> کھڑے ہو جاؤ، 15 سے 30 منٹ کا وقفہ، کوئی سائز نہیں کوئی انتقام نہیں۔</li>\n<li><strong>کائنات:</strong> میری واچ لسٹ میں صرف مائع بڑے کیپس یا انڈیکس کے اختیارات۔ کچھ بھی پتلا نہیں۔</li>\n<li><strong>ٹائمنگ:</strong> پہلے 15 منٹ میں کوئی تجارت نہیں؛ نہیں <em>نیا</em> دوپہر کے اوائل کے بعد تجارت؛ بند ہونے سے پہلے فلیٹ.</li>\n<li><strong>ہر حکم:</strong> اندراج، سٹاپ اور ہدف پہلے لکھا گیا؛ حد حکم؛ کوئی پیچھا نہیں.</li>\n<li><strong>اگر کوئی اصول ٹوٹ جاتا ہے:</strong> دن کے لئے رکیں اور جو کچھ ہوا اس کی جریدہ کریں۔</li>\n</ol>\n<p>ایک مختصر، ایماندارانہ لائن: یہ ایک تعلیمی ٹیمپلیٹ ہے، ذاتی مشورے نہیں۔ کسی بھی حقیقی رقم سے پہلے سینڈ باکس ٹریڈنگ (اونالائزر موڈ OpenAlgo) میں اس کی مشق کریں، اور نمبروں کو اپنے اکاؤنٹ میں ٹیون کریں۔</p>\n<h2 id=\"intraday-vs-the-swing-trader-s-plan\">انٹرا ڈے بمقابلہ سوئنگ ٹریڈر کا منصوبہ</h2>\n<p>پچھلے باب میں سٹاک ٹریڈر کا منصوبہ ایک ہی ڈھانچے کو شیئر کرتا ہے - خطرہ فی تجارت، ایک سٹاپ، ایک روزانہ کی حد - لیکن ڈائل مختلف طریقے سے سیٹ کیے گئے ہیں، کیونکہ راتوں رات ہولڈنگ کرنا ہر شام فلیٹ رہنے سے مختلف کھیل ہے۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>انٹرا ڈے تاجر</th>\n<th>سوئنگ (اسٹاک) کا تاجر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ہولڈنگ وقت</td>\n<td>منٹ سے گھنٹے؛ قریب سے فلیٹ</td>\n<td>دنوں سے ہفتوں تک؛ راتوں رات رکھتا ہے</td>\n</tr>\n<tr>\n<td>سب سے بڑا دشمن</td>\n<td>اوور ٹریڈنگ اور حقیقی وقت میں بدلہ</td>\n<td>سوتے وقت وقفہ کا خطرہ</td>\n</tr>\n<tr>\n<td>فی دن تجارت</td>\n<td>چند اور محدود (3 سے 5)</td>\n<td>اکثر صفر نیا؛ کھلے کا انتظام کریں</td>\n</tr>\n<tr>\n<td>وقت کا قاعدہ</td>\n<td>نازک - کھلے اور بند خطرے والے زون ہیں۔</td>\n<td>معمولی - ایک دن میں ایک پرسکون فیصلہ</td>\n</tr>\n<tr>\n<td>روزانہ نقصان کی حد</td>\n<td>مشکل، پھر سوئچ آف</td>\n<td>مفید، لیکن مارنے میں سست</td>\n</tr>\n<tr>\n<td>اخراجات اور پھسلن</td>\n<td>سختی سے کاٹنا - تعدد انہیں ضرب دیتا ہے۔</td>\n<td>ہر تجارت کا چھوٹا حصہ</td>\n</tr>\n</tbody></table>\n<p>ایک ہی خیال، مختلف رفتار۔ انٹرا ڈے ٹریڈر کو خاص طور پر سخت اور تیز گڑھوں کی ضرورت ہوتی ہے کیونکہ انہیں خود سے بچانے کے لیے راتوں رات کوئی وقفہ نہیں ہوتا ہے۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>یہ قوانین انٹرا ڈے اکاؤنٹ کے مرنے کے عام طریقوں کو کم کرتے ہیں۔ وہ منافع کا وعدہ نہیں کرتے، اور ان کی ایمانداری کی حد ہوتی ہے۔</p>\n<p><strong>ایک منصوبہ جس کی آپ اطاعت نہیں کرتے وہ صرف سجاوٹ ہے۔</strong> سب سے مشکل لمحہ وہ ہوتا ہے جب آپ اپنے یومیہ اسٹاپ کو مارنے کے بعد ایک کلک کریں۔ یہاں کا ہر قاعدہ اس وقت ناکام ہو جاتا ہے جب آپ خود کو \"صرف یہ ایک بار\" کہتے ہیں۔ یہ منصوبہ صرف اس صورت میں کام کرتا ہے جب سوئچ آف کرنا غیر گفت و شنید ہو - اور بہت سے ابتدائی لوگ اس پر یقین کرنے سے پہلے ہی مہنگا طریقہ سیکھ لیتے ہیں۔</p>\n<p><strong>اچھے اصول ہارنے والی حکمت عملی کو ٹھیک نہیں کر سکتے۔</strong> پوزیشن کا سائز اور روزانہ اسٹاپ کنٹرول <em>کتنی جلدی</em> آپ ہار جاتے ہیں وہ ایک کنارے نہیں بناتے ہیں. اگر آپ کے اندراجات میں کوئی کنارہ نہیں ہے تو، ایک کامل خطرے کا منصوبہ صرف آپ کو زیادہ آہستہ آہستہ کھو دیتا ہے۔ خطرے کے اصول آپ کو ایک کنارے تلاش کرنے کے لیے کافی دیر تک زندہ رکھتے ہیں - وہ کنارے نہیں ہیں۔</p>\n<p><strong>اخراجات خاموشی سے آپ کو بہرحال شکست دے سکتے ہیں۔</strong> ستمبر 2024 میں شائع ہونے والے SEBI کے مطالعے سے پتا چلا ہے کہ ایکویٹی ڈیریویٹیوز (F&amp;O) میں تقریباً 91% انفرادی تاجروں نے FY2024 میں خالص نقصان کیا، اوسط خسارے میں چلنے والے تاجر کو اس سال تقریباً 1.2 لاکھ روپے کا نقصان ہوا - مدت کے لحاظ سے مخصوص ڈیٹا، مستقل قانون نہیں۔ بار بار تجارت کرنے سے بروکریج، STT اور آپ کے خلاف پھسلن بھی ہوتی ہے۔ یہاں تک کہ ایک نظم و ضبط والا چھوٹا تاجر بھی یہ جان سکتا ہے کہ تجارت کے اخراجات اکثر کم منافع سے زیادہ ہوتے ہیں۔ بعض اوقات سب سے زیادہ منافع بخش خطرے کا اصول یہ ہے کہ بہت کم تجارت کریں، یا انٹرا ڈے بالکل نہ کریں۔</p>\n<p>یہ تعلیم ہے، انٹرا ڈے تجارت کی سفارش نہیں۔ یہ وہ گارڈریل سیٹ ہے جسے آپ چاہیں گے۔ <em>اگر</em> آپ کا انتخاب کریں.</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> انٹرا ڈے رسک پلان پر دو اہم ترین نمبر کیا ہیں؟</summary><p>روزانہ تجارت کی زیادہ سے زیادہ تعداد (اوور ٹریڈنگ کو روکنے کے لیے) اور سخت زیادہ سے زیادہ روزانہ نقصان - مثال کے طور پر مائنس 2% یا دو ہارنے والی تجارت۔ جب روزانہ نقصان ہوتا ہے، تو آپ بغیر کسی استثناء کے دن کے لیے سوئچ آف کر دیتے ہیں۔</p>\n</details><details>\n<summary><strong>2.</strong> منصوبہ بندی میں قوت ارادی کے لیے چھوڑنے کے بجائے انتقام نہ لینے کا اصول کیوں بنایا گیا ہے؟</summary><p>چونکہ ایک نقصان ایک ہی فائدہ سے دوگنا زیادہ تکلیف دیتا ہے، اس لیے اسے واپس جیتنے کی خواہش بالکل اس وقت سخت ہوتی ہے جب فیصلہ بدترین ہو۔ پہلے سے طے شدہ اصول - کسی بھی نقصان کے بعد 15 سے 30 منٹ کا وقفہ اور کوئی سائز نہیں بڑھانا - فیصلے کو جذباتی لمحے سے ہٹا دیتا ہے۔</p>\n</details><details>\n<summary><strong>3.</strong> انٹرا ڈے ٹریڈر کے لیے لیکویڈیٹی فلٹر کیوں اہمیت رکھتا ہے؟</summary><p>ایک مائع، اعلیٰ حجم کے نام میں خرید و فروخت کی قیمتوں کے درمیان فرق بہت کم ہوتا ہے، اس لیے داخل ہونے اور باہر نکلنے کے اخراجات تقریباً کچھ نہیں ہوتے۔ ایک پتلے، غیر مائع اسٹاک میں جو خلا وسیع ہے اور آپ کے اسٹاپ آپ کی سطح سے بہت دور ہوتے ہیں، لہذا پھسلن خاموشی سے تجارت کے بعد تجارت کو کھا جاتی ہے۔</p>\n</details><details>\n<summary><strong>4.</strong> تجارتی دن کے کن حصوں میں سب سے زیادہ خطرہ ہوتا ہے، اور کیا اصول ہے؟</summary><p>کھلنے کے بعد کے پہلے چند منٹ سب سے تیز اور پرتشدد ہوتے ہیں، اور دیر کا سیشن وہ ہوتا ہے جہاں مایوسی کا کاروبار ہوتا ہے۔ اصول یہ ہے کہ پہلے 15 منٹ کو چھوڑ دیں، دوپہر کے اوائل تک نئی تجارتیں کھولنا بند کر دیں، اور بند ہونے سے پہلے ہموار ہو جائیں۔</p>\n</details><details>\n<summary><strong>5.</strong> انٹرا ڈے پلان سوئنگ ٹریڈر کے پلان سے کیسے مختلف ہے؟</summary><p>ایک ہی کنکال، مختلف ڈائلز۔ انٹرا ڈے ٹریڈر قریب سے بالکل فلیٹ ہے، اس لیے دشمن اوور ٹریڈنگ کر رہا ہے اور حقیقی وقت میں بدلہ لے رہا ہے، اس کے لیے ایک سخت تجارتی کیپ، ایک سخت روزانہ اسٹاپ اور ٹائمنگ کے سخت قوانین کی ضرورت ہے۔ سوئنگ ٹریڈر راتوں رات ہولڈ کرتا ہے، لہذا فرق کا خطرہ اہم تشویش ہے اور دن کے وقت کے معاملات بہت کم ہیں۔</p>\n</details>\n","toc":[{"level":2,"text":"انٹرا ڈے لوگوں کو سب سے تیزی سے کیوں توڑ دیتا ہے۔","id":"why-intraday-breaks-people-fastest"},{"level":2,"text":"چھ گارڈریلز، ایک وقت میں ایک","id":"the-six-guardrails-one-at-a-time"},{"level":2,"text":"ایک صفحے کا منصوبہ (اسے کاپی کریں)","id":"the-one-page-plan-copy-this"},{"level":2,"text":"انٹرا ڈے بمقابلہ سوئنگ ٹریڈر کا منصوبہ","id":"intraday-vs-the-swing-trader-s-plan"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"21":{"html":"<p>ارجن کے پاس 2,00,000 روپے تھے اور وہ مستقبل میں تجارت کرنے کا منصوبہ تھا۔ NIFTY کا ایک لاٹ، جس کا انڈیکس 24,000 کے قریب ہے اور ایک لاٹ سائز تقریباً 65 ہے (ایکسچینج کے ذریعہ وقتاً فوقتاً لاٹ سائزز پر نظر ثانی کی جاتی ہے - ہمیشہ موجودہ کنٹریکٹ کی تفصیلات چیک کریں)، انڈیکس کے تقریباً 15,60,000 روپے کو کنٹرول کرتا ہے - اس لیے اسے راتوں رات رکھنے کے لیے بروکر کا مارجن تقریباً 1,008 روپے تھا۔ ارجن نے وہ ایک لاٹ لگایا۔ یہ اچھا لگا: وہ \"صرف\" ایک لاٹ استعمال کر رہا تھا، اور اس کے پاس اب بھی 20,000 روپے باقی تھے۔ اس رات ایک عالمی سرخی نے اگلے کھلنے سے پہلے NIFTY کو تقریباً 350 پوائنٹس نیچے دھکیل دیا۔ اس کا نقصان 350 گنا 65، یا 22,750 روپے تھا – جو 20,000 روپے تکیہ اس نے چھوڑا تھا۔ اگلی صبح اس کے اکاؤنٹ میں مارجن کی کمی ظاہر ہوئی، اور پوزیشن کو کھلے کے قریب مربع کر دیا گیا، اس اقدام کی تقریباً بدترین قیمت پر نقصان کو بند کر دیا۔ وہ سائز میں لاپرواہ نہیں تھا۔ اس نے محض کوئی فالتو نقد رقم نہیں رکھی تھی، اس لیے راتوں رات ایک عام ہلچل ایک زبردستی باہر نکلنا بن گئی۔</p>\n<p>یہ باب فیوچر ٹریڈر کی پوری خطرے کی دنیا کو ایک صفحہ میں بدل دیتا ہے جسے آپ حقیقت میں استعمال کر سکتے ہیں۔ فیوچر لکیری اور لیوریجڈ ہوتے ہیں - وہ ہر اقدام کو دونوں طرح سے بڑھاتے ہیں - لہذا منصوبہ زیادہ تر اس بارے میں ہے کہ آپ کے خیال کو کام کرنے کا موقع ملنے سے پہلے مجبور نہ کیا جائے۔</p>\n<h2 id=\"why-futures-need-their-own-plan\">مستقبل کو اپنے منصوبے کی ضرورت کیوں ہے۔</h2>\n<p>جو اسٹاک آپ اپنی نقدی سے خریدتے ہیں وہ گر سکتا ہے اور پھر بھی آپ اس کے مالک ہیں۔ آپ انتخاب کرتے ہیں کہ کب فروخت کرنا ہے۔ مستقبل کی پوزیشن دو طریقوں سے مختلف ہوتی ہے۔ سب سے پہلے، اس کا فائدہ اٹھایا جاتا ہے: آپ معاہدے کی قیمت کا ایک حصہ مارجن کے طور پر ڈالتے ہیں، اس لیے انڈیکس میں ایک چھوٹا فیصد منتقل ہونا آپ کے اکاؤنٹ میں ایک بڑا فیصد منتقل ہوتا ہے۔ رسک مینجمنٹ کورس کے لیوریج باب نے اس میگنفائنگ گلاس کو تفصیل سے دکھایا - یہ دونوں طریقوں سے کاٹتا ہے، اور ہارنے والی طرف یہ آپ کی توقع سے زیادہ تیز ہو سکتا ہے۔ دوسرا، فیوچرز کو ہر روز مارکیٹ میں نشان زد کیا جاتا ہے۔ ہر شام آپ کے فائدے اور نقصانات کو آپ کے اکاؤنٹ میں نقد رقم میں طے کیا جاتا ہے۔ برا دن کوئی کاغذی نمبر نہیں ہے جسے آپ نظر انداز کر سکتے ہیں - یہ اصل رقم چھوڑنا ہے، اور اگر آپ کا اکاؤنٹ مطلوبہ مارجن سے کم ہو جاتا ہے، تو آپ کا بروکر آپ کو اسکوائر کر سکتا ہے چاہے آپ اسے پسند کریں یا نہ کریں۔</p>\n<p>لہذا مستقبل کے تاجر کا دشمن شاذ و نادر ہی \"غلط\" ہوتا ہے۔ انتظار سے بچنے کے لیے نقد رقم کے بغیر یہ بہت جلد ہو رہا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 250\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"NIFTY فیوچرز کا ایک لاٹ تقریباً ساڑھے پندرہ لاکھ روپے کی نمائش کو کنٹرول کرتا ہے جب کہ دو لاکھ مارجن سے کم کی ضرورت ہوتی ہے، یہ دکھاتا ہے کہ کس طرح لیوریج چھوٹے انڈیکس کو بڑے اکاؤنٹ میں منتقل کرتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"250\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ایک لاٹ پہلے ہی بہت کچھ کنٹرول کرتا ہے۔</text>\n  <rect x=\"50\" y=\"60\" width=\"330\" height=\"150\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <text x=\"215\" y=\"88\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">تصوراتی آپ کنٹرول کرتے ہیں</text>\n  <text x=\"215\" y=\"128\" text-anchor=\"middle\" fill=\"#4c72b0\" font-size=\"26\" font-weight=\"700\" font-family=\"sans-serif\">15,60,000 روپے</text>\n  <text x=\"215\" y=\"158\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">24,000 x 65 (ایک لاٹ)</text>\n  <text x=\"215\" y=\"186\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">ایک فیصد انڈیکس حرکت = 15,600 روپے</text>\n  <rect x=\"430\" y=\"60\" width=\"280\" height=\"150\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <text x=\"570\" y=\"88\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">مارجن آپ نے لگایا</text>\n  <text x=\"570\" y=\"128\" text-anchor=\"middle\" fill=\"#dd8452\" font-size=\"26\" font-weight=\"700\" font-family=\"sans-serif\">~ 1,80,000 روپے</text>\n  <text x=\"570\" y=\"158\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">تصور کا تقریباً 11.5 فیصد</text>\n  <text x=\"570\" y=\"186\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">تو تقریباً 9x لیوریج</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ایک لاٹ پہلے سے ہی ایک بڑی شرط ہے۔ لیوریج کا مطلب ہے کہ انڈیکس میں ایک چھوٹی سی حرکت آپ کے کیش میں ایک بڑا اقدام ہے۔</figcaption>\n</figure>\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>مستقبل میں، بقا کا انحصار صحیح ہونے پر کم اور زبردستی نہ کیے جانے پر زیادہ ہے۔ اپنے لیوریج کو بروکر کی اجازت سے نیچے رکھیں، اور ہمیشہ فالتو کیش رکھیں تاکہ ایک عام روزانہ مارک ٹو مارکٹ نقصان کا اسکوائر آف پر مجبور ہونے کا امکان بہت کم ہو۔</p>\n</div></div>\n<h2 id=\"the-mtm-buffer-keep-fuel-in-the-tank\">MTM بفر: ٹینک میں ایندھن رکھیں</h2>\n<p>یہاں ایک ہی عادت ہے جس نے ارجن کو بچایا ہوگا۔ کبھی بھی اپنے تمام سرمائے کو مارجن کے طور پر متعین نہ کریں۔ آپ جو نقد رقم واپس رکھتے ہیں وہ آپ کا ہے۔ <strong>مارک ٹو مارکیٹ بفر</strong> - وہ ایندھن جو آپ کو مارجن کی خلاف ورزی کیے بغیر اور بدترین ٹک پر چوکے ہوئے ایک برے دن کو جذب کرنے دیتا ہے۔</p>\n<p>اپنے اکاؤنٹ کو فیول ٹینک سمجھیں۔ آپ کی پوزیشن کو جس مارجن کی ضرورت ہے وہ ایندھن ہے جو پہلے سے جل رہا ہے۔ بفر لائن کے نیچے ریزرو ہے۔ اگر آپ مارجن کے ساتھ ٹینک کو کنارے پر بھرتے ہیں، تو پہلا ہیڈ ونڈ اسے خالی کر دیتا ہے اور انجن ختم ہو جاتا ہے۔ ایک ریزرو رکھیں - ایک موٹا اصول یہ ہے کہ آپ اپنے نصف سے زیادہ سرمائے کو مارجن کے طور پر استعمال نہ کریں اور باقی آدھے کو بفر کے طور پر چھوڑ دیں - اور آپ روزانہ کے جھولوں پر سوار ہو سکتے ہیں جو دھوئیں پر چلنے والے ہر شخص کو ہلا کر رکھ دیتے ہیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 260\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ساتھ ساتھ دو اکاؤنٹ ٹینک۔ پہلا تقریباً مکمل طور پر مارجن سے بھرا ہوا ہے اور اس میں کوئی ریزرو نہیں ہے، اس لیے یومیہ نقصان اسے کم سے کم سے نیچے کر دیتا ہے اور اسکوائر آف پر مجبور کرتا ہے۔ دوسرا مارجن کے طور پر صرف نصف کا استعمال کرتا ہے اور ریزرو بفر رکھتا ہے، لہذا وہی روزانہ نقصان محفوظ طریقے سے کم از کم سے اوپر رہتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"260\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ایک ہی اکاؤنٹ، وہی برا دن - ایک زندہ رہتا ہے۔</text>\n  <rect x=\"120\" y=\"55\" width=\"160\" height=\"170\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <rect x=\"120\" y=\"70\" width=\"160\" height=\"140\" rx=\"0\" fill=\"#c44e52\" fill-opacity=\"0.35\"/>\n  <text x=\"200\" y=\"145\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">مارجن استعمال کیا</text>\n  <text x=\"200\" y=\"163\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">~ تمام سرمایہ</text>\n  <line x1=\"110\" y1=\"190\" x2=\"290\" y2=\"190\" stroke=\"#c44e52\" stroke-width=\"2\" stroke-dasharray=\"5 4\"/>\n  <text x=\"200\" y=\"245\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"11\" font-weight=\"700\" font-family=\"sans-serif\">کوئی بفر نہیں: روزانہ نقصان = مربع بند</text>\n  <rect x=\"480\" y=\"55\" width=\"160\" height=\"170\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <rect x=\"480\" y=\"140\" width=\"160\" height=\"70\" rx=\"0\" fill=\"#4c72b0\" fill-opacity=\"0.40\"/>\n  <rect x=\"480\" y=\"70\" width=\"160\" height=\"70\" rx=\"0\" fill=\"#55a868\" fill-opacity=\"0.30\"/>\n  <text x=\"560\" y=\"108\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">بفر (ریزرو)</text>\n  <text x=\"560\" y=\"180\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">مارجن استعمال کیا</text>\n  <line x1=\"470\" y1=\"140\" x2=\"650\" y2=\"140\" stroke=\"#55a868\" stroke-width=\"2\" stroke-dasharray=\"5 4\"/>\n  <text x=\"560\" y=\"245\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"11\" font-weight=\"700\" font-family=\"sans-serif\">بفر نقصان کو جذب کرتا ہے: آپ اندر رہتے ہیں۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">لائن کے نیچے ریزرو وہ ہے جو روزانہ مارک ٹو مارکیٹ نقصان کو جبری اخراج بننے سے روکتا ہے۔</figcaption>\n</figure><h2 id=\"overnight-rollover-margin-stress-and-events\">راتوں رات، رول اوور، مارجن تناؤ اور واقعات</h2>\n<p>اس منصوبے کے لیے چار مزید اصول ہیں۔ ہر ایک ایسی قوت کے بارے میں ہے جو مستقبل کو اسٹاک سے زیادہ سختی سے ٹکراتا ہے۔</p>\n<p><strong>راتوں رات خطرہ۔</strong> جب مارکیٹ کھلی ہو تو اسٹاپ لاس آپ کی حفاظت کرتا ہے۔ سیشنوں کے درمیان، قیمت اس سے سیدھے آگے بڑھ سکتی ہے۔ اس لیے جو کچھ بھی آپ رات بھر لے جاتے ہیں اس کا سائز چھوٹا ہو - یا کسی معروف پرخطر رات میں کچھ بھی نہ لے جائیں۔ نقصان جو سب سے اہم ہے وہ وہ اقدام ہے جس کے ذریعے آپ تجارت نہیں کرسکتے ہیں۔</p>\n<p><strong>رول اوور ڈسپلن۔</strong> مستقبل کا معاہدہ ختم ہو رہا ہے۔ میعاد ختم ہونے کے بعد کسی پوزیشن کو برقرار رکھنے کے لیے آپ کو اسے \"رول\" کرنا ہوگا - ختم ہونے والا معاہدہ بند کریں اور اگلے مہینے کھولیں۔ یہ کام ختم ہونے سے چند دن پہلے کریں، نہ کہ ایکسپائری ڈے پر۔ ایکسپائری ڈے پر، لیکویڈیٹی کم ہوتی ہے، پھیل جاتی ہے، اور آپ کو جو بھی قیمت مل سکتی ہے اس پر تجارت کرنے پر مجبور کیا جاتا ہے۔ جلد رولنگ پرسکون ہے؛ آخری دن رولنگ ایک جھگڑا ہے.</p>\n<p><strong>مارجن تناؤ۔</strong> پوزیشن کے لیے مطلوبہ مارجن مقرر نہیں ہے۔ جب اتار چڑھاؤ بڑھتا ہے، ایکسچینج مارجن بڑھاتے ہیں - کبھی تیزی سے، کبھی اسی ہفتے مارکیٹ گرتی ہے۔ ایک ایسی پوزیشن جس کو ایک پرسکون دن میں 1,80,000 روپے کی ضرورت تھی اچانک کہیں زیادہ کا مطالبہ کر سکتی ہے۔ اگر آپ حد کے قریب تھے، تو یہ اضافہ ہی آپ کو کاٹنے پر مجبور کر سکتا ہے۔ آپ کا بفر وہ ہے جو مارجن میں اضافے کو جذب کرتا ہے، نہ کہ صرف قیمت میں کمی۔</p>\n<p><strong>واقعہ سے بچنا۔</strong> بجٹ، مرکزی بینک کی شرح کا فیصلہ، ایک اہم انتخابی نتیجہ، ایک بڑی کمپنی یا عالمی سرخی - یہ ایسی معلوم تاریخیں ہیں جو ایسے خلا پیدا کر سکتی ہیں جو کوئی روک نہیں سکتا۔ فلیٹ یا ہیجڈ میں جائیں۔ سکوں کے فلپ میں پورے سائز کو رکھنے کے لیے کوئی انعام نہیں ہے۔ واقعہ میں فلیٹ ایک پوزیشن بھی ہے: نہ ہارنے کی پوزیشن۔</p>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>کلاسک فیوچر بلو اپ ایک ہی وقت میں تین غلطیوں کا ڈھیر لگاتا ہے: بروکر کی جانب سے زیادہ سے زیادہ لیوریج کا استعمال کرتے ہوئے، کوئی مارک ٹو مارکیٹ بفر نہ رکھنا، اور اس پورے سائز کی پوزیشن کو راتوں رات ایک معروف ایونٹ میں رکھنا۔ ہر ایک اکیلے زندہ ہے؛ وہ ایک ساتھ مل کر تاریخ کے انتظار میں ایک زبردستی مربع ہیں۔ حل ان تینوں کے الٹ ہے - معمولی فائدہ اٹھانا، ایک چربی کیش بفر، اور واقعات میں کم یا صفر سائز۔</p>\n</div></div>\n<h2 id=\"your-one-page-futures-risk-plan\">آپ کا ایک صفحہ مستقبل کے خطرے کا منصوبہ</h2>\n<p>کسی بھی مستقبل کی پوزیشن پر آنے سے پہلے اسے چلائیں۔ نمبرز 2,00,000 روپے کے اکاؤنٹ کے لیے مثالی اقدار ہیں - انہیں اپنے حساب سے پیمانہ کریں۔ یہ تعلیم ہے، ذاتی مشورے نہیں۔</p>\n<ol>\n<li><strong>لیوریج ٹوپی۔</strong> مارجن کے طور پر اپنے تقریباً نصف سے زیادہ سرمائے کا استعمال نہ کریں۔ 2,00,000 روپے پر، اس کا مطلب ہے تقریباً 1,00,000 روپے کا مارجن – جس کا اکثر مطلب یہ ہے کہ چھوٹے تصوراتی معاہدے کی تجارت کرنا یا محض دوسری لاٹ نہ لینا، چاہے بروکر آپ کو اجازت دے دے۔</li>\n<li><strong>MTM بفر۔</strong> کم از کم اپنے سرمائے کو فالتو نقدی کے طور پر رکھیں - یہاں، تقریباً 1,00,000 روپے - اچھوت، خالصتاً روزانہ کے نقصانات اور مارجن میں اضافے کو جذب کرنے کے لیے۔</li>\n<li><strong>فی تجارت خطرہ۔</strong> داخلے سے پہلے اپنے روپے کے نقصان کا فیصلہ کریں اور وہیں اسٹاپ لگائیں۔ اسے سرمائے کے تقریباً 1-2% تک رکھیں - تقریباً 2,000 سے 4,000 روپے - جو کہ NIFTY پر صرف دسیوں پوائنٹس ہیں، اس لیے یہ آپ کی پوزیشن کو ایمانداری سے درست کرتا ہے۔</li>\n<li><strong>راتوں رات حکمرانی۔</strong> راتوں رات چھوٹے سائز لے جائیں، اور کسی معروف واقعہ سے پہلے رات بھر کچھ بھی نہ لے جائیں۔</li>\n<li><strong>رول اوور اصول۔</strong> میعاد ختم ہونے سے دو سے تین دن پہلے اگلے معاہدے پر جائیں، میعاد ختم ہونے کے دن کبھی نہیں۔</li>\n<li><strong>واقعہ کا اصول۔</strong> بجٹ، شرح کے فیصلوں، انتخابی نتائج اور اہم شیڈول خبروں میں فلیٹ یا ہیجڈ رہیں۔</li>\n<li><strong>روزانہ سٹاپ.</strong> اگر آپ ایک دن میں ایک مقررہ رقم کھو دیتے ہیں - کہیے کہ سرمایہ کا 4%، تقریباً 8,000 روپے - آپ کا دن پورا ہو گیا ہے۔ کوئی انتقامی تجارت نہیں۔</li>\n</ol>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 320\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک صفحے کا فیوچر رسک پلان کارڈ جس میں سات اصول درج ہیں: مارجن کے طور پر آدھے سرمائے کا لیوریج کیپ، دوسرے نصف کا مارک ٹو مارکیٹ بفر، ایک سے دو فیصد فی ٹریڈ رسک، راتوں رات چھوٹا سائز، میعاد ختم ہونے سے پہلے رول، ایونٹس میں فلیٹ ہونا، اور روزانہ چار فیصد پر سٹاپ۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"320\" rx=\"12\" fill=\"#0d1117\"/>\n  <rect x=\"30\" y=\"20\" width=\"700\" height=\"280\" rx=\"12\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <text x=\"380\" y=\"52\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"17\" font-family=\"sans-serif\">فیوچر ٹریڈر - ایک صفحے کا رسک پلان</text>\n  <line x1=\"55\" y1=\"66\" x2=\"705\" y2=\"66\" stroke=\"#30363d\"/>\n  <text x=\"60\" y=\"98\" fill=\"#55a868\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">1. لیوریج ٹوپی</text>\n  <text x=\"250\" y=\"98\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">سرمایہ کے نصف سے کم مارجن</text>\n  <text x=\"60\" y=\"128\" fill=\"#4c72b0\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">2. MTM بفر</text>\n  <text x=\"250\" y=\"128\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">باقی نصف اسپیئر نقد کے طور پر رکھیں</text>\n  <text x=\"60\" y=\"158\" fill=\"#55a868\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">3. فی تجارت خطرہ</text>\n  <text x=\"250\" y=\"158\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">سرمایہ کا 1-2%، داخلے سے پہلے سٹاپ سیٹ</text>\n  <text x=\"60\" y=\"188\" fill=\"#dd8452\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">4. راتوں رات</text>\n  <text x=\"250\" y=\"188\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">چھوٹے سائز؛ واقعات سے پہلے فلیٹ</text>\n  <text x=\"60\" y=\"218\" fill=\"#dd8452\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">5. رول اوور</text>\n  <text x=\"250\" y=\"218\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">2-3 دن پہلے رول کریں، کبھی ختم ہونے والے دن پر نہیں۔</text>\n  <text x=\"60\" y=\"248\" fill=\"#c44e52\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">6. واقعات</text>\n  <text x=\"250\" y=\"248\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">فلیٹ یا معلوم خبروں میں ہیجڈ</text>\n  <text x=\"60\" y=\"278\" fill=\"#c44e52\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">7. روزانہ سٹاپ</text>\n  <text x=\"250\" y=\"278\" fill=\"#cdd9e5\" font-size=\"12\" font-family=\"sans-serif\">ایک دن میں ~ 4% کمی = روکیں، کوئی بدلہ نہیں۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">اس کا اسکرین شاٹ۔ اسے ہر پوزیشن سے پہلے پڑھیں۔ نمبر مثالیں ہیں - انہیں اپنے کیپیٹل میں پیمانہ کریں۔</figcaption>\n</figure><h2 id=\"how-this-differs-from-the-stock-trader-s-plan\">یہ اسٹاک ٹریڈر کے پلان سے کیسے مختلف ہے۔</h2>\n<p>اسٹاک ٹریڈر کا پلان اور فیوچر پلان ایک ریڑھ کی ہڈی کا اشتراک کرتے ہیں - فی تجارت خطرہ، ایک سٹاپ، روزانہ نقصان کی حد، ایک جریدہ۔ دو چیزیں مستقبل کو سخت بناتی ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>اسٹاک تاجر</th>\n<th>فیوچر تاجر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>فائدہ اٹھانا</td>\n<td>عام طور پر کوئی نہیں (اپنی نقدی)</td>\n<td>بلٹ ان - ایک چھوٹا سا اقدام بڑھا ہوا ہے۔</td>\n</tr>\n<tr>\n<td>روزانہ تصفیہ</td>\n<td>نہیں - نقصان کاغذ پر ہے جب تک آپ فروخت نہ کریں۔</td>\n<td>ہاں - روزانہ کیش میں مارکیٹ کے لیے نشان زد</td>\n</tr>\n<tr>\n<td>زبردستی باہر نکلنا</td>\n<td>نایاب</td>\n<td>مارجن کا شارٹ فال آپ کو دور کر سکتا ہے۔</td>\n</tr>\n<tr>\n<td>اضافی قواعد کی ضرورت ہے۔</td>\n<td>سائز کرنا، روکنا، روزانہ کی حد</td>\n<td>یہ سب کچھ، نیز لیوریج کیپ، ایک MTM بفر، رول اوور اور مارجن سٹریس پلاننگ</td>\n</tr>\n</tbody></table>\n<p>اسٹاک ٹریڈر تھوڑی دیر کے لیے غلط ہو سکتا ہے اور بس انتظار کر سکتا ہے۔ ایک فیوچر تاجر جو بغیر کسی بفر کے غلط ہے اسے تجارت سے ہٹا دیا جاتا ہے۔ یہی وجہ ہے کہ فیوچر پلان میں کیش ریزرو اور لیوریج کیپ کو سب سے اوپر شامل کیا جاتا ہے جو اسٹاک ٹریڈر پہلے سے کرتا ہے۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>یہ منصوبہ ان طریقوں کو کم کرتا ہے جو مستقبل آپ کو برباد کر سکتے ہیں۔ یہ انہیں دور نہیں کرتا۔</p>\n<p><strong>ایک فرق آپ کے بفر سے تجاوز کر سکتا ہے۔</strong> واقعی راتوں رات ایک پرتشدد اقدام - ایک جنگ کی سرخی، ایک صدمے کا نتیجہ - یہاں تک کہ صحت مند ریزرو کو بھی اڑا سکتا ہے۔ بفر ہر بلیک سوان ڈے پر نہیں بلکہ عام برے دنوں میں بقا خریدتا ہے۔ یہی وجہ ہے کہ ایونٹ کا اصول یہ کہتا ہے کہ فلیٹ ہو، نہ صرف اچھی طرح سے بفر ہو۔</p>\n<p><strong>نظم و ضبط کمزور کڑی ہے، قوانین نہیں۔</strong> منصوبہ لکھنا آسان ہے اور 3:15 بجے اس پر عمل کرنا مشکل ہے جب آپ نیچے ہوتے ہیں اور اسے واپس چاہتے ہیں۔ آپ جس منصوبہ کو اوور رائیڈ کرتے ہیں وہ منصوبہ نہیں ہے۔ اس باب میں سب سے مشکل لائن روزانہ کا سٹاپ ہے، کیونکہ یہ اسکرین کے کھلے رہنے کے دوران آپ سے دور جانے کو کہتی ہے۔</p>\n<p><strong>مارجن میں اضافہ آپ کے ردعمل سے زیادہ تیزی سے پہنچ سکتا ہے۔</strong> اتار چڑھاؤ سے چلنے والے مارجن میں اضافہ سیشنوں کے درمیان ہو سکتا ہے، اس لیے آپ پہلے ہی مارجن کی کمی سے بیدار ہو جاتے ہیں۔ لیوریج کیپ کے نیچے اچھی طرح سے چلنا ہی واحد حقیقی دفاع ہے - ایسی کوئی چالاک تجارت نہیں ہے جو حد سے زیادہ لیوریج کو والیوم اسپائک میں ٹھیک کرتی ہے۔</p>\n<p>اس میں سے کوئی بھی مستقبل کی تجارت یا کسی خاص سائز کو استعمال کرنے کا مشورہ نہیں ہے۔ یہ ایک نقشہ ہے جہاں فیوچر ٹریڈرز کو زبردستی باہر نکالا جاتا ہے، لہذا آپ ایک ایسا منصوبہ بنا سکتے ہیں جو آپ کو برقرار رکھے۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> فیوچر ٹریڈر کو مارک ٹو مارکیٹ بفر کی ضرورت کیوں ہے جو کیش اسٹاک خریدار کو نہیں ہے؟</summary><p>فیوچرز ہر روز نقد رقم میں طے کیے جاتے ہیں اور مارجن کی ضرورت ہوتی ہے۔ اگر روزانہ کا نقصان آپ کے اکاؤنٹ کو مطلوبہ مارجن سے نیچے دھکیلتا ہے، تو بروکر آپ کو اسکوائر کر سکتا ہے۔ فالتو کیش کا ایک بفر ان روزمرہ کے نقصانات کو جذب کر لیتا ہے لہذا ایک عام جھول آپ کو باہر نہیں نکال سکتا۔ ایک نقد اسٹاک خریدار مکمل طور پر شیئر کا مالک ہوتا ہے اور صرف انتظار کر سکتا ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> ایک NIFTY 24,000 کے قریب لاٹ تقریباً کتنا کنٹرول کرتا ہے، اور اس سے فرق کیوں پڑتا ہے؟</summary><p>تصوراتی نمائش کے تقریباً 15,60,000 روپے (65 کے قریب 24,000 گنا)، تقریباً 1,80,000 روپے کے مارجن پر رکھے گئے ہیں۔ اس سے فرق پڑتا ہے کیونکہ ایک لاٹ پہلے سے ہی ایک بڑی، لیوریجڈ شرط ہے - 1% انڈیکس کی منتقلی آپ کے اکاؤنٹ میں تقریباً 15,600 روپے ہے - لہذا \"صرف ایک لاٹ\" خود بخود چھوٹا نہیں ہے۔</p>\n</details><details>\n<summary><strong>3.</strong> ایکسپائری ڈے کے بجائے فیوچر پوزیشن کو جلد کیوں رول کریں؟</summary><p>ایکسپائری ڈے پر لیکویڈیٹی پتلی اور پھیل جاتی ہے، اس لیے آپ کو کم قیمت پر تجارت کرنے پر مجبور کیا جاتا ہے۔ دو یا تین دن پہلے رولنگ آپ کو میعاد ختم ہونے والا معاہدہ بند کرنے اور مناسب قیمتوں پر اگلے مہینے پرسکون طریقے سے کھولنے دیتا ہے۔</p>\n</details><details>\n<summary><strong>4.</strong> فیوچر بلو اپ میں عام طور پر کون سی تین غلطیاں ایک ساتھ ہوتی ہیں؟</summary><p>زیادہ سے زیادہ فائدہ اٹھاتے ہوئے بروکر اجازت دیتا ہے، کوئی مارک ٹو مارکیٹ بفر نہ رکھتے ہوئے، اور پورے سائز کو کسی معروف ایونٹ میں راتوں رات روکے رکھنا۔ ہر ایک اکیلے زندہ ہے؛ انہوں نے مل کر ایک بری تاریخ پر زبردستی اسکوائر آف قائم کیا۔</p>\n</details><details>\n<summary><strong>5.</strong> کیوں بڑھتا ہوا اتار چڑھاؤ آپ کو پوزیشن کم کرنے پر مجبور کر سکتا ہے یہاں تک کہ اگر قیمت آپ کے اسٹاپ پر نہیں آئی ہے؟</summary><p>کیونکہ تبادلے مارجن کی ضروریات کو بڑھاتے ہیں جب اتار چڑھاؤ بڑھتا ہے، اکثر تیزی سے اور بدترین لمحے پر۔ اگر آپ اپنی مارجن کی حد کے قریب تھے، تو صرف زیادہ ضرورت ہی کمی پیدا کر سکتی ہے اور آپ کو کم کرنے پر مجبور کر سکتی ہے - یہی وجہ ہے کہ بفر کو مارجن میں اضافے کو پورا کرنا چاہیے، نہ کہ صرف قیمتوں میں ہونے والے نقصانات۔</p>\n</details>\n","toc":[{"level":2,"text":"مستقبل کو اپنے منصوبے کی ضرورت کیوں ہے۔","id":"why-futures-need-their-own-plan"},{"level":2,"text":"MTM بفر: ٹینک میں ایندھن رکھیں","id":"the-mtm-buffer-keep-fuel-in-the-tank"},{"level":2,"text":"راتوں رات، رول اوور، مارجن تناؤ اور واقعات","id":"overnight-rollover-margin-stress-and-events"},{"level":2,"text":"آپ کا ایک صفحہ مستقبل کے خطرے کا منصوبہ","id":"your-one-page-futures-risk-plan"},{"level":2,"text":"یہ اسٹاک ٹریڈر کے پلان سے کیسے مختلف ہے۔","id":"how-this-differs-from-the-stock-trader-s-plan"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"22":{"html":"<p>وکرم نے سوچا کہ اختیارات خریدنا F&amp;O میں محفوظ طریقہ ہے۔ ہر جمعرات کو اس نے ایک سستی، دور دراز کی کال خریدی - 5 روپے، 7 روپے، کبھی کبھی 4 روپے - اور خود کو بتایا کہ نقصان بہت کم ہے۔ \"یہ صرف 325 روپے بہت ہے۔ اگر یہ چلتا ہے تو یہ ایک دس بیگ ہے۔\" زیادہ تر ہفتے اس کی میعاد بے کار ہو گئی۔ کچھ بار یہ پاپ ہوا اور وہ ایک باصلاحیت کی طرح محسوس ہوا۔ لیکن چار مہینوں کے بعد وہ بیٹھ گیا اور اسے شامل کیا: بہت سے چھوٹے نقصانات، ایک دو اچھی جیت، اور ایک اکاؤنٹ جو شروع ہوا اس سے ایک تہائی چھوٹا تھا۔ اس نے کبھی بھی ایک تجارت میں دھماکہ نہیں کیا تھا۔ اس کا خون بہہ چکا تھا، ایک وقت میں ایک سستا ٹکٹ۔ یہ باب اس غلطی کو ایک منصوبہ میں بدل دیتا ہے۔</p>\n<p>اختیارات خریدنا F&amp;O کا سب سے ابتدائی دوستانہ گوشہ ہے، کیونکہ آپ کا نقصان آپ کے ادا کردہ پریمیم پر ہوتا ہے۔ وہ حقیقی ہے۔ لیکن \"کیپڈ\" دو بدصورت سچائیوں کو چھپاتا ہے: ایک خریدا ہوا اختیار عام طور پر کھو جاتا ہے، اور ٹوپی ہے <em>پوری</em> پریمیم صفر پر جا رہا ہے۔ رسک مینجمنٹ کورس میں اس بات کا احاطہ کیا گیا ہے کہ کیوں - ٹائم ڈیکی (تھیٹا)، برا ٹائمنگ، اور IV خریدار کے خلاف سب کو کچل دیتے ہیں۔ یہ باب پلے بک ہے جو تینوں زندہ ہے۔</p>\n<h2 id=\"the-buyer-s-deal-in-one-line\">خریدار کا سودا، ایک لائن میں</h2>\n<p>جب آپ کال یا پوٹ خریدتے ہیں، تو آپ سامنے ایک پریمیم ادا کرتے ہیں اور وہ پریمیم سب سے زیادہ ہے جسے آپ کھو سکتے ہیں۔ کوئی مارجن کال نہیں، کوئی اضافی واجب الادا نہیں۔ ٹریڈ آف: وقت، اتار چڑھاؤ، اور جیت کی کم شرح سب آپ کے خلاف کام کر رہے ہیں۔ لہذا ایک خریدار کے لیے خطرہ کا پورا منصوبہ ایک چیز کے بارے میں ہے - اس بات کو یقینی بنانا کہ جب پریمیم صفر پر چلا جائے، اور یہ اکثر ہوتا ہے، نقصان چھوٹا، منصوبہ بند اور زندہ رہنے کے قابل تھا۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>خریدا ہوا آپشن صفر پر جا سکتا ہے، اور اکثر ایسا ہوتا ہے۔ اس لیے صرف پیسے کا خطرہ مول لیں جس سے آپ مکمل طور پر ٹھیک ہیں، تجارت کو کام کرنے کے لیے کافی وقت دیں، اور باہر نکلنے کا فیصلہ کریں۔ <em>پہلے</em> آپ خرید پر کلک کریں۔ خریدار کا کام ہر بار جیتنا نہیں ہے - یہ ہر نقصان کو اتنا چھوٹا رکھنا ہے کہ ایک خراب سلسلہ آپ کو ختم نہ کر سکے۔</p>\n</div></div>\n<h2 id=\"rule-1-a-premium-budget-you-can-lose-entirely\">قاعدہ 1: ایک پریمیم بجٹ جس سے آپ مکمل طور پر کھو سکتے ہیں۔</h2>\n<p>آپشن پریمیم کا علاج کریں جیسے نقد آپ نے ادائیگی کے موقع پر آگ لگا دی۔ ہر تجارت کے لیے صرف ایک چھوٹا، مقررہ ٹکڑا کا خطرہ - تقریباً <strong>آپ کے اکاؤنٹ کا 1-2%</strong> - اور کبھی نہیں.</p>\n<p>کہو کہ آپ کے پاس 2,00,000 روپے ہیں۔ ایک فیصد 2,000 روپے ہے۔ دو فیصد 4000 روپے ہے۔ یہ ایک واحد آپشن خریدنے پر آپ کی حد ہے۔ ایک NIFTY لاٹ لگ بھگ 65 یونٹس ہے (ایکسچینج کے ذریعہ وقتا فوقتا لاٹ سائزز پر نظرثانی کی جاتی ہے - ہمیشہ موجودہ معاہدے کی تفصیلات کو چیک کریں)، لہذا 50 روپے فی یونٹ کے پریمیم کی قیمت 3,250 روپے ہے - جو کہ 2% کے اندر فٹ بیٹھتا ہے۔ 120 روپے فی یونٹ کے پریمیم کی قیمت 7,800 روپے ہے، جو آپ کے اکاؤنٹ کا 3.9 فیصد ہے۔ بہت بڑا۔ آپ یا تو اسے چھوڑ دیں، سستی اندراج کا انتظار کریں، یا قبول کریں کہ یہ معاہدہ ابھی تک آپ کے سائز کے اکاؤنٹ کے لیے نہیں ہے۔</p>\n<p>سیٹ a <strong>ماہانہ پریمیم بجٹ</strong> بھی - کل جو آپ پورے مہینے میں آپشن خریدنے پر خرچ کرنے کے لیے تیار ہیں، کہیے کہ 5% سرمایہ (10,000 روپے یہاں)۔ جب مہینے کا بجٹ ختم ہو جاتا ہے، تو آپ اگلے مہینے تک خریداری کر لیتے ہیں۔ یہ واحد ٹوپی وہی ہے جس نے وکرم کو بچایا ہوگا: یہ تیس بار دہرائے جانے والے \"یہ صرف 325 روپے ہے\" کا آہستہ خون روکتا ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 270\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"دو لاکھ روپے کا سرمایہ بار۔ ایک سے دو فیصد کا ایک پتلا ٹکڑا اس طرح نمایاں کیا جاتا ہے کہ آپ کو ایک آپشن خریدنے پر سب سے زیادہ خطرہ ہوتا ہے، اور پانچ فیصد کا ایک چھوٹا ماہانہ بجٹ بلاک اس کے ساتھ بیٹھتا ہے۔ ایک تیر دکھاتا ہے کہ خطرے میں پڑنے والا ٹکڑا صفر تک گر سکتا ہے۔\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"270\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"15\">پریمیم بجٹ: ایک چھوٹی، مقررہ ٹکڑا کا خطرہ مول لیں جسے آپ مکمل طور پر کھو سکتے ہیں۔</text>\n  <rect x=\"60\" y=\"70\" width=\"540\" height=\"60\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\" stroke-width=\"2\"/>\n  <text x=\"330\" y=\"106\" text-anchor=\"middle\" fill=\"#9db4d8\" font-size=\"13\" font-weight=\"700\">کل سرمایہ - 2,00,000 روپے</text>\n  <rect x=\"60\" y=\"160\" width=\"60\" height=\"60\" rx=\"8\" fill=\"#c44e52\" fill-opacity=\"0.55\" stroke=\"#c44e52\" stroke-width=\"1.5\"/>\n  <text x=\"90\" y=\"246\" text-anchor=\"middle\" fill=\"#f3c9c9\" font-size=\"11\" font-weight=\"700\">1-2% فی تجارت</text>\n  <text x=\"90\" y=\"262\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\">2,000-4,000 روپے</text>\n  <rect x=\"135\" y=\"160\" width=\"120\" height=\"60\" rx=\"8\" fill=\"#dd8452\" fill-opacity=\"0.45\" stroke=\"#dd8452\" stroke-width=\"1.5\"/>\n  <text x=\"195\" y=\"246\" text-anchor=\"middle\" fill=\"#f1cdaf\" font-size=\"11\" font-weight=\"700\">~5% ماہانہ کیپ</text>\n  <text x=\"195\" y=\"262\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10\">کل 10,000 روپے</text>\n  <rect x=\"300\" y=\"160\" width=\"300\" height=\"60\" rx=\"8\" fill=\"#55a868\" fill-opacity=\"0.30\" stroke=\"#55a868\" stroke-width=\"1.5\"/>\n  <text x=\"450\" y=\"196\" text-anchor=\"middle\" fill=\"#a9d3b0\" font-size=\"12\" font-weight=\"700\">اچھوتا - آپشن خریدنے کے لیے نہیں۔</text>\n  <line x1=\"90\" y1=\"225\" x2=\"90\" y2=\"252\" stroke=\"#c44e52\" stroke-width=\"0\"/>\n  <path d=\"M 650 80 L 650 215\" stroke=\"#c44e52\" stroke-width=\"2\" stroke-dasharray=\"5 4\" marker-end=\"url(#zar)\"/>\n  <defs><marker id=\"zar\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"3.2\" orient=\"auto\"><path d=\"M0,0 L7,3.2 L0,6.4 z\" fill=\"#c44e52\"/></marker></defs>\n  <text x=\"690\" y=\"150\" text-anchor=\"middle\" fill=\"#f3c9c9\" font-size=\"11\" font-weight=\"700\">ایک خریدا</text>\n  <text x=\"690\" y=\"166\" text-anchor=\"middle\" fill=\"#f3c9c9\" font-size=\"11\" font-weight=\"700\">اختیار کر سکتے ہیں</text>\n  <text x=\"690\" y=\"182\" text-anchor=\"middle\" fill=\"#f3c9c9\" font-size=\"11\" font-weight=\"700\">صفر پر جائیں</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">آپ جس ٹکڑوں کو خطرے میں ڈالتے ہیں وہ جان بوجھ کر چھوٹا ہے، کیونکہ اس کا پورا حصہ ختم ہو سکتا ہے۔</figcaption>\n</figure><h2 id=\"rule-2-choose-an-expiry-that-gives-the-trade-time\">قاعدہ 2: ایک ختم ہونے کا انتخاب کریں جو تجارت کا وقت فراہم کرے۔</h2>\n<p>ایک ہی دن اور ہفتہ وار اختیارات سب سے زیادہ دلچسپ اور سب سے زیادہ سزا دینے والے ہیں۔ وہ تقریباً تمام وقتی قدر ہیں، اس لیے وہ تقریباً تمام بوسیدہ ہیں۔ میعاد ختم ہونے کے قریب، تھیٹا آپ کے پریمیم کو اتنی ہی تیزی سے پگھلاتا ہے - اور ایکسپائری کے دن پگھلنا ظالمانہ ہوتا ہے۔ ہفتہ وار خریدنے والا ایک ابتدائی ہر ایک گھنٹے میں گھڑی سے لڑ رہا ہے۔</p>\n<p>درست کرنا آسان ہے: <strong>تجارت کا وقت دیں۔</strong>. ختم ہونے والی میعادوں کو ترجیح دیں جو ہفتوں سے باہر ہیں، گھنٹے نہیں، لہذا آپ کے نظارے کو ختم کرنے کی گنجائش ہے اس سے پہلے کہ وہ پریمیم کھا لے۔ رسک مینجمنٹ کورس کا آپشن خریدار رسک باب براہ راست زوال کے منحنی خطوط کو ظاہر کرتا ہے - یہ جلد ہی برقرار رہتا ہے اور آخر میں ایک پہاڑ سے گر جاتا ہے۔ چٹان خریدنا مبتدی کی کلاسک غلطی ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 260\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"دو زوال کے راستے۔ ایک ہفتہ وار آپشن تیزی سے گرتا ہے اور تیزی سے صفر تک پہنچ جاتا ہے، جس سے بچنے کے لیے لاٹری کلف کا لیبل لگا ہوا ہے۔ ایک طویل تاریخ والا آپشن اسی کھڑکی پر آہستہ آہستہ اور آہستہ سے زوال پذیر ہوتا ہے، جس سے تجارت کو کام کرنے کا وقت ملتا ہے۔\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"260\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"28\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"15\">تجارت کو وقت دیں: سست زوال ہفتہ وار چٹان کو شکست دیتا ہے۔</text>\n  <line x1=\"80\" y1=\"210\" x2=\"710\" y2=\"210\" stroke=\"#2d3640\" stroke-width=\"1.2\"/>\n  <line x1=\"80\" y1=\"50\" x2=\"80\" y2=\"210\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <text x=\"72\" y=\"66\" text-anchor=\"end\" fill=\"#8b949e\" font-size=\"10\">پریمیم</text>\n  <text x=\"395\" y=\"232\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10.5\">وقت گزر رہا ہے -&gt;</text>\n  <path d=\"M 80 90 C 200 130, 280 200, 330 208\" fill=\"none\" stroke=\"#c44e52\" stroke-width=\"3\"/>\n  <text x=\"250\" y=\"120\" fill=\"#f3c9c9\" font-size=\"11.5\" font-weight=\"700\">ایک ہی دن / ہفتہ وار</text>\n  <text x=\"250\" y=\"137\" fill=\"#8b949e\" font-size=\"10.5\">تمام زوال پذیر، تیزی سے صفر پر پگھل جاتے ہیں۔</text>\n  <path d=\"M 80 105 C 300 120, 520 138, 700 175\" fill=\"none\" stroke=\"#55a868\" stroke-width=\"3\"/>\n  <text x=\"500\" y=\"118\" fill=\"#a9d3b0\" font-size=\"11.5\" font-weight=\"700\">ختم ہونے کے لئے ہفتے</text>\n  <text x=\"500\" y=\"135\" fill=\"#8b949e\" font-size=\"10.5\">نرم رساو - صحیح ہونے کا کمرہ</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">معیاد ختم ہونے کے لیے زیادہ وقت ایک سست خون خریدتا ہے - اور آپ کے نقطہ نظر کے سامنے آنے کا ایک حقیقی موقع۔</figcaption>\n</figure><h2 id=\"rule-3-respect-implied-volatility-do-not-overpay\">قاعدہ 3: مضمر اتار چڑھاؤ کا احترام کریں - زیادہ ادائیگی نہ کریں۔</h2>\n<p>مضمر اتار چڑھاؤ ( IV) متوقع جھولوں کے لیے مارکیٹ کی قیمت ہے۔ کسی معروف واقعہ سے پہلے - کمپنی کے نتائج، بجٹ، ایک RBI فیصلہ - ہر کوئی ایک بڑے اقدام کے لیے تیار ہوتا ہے، لہذا IV کو پمپ کیا جاتا ہے اور اختیارات مل جاتے ہیں۔ <em>مہنگا</em>. آپ صحیح سمت میں ہو سکتے ہیں اور پھر بھی ہار سکتے ہیں، کیونکہ ایک بار جب ایونٹ گزر جاتا ہے تو غیر یقینی صورتحال ختم ہو جاتی ہے، IV گر جاتا ہے، اور فلایا ہوا پریمیم اس کے ساتھ کم ہوجاتا ہے۔ یعنی <strong>IV کو کچلنا</strong>.</p>\n<p>نظم و ضبط: کوئی آپشن صرف اس وجہ سے نہ خریدیں کہ کوئی واقعہ قریب ہے اور کوئی بڑا اقدام \"واضح\" محسوس ہوتا ہے۔ اگر IV غیر معمولی طور پر زیادہ ہے، تو آپ زیادہ ادائیگی کر رہے ہیں، اور ہجوم نے پہلے ہی اس اقدام کے لیے ادائیگی کی جس کی آپ توقع کر رہے ہیں۔ یہ جانتے ہوئے کہ آپ زیادہ ادائیگی کر رہے ہیں یا تو سائز کم کریں، یا بس انتظار کریں۔ واقعات دوگنا خطرناک ہونے سے پہلے سستی محسوس کرنے والے دور -OTMکے اختیارات: اعلی IV <em>اور</em> تقریبا خالص وقت کی قیمت.</p>\n<h2 id=\"rule-4-a-stop-loss-in-premium-terms\">قاعدہ 4: پریمیم شرائط میں سٹاپ لاس</h2>\n<p>خریدار کا اسٹاپ چارٹ پر قیمت نہیں ہے - یہ اس پر ایک سطح ہے۔ <em>پریمیم</em>. داخل ہونے سے پہلے اس کا فیصلہ کریں۔ ایک صاف، میکانی اصول: <strong>پریمیم کے مائنس 50% پر باہر نکلیں۔</strong> 50 روپے فی یونٹ ادا کریں، آپ 25 روپے سے باہر ہیں۔ 65 یونٹ والے لاٹ پر جو نقصان کو 1,625 روپے تک محدود کرتا ہے - 2,00,000 روپے کے اکاؤنٹ کے 1% سے کم - صفر پر جانے کے بجائے \"اگر یہ واپس آجاتا ہے۔\"</p>\n<p>شامل کریں <strong>وقت روک</strong> بھی: \"اگر اس نے کام نہیں کیا تو ایک مقررہ دن تک باہر۔\" ایک آپشن جو آپ کے نقطہ نظر کی ضرورت ہے۔ <em>آج</em> اور حاصل نہیں کیا یہ شاذ و نادر ہی قابل قدر ہے کشی چٹان میں انعقاد. پرائس سٹاپ یا ٹائم سٹاپ، جو بھی پہلے آئے۔ بات یہ ہے کہ \"امید ختم ہونے تک\" کوئی منصوبہ نہیں ہے - یہ ہے کہ کس طرح 3,250 روپے کا ٹکٹ ہر بار 3,250 روپے کا نقصان بن جاتا ہے۔</p>\n\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>خریدار کی تین غلطیاں جو زیادہ تر نقصان کا باعث بنتی ہیں۔ <strong>کوئی پریمیم بجٹ نہیں:</strong> بغیر ماہانہ کیپ کے بار بار خریدنا، اس لیے خاموشی سے تیس چھوٹے نقصانات دو جیتوں سے زیادہ ہیں - وکرم کا عین مطابق خون۔ <strong>لاٹری خریدنا:</strong> ایک جیک پاٹ کی امید میں بار بار سستے دور-OTMہفتہ وار خریدنا؛ وہ ادا کرتے ہیں اس سے کہیں زیادہ بیکار ختم ہو جاتے ہیں۔ <strong>کوئی روک نہیں:</strong> کھونے والے آپشن کو صفر پر رکھنا \"اگر یہ اچھال جاتا ہے۔\" بہتر اقدام ان تینوں کے برعکس ہے - ایک مقررہ بجٹ، ان پر حقیقی وقت کے ساتھ پیسے کے قریب کے اختیارات، اور مائنس 50٪ پر یا ایک مقررہ دن تک پہلے سے طے شدہ اخراج۔</p>\n</div></div>\n<h2 id=\"the-one-page-option-buyer-risk-plan\">ایک صفحے کا اختیار خریدار خطرے کا منصوبہ</h2>\n<p>یہ پرنٹ کریں۔ اس کے ذریعے خریدنے والے ہر آپشن کو چلائیں۔ اگر آپ تمام چھ پر نشان نہیں لگا سکتے تو تجارت کو چھوڑ دیں۔</p>\n<ol>\n<li><strong>پریمیم بجٹ:</strong> اس ایک خرید پر سرمایہ کے 1-2% سے زیادہ کا خطرہ نہ کریں، اور میری ماہانہ کیپ (~5%) کے اندر رہیں۔</li>\n<li><strong>کل نقصان ٹیسٹ:</strong> اگر یہ پریمیم صفر پر چلا جاتا ہے تو میں حقیقی طور پر ٹھیک ہوں، کیونکہ یہ اکثر ہوگا۔</li>\n<li><strong>میعاد ختم:</strong> ختم ہونے میں ہفتے، ایک ہی دن یا ہفتہ وار لاٹری نہیں - تجارت کے پاس کام کرنے کا وقت ہے۔</li>\n<li><strong>IV چیک:</strong> IV کسی قریبی واقعے سے پمپ نہیں کیا جاتا ہے۔ اگر ایسا ہے تو، میں جان بوجھ کر زیادہ ادائیگی کر رہا ہوں یا میں انتظار کر رہا ہوں۔</li>\n<li><strong>ہڑتال:</strong> حقیقی قیمت کے ساتھ قریب سے پیسہ، سستا دور OTM جیک پاٹ ٹکٹ نہیں۔</li>\n<li><strong>اب باہر نکلنے کا فیصلہ کیا:</strong> پریمیم کے مائنس 50% پر، یا ایک مقررہ دن تک - جو بھی پہلے آئے۔</li>\n</ol>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 320\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"چھ نمبر والے اصولوں کے ساتھ ایک صفحے کا آپشن خریدار رسک پلان کارڈ: پریمیم بجٹ ایک سے دو فیصد فی تجارت، سب کچھ کھونے پر جرمانہ، ایکسپائری ہفتے ختم، چیک کریں کہ IV پمپ نہیں ہوا، پیسے کے قریب سے اسٹرائیک، اور پریمیم کے مائنس پچاس فیصد پر یا ایک مقررہ دن تک باہر نکلیں۔\" font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"320\" fill=\"#0d1117\"/>\n  <rect x=\"20\" y=\"18\" width=\"720\" height=\"288\" rx=\"14\" fill=\"#11161d\" stroke=\"#4c72b0\" stroke-width=\"2\"/>\n  <text x=\"380\" y=\"50\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\">ایک صفحے کا اختیار خریدار خطرے کا منصوبہ</text>\n  <line x1=\"50\" y1=\"64\" x2=\"710\" y2=\"64\" stroke=\"#30363d\" stroke-width=\"1.2\"/>\n  <g font-family=\"system-ui, -apple-system, Segoe UI, Roboto, sans-serif\">\n    <circle cx=\"66\" cy=\"92\" r=\"11\" fill=\"#4c72b0\"/><text x=\"66\" y=\"96\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"12\" font-weight=\"700\">1</text>\n    <text x=\"88\" y=\"89\" fill=\"#cdd9e5\" font-size=\"12.5\" font-weight=\"700\">پریمیم بجٹ</text>\n    <text x=\"88\" y=\"106\" fill=\"#8b949e\" font-size=\"11\">فی خرید سرمایہ کا 1-2%؛ ~5% ماہانہ کیپ</text>\n    <circle cx=\"66\" cy=\"138\" r=\"11\" fill=\"#dd8452\"/><text x=\"66\" y=\"142\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"12\" font-weight=\"700\">2</text>\n    <text x=\"88\" y=\"135\" fill=\"#cdd9e5\" font-size=\"12.5\" font-weight=\"700\">مکمل نقصان ٹیسٹ</text>\n    <text x=\"88\" y=\"152\" fill=\"#8b949e\" font-size=\"11\">ٹھیک ہے اگر یہ پریمیم صفر پر چلا جاتا ہے - یہ اکثر ہوگا۔</text>\n    <circle cx=\"66\" cy=\"184\" r=\"11\" fill=\"#55a868\"/><text x=\"66\" y=\"188\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"12\" font-weight=\"700\">3</text>\n    <text x=\"88\" y=\"181\" fill=\"#cdd9e5\" font-size=\"12.5\" font-weight=\"700\">وقت کے ساتھ ختم</text>\n    <text x=\"88\" y=\"198\" fill=\"#8b949e\" font-size=\"11\">ہفتے باہر، ایک ہی دن / ہفتہ وار لاٹری نہیں۔</text>\n    <circle cx=\"408\" cy=\"92\" r=\"11\" fill=\"#8172b3\"/><text x=\"408\" y=\"96\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"12\" font-weight=\"700\">4</text>\n    <text x=\"430\" y=\"89\" fill=\"#cdd9e5\" font-size=\"12.5\" font-weight=\"700\">IV چیک کریں۔</text>\n    <text x=\"430\" y=\"106\" fill=\"#8b949e\" font-size=\"11\">قریبی واقعہ سے پمپ نہیں ہوا - یا میں انتظار کرتا ہوں۔</text>\n    <circle cx=\"408\" cy=\"138\" r=\"11\" fill=\"#37b3a4\"/><text x=\"408\" y=\"142\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"12\" font-weight=\"700\">5</text>\n    <text x=\"430\" y=\"135\" fill=\"#cdd9e5\" font-size=\"12.5\" font-weight=\"700\">ہڑتال</text>\n    <text x=\"430\" y=\"152\" fill=\"#8b949e\" font-size=\"11\">پیسے کے قریب، دور OTM ٹکٹ نہیں۔</text>\n    <circle cx=\"408\" cy=\"184\" r=\"11\" fill=\"#c44e52\"/><text x=\"408\" y=\"188\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"12\" font-weight=\"700\">6</text>\n    <text x=\"430\" y=\"181\" fill=\"#cdd9e5\" font-size=\"12.5\" font-weight=\"700\">اب باہر نکلنے کا فیصلہ کیا ہے۔</text>\n    <text x=\"430\" y=\"198\" fill=\"#8b949e\" font-size=\"11\">پریمیم کے -50% پر، یا ایک مقررہ دن تک</text>\n  </g>\n  <rect x=\"50\" y=\"224\" width=\"660\" height=\"62\" rx=\"10\" fill=\"#0d1117\" stroke=\"#30363d\" stroke-width=\"1.2\"/>\n  <text x=\"380\" y=\"248\" text-anchor=\"middle\" fill=\"#9db4d8\" font-size=\"12\" font-weight=\"700\">کام کی مثال - روپے 2,00,000 اکاؤنٹ</text>\n  <text x=\"380\" y=\"268\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\">50/unit x 65 = 3,250 روپے (2% سے کم) ادا کریں۔ 1,625 روپے کے قریب نقصان 25 روپے پر بند کریں۔</text>\n  <text x=\"380\" y=\"282\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10.5\">صرف تعلیم - سرمایہ کاری کا مشورہ نہیں۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">چھ چیک اور ایک کام کی مثال - ایک ہی کارڈ پر خریدار کا پورا منصوبہ۔</figcaption>\n</figure><h2 id=\"buyer-s-plan-vs-seller-s-plan\">خریدار کا منصوبہ بمقابلہ بیچنے والے کا منصوبہ</h2>\n<p>اگلا باب آپشن بناتا ہے۔ <em>بیچنے والے کا</em> منصوبہ، اور یہ تقریبا ایک آئینے کی تصویر ہے. ان کو ساتھ ساتھ دیکھ کر ہر ایک واضح ہو جاتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>آپشن خریدار</th>\n<th>آپشن بیچنے والا</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ادا کرتا ہے یا جمع کرتا ہے۔</td>\n<td>سامنے پریمیم ادا کرتا ہے۔</td>\n<td>سامنے پریمیم جمع کرتا ہے۔</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>پریمیم - محدود، لیکن اکثر <em>تمام</em> اس کا</td>\n<td>نایاب، بڑا، پریمیم سے کہیں زیادہ ہو سکتا ہے۔</td>\n</tr>\n<tr>\n<td>وقت کی خرابی (تھیٹا)</td>\n<td>دشمن - آپ کو روزانہ خون بہاتا ہے۔</td>\n<td>دوست - آمدنی میں کمی</td>\n</tr>\n<tr>\n<td>جیت کی شرح</td>\n<td>کم - آپ اکثر ہار جاتے ہیں۔</td>\n<td>اعلی - آپ اکثر جیتتے ہیں۔</td>\n</tr>\n<tr>\n<td>بنیادی رسک کنٹرول</td>\n<td>چھوٹا پریمیم بجٹ، ختم ہونے کا وقت، ایک -50% اسٹاپ</td>\n<td>متعین خطرہ، مارجن بفر، ایک ٹیل ہیج</td>\n</tr>\n<tr>\n<td>قاتل سے بچنے کی عادت</td>\n<td>لاٹری سستے ہفتہ وار خریدنا</td>\n<td>برہنہ بیچنا اور سکون کے لیے سائز کرنا</td>\n</tr>\n</tbody></table>\n<p>نہ ہی \"محفوظ\" ہے۔ وہ مخالف طریقوں سے ناکام ہوتے ہیں: خریدار چھوٹے اور اکثر ہارتا ہے، بیچنے والا اکثر جیتتا ہے اور بہت کم ہارتا ہے۔ ہر پوزیشن کو سائز دیں لہذا غلط ہونا زندہ ہے۔ یہ تعلیم ہے، ذاتی مشورے نہیں۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>حدود کے بارے میں ایماندار رہو. یہ منصوبہ آپ کو برقرار رکھتا ہے۔ <em>نقصانات</em> چھوٹے اور سمجھدار؛ یہ آپ کو نہیں بناتا <em>جیت</em>. وقت، زوال، اور اتار چڑھاؤ ڈیزائن کے لحاظ سے خریدار کے خلاف اسٹیک ہوتے ہیں، اس لیے آپ تمام چھ اصولوں پر عمل کر سکتے ہیں - سمجھدار بجٹ، ختم ہونے میں ہفتے، کوئی ایونٹ زیادہ ادائیگی نہیں، ایک حقیقی اسٹاپ - اور پھر بھی کھوتے ہیں، کیونکہ یہ اقدام بہت چھوٹا تھا یا بہت سست تھا جو آپ نے ادا کی تھی۔ یہ آپ کی غلطی نہیں ہے۔ یہ خریدار ہونے کی ساختی قیمت ہے۔</p>\n<p>مائنس 50% پر سٹاپ بھی آپ کو فرق سے نہیں بچائے گا: اگر پریمیم راتوں رات آپ کے سٹاپ سے بہت نیچے کھلتا ہے، تو آپ منصوبہ بندی سے بدتر باہر نکل جاتے ہیں۔ اور بجٹ کی ٹوپی صرف اس صورت میں کام کرتی ہے جب آپ واقعی اس کی تعمیل کرتے ہیں - خون بہا اس لمحے واپس آتا ہے جب \"صرف ایک اور سستی کال\" واپس آجاتی ہے۔ خریداری کے اختیارات کو کبھی کبھار، اچھی طرح سے منتخب کردہ، ایک تیز اقدام پر وقت کی پابندی کے لیے بہترین استعمال کیا جاتا ہے جس کی آپ حقیقی طور پر توقع کرتے ہیں۔ دفاع ہمیشہ کم ہوتا ہے، بہتر خریدتا ہے، ان میں سے زیادہ نہیں۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> ایک آپشن خریدار کو صرف پیسے کا خطرہ کیوں ہونا چاہئے وہ مکمل طور پر کھو رہے ہیں؟</summary><p>کیونکہ خریدا ہوا آپشن - اور اکثر ہوتا ہے - صفر تک جا سکتا ہے۔ پریمیم سب سے زیادہ ہے جسے آپ کھو سکتے ہیں، لیکن کھونا <em>پوری</em> پریمیم ایک عام نتیجہ ہے، نایاب نہیں۔ اس لیے صرف ایک چھوٹی، مقررہ ٹکڑا کا خطرہ مول لیں جسے آپ بغیر کسی نقصان کے مکمل طور پر کھو سکتے ہیں۔</p>\n</details><details>\n<summary><strong>2.</strong> پریمیم بجٹ کا اصول نمبروں کے ساتھ کیا کہتا ہے؟</summary><p>ایک واحد آپشن خریدنے پر تقریباً 1-2% سرمائے کا خطرہ، اور کل ماہانہ آپشن خرچ تقریباً 5% تک محدود۔ 2,00,000 روپے کے اکاؤنٹ پر جو کہ فی تجارت 2,000-4,000 روپے ہے اور مہینے کے لیے تقریباً 10,000 روپے۔ جب ماہانہ بجٹ ختم ہو جاتا ہے، تو آپ اگلے مہینے تک خریدنا بند کر دیتے ہیں۔</p>\n</details><details>\n<summary><strong>3.</strong> ایک ابتدائی کے طور پر ایک ہی دن اور ہفتہ وار میعاد ختم ہونے سے کیوں بچیں؟</summary><p>وہ تقریباً مکمل طور پر وقت کی قدر ہیں، اس لیے وہ تقریباً مکمل طور پر بوسیدہ ہو چکے ہیں، اور پگھلنے کی رفتار بے دردی سے ختم ہو جاتی ہے۔ آپ ہر گھنٹے کی گھڑی سے لڑ رہے ہیں۔ میعاد ختم ہونے والے ہفتوں کا انتخاب کرنے سے تھیٹا کے پریمیم کھانے سے پہلے آپ کے نظارے کو دیکھنے کے لئے ایک ہلکی کشی اور حقیقی جگہ ملتی ہے۔</p>\n</details><details>\n<summary><strong>4.</strong> خریدار کا سٹاپ لاس کیا ہے، اور صاف اصول کیا ہے؟</summary><p>یہ ایک سطح پر ہے۔ <em>پریمیم</em>، چارٹ کی قیمت نہیں، آپ کے داخل ہونے سے پہلے طے کرلیں۔ ایک صاف اصول یہ ہے کہ پریمیم کے مائنس 50% پر باہر نکلیں - 50 روپے ادا کریں، 25 روپے پر باہر نکلیں - اور اگر یہ کام نہیں کرتا ہے تو ایک مقررہ دن تک باہر نکلنے کے لیے ایک ٹائم اسٹاپ۔ جو بھی پہلے مارتا ہے۔ \"امید ختم ہونے تک\" کوئی روک نہیں ہے۔</p>\n</details><details>\n<summary><strong>5.</strong> لاٹری خریدنا کیا ہے، اور اس سے اکاؤنٹ خشک کیوں ہوتا ہے؟</summary><p>یہ بار بار سستے، پیسے سے باہر کے اختیارات خرید رہا ہے - \"یہ صرف 5 روپے ہے\" - ایک جیک پاٹ کی امید میں۔ وہ اپنی ادائیگی سے کہیں زیادہ بار بیکار ختم ہو جاتے ہیں، لہذا چھوٹے نقصانات کا ایک مستقل سلسلہ خاموشی سے نایاب بڑی جیت سے زیادہ ہے۔ آپ کو ایک تجارت میں اڑا نہیں ہے؛ آپ نے ایک وقت میں ایک سستا ٹکٹ نکال دیا۔</p>\n</details>\n","toc":[{"level":2,"text":"خریدار کا سودا، ایک لائن میں","id":"the-buyer-s-deal-in-one-line"},{"level":2,"text":"قاعدہ 1: ایک پریمیم بجٹ جس سے آپ مکمل طور پر کھو سکتے ہیں۔","id":"rule-1-a-premium-budget-you-can-lose-entirely"},{"level":2,"text":"قاعدہ 2: ایک ختم ہونے کا انتخاب کریں جو تجارت کا وقت فراہم کرے۔","id":"rule-2-choose-an-expiry-that-gives-the-trade-time"},{"level":2,"text":"قاعدہ 3: مضمر اتار چڑھاؤ کا احترام کریں - زیادہ ادائیگی نہ کریں۔","id":"rule-3-respect-implied-volatility-do-not-overpay"},{"level":2,"text":"قاعدہ 4: پریمیم شرائط میں سٹاپ لاس","id":"rule-4-a-stop-loss-in-premium-terms"},{"level":2,"text":"ایک صفحے کا اختیار خریدار خطرے کا منصوبہ","id":"the-one-page-option-buyer-risk-plan"},{"level":2,"text":"خریدار کا منصوبہ بمقابلہ بیچنے والے کا منصوبہ","id":"buyer-s-plan-vs-seller-s-plan"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"23":{"html":"<p>ارجن نے آمدنی کے اختیارات بیچے۔ وہ اس کے بارے میں لاپرواہ نہیں تھا - اس نے طے شدہ خطرے کے پھیلاؤ کو استعمال کرنے کے لئے کافی پڑھا تھا، کبھی بھی مکمل طور پر ننگا نہیں ہوا تھا۔ ایک سال تک اس نے خوبصورتی سے کام کیا: زیادہ تر ہفتوں میں چند ہزار روپے، 5,00,000 روپے کے اکاؤنٹ سے نکالے گئے۔ لیکن اس کے منصوبے میں دو خاموش سوراخ تھے۔ اس نے کوئی ٹیل ہیج نہیں رکھا، کیونکہ \"اس سے صرف پیسے کا خون بہاتا ہے،\" اور اس کے پاس برے دن کے لیے کوئی مشکل نہیں تھا، کیونکہ \"میں اسے جیسے ہی آئے گا سنبھالوں گا۔\" پھر ایک گیپ ڈاون صبح اس کے تین اسپریڈ ایک ہی وقت میں اپنے زیادہ سے زیادہ نقصان کے قریب کھل گئے۔ اس نے منجمد کیا، پھر گرتی ہوئی منڈی میں سائز کا اضافہ کر کے تجارت کو \"منظم\" کیا - اور دوپہر کے کھانے سے اس نے چار ماہ سے زیادہ کی آمدنی واپس کر دی۔ اس کے ڈھانچے کے بارے میں کچھ بھی غلط نہیں تھا۔ ان کے اردگرد کا منصوبہ تھا۔</p>\n<p>یہ وہ باب ہے جس کی طرف پورا Option-Seller Playbook تعمیر کر رہا ہے: آمدنی بیچنے والے کے لیے ایک ٹھوس، استعمال کے لیے تیار، ایک صفحے کا رسک پلان۔ فروخت کے اختیارات اس کورس میں کسی بھی طرز کو کم سے کم معاف کرتے ہیں، لہذا اس کا منصوبہ سب سے سخت ہونا چاہیے۔</p>\n<h2 id=\"why-the-seller-needs-the-tightest-plan\">بیچنے والے کو سخت ترین پلان کی ضرورت کیوں ہے۔</h2>\n<p>ٹیل رسک باب سے بیچنے والے کے خطرے کی شکل کو یاد رکھیں۔ آپ کا منافع محدود ہے - آپ جو پریمیم جمع کرتے ہیں وہ سب سے زیادہ ہے جو آپ کبھی بھی کما سکتے ہیں۔ آپ کا نقصان اسی طرح آرام دہ اور پرسکون طریقے سے محدود نہیں ہے۔ آپ چھوٹی اور اکثر جیتتے ہیں، اور ایک بار میں آپ بڑی ہار جاتے ہیں۔ ایک وقفہ والا دن کئی مہینوں کے پریمیم سے بڑا ہو سکتا ہے۔ یہ عدم توازن ہی سارا مسئلہ ہے، اور اس کا مطلب ہے کہ بیچنے والا زیادہ تر وقت صحیح ہونے پر بھروسہ نہیں کر سکتا۔ آپ پہلے ہی ہیں۔ منصوبہ اس نایاب دن کے لیے موجود ہے جس دن آپ غلط ہیں۔</p>\n<p>لہذا بیچنے والے کا منصوبہ زیادہ پیسہ کمانے کے لئے نہیں بنایا گیا ہے۔ یہ اس لیے بنایا گیا ہے کہ ایک برا دن آپ کو ختم نہیں کر سکتا۔ چھ اصول تقریباً تمام کام کرتے ہیں، اور وہ صرف اس صورت میں مدد کرتے ہیں جب ان میں سے ہر ایک کا فیصلہ کیا جائے۔ <strong>پہلے</strong> آپ داخل ہوتے ہیں، پرسکون میں، درمیانی گھبراہٹ کی ایجاد نہیں کی گئی تھی۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>بیچنے والا زندہ رہ کر جیت جاتا ہے۔ آپ کا کنارہ پہلے ہی چھوٹے، متواتر پریمیم میں ہے - آپ کا کام اس بات کو یقینی بنانا ہے کہ کوئی ایک دن، فرق یا اتار چڑھاؤ ان میں سے ایک سال کو ختم نہ کر سکے۔ منصوبہ بقا ہے، آمدنی نہیں۔</p>\n</div></div>\n<h2 id=\"the-six-rules-in-order\">چھ اصول، ترتیب میں</h2>\n<p><strong>1. صرف طے شدہ خطرہ۔</strong> ہر پوزیشن ایک اسپریڈ ہے - ایک مختصر آپشن ہمیشہ ایک ہی طرف ایک سستا، مزید باہر لانگ آپشن کے ساتھ جوڑا جاتا ہے۔ کبھی برہنہ۔ یہ نییکڈ سیلنگ بمقابلہ ہیجڈ سیلنگ باب کا سبق ہے: ایک اسپریڈ آپ کو داخل ہونے سے پہلے زیادہ سے زیادہ نقصان پہنچاتا ہے، جبکہ ایک ننگا شارٹ اوپن اینڈڈ چلتا ہے۔ کیپ جس نے زیادہ سے زیادہ چھوٹے کی وضاحت کی ہے - کہتے ہیں کہ کوئی بھی پوزیشن 5,00,000 روپے کے اکاؤنٹ پر تقریباً 10,000 روپے کے 2% سے زیادہ سرمائے سے محروم نہیں ہوسکتی ہے۔ \"تعریف شدہ\" کا مطلب معلوم ہے، خود بخود چھوٹا نہیں، لہذا آپ کو اب بھی اس کا سائز بنانا ہوگا۔</p>\n<p><strong>2. ایک مارجن بفر۔</strong> ایک اتار چڑھاؤ اسپائک مارجن کو بڑھاتا ہے جو آپ کے بروکر کا مطالبہ بدترین ممکنہ لمحے پر ہوتا ہے۔ اگر آپ اپنا تقریباً سارا مارجن استعمال کر رہے ہیں، تو وہ اسپائیک سب سے بدصورت قیمت پر ایک مربع بند کو مجبور کر سکتا ہے - آپ سب سے نیچے بند ہو جاتے ہیں، نہ کہ انتخاب سے۔ اس لیے اپنے مارجن کا صرف ایک حصہ تعینات کریں: آپ کے پاس جو کچھ ہے اس کا زیادہ سے زیادہ 50-60% استعمال کرنے کا مقصد، 40-50% کو کشن کے طور پر مفت چھوڑ کر۔ اضافی مارجن بیکار رقم نہیں ہے۔ یہ وہی ہے جو ایک برے دن کو مجبور دن بننے سے روکتا ہے۔</p>\n<p><strong>3. ایک کھڑا دم ہیج۔</strong> ہر وقت سستے، پیسے سے باہر کے طویل اختیارات میں ایک چھوٹی پوزیشن پر فائز رہیں - ٹیل رسک باب سے انشورنس۔ اس پر ہر ماہ تھوڑا سا خرچ ہوتا ہے، شاید سرمایہ کا 0.5-1%، اور عام طور پر بیکار ختم ہو جاتا ہے۔ یہی بات ہے۔ بلیک سوان کے فرق پر یہ قیمت میں پھٹ جاتا ہے اور تباہی کی ادائیگی کرتا ہے۔ آپ اسے پرسکون مہینوں میں بالکل ٹھیک رکھتے ہیں کیونکہ آپ اس دن کا اندازہ نہیں لگا سکتے جس دن آپ کو اس کی ضرورت ہوگی۔</p>\n<p><strong>4. پہلے سے طے شدہ ایڈجسٹمنٹ کے اصول۔</strong> داخلے سے پہلے اپنی ایڈجسٹمنٹ کا فیصلہ کریں، ہارنے والی پوزیشن کی گرمی میں نہیں۔ ایڈجسٹمنٹ رسک باب سے: اچھی ایڈجسٹمنٹ خطرے کو کم کرتی ہے۔ ایک برا صرف نقصان کو چھپاتا ہے اور خاموشی سے پوزیشن کو بڑھاتا ہے۔ اصول لکھیں - مثال کے طور پر، \"اگر میری مختصر ہڑتال کا تجربہ کیا جاتا ہے، تو میں ایک بار رول کرتا ہوں یا بند کرتا ہوں؛ میں کبھی بھی ننگے سائز کا اضافہ نہیں کرتا؛ میں فی پوزیشن زیادہ سے زیادہ ایک ایڈجسٹمنٹ کی اجازت دیتا ہوں۔\" سکون میں بنایا گیا ایک اصول آپ کو اس بہادر، احمقانہ خیال سے بچاتا ہے جو آپ کو سرخ صبح کو 9:30 پر آئے گا۔</p>\n<p><strong>5. زیادہ سے زیادہ نقصان کا دن۔</strong> ایک مشکل روزانہ سٹاپ مقرر کریں. اگر دن کے لیے آپ کا کل نقصان - اوپن پلس کا احساس، ہر پوزیشن پر - ایک مقررہ اعداد و شمار تک پہنچ جاتا ہے، کہیے کہ سرمایہ کا 3% (5,00,000 روپے پر تقریباً 15,000 روپے)، آپ سب کچھ بند کر دیتے ہیں اور دن کے لیے تجارت بند کر دیتے ہیں۔ نہیں \"مجھے صرف اچھال کا انتظار کرنے دو۔\" یہ وہ اصول ہے جو ارجن کے پاس نہیں تھا۔ یہ سرکٹ بریکر ہے جو ایک خوفناک دن کو محض برے دن میں بدل دیتا ہے۔</p>\n<p><strong>6. ایونٹ فلٹرز۔</strong> کسی معروف بڑے ایونٹ میں کوئی تازہ فروخت نہیں ہوئی۔ بجٹ کا دن، مرکزی بینک کا ایک بڑا فیصلہ، انتخابی نتائج، بھاری آمدنی کی تاریخ - یہ بالکل اس وقت ہوتے ہیں جب خلاء اور اتار چڑھاؤ کے دھماکے ہوتے ہیں۔ ہر سیلنگ سائیکل سے پہلے کیلنڈر کو چیک کریں، اور صرف ایک یا دو دن میں طے شدہ جھٹکے سے پہلے نیا مختصر پریمیم نہ کھولیں۔ پکڑو یا بند کرو، لیکن اس میں فروخت نہ کرو.</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 380\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک صفحہ کے آپشن سیلر رسک پلان کے عنوان سے ایک کارڈ، جس میں ایک گرڈ میں چھ نمبر والے اصول دکھائے گئے ہیں: صرف متعین خطرہ، مارجن بفر، اسٹینڈ ٹیل ہیج، پہلے سے سیٹ ایڈجسٹمنٹ کے اصول، زیادہ سے زیادہ نقصان کا دن، اور ایونٹ فلٹرز، ہر ایک مختصر عددی رہنما خطوط کے ساتھ۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"380\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"34\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"17\" font-family=\"sans-serif\">ایک صفحے کا اختیار بیچنے والا رسک پلان</text>\n  <text x=\"380\" y=\"56\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11.5\" font-family=\"sans-serif\">چھ قواعد، تمام داخلے سے پہلے طے شدہ۔ مثال اکاؤنٹ: 5,00,000 روپے۔</text>  <rect x=\"36\" y=\"74\" width=\"340\" height=\"86\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <circle cx=\"62\" cy=\"100\" r=\"13\" fill=\"#55a868\"/><text x=\"62\" y=\"105\" text-anchor=\"middle\" fill=\"#0d1117\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">1</text>\n  <text x=\"86\" y=\"100\" fill=\"#55a868\" font-size=\"13.5\" font-weight=\"700\" font-family=\"sans-serif\">صرف متعین خطرہ</text>\n  <text x=\"86\" y=\"120\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">ہمیشہ ایک پھیلاؤ، کبھی ننگا نہیں.</text>\n  <text x=\"86\" y=\"138\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">زیادہ سے زیادہ نقصان فی پوزیشن 2% سے کم (تقریباً 10,000 روپے)۔</text>  <rect x=\"384\" y=\"74\" width=\"340\" height=\"86\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <circle cx=\"410\" cy=\"100\" r=\"13\" fill=\"#4c72b0\"/><text x=\"410\" y=\"105\" text-anchor=\"middle\" fill=\"#0d1117\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">2</text>\n  <text x=\"434\" y=\"100\" fill=\"#4c72b0\" font-size=\"13.5\" font-weight=\"700\" font-family=\"sans-serif\">ایک مارجن بفر</text>\n  <text x=\"434\" y=\"120\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">مارجن کا زیادہ سے زیادہ 50-60% استعمال کریں۔</text>\n  <text x=\"434\" y=\"138\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">اسپیئر مارجن اتار چڑھاؤ کے اضافے سے بچ جاتا ہے۔</text>  <rect x=\"36\" y=\"170\" width=\"340\" height=\"86\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <circle cx=\"62\" cy=\"196\" r=\"13\" fill=\"#8172b3\"/><text x=\"62\" y=\"201\" text-anchor=\"middle\" fill=\"#0d1117\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">3</text>\n  <text x=\"86\" y=\"196\" fill=\"#8172b3\" font-size=\"13.5\" font-weight=\"700\" font-family=\"sans-serif\">ایک کھڑا دم ہیج</text>\n  <text x=\"86\" y=\"216\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">سستا دور -OTMلمبا، ہمیشہ جاری۔</text>\n  <text x=\"86\" y=\"234\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">ماہانہ تقریباً 0.5-1% لاگت آتی ہے۔ اس کے قابل</text>  <rect x=\"384\" y=\"170\" width=\"340\" height=\"86\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <circle cx=\"410\" cy=\"196\" r=\"13\" fill=\"#37b3a4\"/><text x=\"410\" y=\"201\" text-anchor=\"middle\" fill=\"#0d1117\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">4</text>\n  <text x=\"434\" y=\"196\" fill=\"#37b3a4\" font-size=\"13.5\" font-weight=\"700\" font-family=\"sans-serif\">پہلے سے طے شدہ ایڈجسٹمنٹ کے اصول</text>\n  <text x=\"434\" y=\"216\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">داخلے سے پہلے فیصلہ کیا، گھبراہٹ میں نہیں۔</text>\n  <text x=\"434\" y=\"234\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">ایک ایڈجسٹمنٹ۔ کبھی بھی ننگے سائز کا اضافہ نہ کریں۔</text>  <rect x=\"36\" y=\"266\" width=\"340\" height=\"86\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <circle cx=\"62\" cy=\"292\" r=\"13\" fill=\"#c44e52\"/><text x=\"62\" y=\"297\" text-anchor=\"middle\" fill=\"#0d1117\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">5</text>\n  <text x=\"86\" y=\"292\" fill=\"#c44e52\" font-size=\"13.5\" font-weight=\"700\" font-family=\"sans-serif\">زیادہ سے زیادہ نقصان کا دن</text>\n  <text x=\"86\" y=\"312\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">ایک دن میں 3 فیصد کمی (تقریباً 15,000 روپے)؟</text>\n  <text x=\"86\" y=\"330\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">سب کچھ بند کرو۔ دن کے لیے رک جاؤ۔</text>  <rect x=\"384\" y=\"266\" width=\"340\" height=\"86\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n  <circle cx=\"410\" cy=\"292\" r=\"13\" fill=\"#dd8452\"/><text x=\"410\" y=\"297\" text-anchor=\"middle\" fill=\"#0d1117\" font-size=\"13\" font-weight=\"700\" font-family=\"sans-serif\">6</text>\n  <text x=\"434\" y=\"292\" fill=\"#dd8452\" font-size=\"13.5\" font-weight=\"700\" font-family=\"sans-serif\">ایونٹ کے فلٹرز</text>\n  <text x=\"434\" y=\"312\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">بڑے معروف واقعات میں کوئی تازہ فروخت نہیں ہوئی۔</text>\n  <text x=\"434\" y=\"330\" fill=\"#cdd9e5\" font-size=\"11.5\" font-family=\"sans-serif\">بجٹ، پالیسی، انتخابات، نتائج۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">یہ پرنٹ کریں۔ ہر قاعدہ پرامن طریقے سے طے کیا جاتا ہے اور اس دن بحث کے بغیر اطاعت کی جاتی ہے۔</figcaption>\n</figure><p>ان میں سے دو اصول - ٹیل ہیج اور زیادہ سے زیادہ نقصان کا دن - وہ ہیں جو ابتدائی طور پر پہلے چھوڑتے ہیں، اور یہ بالکل وہی دو ہیں جو فیصلہ کرتے ہیں کہ آیا ایک وقفہ والا دن زندہ رہنے کے قابل ہے۔ نیچے دی گئی تصویر سے پتہ چلتا ہے کہ ہیج اتنا اہم کیوں ہے۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"مارکیٹ کے نیچے گرنے پر ایک ادائیگی کا خاکہ: ایک متعین خطرے کا پھیلاؤ ایک معلوم منزل پر پھیلتا ہے، اور ایک دور OTM ٹیل ہیج دور کی طرف تیزی سے چڑھتا ہے، اس لیے مشترکہ پوزیشن واپس اوپر جاتی ہے اور ایک انتہائی خلا سے بچ جاتی ہے، جب کہ ٹیل ہیج کے بغیر پوزیشن گرتی رہتی ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"30\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">متعین خطرے کے علاوہ ٹیل ہیج خلا سے بچ جاتا ہے۔</text>\n  <line x1=\"70\" y1=\"55\" x2=\"70\" y2=\"255\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <line x1=\"70\" y1=\"175\" x2=\"720\" y2=\"175\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n  <text x=\"78\" y=\"68\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">منافع / نقصان</text>\n  <text x=\"86\" y=\"170\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">صفر</text>\n  <text x=\"84\" y=\"248\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">مارکیٹ فرق نیچے</text>\n  <text x=\"640\" y=\"170\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">مارکیٹ مستحکم</text>\n  <polyline points=\"70,214 380,214 520,160 720,160\" fill=\"none\" stroke=\"#55a868\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/>\n  <text x=\"120\" y=\"206\" fill=\"#55a868\" font-size=\"11.5\" font-weight=\"700\" font-family=\"sans-serif\">پھیلاؤ: یہاں فرش (زیادہ سے زیادہ نقصان)</text>\n  <polyline points=\"70,78 200,118 330,160 470,175 720,175\" fill=\"none\" stroke=\"#8172b3\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/>\n  <text x=\"92\" y=\"96\" fill=\"#8172b3\" font-size=\"11.5\" font-weight=\"700\" font-family=\"sans-serif\">ٹیل ہیج چڑھتی ہے۔</text>\n  <polyline points=\"70,120 200,150 330,196 460,200 560,180 720,160\" fill=\"none\" stroke=\"#37b3a4\" stroke-width=\"3.5\"/>\n  <text x=\"330\" y=\"226\" fill=\"#37b3a4\" font-size=\"11.5\" font-weight=\"700\" font-family=\"sans-serif\">combined: کنٹرول کیا جاتا ہے، پھر بیک اوپر اٹھاتا ہے۔</text>\n  <polyline points=\"330,196 200,228 70,252\" fill=\"none\" stroke=\"#c44e52\" stroke-width=\"2.5\" stroke-dasharray=\"3 3\"/>\n  <text x=\"76\" y=\"272\" fill=\"#c44e52\" font-size=\"11.5\" font-weight=\"700\" font-family=\"sans-serif\">کوئی ٹیل ہیج نہیں: گرتا رہتا ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">پھیلاؤ نقصان کو پورا کرتا ہے۔ دور OTM ہیج ایک انتہائی خلا پر بدترین کیس کو اٹھاتا ہے۔</figcaption>\n</figure>\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>تینوں منصوبہ بندی کرنے والے تقریباً ہمیشہ ایک جیسے ہوتے ہیں۔ <strong>ننگی فروخت</strong> - حفاظتی لمبے کو چھوڑنا کیونکہ مارجن کم ہے اور پریمیم زیادہ ہے - معلوم نقصان کو اوپن اینڈڈ میں بدل دیتا ہے۔ <strong>کوئی ٹیل ہیج نہیں۔</strong> - سستے دور - OTM کو چھوڑنا طویل ہے کیونکہ وہ پرسکون مہینوں میں \"صرف خون بہتے ہیں\" - ایک اہم دن آپ کو مکمل طور پر بے نقاب کر دیتا ہے۔ <strong>زیادہ سے زیادہ نقصان کا دن نہیں۔</strong> - کوئی مشکل روزانہ سٹاپ نہیں ہے، لہذا ایک بری صبح ایک دوگنا نیچے سرپل بن جاتی ہے - یہ ہے کہ ایک ہی سیشن سال میں کیسے مٹ جاتا ہے۔ تینوں رکھیں۔ وہ 95% دنوں میں بورنگ ہوتے ہیں اور باقی 5% میں آپ کو بچاتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-one-page-plan-as-a-checklist\">ایک صفحہ کا منصوبہ بطور چیک لسٹ</h2>\n<p>ہر سیلنگ سائیکل سے پہلے اسے چلائیں۔ اگر کوئی باکس غیر نشان زد ہے تو، پوزیشن تیار نہیں ہے۔ نمبرز 5,00,000 روپے کے اکاؤنٹ کی مثالیں ہیں - انہیں اپنے اکاؤنٹ سے بدل دیں۔</p>\n<ol>\n<li><input disabled=\"\" type=\"checkbox\"> ہر مختصر آپشن کے ساتھ ایک طے شدہ خطرہ ہوتا ہے۔ کچھ بھی ننگا نہیں ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> اس پوزیشن پر میرا زیادہ سے زیادہ نقصان معلوم ہے اور سرمایہ کے 2% سے کم ہے (تقریباً 10,000 روپے)۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> اگر ہر کھلا پھیلاؤ ایک بار میں اپنی زیادہ سے زیادہ حد تک پہنچ جاتا ہے، تو کل بقایا جا سکتا ہے - تقریباً 6-8% سرمایہ، نہ کہ پورے اکاؤنٹ میں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں اپنے مارجن کا زیادہ سے زیادہ 50-60% استعمال کر رہا ہوں۔ اتار چڑھاؤ کی بڑھتی ہوئی وارداتوں کے لیے کشن مفت ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> ایک کھڑا دور OTM ٹیل ہیج ابھی آن ہے، \"بعد میں شامل نہیں کیا جائے گا۔\"</li>\n<li><input disabled=\"\" type=\"checkbox\"> میرا ایڈجسٹمنٹ اصول اندراج سے پہلے لکھا جاتا ہے: ایک ایڈجسٹمنٹ، رول یا بند، کبھی بھی ننگے سائز کا اضافہ نہ کریں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میرا زیادہ سے زیادہ نقصان کا دن مقرر ہے: 3% نیچے (تقریباً 15,000 روپے) اور میں سب کچھ بند کر کے رک جاتا ہوں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> میں نے کیلنڈر چیک کیا - بجٹ، پالیسی میٹنگز، انتخابات یا بڑے نتائج میں کوئی نئی فروخت نہیں ہوئی۔</li>\n</ol>\n<p><em>یہ ایک تعلیمی مثال ہے کہ کس طرح بیچنے والے کا منصوبہ ایک ساتھ فٹ بیٹھتا ہے، ذاتی مشورے یا اختیارات فروخت کرنے کی سفارش نہیں۔ نمبر مثالیں ہیں؛ آپ کا سرمایہ، خطرے کی برداشت اور قواعد آپ کے اپنے ہیں۔</em></p>\n<h2 id=\"seller-s-plan-vs-buyer-s-plan\">بیچنے والے کا منصوبہ بمقابلہ خریدار کا منصوبہ</h2>\n<p>رسک پلان فار آپشن بائرز کے باب نے مخالف منصوبہ بنایا، کیونکہ دونوں فریق مخالف خطرات رکھتے ہیں۔ انہیں ساتھ ساتھ دیکھنا ہر ایک کو واضح کرتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>سوال</th>\n<th>آپشن خریدار</th>\n<th>آپشن بیچنے والا</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>اہم خطرہ</td>\n<td>آہستہ خون بہنا - پریمیم زوال صفر تک پہنچ جاتا ہے۔</td>\n<td>مہینوں کو مٹانے والے ایک دن کا وقفہ</td>\n</tr>\n<tr>\n<td>سب سے بڑا واحد اصول</td>\n<td>ایک پریمیم بجٹ جسے آپ مکمل طور پر کھو سکتے ہیں۔</td>\n<td>صرف خطرے کی وضاحت، کبھی بھی ننگے نہیں</td>\n</tr>\n<tr>\n<td>مارجن</td>\n<td>سامنے پریمیم ادا کرتا ہے، تھوڑا مارجن</td>\n<td>اسپائکس کے لیے مارجن بفر کی ضرورت ہے۔</td>\n</tr>\n<tr>\n<td>کھڑا ہیج</td>\n<td>تجارت ہے - طویل اختیار پہلے سے ہی خطرہ ہے</td>\n<td>اوپر ایک الگ دور -OTMلمبا</td>\n</tr>\n<tr>\n<td>روزانہ سٹاپ</td>\n<td>مفید</td>\n<td>غیر گفت و شنید</td>\n</tr>\n<tr>\n<td>واقعات</td>\n<td>ایک دوست بن سکتا ہے - ایک فرق آپ کو ادا کر سکتا ہے</td>\n<td>دشمن ہیں - ان کو فلٹر کریں۔</td>\n</tr>\n</tbody></table>\n<p>خریدار کا منصوبہ زیادہ تر لاٹری ٹکٹوں پر زیادہ خرچ نہ کرنے کے بارے میں ہے۔ بیچنے والے کا منصوبہ نایاب دن سے تباہ نہ ہونے کے بارے میں ہے۔ ایک ہی ساز، آئینہ-تصویر نظم و ضبط۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>یہ اصول بیچنے والے کے خطرے کو کم کرتے ہیں۔ وہ اسے حذف نہیں کرتے۔ کناروں کے بارے میں ایماندار رہو.</p>\n<p><strong>متعین خطرہ اب بھی ایک بڑی تعداد ہوسکتا ہے۔</strong> ایک اسپریڈ آپ کے نقصان کو کم کرتا ہے، لیکن کیپ آپ کے جمع کیے گئے پریمیم سے کئی گنا زیادہ ہوسکتی ہے، اور اسی دن زیادہ سے زیادہ اسپریڈز کا اضافہ ہوتا ہے۔ \"تعریف شدہ\" \"معلوم\" ہے، \"چھوٹا نہیں۔\" اگر مشترکہ متعین زیادہ سے زیادہ آپ کے اکاؤنٹ کو توڑ سکتا ہے، تو منصوبہ سجاوٹ ہے۔</p>\n<p><strong>ہیج اور بفر آپ کی لاگت آئے گی۔</strong> کھڑے پونچھ سے ہر مہینے تھوڑا سا خون بہتا ہے اور عام طور پر بیکار ختم ہو جاتا ہے۔ فالتو مارجن کچھ نہیں کماتا ہے۔ ایک پُرسکون سال کے دوران، دونوں واپسی پر گھسیٹتے ہیں اور بیک ٹیسٹ کی تجویز کے مقابلے میں فروخت کو کم منافع بخش بناتے ہیں۔ یہ ڈریگ وہ پریمیم ہے جو آپ زندہ رہنے کے لیے ادا کرتے ہیں - حقیقی، اور اس کے قابل، لیکن حقیقی۔</p>\n<p><strong>زیادہ سے زیادہ نقصان کا دن آپ کو بدترین ٹک پر روک سکتا ہے۔</strong> کبھی کبھی آپ گھبراہٹ میں سب کچھ بند کر دیتے ہیں اور دس منٹ بعد مارکیٹ پلٹ جاتی ہے۔ ہارڈ سٹاپ آپ کو کبھی کبھار اچھالنا پڑے گا۔ یہ ایک دن کو کبھی بھی بغیر کسی حد کے چلنے نہ دینے کی قیمت ہے، اور یہ ادا کرنے کے قابل قیمت ہے - ایک چھوٹی ہوئی اچھال قابل وصولی ہے۔ ایک اڑا ہوا اکاؤنٹ نہیں ہے.</p>\n<p><strong>فرق اب بھی آپ کے ہیج سے تجاوز کر سکتا ہے۔</strong> واقعی انتہائی سخت دن، حتیٰ کہ دور OTM بھی اس اقدام کو مکمل طور پر کور نہیں کر سکتا، اور مناسب قیمت پر تجارت کرنے کے لیے لیکویڈیٹی بہت پتلی ہو سکتی ہے۔ کوئی ڈھانچہ سیاہ ہنس کو بے درد نہیں بناتا۔ منصوبہ بقا خریدتا ہے - اگلے مہینے بیچنے کے لیے جینا - اس بات کی ضمانت نہیں کہ آپ بغیر کسی نقصان کے چلے جائیں۔</p>\n<p>یہ اس کا نقشہ ہے جہاں بیچنے والے کا خطرہ رہتا ہے، نہ کہ آپشن بیچنے یا کسی خاص طریقے سے ہیج کرنے کا مشورہ۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> آپشن بیچنے والے کا منصوبہ صارف کی تمام اقسام میں سخت ترین کیوں ہونا چاہیے؟</summary><p>کیونکہ بیچنے والے کا فائدہ محدود ہے جبکہ نقصان نہیں ہے۔ آپ چھوٹے اور اکثر جیتتے ہیں، لہذا ایک وقفہ والا دن کئی مہینوں کے پریمیم سے بڑا ہو سکتا ہے۔ منصوبہ زیادہ پیسہ کمانے کے لیے نہیں ہے - یہ اس نایاب دن سے بچنے کے لیے ہے جس دن آپ غلط ہیں۔</p>\n</details><details>\n<summary><strong>2.</strong> عملی طور پر \"صرف متعین خطرے\" کا کیا مطلب ہے، اور کبھی برہنہ کیوں؟</summary><p>ہر مختصر آپشن کو ایک ہی طرف سے ایک سستا، مزید طویل عرصے سے جوڑا جاتا ہے، لہذا آپ کے داخل ہونے سے پہلے آپ کا زیادہ سے زیادہ نقصان معلوم ہوجاتا ہے۔ ایک ننگے شارٹ میں کھلے عام نقصان ہوتا ہے۔ متعین خطرے کا مطلب یہ بھی ہے کہ زیادہ سے زیادہ چھوٹی معلوم حد تک محدود کرنا - مثال کے طور پر فی پوزیشن کیپٹل کے 2% سے کم۔</p>\n</details><details>\n<summary><strong>3.</strong> اپنے تمام مارجن کو استعمال کرنے کے بجائے مارجن بفر کیوں رکھیں؟</summary><p>اتار چڑھاؤ کی بڑھتی ہوئی واردات اس مارجن کو بڑھا دیتی ہے جو آپ کا بروکر بدترین لمحے میں مانگتا ہے۔ اگر آپ کو مکمل طور پر تعینات کیا گیا ہے، تو وہ اسپائیک بدصورت قیمت پر ایک مربع کو بند کر سکتا ہے۔ مارجن کا صرف 50-60% استعمال کرنے سے کشن رہ جاتا ہے تاکہ برا دن جبری دن نہ بن جائے۔</p>\n</details><details>\n<summary><strong>4.</strong> زیادہ سے زیادہ نقصان کا دن کیا ہے، اور جب آپ اسے مارتے ہیں تو آپ کیا کرتے ہیں؟</summary><p>یہ ایک مشکل یومیہ اسٹاپ ہے - تمام عہدوں پر ایک مقررہ روپے کا نقصان، مثال کے طور پر سرمائے کا 3%۔ جب آپ اس تک پہنچ جاتے ہیں، تو آپ سب کچھ بند کر دیتے ہیں اور دن کے لیے تجارت بند کر دیتے ہیں۔ اچھال کا انتظار نہیں۔ یہ سرکٹ بریکر ہے جو ایک خوفناک دن کو محض برے دن میں بدل دیتا ہے۔</p>\n</details><details>\n<summary><strong>5.</strong> داخلے سے پہلے ایڈجسٹمنٹ کے اصولوں کا فیصلہ ہارنے والی تجارت کے دوران کیوں کریں؟</summary><p>کھونے کی پوزیشن میں آپ جذباتی ہوتے ہیں، اور گھبراہٹ کی ایڈجسٹمنٹ عام طور پر اس نقصان کو چھپا دیتی ہے جب کہ خاموشی سے پوزیشن میں اضافہ ہوتا ہے - اکثر ننگے سائز کا اضافہ کرکے۔ پرسکون انداز میں لکھا ہوا ایک اصول (\"ایک ایڈجسٹمنٹ، رول یا بند، کبھی بھی ننگے سائز کا اضافہ نہ کریں\") آپ کو اس بہادر، مہنگے خیال سے بچاتا ہے جو آپ کو سرخ صبح میں آئے گا۔</p>\n</details>\n","toc":[{"level":2,"text":"بیچنے والے کو سخت ترین پلان کی ضرورت کیوں ہے۔","id":"why-the-seller-needs-the-tightest-plan"},{"level":2,"text":"چھ اصول، ترتیب میں","id":"the-six-rules-in-order"},{"level":2,"text":"ایک صفحہ کا منصوبہ بطور چیک لسٹ","id":"the-one-page-plan-as-a-checklist"},{"level":2,"text":"بیچنے والے کا منصوبہ بمقابلہ خریدار کا منصوبہ","id":"seller-s-plan-vs-buyer-s-plan"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"24":{"html":"<p>ارجن تقریباً 50,00,000 روپے کا اسٹاک پورٹ فولیو چلاتا تھا۔ مرکزی بجٹ سے ایک ہفتہ پہلے وہ گھبرا گیا تھا - بجٹ مارکیٹوں کو سختی سے منتقل کر سکتا ہے - لہذا اس نے اپنے آپ کو بچانے کے لیے کچھ NIFTY فیوچرز کو مختصر کیا۔ سمجھدار بجٹ آیا اور خاموشی سے چلا گیا، کچھ بھی ڈرامائی نہیں ہوا، اور ارجن کام میں مصروف ہوگیا۔ وہ بھول گیا تھا کہ شارٹ ابھی باقی ہے۔ اگلے دو مہینوں میں NIFTY تقریباً 8% بڑھ گیا۔ کاغذ پر اس کا اسٹاک اچھی طرح سے حاصل ہوا، لیکن اس کے بھولے ہوئے مختصر مستقبل میں تقریباً اتنی ہی رقم ضائع ہوئی۔ واضح طور پر ابھرتی ہوئی مارکیٹ میں اس نے کچھ بھی نہیں بنایا تھا - اور مراعات کے لیے مارجن اور لے جانے کے اخراجات ادا کیے تھے۔ اس کی انشورنس خاموشی سے اس کے اپنے پورٹ فولیو کے خلاف شرط میں بدل گئی تھی۔</p>\n<p>یہی ایک غلطی ہے جسے روکنے کے لیے یہ باب بنایا گیا ہے۔ ہیج ایک عارضی ٹول ہے جس میں کام اور آخری تاریخ ہے۔ جس لمحے آپ اس کے بارے میں بھول جاتے ہیں، یہ تحفظ ہونا چھوڑ دیتا ہے اور دوسری پوزیشن بن جاتا ہے جس کا آپ نے کبھی انعقاد نہیں کرنا تھا۔</p>\n<h2 id=\"a-hedge-is-a-borrowed-umbrella-not-a-new-home\">ہیج ایک مستعار چھتری ہے، نیا گھر نہیں۔</h2>\n<p>ایک چھتری کی طرح ہیج کے بارے میں سوچیں جو آپ ادھار لیتے ہیں کیونکہ بارش کی پیش گوئی ہے۔ آپ اسے طوفان کے لیے کھولتے ہیں، اور جب آسمان صاف ہو جاتا ہے تو آپ اسے بند کر دیتے ہیں اور واپس دیتے ہیں۔ آپ اسے کھلا رکھتے ہوئے گھر کے اندر گھومتے نہیں رہتے۔ ایک ہیج اسی طرح کام کرتا ہے: آپ اسے کسی خاص خطرے کے لیے لگاتے ہیں، جب وہ خطرہ فعال ہوتا ہے تو اسے پکڑ لیتے ہیں، اور خطرہ گزر جانے پر اسے اتار دیتے ہیں۔ اسے بہت لمبا کھلا رہنے دیں اور یہ آپ کے راستے میں آجائے گا - اور آپ کو لاگت آئے گی۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک ہیج ایک نظم و ضبط، عارضی ٹول ہے، ایسی پوزیشن نہیں جسے آپ بھول جاتے ہیں۔ بالکل اس کی وضاحت کریں کہ آپ کس چیز کی حفاظت کر رہے ہیں، اسے سائز دیں، اس کی قیمت لگائیں، اسے ایکسپائری دیں، اور فیصلہ کریں کہ یہ کب بند ہو جائے - اس سے پہلے کہ آپ اسے رکھیں۔</p>\n</div></div>\n<p>ذیل میں سب کچھ ایک عمل ہے، پانچ مراحل میں۔ کسی بھی ہیج سے پہلے پانچوں میں سے گزریں، اور ہیج ہیج رہتا ہے۔</p>\n<h2 id=\"step-1-define-the-exposure-name-it-or-you-cannot-hedge-it\">مرحلہ 1 - نمائش کی وضاحت کریں (اس کا نام دیں، یا آپ اسے بچا نہیں سکتے)</h2>\n<p>یہ وہ مرحلہ ہے جسے ابتدائی طور پر چھوڑ دیا جاتا ہے، اور اس کو چھوڑنے سے سب کچھ برباد ہو جاتا ہے۔ ہیج کرنے سے پہلے، ایک سادہ جملے میں تین چیزیں لکھیں:</p>\n<ul>\n<li><strong>کونسی پوزیشن</strong> آپ حفاظت کر رہے ہیں (ایک مخصوص اسٹاک، ایک ٹوکری، ایک مستقبل کی پوزیشن، مستقبل میں نقد کی ضرورت)۔</li>\n<li><strong>کتنا</strong> اس میں سے - روپے کی قدر خطرے میں ہے۔</li>\n<li><strong>کس چیز کے خلاف</strong> - صحیح خطرہ۔ ایک مارکیٹ وسیع کریش؟ ایک نتیجہ؟ ایک کرنسی کی حرکت؟</li>\n</ul>\n<p>\"میں مارکیٹ کے بارے میں گھبراتا ہوں\" ایک نمائش نہیں ہے۔ یہ سائز یا قیمت یا ختم نہیں کیا جا سکتا، لہذا یہ ہیج نہیں کیا جا سکتا ہے - اس کے بارے میں صرف فکر مند ہوسکتا ہے. \"میرا 50,00,000 روپے کا ایکویٹی پورٹ فولیو، بجٹ کے ارد گرد اگلے دو ہفتوں میں زبردست گراوٹ کے خلاف\" - <em>کہ</em> آپ ہیج کر سکتے ہیں، کیونکہ ہر لفظ بعد میں نمبر میں بدل جاتا ہے۔</p>\n<h2 id=\"step-2-size-the-hedge-full-or-partial-using-beta-and-notional\">مرحلہ 2 - ہیج کا سائز (مکمل یا جزوی، بیٹا اور تصوراتی استعمال کرتے ہوئے)</h2>\n<p>اب فیصلہ کریں کہ کتنا تحفظ خریدنا ہے۔ ہیجنگ ماڈیول سے دو خیالات کام کرتے ہیں: <strong>تصوراتی قدر</strong> (پورا روپیہ آپ کے ہیج کنٹرولز کی قدر کرتا ہے) اور <strong>بیٹا</strong> (جب انڈیکس حرکت کرتا ہے تو آپ کی ہولڈنگ کتنی حرکت کرتی ہے - 1.2 کے بیٹا کا مطلب ہے کہ یہ 20% زیادہ حرکت کرتا ہےNIFTYسے)۔</p>\n<p>کام کی مثال۔ ارجن کی کتاب تقریباً 1.2 سے NIFTY کے بیٹا کے ساتھ 50,00,000 روپے ہے۔</p>\n<ul>\n<li>ہیج کے لیے بیٹا ایڈجسٹ شدہ قدر = 50,00,000 x 1.2 = <strong>60,00,000 روپے</strong>.</li>\n<li>کہتے ہیں کہ NIFTY 24,000 کے قریب ہے اور لاٹ تقریباً 65 ہے (ایکسچینج کے ذریعے وقتاً فوقتاً لاٹ سائزز پر نظر ثانی کی جاتی ہے - ہمیشہ موجودہ کنٹریکٹ کی تفصیلات کو چیک کریں)، تو ایک فیوچر لاٹ 24,000 x 65 = کنٹرول کرتا ہے۔ <strong>15,60,000 روپے</strong> تصور کی.</li>\n<li>مکمل ہیج = 60,00,000 / 15,60,000 = <strong>تقریباً 3.8 لاٹ</strong>. وہ لاٹ کے ایک حصے کی تجارت نہیں کر سکتا، اس لیے مکمل ہیج کا مطلب ہے تقریباً 4 لاٹ اور جزوی ہیج کا مطلب کم ہے۔</li>\n</ul>\n<p>اے <strong>مکمل ہیج</strong> پورے اقدام کو منسوخ کرنے کا مقصد۔ اے <strong>جزوی ہیج</strong> - 2 لاٹ کا کہنا ہے کہ تقریباً 31,20,000 روپے کا تصور - اگر مارکیٹ میں اضافہ ہوتا ہے تو فائدہ کے لیے کمرے چھوڑتے ہوئے گرنے کو نرم کرتا ہے۔ زیادہ تر شروعات کرنے والے اوور ہیج کرتے ہیں: وہ اپنی نمائش سے زیادہ تحفظ خریدتے ہیں، جو مارکیٹ کے اپنے راستے پر چلنے کے وقت ہیج کو خاموشی سے ایک تازہ دشاتمک شرط میں بدل دیتا ہے۔ ہیج کو نمائش سے جوڑیں، کبھی بھی بڑا نہ ہو۔</p>\n<h2 id=\"step-3-know-the-all-in-cost-before-you-place-it\">مرحلہ 3 - لگانے سے پہلے تمام لاگت جانیں۔</h2>\n<p>ایک ہیج انشورنس ہے، اور انشورنس کا پریمیم ہوتا ہے۔ پورا بل شامل کریں۔ <em>پہلے</em> آپ عہد کریں، اس کے بعد نہیں:</p>\n<ul>\n<li>کے لیے <strong>حفاظتی ڈال</strong>: آپشن پریمیم (مثال کے طور پر 200 x 65 روپے = 13,000 روپے فی لاٹ)، نیز بروکریج، STT، اور بولی پوچھنا آپ کو کراس کر دیتا ہے۔</li>\n<li>کے لیے <strong>مستقبل ہیج</strong>: مسدود مارجن، لے جانے کی لاگت، اور - بڑا - <strong>الٹا آپ ہار مان لیتے ہیں۔</strong> اگر آپ کے مختصر ہونے کے دوران بازار بڑھتا ہے۔</li>\n</ul>\n<p>اگر دو ہفتوں کے لیے 50,00,000 روپے کی حفاظت پر آپ کو 45,000 روپے لاگت آتی ہے، تو یہ کتاب کا تقریباً 0.9% ہے۔ کیا یہ اس خطرے کے قابل ہے؟ کبھی کبھی ہاں، کبھی کبھی ایماندارانہ جواب ہوتا ہے \"اس کے بجائے پوزیشن کو ٹرم کریں۔\" آپ صرف اس وقت فیصلہ کر سکتے ہیں جب آپ کو نمبر معلوم ہو جائے۔</p>\n<h2 id=\"step-4-match-the-expiry-to-the-risk-window\">مرحلہ 4 - ایکسپائری کو رسک ونڈو سے جوڑیں۔</h2>\n<p>ایک ہیج کی عمر ہوتی ہے؛ اسے خطرے کا احاطہ کریں اور زیادہ نہیں۔ اگر آپ کا خطرہ معلوم تاریخ پر بجٹ ہے، تو آرام سے کوئی آپشن منتخب کریں یا مستقبل کی میعاد ختم ہو جائے۔ <em>شامل ہیں</em> وہ تاریخ - وہ نہیں جو ایک دن پہلے ختم ہو جائے، جو آپ کو بدترین لمحے میں برہنہ چھوڑے۔ اگر نمائش ایک چوتھائی تک چلتی ہے، تو آپ کو ماہانہ ہیج کو آگے بڑھانا پڑ سکتا ہے۔ ہیج کی زندگی کو رسک ونڈو سے جوڑیں: بہت چھوٹا اور خطرہ گزرنے سے پہلے ہی ختم ہوجاتا ہے۔ بہت طویل ہے اور آپ تحفظ کے لیے ادائیگی کرتے ہیں جس کی آپ کو مزید ضرورت نہیں ہے۔</p>\n<h2 id=\"step-5-decide-when-to-remove-it-before-you-enter\">مرحلہ 5 - فیصلہ کریں کہ اسے کب ہٹانا ہے (داخل ہونے سے پہلے)</h2>\n<p>ایگزٹ رول اسی وقت لکھیں جب آپ اندراج لکھتے ہیں۔ ٹرگر آسان ہے: <strong>جب نمائش ختم ہوجاتی ہے تو ہیج بند ہوجاتا ہے۔</strong></p>\n<ul>\n<li>ہیجنگ ایک <em>واقعہ</em>? ایونٹ ہضم ہونے کے بعد اسے سیشن سے ہٹا دیں۔</li>\n<li>ہیجنگ a <em>پوزیشن</em>? جب آپ اس پوزیشن کو بیچتے یا تراشتے ہیں تو ہیج کو ہٹا دیں۔</li>\n<li>پہنچنا <em>میعاد ختم</em>? ایک واضح انتخاب کریں - رول کریں یا ہٹائیں - اسے کبھی بھی خود بخود فراموش نہ ہونے دیں۔</li>\n</ul>\n<p>جس دن آپ ہیج لگاتے ہیں اس دن کیلنڈر کی یاد دہانی سیٹ کریں۔ ارجن کا سارا نقصان اس ایک قدم کی کمی سے ہوا۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 280\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک ٹائم لائن جو خطرے سے پہلے لگائے گئے ہیج کو دکھاتی ہے، جو رسک ونڈو سے ہوتی ہے، پھر جب خطرہ گزر جاتا ہے تو ہٹا دیا جاتا ہے - ایک سرخ ڈیشڈ برانچ کے ساتھ یہ ظاہر ہوتا ہے کہ اسے ہٹانا بھول جانا ہیج کو حادثاتی دشاتمک شرط میں بدل دیتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"280\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"32\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">ہیج کی زندگی: اسے لگانا، پکڑنا، ہٹانا</text>\n  <defs>\n    <marker id=\"arrL\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L7,3 L0,6 Z\" fill=\"#8b949e\"/></marker>\n  </defs>\n  <line x1=\"80\" y1=\"150\" x2=\"660\" y2=\"150\" stroke=\"#8b949e\" stroke-width=\"2\" marker-end=\"url(#arrL)\"/>\n  <rect x=\"180\" y=\"100\" width=\"300\" height=\"100\" rx=\"10\" fill=\"#4c72b0\" fill-opacity=\"0.12\" stroke=\"#4c72b0\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n  <text x=\"330\" y=\"92\" text-anchor=\"middle\" fill=\"#4c72b0\" font-size=\"11\" font-weight=\"700\" font-family=\"sans-serif\">خطرے کی کھڑکی</text>\n  <circle cx=\"180\" cy=\"150\" r=\"13\" fill=\"#55a868\"/>\n  <circle cx=\"330\" cy=\"150\" r=\"13\" fill=\"#4c72b0\"/>\n  <circle cx=\"480\" cy=\"150\" r=\"13\" fill=\"#55a868\"/>\n  <text x=\"180\" y=\"232\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">اسے لگاؤ</text>\n  <text x=\"180\" y=\"250\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">خطرے سے پہلے</text>\n  <text x=\"330\" y=\"232\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">کے ذریعے پکڑو</text>\n  <text x=\"330\" y=\"250\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">جبکہ خطرہ فعال ہے۔</text>\n  <text x=\"480\" y=\"232\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-weight=\"700\" font-family=\"sans-serif\">اسے ہٹا دیں۔</text>\n  <text x=\"480\" y=\"250\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">خطرہ گزر گیا ہے</text>\n  <line x1=\"480\" y1=\"150\" x2=\"660\" y2=\"110\" stroke=\"#c44e52\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/>\n  <text x=\"600\" y=\"96\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"11\" font-weight=\"700\" font-family=\"sans-serif\">ہٹانا بھول جاؤ</text>\n  <text x=\"600\" y=\"112\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"11\" font-family=\"sans-serif\">= حادثاتی شرط</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">ایک ہیج کا آغاز اور اختتام ہوتا ہے۔ آخر کو چھوڑ دیں اور یہ ایک ایسی پوزیشن بن جاتی ہے جس کا آپ نے کبھی انتخاب نہیں کیا۔</figcaption>\n</figure>\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>دو غلطیاں ایک ہیج کو زخم میں بدل دیتی ہیں۔ پہلا ہے۔ <strong>باہر نکلنے کے بغیر ایک ہیج</strong>: آپ اسے لگاتے ہیں، خطرہ گزر جاتا ہے، اور آپ اسے بھول جاتے ہیں - اس لیے ایک ابھرتی ہوئی مارکیٹ (ارجن) میں ایک چھوٹا ہیج خون بہہ رہا ہے یا خاموشی سے لمبا پوٹ ختم نہیں ہو جاتا۔ داخل ہونے سے پہلے ہمیشہ ہٹانے کا محرک اور ایک یاد دہانی سیٹ کریں۔ دوسرا ہے۔ <strong>ایک غیر متعینہ خطرے کو روکنا</strong>: \"میں ڈرتا ہوں\" کو سائز، قیمت، یا ختم نہیں کیا جا سکتا، لہذا ہیج بغیر کسی آف سوئچ کے گھومتا ہے۔ اگر آپ نمائش کو ایک جملے میں نام نہیں دے سکتے ہیں، تو آپ ہیجنگ نہیں کر رہے ہیں - آپ اندازہ لگا رہے ہیں، اور اس کی ادائیگی کر رہے ہیں۔</p>\n</div></div>\n<h2 id=\"your-one-page-hedger-plan\">آپ کا ایک صفحے کا ہیجر پلان</h2>\n<p>کوئی بھی ہیج لگانے سے پہلے اسے کاغذ پر یا نوٹ میں بھریں۔ اگر کوئی لائن خالی ہے تو آپ تیار نہیں ہیں۔</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>ایکسپوژر:</strong> میں ایک جملے میں پوزیشن، اس کی روپے کی قیمت، اور صحیح خطرے کا نام دے سکتا ہوں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>سائز:</strong> میں نے بیٹا اور تصوراتی سے ہیج کا سائز کیا ہے، اور مقصد کے مطابق مکمل یا جزوی انتخاب کیا ہے (کبھی بھی نمائش سے بڑا نہیں)۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>لاگت:</strong> میں تمام لاگت جانتا ہوں - پریمیم یا مارجن، اسپریڈ، چارجز، اور اوپر دیا گیا - اور یہ اس خطرے کے لیے قابل ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>میعاد ختم:</strong> ہیج کی زندگی پورے خطرے کی کھڑکی پر محیط ہے، اگر خطرہ اس سے زیادہ ہو جائے تو اسے رول کرنے کے منصوبے کے ساتھ۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>باہر نکلیں:</strong> میں نے ہٹانے کا محرک لکھا ہے (\"آج آتا ہے جب ___\") اور اس کے لیے کیلنڈر کی یاد دہانی ترتیب دی ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>صحت کی جانچ:</strong> یہ ایک ہیج ہے، ایک نقطہ نظر نہیں ہے. اگر میں صرف گرنے پر شرط لگانا چاہتا ہوں، تو مجھے ایسا کہنا چاہیے اور اسے شرط کے طور پر سائز دینا چاہیے، اسے \"تحفظ\" کے اندر نہیں چھپانا چاہیے۔</li>\n</ul>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 384\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک صفحے کا ہیجر پلان کارڈ جس میں پانچ اسٹیک شدہ قطاریں ہیں: نمائش کی وضاحت کریں، ہیج کا سائز بنائیں، لاگت جانیں، میعاد ختم ہونے سے مماثل ہوں، اور فیصلہ کریں کہ اسے کب ہٹانا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"384\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"34\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"17\" font-family=\"sans-serif\">ایک صفحے کا ہیجر پلان</text>\n  <text x=\"380\" y=\"54\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">ہیج لگانے سے پہلے ہر قطار کو بھریں۔</text>\n  <g font-family=\"sans-serif\">\n    <rect x=\"40\" y=\"68\" width=\"680\" height=\"52\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n    <rect x=\"40\" y=\"68\" width=\"6\" height=\"52\" rx=\"3\" fill=\"#4c72b0\"/>\n    <text x=\"70\" y=\"92\" fill=\"#4c72b0\" font-size=\"13\" font-weight=\"700\">1 نمائش</text>\n    <text x=\"230\" y=\"100\" fill=\"#cdd9e5\" font-size=\"12\">کون سی پوزیشن، کتنا، کس خطرے کے خلاف - ایک جملے میں</text>\n    <rect x=\"40\" y=\"128\" width=\"680\" height=\"52\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n    <rect x=\"40\" y=\"128\" width=\"6\" height=\"52\" rx=\"3\" fill=\"#37b3a4\"/>\n    <text x=\"70\" y=\"152\" fill=\"#37b3a4\" font-size=\"13\" font-weight=\"700\">2 سائز</text>\n    <text x=\"230\" y=\"160\" fill=\"#cdd9e5\" font-size=\"12\">مکمل یا جزوی - بیٹا x تصوراتی سے، کبھی بھی نمائش سے بڑا نہیں۔</text>\n    <rect x=\"40\" y=\"188\" width=\"680\" height=\"52\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n    <rect x=\"40\" y=\"188\" width=\"6\" height=\"52\" rx=\"3\" fill=\"#dd8452\"/>\n    <text x=\"70\" y=\"212\" fill=\"#dd8452\" font-size=\"13\" font-weight=\"700\">3 لاگت</text>\n    <text x=\"230\" y=\"220\" fill=\"#cdd9e5\" font-size=\"12\">آل ان بل - پریمیم یا مارجن، اسپریڈ، چارجز، اوپر دیا گیا۔</text>\n    <rect x=\"40\" y=\"248\" width=\"680\" height=\"52\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n    <rect x=\"40\" y=\"248\" width=\"6\" height=\"52\" rx=\"3\" fill=\"#8172b3\"/>\n    <text x=\"70\" y=\"272\" fill=\"#8172b3\" font-size=\"13\" font-weight=\"700\">4 ختم ہونا</text>\n    <text x=\"230\" y=\"280\" fill=\"#cdd9e5\" font-size=\"12\">پوری رسک ونڈو کو ڈھانپیں - اگر خطرہ ہیج سے زیادہ ہو جائے تو رول کریں۔</text>\n    <rect x=\"40\" y=\"308\" width=\"680\" height=\"52\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\"/>\n    <rect x=\"40\" y=\"308\" width=\"6\" height=\"52\" rx=\"3\" fill=\"#55a868\"/>\n    <text x=\"70\" y=\"332\" fill=\"#55a868\" font-size=\"13\" font-weight=\"700\">5 باہر نکلیں۔</text>\n    <text x=\"230\" y=\"340\" fill=\"#cdd9e5\" font-size=\"12\">تحریری ہٹانے کا محرک + ایک یاد دہانی - خطرہ ختم ہونے پر بند ہوجاتا ہے۔</text>\n  </g>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">پانچ قطاریں۔ خالی قطار کا مطلب ہے کہ ہیج تیار نہیں ہے۔</figcaption>\n</figure><h2 id=\"how-hedging-differs-by-who-you-are\">آپ کون ہیں اس سے ہیجنگ کس طرح مختلف ہے۔</h2>\n<p>پانچ مراحل سب کے لیے یکساں ہیں، لیکن جو چیز ان میں بھرتی ہے وہ بہت بدل جاتی ہے۔ ہٹانے کا محرک خاص طور پر: یہ ہمیشہ \"جب نمائش ختم ہوتی ہے\" - لیکن نمائش کا مطلب ہر فرد کے لیے کچھ مختلف ہوتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>وہ کیا ہیج کرتے ہیں۔</th>\n<th>عام ٹول</th>\n<th>رسک ونڈو</th>\n<th>کب ہٹانا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>ایک مرتکز اسٹاک یا پورا پورٹ فولیو، کریش یا کسی معروف واقعہ کے خلاف</td>\n<td>حفاظتی پوٹ یا مختصر انڈیکس مستقبل</td>\n<td>ایونٹ، یا ہولڈنگ کو تراشنے تک</td>\n<td>ایونٹ کے بعد، یا جب پوزیشن فروخت کی جاتی ہے۔</td>\n</tr>\n<tr>\n<td>ایف اینڈ او تاجر</td>\n<td>کھلی لیوریجڈ پوزیشن پر راتوں رات وقفہ کا خطرہ</td>\n<td>ایک مخالف ٹانگ، مزید-OTMاختیار، یا چھوٹا سائز</td>\n<td>اکثر اوقات ایک میعاد ختم ہونے تک</td>\n<td>جب پوزیشن بند ہوجاتی ہے یا واقعہ گزر جاتا ہے۔</td>\n</tr>\n<tr>\n<td>کاروبار</td>\n<td>ایک حقیقی نقد بہاؤ - ایک درآمد کنندہ کے ڈالر، ایک ان پٹ لاگت والی اجناس</td>\n<td>کرنسی یا کموڈٹی فیوچر یا فارورڈز</td>\n<td>انوائس یا ادائیگی کی تاریخ سے مماثل</td>\n<td>جب بنیادی نقدی کا بہاؤ واقعتاً طے ہو جاتا ہے۔</td>\n</tr>\n</tbody></table>\n<p>کاروباری معاملہ صاف ترین استاد ہے: ہیج موجود ہے۔ <em>صرف</em> کیونکہ ایک حقیقی ادائیگی آ رہی ہے، اور یہ ادائیگی کے دن ختم ہو جاتی ہے۔ ہر اچھے ہیج کو محسوس کرنا چاہئے کہ وہ کسی حقیقی چیز سے منسلک ہے۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>یہ عمل ہیجز کو نظم و ضبط بناتا ہے۔ یہ ان پر جادو نہیں کرتا۔ حدود کے بارے میں ایماندار رہو.</p>\n<p><strong>بنیاد خطرہ۔</strong> ایک انڈیکس ہیج بالکل ٹریک نہیں کرتا ہے۔ <em>آپ کا</em> اسٹاک آپ کے مخصوص حصص گرنے کے دوران انڈیکس برقرار رہ سکتا ہے، جس سے آپ کاغذ پر ہیجڈ رہتے ہیں اور پھر بھی کھوتے رہتے ہیں۔ ہیج خطرے کو کم کرتا ہے؛ یہ شاذ و نادر ہی اسے منسوخ کرتا ہے۔</p>\n<p><strong>چنکی آلات۔</strong> لاٹ سائز کا مطلب ہے کہ آپ اکثر ایک چھوٹی کتاب کو ٹھیک ٹھیک ہیج نہیں کر سکتے ہیں - ایک NIFTY لاٹ آپ کے پورے پورٹ فولیو سے بڑا ہو سکتا ہے۔ آپ کو اوور ہیجنگ اور ہیجنگ کے درمیان انتخاب کرنا چھوڑ دیا گیا ہے، اور اوور ہیجنگ ایک ایسا جال ہے جو حادثاتی شرط پیدا کرتا ہے۔</p>\n<p><strong>اپنے اعصاب کو اوور ہیج کرنے سے لاگت کو گھسیٹیں۔</strong> اگر آپ ہر ہلچل کو روکتے ہیں تو، پریمیم اور دیے گئے الٹا آپ کو آہستہ آہستہ خون بہاتے ہیں۔ ہر خطرہ بیمہ کرنے کے قابل نہیں ہے۔ جیسا کہ پہلے ابواب نے کہا تھا: ایک چھوٹی کتاب، ایک لمبی SIP، یا ایک چھوٹی سی پوزیشن عام طور پر ہیجڈ کے مقابلے میں تنہا چھوڑنا بہتر ہے۔</p>\n<p><strong>ایک ہیج ایسی پوزیشن کو ٹھیک نہیں کر سکتا جو بہت بڑی ہو۔</strong> اگر آپ کے سونے کا واحد طریقہ ہیجنگ ہے، تو اصل جواب ایک چھوٹی پوزیشن ہو سکتی ہے۔ کاٹنا اکثر حفاظت سے سستا اور صاف ہوتا ہے۔</p>\n<p>یہ تعلیم ہے، ذاتی مشورے نہیں۔ نکتہ نظم و ضبط ہے - نمائش کو نام دیں، اس کی قیمت لگائیں، اس کا وقت لگائیں، اور اسے ختم کریں - لہذا آپ کا تحفظ تحفظ ہی رہتا ہے اور یہ کبھی بھی شرط نہیں بنتا کہ آپ بھول گئے کہ آپ نے رکھا ہے۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> \"میں مارکیٹ کے بارے میں گھبراتا ہوں\" ایسی چیز کیوں نہیں ہے جسے آپ ہیج کر سکتے ہیں؟</summary><p>کیونکہ اس کا نہ کوئی سائز ہے، نہ قیمت ہے اور نہ ہی کوئی انتہا ہے۔ ایک ہیج کو ایک نامزد نمائش کی ضرورت ہوتی ہے - کون سی پوزیشن، کتنا، کس خطرے کے خلاف - لہذا اس کا سائز، لاگت، ایکسپائری دی گئی اور ہٹایا جا سکتا ہے۔ ایک مبہم احساس کا کوئی آف سوئچ نہیں ہوتا ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> ارجن کا ہیج ہارنے والی شرط میں کیسے بدل گیا؟</summary><p>اس نے بجٹ سے پہلے NIFTY فیوچر کو شارٹ کیا لیکن ایونٹ گزرنے کے بعد شارٹ کو کبھی نہیں ہٹایا۔ جیسا کہ دو مہینوں میں مارکیٹ میں تقریباً 8% کا اضافہ ہوا، بھولے ہوئے شارٹ نے تقریباً اس کے اسٹاک کو جو کچھ حاصل کیا وہ کھو دیا - اس لیے اس کی انشورنس اس کے اپنے پورٹ فولیو کے ساتھ ساتھ مارجن اور لے جانے والے اخراجات کے خلاف ایک حادثاتی شرط بن گئی۔</p>\n</details><details>\n<summary><strong>3.</strong> بیٹا اور تصور آپ کو ہیج کے سائز میں کیسے مدد کرتے ہیں؟</summary><p>بیٹا آپ کو بتاتا ہے کہ آپ کی ہولڈنگ انڈیکس کے مقابلے میں کتنی حرکت کرتی ہے، اس لیے آپ اس سے ہیج کرنے کے لیے رقم کو پیمانہ کرتے ہیں (بیٹا 1.2 پر 50,00,000 روپے کی کتاب کے لیے تقریباً 60,00,000 روپے کی ہیج کی ضرورت ہوتی ہے)۔ تصوراتی ہے کہ روپے کی قدر ایک فیوچر لاٹ کو کنٹرول کرتی ہے، لہذا دونوں کو تقسیم کرنے سے ایک مکمل ہیج کے لیے لاٹوں کی تعداد ملتی ہے۔</p>\n</details><details>\n<summary><strong>4.</strong> ایک ہیج میچ کی میعاد کیا ہونی چاہیے؟</summary><p>خطرے کی کھڑکی۔ ایک ایکسپائری کا انتخاب کریں جو آرام سے خطرے کا احاطہ کرے - ایسا نہیں جو ایونٹ سے ایک دن پہلے گزر جائے - اور اگر ایکسپائر ایک ہی میعاد ختم ہو جائے تو ہیج کو رول کرنے کا منصوبہ بنائیں۔</p>\n</details><details>\n<summary><strong>5.</strong> ہیج کو کب ہٹانا چاہئے؟</summary><p>جب نمائش ختم ہوجاتی ہے: ایونٹ کے بعد کا سیشن ہضم ہوجاتا ہے، جس لمحے آپ اس پوزیشن کو فروخت کرتے ہیں جس کی آپ حفاظت کر رہے تھے، یا ختم ہونے پر واضح رول یا ہٹانے کے فیصلے کے ذریعے۔ ٹرگر لکھیں اور جس دن آپ نے ہیج لگایا ہے اس دن ایک یاد دہانی سیٹ کریں۔</p>\n</details>\n","toc":[{"level":2,"text":"ہیج ایک مستعار چھتری ہے، نیا گھر نہیں۔","id":"a-hedge-is-a-borrowed-umbrella-not-a-new-home"},{"level":2,"text":"مرحلہ 1 - نمائش کی وضاحت کریں (اس کا نام دیں، یا آپ اسے بچا نہیں سکتے)","id":"step-1-define-the-exposure-name-it-or-you-cannot-hedge-it"},{"level":2,"text":"مرحلہ 2 - ہیج کا سائز (مکمل یا جزوی، بیٹا اور تصوراتی استعمال کرتے ہوئے)","id":"step-2-size-the-hedge-full-or-partial-using-beta-and-notional"},{"level":2,"text":"مرحلہ 3 - لگانے سے پہلے تمام لاگت جانیں۔","id":"step-3-know-the-all-in-cost-before-you-place-it"},{"level":2,"text":"مرحلہ 4 - ایکسپائری کو رسک ونڈو سے جوڑیں۔","id":"step-4-match-the-expiry-to-the-risk-window"},{"level":2,"text":"مرحلہ 5 - فیصلہ کریں کہ اسے کب ہٹانا ہے (داخل ہونے سے پہلے)","id":"step-5-decide-when-to-remove-it-before-you-enter"},{"level":2,"text":"آپ کا ایک صفحے کا ہیجر پلان","id":"your-one-page-hedger-plan"},{"level":2,"text":"آپ کون ہیں اس سے ہیجنگ کس طرح مختلف ہے۔","id":"how-hedging-differs-by-who-you-are"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"25":{"html":"<p>ارجن کے پاس اپنی اسکرین کے ساتھ ایک صفحے کی چیک لسٹ ٹیپ تھی، اور تین ماہ تک اس نے ہر تجارت سے پہلے اسے چلایا۔ چھوٹا، سائز، پرسکون، بورنگ - اور اس کے اکاؤنٹ سے ایک سال میں پہلی بار خون بہنا بند ہوگیا۔ پھر جمعرات کا روزہ آیا۔ ایک سیٹ اپ جسے وہ پسند کرتا تھا اڑ رہا تھا، اس کی نبض اوپر تھی، اور صفحہ اس کے راستے میں تیز رفتار ٹکرانے کی طرح محسوس ہوا۔ اس نے اسے چھوڑ دیا۔ اس نے اپنے معمول کے سائز کو دوگنا کیا، کبھی فیصلہ نہیں کیا کہ وہ کہاں سے نکلے گا، اور خالص جوش میں داخل ہوا۔ تجارت اس کے خلاف ہو گئی، وہ منجمد ہو گیا، اور اختتام تک اس نے نوے منٹ میں چھ ہفتوں کی محتاط پیشرفت واپس کر دی۔ اگلی صبح اس نے صفحہ دوبارہ پڑھا - اس بار آہستہ آہستہ - اور پہلی ہی سطر، \"کیا میں پرسکون اور آرام کر رہا ہوں؟\"، وہی تھی جس میں وہ ناکام ہو گیا تھا۔ اس کی حکمت عملی میں کچھ بھی غلط نہیں تھا۔ اس نے صرف ایک چیز کو چلانا چھوڑ دیا تھا جس نے اسے اپنے آپ سے بچایا تھا۔</p>\n<p>یہ پورے کورس کا آخری باب ہے، اور یہ صرف ایک کام کرتا ہے: یہ آپ کو وہ صفحہ دیتا ہے۔ دو کورسز میں ہر چیز - پوزیشن سائزنگ، سٹاپ لاسز، ہیجنگ، خوف اور لالچ کی نفسیات - سات چیکوں میں کمپریس ہوتی ہے جو آپ کسی بھی حقیقی رقم کے لائن پر جانے سے پہلے چلاتے ہیں۔ ایک بار نہیں۔ ہر ایک بار۔</p>\n<h2 id=\"the-one-page-that-ties-it-all-together\">ایک صفحہ جو اس سب کو ایک ساتھ باندھتا ہے۔</h2>\n<p>آپ نے بہت سے الگ الگ خیالات سیکھے ہیں۔ سرمائے کی بالٹیاں، ایک فیصد کا اصول، روزانہ نقصان کی حد، کب ہیج کرنا ہے اور کب نہیں، جرنلنگ، جھکاؤ، آپشن بیچنے والے کی دم۔ ایک پرسکون شام کو وہ سب سمجھ میں آتے ہیں۔ مسئلہ کبھی خیال کا نہیں ہوتا۔ مسئلہ اس لمحے کا ہے - تیز بازار، دوڑتا ہوا دل، ایک سیٹ اپ آپ پر چیخ رہا ہے - جب ہر سبق بخارات بن جاتا ہے اور جبلت کا پہیہ چلتا ہے۔</p>\n<p>ایک چیک لسٹ بالکل اس کو حل کرتی ہے۔ ہزاروں گھنٹے کے ساتھ ایک پائلٹ اب بھی ہر ٹیک آف سے پہلے ایک پرنٹ شدہ فہرست پڑھتا ہے، اس لیے نہیں کہ وہ اڑان بھرنا بھول گئے، بلکہ اس لیے کہ فہرست میں تھکاوٹ، پرجوش یا زیادہ اعتماد نہیں ہوتا۔ آپ کا سات سطری صفحہ ایک ہی ٹول ہے۔ یہ فیصلے کو گرما گرم لمحے سے باہر لے جاتا ہے اور واپس اس سکون میں لے جاتا ہے جہاں آپ نے اسے لکھا تھا۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 500\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک صفحہ کا ماسٹر چیک لسٹ کارڈ جس میں سات قطاریں، ہر ایک چیک باکس اور ایک لیبل: سرمایہ، خطرہ فی تجارت، زیادہ سے زیادہ نقصان، ہیج کا فیصلہ، جذباتی حالت، باہر نکلنے کا منصوبہ، اور جائزہ لینے کے عمل۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"500\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"36\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"17\" font-family=\"sans-serif\">ماسٹر چیک لسٹ - ہر حقیقی رقم کی تجارت سے پہلے چلائیں۔</text>\n  <text x=\"380\" y=\"56\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11.5\" font-family=\"sans-serif\">اگر کسی ایک باکس پر ایمانداری سے نشان نہیں لگایا جا سکتا ہے، تو آپ ابھی تک تجارت نہیں کرتے ہیں۔</text>\n  <g font-family=\"sans-serif\">\n    <rect x=\"30\" y=\"72\" width=\"700\" height=\"52\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\" stroke-width=\"1.5\"/>\n    <rect x=\"46\" y=\"88\" width=\"22\" height=\"22\" rx=\"5\" fill=\"none\" stroke=\"#55a868\" stroke-width=\"2\"/>\n    <text x=\"90\" y=\"98\" fill=\"#e6edf3\" font-size=\"13.5\" font-weight=\"700\">1CAPITAL</text>\n    <text x=\"90\" y=\"115\" fill=\"#cdd9e5\" font-size=\"11.5\">پیسے جو میں کھونے کا متحمل ہوں، صحیح بالٹی سے - کرایہ یا EMIs نہیں۔</text>\n    <rect x=\"30\" y=\"132\" width=\"700\" height=\"52\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\" stroke-width=\"1.5\"/>\n    <rect x=\"46\" y=\"148\" width=\"22\" height=\"22\" rx=\"5\" fill=\"none\" stroke=\"#4c72b0\" stroke-width=\"2\"/>\n    <text x=\"90\" y=\"158\" fill=\"#e6edf3\" font-size=\"13.5\" font-weight=\"700\">2 RISKPERTRADE</text>\n    <text x=\"90\" y=\"175\" fill=\"#cdd9e5\" font-size=\"11.5\">سائز اس لیے ایک نقصان پر تقریباً 1% سرمایہ خرچ ہوتا ہے، مزید نہیں۔</text>\n    <rect x=\"30\" y=\"192\" width=\"700\" height=\"52\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\" stroke-width=\"1.5\"/>\n    <rect x=\"46\" y=\"208\" width=\"22\" height=\"22\" rx=\"5\" fill=\"none\" stroke=\"#c44e52\" stroke-width=\"2\"/>\n    <text x=\"90\" y=\"218\" fill=\"#e6edf3\" font-size=\"13.5\" font-weight=\"700\">3 MAXLOSS</text>\n    <text x=\"90\" y=\"235\" fill=\"#cdd9e5\" font-size=\"11.5\">میری روزانہ اور ماہانہ اسٹاپ ٹریڈنگ کی حدیں مقرر ہیں، اور میں ان کے اندر ہوں۔</text>\n    <rect x=\"30\" y=\"252\" width=\"700\" height=\"52\" rx=\"10\" fill=\"#11161d\" stroke=\"#37b3a4\" stroke-width=\"1.5\"/>\n    <rect x=\"46\" y=\"268\" width=\"22\" height=\"22\" rx=\"5\" fill=\"none\" stroke=\"#37b3a4\" stroke-width=\"2\"/>\n    <text x=\"90\" y=\"278\" fill=\"#e6edf3\" font-size=\"13.5\" font-weight=\"700\">4 HEDGE DECISION</text>\n    <text x=\"90\" y=\"295\" fill=\"#cdd9e5\" font-size=\"11.5\">کیا مجھے ایک کی ضرورت ہے؟ اگر ہاں: اس کی قیمت کیا ہے اور یہ کب آتا ہے اس کا فیصلہ کیا جاتا ہے۔</text>\n    <rect x=\"30\" y=\"312\" width=\"700\" height=\"52\" rx=\"10\" fill=\"#11161d\" stroke=\"#8172b3\" stroke-width=\"1.5\"/>\n    <rect x=\"46\" y=\"328\" width=\"22\" height=\"22\" rx=\"5\" fill=\"none\" stroke=\"#8172b3\" stroke-width=\"2\"/>\n    <text x=\"90\" y=\"338\" fill=\"#e6edf3\" font-size=\"13.5\" font-weight=\"700\">5 EMOTIONALSTATE</text>\n    <text x=\"90\" y=\"355\" fill=\"#cdd9e5\" font-size=\"11.5\">پرسکون اور آرام - جھکاؤ پر نہیں، پیچھا نہیں، انتقام کی تجارت نہیں.</text>\n    <rect x=\"30\" y=\"372\" width=\"700\" height=\"52\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\" stroke-width=\"1.5\"/>\n    <rect x=\"46\" y=\"388\" width=\"22\" height=\"22\" rx=\"5\" fill=\"none\" stroke=\"#dd8452\" stroke-width=\"2\"/>\n    <text x=\"90\" y=\"398\" fill=\"#e6edf3\" font-size=\"13.5\" font-weight=\"700\">6 EXITPLAN</text>\n    <text x=\"90\" y=\"415\" fill=\"#cdd9e5\" font-size=\"11.5\">میں کہاں سے نکلتا ہوں - سٹاپ اور ٹارگٹ - میں داخل ہونے سے پہلے ہی طے ہوتا ہے۔</text>\n    <rect x=\"30\" y=\"432\" width=\"700\" height=\"52\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\" stroke-width=\"1.5\"/>\n    <rect x=\"46\" y=\"448\" width=\"22\" height=\"22\" rx=\"5\" fill=\"none\" stroke=\"#4c72b0\" stroke-width=\"2\"/>\n    <text x=\"90\" y=\"458\" fill=\"#e6edf3\" font-size=\"13.5\" font-weight=\"700\">7 REVIEWPROCESS</text>\n    <text x=\"90\" y=\"475\" fill=\"#cdd9e5\" font-size=\"11.5\">میں اس تجارت کو جرنل کروں گا، اور میں ہر ہفتے جریدے کا جائزہ لیتا ہوں۔</text>\n  </g>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">سات لائنیں۔ دونوں کورسز کے پورے، ایک صفحے پر آپ ہر بار پڑھتے ہیں۔</figcaption>\n</figure><h2 id=\"the-seven-checks-one-line-each\">سات چیک، ہر ایک لائن</h2>\n<p>ہر لائن مقصد کے لحاظ سے مختصر ہے۔ گہرائی پہلے ابواب میں رہتی ہے؛ یہاں آپ صرف اس بات کی تصدیق کرتے ہیں کہ جواب اب بھی ہاں میں ہے۔</p>\n<p><strong>1. سرمایہ۔</strong> کیا یہ رقم آپ اپنے رہنے کے طریقے کو تبدیل کیے بغیر کھونے کے متحمل ہوسکتے ہیں؟ یہ صحیح بالٹی سے آنا چاہیے - آپ کی تجارت یا خطرے کی رقم - کبھی بھی ہنگامی فنڈ، کرایہ یا قرض نہیں۔ اگر اس عہدے کے مکمل نقصان سے آپ کے خاندان کو تکلیف پہنچے گی، تو پوزیشن پہلے ہی غلط ہے۔</p>\n<p><strong>2. فی تجارت خطرہ۔</strong> کیا آپ نے اس طرح سائز کیا ہے کہ ایک نقصان پر آپ کے سرمائے کا صرف ایک چھوٹا، مقررہ ٹکڑا خرچ ہوتا ہے - تقریباً 1% عام اصول ہے؟ کہو کہ آپ کے پاس 2,00,000 روپے ہیں۔ ایک فیصد 2000 روپے ہے۔ اسٹاپ کا فاصلہ، آپ کا جوش نہیں، یہ طے کرتا ہے کہ آپ کتنے شیئرز یا لاٹ لے سکتے ہیں۔</p>\n<p><strong>3. زیادہ سے زیادہ نقصان۔</strong> کیا آپ نے روزانہ اور ماہانہ کی حد مقرر کی ہے، اور کیا آپ اب بھی دونوں کے اندر ہیں؟ 4,000 روپے کا روزانہ سٹاپ کا مطلب ہے کہ آپ اس دن کے لیے اسکرین بند کر دیتے ہیں جب آپ اسے مارتے ہیں۔ حد کا فیصلہ مارکیٹ کھلنے سے پہلے، جب آپ پرسکون ہوتے ہیں۔</p>\n<p><strong>4. ہیج کا فیصلہ۔</strong> کیا آپ کو اس پوزیشن کے لیے درحقیقت تحفظ کی ضرورت ہے - ایک بڑی کتاب ایک تقریب میں، توجہ مرکوز یا راتوں رات خطرہ - یا ہیج صرف بات کرنے سے ڈرتا ہے؟ اگر آپ ہیج کرتے ہیں، تو آپ نے پہلے ہی اس کی قیمت کا تعین کر لیا ہے اور فیصلہ کیا ہے کہ یہ کب آتا ہے۔ اگر آپ کو اس کی ضرورت نہیں ہے، تو آپ اسے صاف طور پر چھوڑ دیتے ہیں۔ اکثر سستا اقدام صرف ایک چھوٹی پوزیشن ہوتی ہے۔</p>\n<p><strong>5. جذباتی حالت۔</strong> کیا آپ پرسکون، آرام دہ، اور صاف ہیں - یا جلدی میں ہیں، آخری نقصان سے ناراض ہیں، یا کسی ایسی حرکت کا پیچھا کر رہے ہیں جو آپ سے چھوٹ گئی ہے؟ یہ وہ لائن ہے جو ارجن فیل ہو گئی۔ اگر آپ جھکاؤ پر ہیں، تو صرف درست تجارتی سائز صفر ہے۔</p>\n<p><strong>6. باہر نکلنے کا منصوبہ۔</strong> کیا آپ جانتے ہیں، ابھی، اگر آپ غلط ہیں تو آپ کہاں سے نکلتے ہیں اور اگر آپ صحیح ہیں تو آپ کہاں سے فائدہ اٹھاتے ہیں؟ آپ کے داخل ہونے سے پہلے دونوں نے فیصلہ کیا۔ درمیانی تجارت کا انتخاب کیا گیا ایک ایگزٹ صرف ایک نمبر پہننے والا ایک جذبہ ہے۔</p>\n<p><strong>7. عمل کا جائزہ لیں۔</strong> کیا آپ اس تجارت کو لاگ کریں گے - سیٹ اپ، سائز، وجہ، جذبات، نتیجہ - اور کیا آپ ہر ہفتے اس جریدے کا جائزہ لیں گے؟ یہ وہ لوپ ہے جو نقصانات کو دہرانے کے بجائے سبق میں بدل دیتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>چیک لسٹ کاغذی کارروائی نہیں ہے۔ یہ وہ لمحہ ہے جب آپ جذباتی، تجارت کے دوران آپ کو پرسکون کرنے کے لیے فیصلہ سونپتے ہیں، آپ کی منصوبہ بندی کرتے ہیں۔ ہر حقیقی رقم کے عزم سے پہلے ساتوں کو چلائیں۔ اگر ایک باکس پر بھی ایمانداری سے نشان نہیں لگایا جا سکتا تو جواب \"چھوٹی تجارت\" نہیں ہے - یہ ہے \"ابھی تک تجارت نہ کریں۔\"</p>\n</div></div>\n<h2 id=\"run-it-like-a-gate-not-a-suggestion\">اسے گیٹ کی طرح چلائیں، تجویز نہیں۔</h2>\n<p>سات چیکوں کے بارے میں ایک گیٹ کے طور پر سوچیں جو تمام سات خانوں کو ٹک کرنے تک بند رہتا ہے۔ پانچ نہیں۔ نہیں \"چھ اور ساتویں کے بارے میں ایک اچھا احساس.\" تمام سات۔ جس دن آپ نے ایک سلائڈ ہونے دیا کیونکہ سیٹ اپ بہت اچھا لگتا ہے بالکل اسی دن گمشدہ باکس اہمیت رکھتا تھا۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک گیٹ جو تجارت کے لیے سبز روشنی کے لیے کھلتا ہے جب تمام سات خانوں کو ٹک کیا جاتا ہے۔ اگر کوئی خانہ خالی ہے تو راستہ سرخ روشنی کی طرف جاتا ہے یعنی تجارت نہ کریں۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <defs>\n    <marker id=\"ckg\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#55a868\"/></marker>\n    <marker id=\"ckr\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#c44e52\"/></marker>\n  </defs>\n  <text x=\"380\" y=\"34\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">گیٹ تبھی کھلتا ہے جب ساتوں کو ٹک کیا جاتا ہے۔</text>\n  <g font-family=\"sans-serif\">\n    <rect x=\"40\" y=\"60\" width=\"200\" height=\"180\" rx=\"10\" fill=\"#11161d\" stroke=\"#30363d\" stroke-width=\"1.5\"/>\n    <text x=\"140\" y=\"84\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"12\" font-weight=\"700\">7 چیک</text>\n    <g fill=\"#55a868\">\n      <path d=\"M58,104 l5,5 l9,-11\" stroke=\"#55a868\" stroke-width=\"2.5\" fill=\"none\"/>\n      <path d=\"M58,128 l5,5 l9,-11\" stroke=\"#55a868\" stroke-width=\"2.5\" fill=\"none\"/>\n      <path d=\"M58,152 l5,5 l9,-11\" stroke=\"#55a868\" stroke-width=\"2.5\" fill=\"none\"/>\n      <path d=\"M58,176 l5,5 l9,-11\" stroke=\"#55a868\" stroke-width=\"2.5\" fill=\"none\"/>\n      <path d=\"M58,200 l5,5 l9,-11\" stroke=\"#55a868\" stroke-width=\"2.5\" fill=\"none\"/>\n      <path d=\"M58,224 l5,5 l9,-11\" stroke=\"#55a868\" stroke-width=\"2.5\" fill=\"none\"/>\n    </g>\n    <text x=\"84\" y=\"106\" fill=\"#cdd9e5\" font-size=\"11\">سرمایہ</text>\n    <text x=\"84\" y=\"130\" fill=\"#cdd9e5\" font-size=\"11\">خطرہ فی تجارت</text>\n    <text x=\"84\" y=\"154\" fill=\"#cdd9e5\" font-size=\"11\">زیادہ سے زیادہ نقصان</text>\n    <text x=\"84\" y=\"178\" fill=\"#cdd9e5\" font-size=\"11\">ہیج فیصلہ</text>\n    <text x=\"84\" y=\"202\" fill=\"#cdd9e5\" font-size=\"11\">باہر نکلنے کا منصوبہ</text>\n    <text x=\"84\" y=\"226\" fill=\"#cdd9e5\" font-size=\"11\">جائزہ سیٹ</text>\n    <text x=\"140\" y=\"252\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"10.5\">+ جذباتی حالت: پرسکون</text>\n    <line x1=\"248\" y1=\"120\" x2=\"320\" y2=\"120\" stroke=\"#55a868\" stroke-width=\"2\" marker-end=\"url(#ckg)\"/>\n    <circle cx=\"400\" cy=\"120\" r=\"42\" fill=\"#11161d\" stroke=\"#55a868\" stroke-width=\"3\"/>\n    <circle cx=\"400\" cy=\"120\" r=\"22\" fill=\"#55a868\"/>\n    <text x=\"400\" y=\"190\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"13\" font-weight=\"700\">GREEN</text>\n    <text x=\"400\" y=\"208\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\">تجارت کی جگہ</text>\n    <line x1=\"248\" y1=\"200\" x2=\"320\" y2=\"232\" stroke=\"#c44e52\" stroke-width=\"2\" stroke-dasharray=\"5 4\" marker-end=\"url(#ckr)\"/>\n    <text x=\"270\" y=\"226\" fill=\"#c44e52\" font-size=\"10.5\">کوئی بھی خانہ خالی ہے۔</text>\n    <circle cx=\"610\" cy=\"120\" r=\"42\" fill=\"#11161d\" stroke=\"#c44e52\" stroke-width=\"3\"/>\n    <circle cx=\"610\" cy=\"120\" r=\"22\" fill=\"#c44e52\"/>\n    <text x=\"610\" y=\"190\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"13\" font-weight=\"700\">RED</text>\n    <text x=\"610\" y=\"208\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\">انتظار کریں، یا صفر تجارت کریں۔</text>\n    <line x1=\"445\" y1=\"240\" x2=\"565\" y2=\"150\" stroke=\"#c44e52\" stroke-width=\"2\" stroke-dasharray=\"5 4\" marker-end=\"url(#ckr)\"/>\n  </g>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">گرین کو ساتوں کی ضرورت ہے۔ ایک خالی خانہ آپ کو سرخ رنگ میں بھیجتا ہے - اور سرخ کا مطلب انتظار کرنا ہے۔</figcaption>\n</figure>\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>ایک غلطی جو ہر چیز کو کالعدم کرتی ہے جب آپ پرجوش یا جلدی میں ہوں تو صفحہ کو چھوڑنا ہے۔ یہ خاص طور پر اس وقت ہوتا ہے جب آپ کو اس کی سب سے زیادہ ضرورت ہوتی ہے، اور خاص طور پر جب یہ وقت کے ضیاع کی طرح محسوس ہوتا ہے۔ تیز سیٹ اپ، خلا، \"میں اسے یاد کروں گا\" گھبراہٹ - یہ چیک کو چھوڑنے کی وجوہات نہیں ہیں، یہ الارم ہیں جو آپ کو اسے چلانے کے لیے کہتے ہیں۔ ایک سیٹ اپ جو چیک لسٹ کے نوے سیکنڈ تک زندہ نہیں رہ سکتا وہ کبھی بھی اچھا سیٹ اپ نہیں تھا۔ کل دوبارہ مارکیٹ کھلے گی۔ ایک اڑا ہوا اکاؤنٹ نہیں کرتا.</p>\n</div></div>\n<h2 id=\"the-master-checklist-copy-this\">ماسٹر چیک لسٹ (اسے کاپی کریں)</h2>\n<p>اسے وہیں رکھیں جہاں آپ اسے دیکھیں گے۔ حقیقی رقم کا ارتکاب کرنے سے پہلے ہر باکس پر نشان لگائیں، اگر ضروری ہو تو اونچی آواز میں۔</p>\n<ul>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>سرمایہ</strong> - یہ دائیں بالٹی سے خطرے کی رقم ہے۔ اسے کھونے سے میرے کرایے، EMIs یا ایمرجنسی فنڈ کے بارے میں کچھ نہیں بدلتا۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>خطرہ فی تجارت</strong> - سائز کا اس طرح ایک نقصان میرے سرمائے کا تقریباً 1% ہے، جو میرے اسٹاپ کے فاصلے سے طے ہوتا ہے، میرے موڈ سے نہیں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>زیادہ سے زیادہ نقصان</strong> - میری روزانہ اور ماہانہ اسٹاپ ٹریڈنگ کی حدیں مقرر ہیں، اور میں آج بھی دونوں کے اندر ہوں۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>ہیج کا فیصلہ</strong> - میں نے فیصلہ کیا ہے کہ کیا مجھے تحفظ کی ضرورت ہے؛ اگر ہاں، تو اس کی لاگت اور اس سے نکلنے کا منصوبہ پہلے سے ہی طے شدہ ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>جذباتی حالت</strong> - میں پرسکون اور پر سکون ہوں، جھکاؤ پر نہیں، پیچھا نہیں کر رہا، نقصان کا بدلہ نہیں لینا۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>باہر نکلنے کا منصوبہ</strong> - میں داخل ہونے سے پہلے میرا اسٹاپ اور میرا ہدف لکھ دیا جاتا ہے۔</li>\n<li><input disabled=\"\" type=\"checkbox\"> <strong>عمل کا جائزہ لیں۔</strong> - میں اس تجارت کو جرنل کروں گا اور میں اپنے جریدے کا ہفتہ وار جائزہ لیتا ہوں۔</li>\n</ul>\n<table>\n<thead>\n<tr>\n<th>چیک کریں۔</th>\n<th>پاس ایسا لگتا ہے۔</th>\n<th>فیل لگ رہا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>سرمایہ</td>\n<td>اسپیئر خطرے کی رقم، صحیح بالٹی</td>\n<td>ادھار، یا رقم آپ کو جلد ہی درکار ہے۔</td>\n</tr>\n<tr>\n<td>خطرہ فی تجارت</td>\n<td>سٹاپ پر تقریباً 1%</td>\n<td>\"میں صرف ایک بار ایک بڑا لوں گا\"</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>حدیں مقرر ہیں، آپ ان کے اندر ہیں۔</td>\n<td>کوئی حد نہیں، یا آج ہی گزر چکی ہے۔</td>\n</tr>\n<tr>\n<td>ہیج کا فیصلہ</td>\n<td>ضرورت اور قیمت دونوں نے فیصلہ کیا۔</td>\n<td>مبہم خوف سے بچنا</td>\n</tr>\n<tr>\n<td>جذباتی حالت</td>\n<td>پرسکون، آرام، صاف</td>\n<td>جلدی، غصہ، پیچھا</td>\n</tr>\n<tr>\n<td>باہر نکلنے کا منصوبہ</td>\n<td>رکیں اور پہلے سے سیٹ کو نشانہ بنائیں</td>\n<td>\"میں فیصلہ کروں گا جیسے ہی یہ چلتا ہے\"</td>\n</tr>\n<tr>\n<td>عمل کا جائزہ لیں۔</td>\n<td>جرنل + ہفتہ وار جائزہ</td>\n<td>کوئی ریکارڈ، کوئی جائزہ نہیں۔</td>\n</tr>\n</tbody></table>\n<h2 id=\"every-user-type-runs-this\">ہر صارف کی قسم اسے چلاتی ہے۔</h2>\n<p>سات لائنیں تبدیل نہیں ہوتیں۔ ان کے پیچھے صرف نمبر ہی کرتے ہیں۔ طویل مدتی سرمایہ کار \"خطرہ فی تجارت\" کو ایک مختص کے اندر پوزیشن کے سائز کے طور پر پڑھتا ہے۔ انٹرا ڈے ٹریڈر \"زیادہ سے زیادہ نقصان\" کو روزانہ مشکل روپے کے اسٹاپ کے طور پر پڑھتا ہے۔ آپشن سیلر \"ہیج فیصلہ\" کو اسٹینڈ ٹیل ہیج اور مارجن بفر کے طور پر پڑھتا ہے۔ ایک ہی صفحہ، وہی گیٹ - چاہے آپ SIP سرمایہ کار ہوں، سوئنگ ٹریڈر، فیوچر ٹریڈر، آپشن خریدار، آپشن بیچنے والے، یا ہیجر۔ اس سے پہلے کے ابواب میں اپنے ایک صفحے کے منصوبے سے صحیح نمبر کھینچیں، اور ماسٹر چیک لسٹ ان سب کے اوپر بیٹھتی ہے۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>چیک لسٹ ایک طاقتور ٹول ہے، جادوئی نہیں۔ اس کی حدود کے بارے میں ایماندار رہو.</p>\n<p>یہ ایک بری حکمت عملی کو نہیں بچا سکتا۔ اگر آپ کے طریقہ کار میں کوئی حقیقی برتری نہیں ہے، تو صفحہ کو مکمل طور پر چلانے کا مطلب صرف یہ ہے کہ آپ زیادہ آہستہ اور شائستگی سے ہار جاتے ہیں۔ چیک لسٹ آپ کے سرمائے اور دماغ کی حفاظت کرتی ہے۔ یہ جیتنے والا نظام نہیں بناتا۔ یہ کہیں اور سے آنا ہے۔</p>\n<p>یہ تب ہی کام کرتا ہے جب آپ ایماندار ہوں۔ ساری چیز اس وقت ختم ہو جاتی ہے جب آپ \"میں پرسکون ہوں\" پر ٹک لگاتے ہیں جب آپ کے ہاتھ کانپ رہے ہوتے ہیں، یا کرائے کی رقم کو \"رسک کیپیٹل\" کہتے ہیں کیونکہ سیٹ اپ اچھا لگتا ہے۔ صفحہ آپ کے دماغ کو نہیں پڑھ سکتا - یہ صرف اس سچائی کی عکاسی کر سکتا ہے جو آپ اس میں ڈالتے ہیں۔ کسی ایسے باکس پر نشان لگانا جس پر آپ نے کمائی نہیں کی ہے اس سے کہیں زیادہ بدتر ہے کہ کوئی باکس نہ ہو، کیونکہ یہ حفاظت کی طرح محسوس ہوتا ہے۔</p>\n<p>اور یہ ایک رسم بن سکتی ہے جسے آپ پڑھنا چھوڑ دیتے ہیں۔ سو تجارت کے بعد سات لائنیں ایک اضطراری شکل میں دھندلی ہوسکتی ہیں جسے آپ بغیر سوچے سمجھے ٹیپ کرتے ہیں۔ اسے زندہ رکھیں: کبھی کبھار ہر سطر کو آہستہ سے پڑھیں اور پوچھیں کہ کیا ایماندارانہ جواب واقعی ہاں میں ہے۔ جس دن یہ وال پیپر بن جاتا ہے وہ دن وہ آپ کی حفاظت کرنا چھوڑ دیتا ہے۔</p>\n<p>یہ پورے سفر کا اختتام ہے، اس لیے میں بات کو صاف صاف کہتا ہوں۔ بقا پہلے آتا ہے، منافع دوسرے آتا ہے. آپ کسی ایسے اکاؤنٹ کو کمپاؤنڈ نہیں کر سکتے جس کو اڑا دیا گیا ہو، اور آپ ایسی مارکیٹ کو تجارت نہیں کر سکتے جسے آپ کو چھوڑنے پر مجبور کیا گیا ہو۔ نظم و ضبط کبھی بھی ایسی شخصیت نہیں تھی جس کے ساتھ آپ پیدا ہوئے ہو یا اس کے بغیر - یہ ایک نظام ہے، چھوٹے اصولوں کا ایک مجموعہ اور ایک چھوٹا صفحہ ہے جو جذبات کے آنے سے پہلے آپ کے لیے فیصلہ کرتا ہے۔ اپنے سرمائے، اپنے سائز، اپنے نقصانات، اپنے ہیجز، اپنی ذہنی حالت، اپنے اخراج، اور اپنے جائزہ لوپ پر عبور حاصل کریں، اور منافع قسمت کی بجائے وقت اور صبر کا سوال بن جاتا ہے۔</p>\n<p>ان دونوں کورسز کا مقصد اس مہینے میں کبھی بھی آپ کو امیر نہیں بنانا تھا۔ یہ یقینی بنانا تھا کہ آپ اگلے سال بھی یہاں موجود ہیں - اب بھی سیکھ رہے ہیں، ابھی بھی کھیل میں، آپ کے سرمائے اور آپ کے اعتماد کو برقرار ہے۔ اگر آپ ان سب میں سے ایک چیز لیں تو یہ صفحہ لے لیں۔ اس کی ہر سطر کے نیچے فاؤنڈیشنز کے لیے - بالٹیاں، سائز سازی کی ریاضی، سٹاپ لاسز، ڈرا ڈاؤن میتھس - رسک مینجمنٹ کورس پر واپس جائیں۔ یہ وہ جگہ ہے جہاں یہ چیک لسٹ بنائی گئی تھی۔ آخر تک پڑھنے کا شکریہ۔ اب وہ تاجر بنیں جو صفحہ چلاتا ہے۔</p>\n<p>یہ باب، اور یہ پورا کورس، صرف تعلیم کے لیے ہے اور سرمایہ کاری کا مشورہ نہیں ہے۔ یہاں کا ہر نمبر ایک مثال ہے، نہ کہ آپ کے اپنے پیسوں کی سفارش۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> ماسٹر چیک لسٹ کا واحد کام کیا ہے؟</summary><p>فیصلے کو گرما گرم، تجارت کے وقت سے باہر لے جانے کے لیے اور آپ کے اصولوں کو لکھنے والے پر سکون، منصوبہ بندی کے ورژن پر واپس جانے کے لیے۔ یہ دونوں کورسز کو سات چیکوں میں کمپریس کرتا ہے جو آپ کسی بھی حقیقی رقم کے عزم سے پہلے چلاتے ہیں۔</p>\n</details><details>\n<summary><strong>2.</strong> چیک لسٹ میں شامل سات شعبوں کے نام بتائیں۔</summary><p>سرمایہ، خطرہ فی تجارت، زیادہ سے زیادہ نقصان، ہیج کا فیصلہ، جذباتی حالت، ایگزٹ پلان، اور جائزہ کا عمل۔ ہر ایک ایک لائن ہے جس کی آپ تصدیق کرتے ہیں کہ ابھی بھی ہاں ہے۔</p>\n</details><details>\n<summary><strong>3.</strong> اگر سات خانوں میں سے کسی ایک پر بھی ایمانداری سے نشان نہیں لگایا جا سکتا تو آپ کیا کریں گے؟</summary><p>آپ ابھی تک تجارت نہیں کرتے ہیں۔ گیٹ صرف اس وقت کھلتا ہے جب ساتوں سبز ہوں۔ ایک خالی خانے کا مطلب ہے انتظار کریں، یا صفر کے سائز کی تجارت کریں - نہ کہ \"تھوڑا چھوٹا اور امید سے تجارت کریں۔\"</p>\n</details><details>\n<summary><strong>4.</strong> جب آپ جلدی یا پرجوش محسوس کرتے ہیں تو چیک لسٹ کو چھوڑنا سب سے زیادہ خطرناک کیوں ہے؟</summary><p>کیونکہ رش اور جوش وہ حالات ہیں جو آپ کو بڑا بنا دیتے ہیں، باہر نکلنا چھوڑ دیتے ہیں، اور آپ کی جذباتی حالت کو نظر انداز کر دیتے ہیں۔ تیز سیٹ اپ جو آپ کو صفحہ کو چھوڑنے پر اکساتا ہے وہ الارم ہے جو آپ کو اسے چلانے کے لیے بتاتا ہے۔ ایک سیٹ اپ جو چیکنگ کے نوے سیکنڈ تک زندہ نہیں رہ سکتا کبھی بھی لینے کے قابل نہیں تھا۔</p>\n</details><details>\n<summary><strong>5.</strong> چیک لسٹ آپ کے لیے کیا نہیں کر سکتی؟</summary><p>یہ کوئی حکمت عملی طے نہیں کر سکتا جس کی کوئی برتری نہیں ہے، یہ کام نہیں کر سکتا اگر آپ بے ایمانی سے باکس کو نشان زد کرتے ہیں، اور اگر یہ ایک بے سوچے سمجھے رسم بن جائے تو یہ طاقت کھو دیتا ہے۔ یہ آپ کے سرمائے اور آپ کی ذہنیت کی حفاظت کرتا ہے، لیکن جیتنے کا طریقہ اور ایمانداری آپ سے آنی چاہیے۔</p>\n</details>\n","toc":[{"level":2,"text":"ایک صفحہ جو اس سب کو ایک ساتھ باندھتا ہے۔","id":"the-one-page-that-ties-it-all-together"},{"level":2,"text":"سات چیک، ہر ایک لائن","id":"the-seven-checks-one-line-each"},{"level":2,"text":"اسے گیٹ کی طرح چلائیں، تجویز نہیں۔","id":"run-it-like-a-gate-not-a-suggestion"},{"level":2,"text":"ماسٹر چیک لسٹ (اسے کاپی کریں)","id":"the-master-checklist-copy-this"},{"level":2,"text":"ہر صارف کی قسم اسے چلاتی ہے۔","id":"every-user-type-runs-this"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true},"26":{"html":"<p>میرا نے کچھ سال پہلے سے ایک صاف ستھرا مفتPDFپایا اور اس پر انجیل کی طرح بھروسہ کیا۔ اس نے کہا کہ ایک NIFTY لاٹ 50 یونٹس تھا، لہذا یہ وہ نمبر ہے جو وہ اپنی پہلی آپشن ٹریڈ کو سائز کرنے کے لیے استعمال کرتی تھی۔ پریشانی آسان تھی: ایکسچینج نے لاٹ پر نظر ثانی کی تھی جب سے PDF لکھا گیا تھا۔ اس کی اصل پوزیشن مختلف سائز کی تھی، اس کا خطرہ اس کی سوچ سے بڑا تھا، اور اس کے بروکر نے جو مارجن بلاک کیا تھا وہ اس کی صاف ستھرا اسپریڈشیٹ سے میل نہیں کھاتا تھا۔ اس کے منصوبے کے بارے میں کچھ بھی احمقانہ نہیں تھا۔ اس نے ابھی ایک ایسے نمبر پر کام کیا تھا جو خاموشی سے ختم ہو گیا تھا جبکہ وہ نظر نہیں آرہا تھا۔ وہ واحد عادت - کسی اعداد و شمار کو کاپی کرنا اور کبھی بھی یہ نہیں جانچنا کہ یہ کب سچ ہے - وہی ہے جسے ٹھیک کرنے کے لیے یہ آخری باب موجود ہے۔</p>\n<p>یہ کورس اور اس کے ساتھی رسک مینجمنٹ کورس دونوں نمبروں سے بھرے ہوئے ہیں۔ بہت سائز۔ میعاد ختم ہونے کی تاریخیں۔ حاشیہ چارجز۔ ہیجنگ کے اخراجات۔ SEBI مطالعہ کے اعداد و شمار۔ ان میں سے ہر ایک حقیقت ہے جو بدل جاتی ہے۔ ایکسچینج معاہدے کے سائز پر نظر ثانی کرتے ہیں۔ SEBI مارجن اور سیٹلمنٹ کے قواعد کو اپ ڈیٹ کرتا ہے۔ ٹیکس اور اسٹامپ کے اعداد و شمار بجٹ اور سرکلر میں تبدیل ہوتے ہیں۔ 2024 کے مطالعے کے اعدادوشمار 2024 کو بیان کرتے ہیں، اگلے سال نہیں۔ لہذا سب سے مفید چیز جو ایک ابتدائی کورس سکھا سکتا ہے وہ نمبر نہیں ہے۔ یہ ایک عادت ہے: ہمیشہ جانیں کہ نمبر کہاں سے آتا ہے، اور ہمیشہ اس تاریخ کو جانیں کہ یہ سچ تھا۔</p>\n<h2 id=\"why-stale-numbers-and-second-hand-stats-are-dangerous\">باسی نمبر اور سیکنڈ ہینڈ اعدادوشمار خطرناک کیوں ہیں؟</h2>\n<p>غلط نمبر غلط محسوس نہیں ہوتا۔ یہ آپ کی اسپریڈشیٹ میں پرسکون اور پراعتماد نظر آتا ہے، اور یہ خاموشی سے اپنے اوپر بنائے گئے ہر حساب کو زہر دے دیتا ہے۔ ایک پرانا لاٹ سائز استعمال کریں اور آپ کی پوزیشن کا سائز بند ہے۔ ایک پرانا مارجن اصول استعمال کریں اور جب آپ کم از کم اس کی توقع کریں تو آپ کا اکاؤنٹ چھوٹا ہو گا۔ برسوں پرانے اعدادوشمار کا حوالہ دیں گویا یہ آج کی سچائی ہے اور آپ اپنے آپ کو ان مشکلات کے بارے میں گمراہ کرتے ہیں جن کا آپ کو درحقیقت سامنا ہے۔</p>\n<p>دوسرے ہاتھ کے اعدادوشمار ان کا اپنا جال ہیں۔ ایک شخصیت ایک سرکاری مطالعہ سے، خبر کی سرخی تک، فورم کی پوسٹ تک، ایک ریل تک سفر کرتی ہے، اور جب تک یہ آپ تک پہنچتی ہے، وہ اکثر اپنی تاریخ، اپنا ماخذ اور نصف معنی کھو چکی ہوتی ہے۔ ایماندارانہ حل ہر معاملے میں یکساں ہے: اصل ماخذ پر واپس جائیں، وہاں نمبر پڑھیں، اور اسے پڑھنے کی تاریخ لکھیں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 220\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"ایک چار قدم بہاؤ۔ جو نمبر آپ استعمال کرنا چاہتے ہیں وہ آفیشل سورس کی جانچ پڑتال کی طرف لے جاتا ہے، پھر اسے تاریخ کے مطابق ٹیگ کے ساتھ لکھتا ہے، پھر تجارت کرنے سے پہلے دوبارہ چیک کرتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"220\" rx=\"12\" fill=\"#0d1117\"/>\n  <defs>\n    <marker id=\"fv\" markerWidth=\"9\" markerHeight=\"9\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#4c72b0\"/></marker>\n  </defs>\n  <text x=\"380\" y=\"32\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">کسی بھی بدلتے ہوئے نمبر کو محفوظ میں تبدیل کریں۔</text>\n  <g font-family=\"sans-serif\">\n    <rect x=\"24\" y=\"64\" width=\"150\" height=\"92\" rx=\"10\" fill=\"#11161d\" stroke=\"#dd8452\" stroke-width=\"1.5\"/>\n    <text x=\"99\" y=\"100\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12.5\" font-weight=\"700\">ایک نمبر</text>\n    <text x=\"99\" y=\"120\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\">آپ چاہتے ہیں</text>\n    <text x=\"99\" y=\"136\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\">پر عمل کرنے کے لئے</text>\n    <line x1=\"178\" y1=\"110\" x2=\"206\" y2=\"110\" stroke=\"#4c72b0\" stroke-width=\"2\" marker-end=\"url(#fv)\"/>\n    <rect x=\"210\" y=\"64\" width=\"150\" height=\"92\" rx=\"10\" fill=\"#11161d\" stroke=\"#4c72b0\" stroke-width=\"1.5\"/>\n    <text x=\"285\" y=\"100\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12.5\" font-weight=\"700\">تصدیق کریں۔</text>\n    <text x=\"285\" y=\"120\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\">اہلکار میں</text>\n    <text x=\"285\" y=\"136\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\">ذریعہ</text>\n    <line x1=\"364\" y1=\"110\" x2=\"392\" y2=\"110\" stroke=\"#4c72b0\" stroke-width=\"2\" marker-end=\"url(#fv)\"/>\n    <rect x=\"396\" y=\"64\" width=\"150\" height=\"92\" rx=\"10\" fill=\"#11161d\" stroke=\"#8172b3\" stroke-width=\"1.5\"/>\n    <text x=\"471\" y=\"100\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12.5\" font-weight=\"700\">اسے ٹیگ کریں۔</text>\n    <text x=\"471\" y=\"120\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\">لکھیں \"کے طور پر</text>\n    <text x=\"471\" y=\"136\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\">29 جون 2026\"</text>\n    <line x1=\"550\" y1=\"110\" x2=\"578\" y2=\"110\" stroke=\"#4c72b0\" stroke-width=\"2\" marker-end=\"url(#fv)\"/>\n    <rect x=\"582\" y=\"64\" width=\"154\" height=\"92\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\" stroke-width=\"1.5\"/>\n    <text x=\"659\" y=\"100\" text-anchor=\"middle\" fill=\"#e6edf3\" font-size=\"12.5\" font-weight=\"700\">دوبارہ چیک کریں۔</text>\n    <text x=\"659\" y=\"120\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\">آپ سے پہلے</text>\n    <text x=\"659\" y=\"136\" text-anchor=\"middle\" fill=\"#cdd9e5\" font-size=\"11\">اس پر تجارت</text>\n  </g>\n  <text x=\"380\" y=\"194\" text-anchor=\"middle\" fill=\"#8b949e\" font-size=\"11\" font-family=\"sans-serif\">تاریخ کا ٹیگ حفاظت ہے۔ تاریخ کے بغیر نمبر یونیفارم پہنے ہوئے ایک اندازہ ہے۔</text>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">چار چھوٹے قدم ایک ایسے نمبر کو تبدیل کر دیتے ہیں جو آپ کو مل جاتا ہے جس پر آپ بھروسہ کر سکتے ہیں۔</figcaption>\n</figure><h2 id=\"the-fact-to-source-table\">حقیقت سے ماخذ کی میز</h2>\n<p>یہ باب کا دل ہے۔ اسے ایسی جگہ رکھیں جہاں آپ اسے تلاش کر سکیں۔ جب کوئی بدلتا ہوا حقیقت تجارت کے لیے اہمیت رکھتا ہے، تو اس کورس، بلاگ، یا چیٹ گروپ پر بھروسہ نہ کریں۔ قطار کے ماخذ پر جائیں اور موجودہ قدر خود پڑھیں۔</p>\n<table>\n<thead>\n<tr>\n<th>حقیقت</th>\n<th>جہاں تصدیق کرنی ہے۔</th>\n<th>نوٹ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>لاٹ سائزز اور کنٹریکٹ اسپیکس ( NIFTY، BANKNIFTY، اسٹاک F&amp;O)</td>\n<td>NSE nseindia.com پر ایکویٹی ڈیریویٹوز معاہدے کی معلومات کے صفحات</td>\n<td>ایکسچینجز وقتا فوقتا لاٹوں پر نظر ثانی کرتے ہیں۔ پوزیشن کو سائز دینے سے پہلے ہمیشہ موجودہ سائیکل کی تصدیق کریں۔</td>\n</tr>\n<tr>\n<td>ختم ہونے والا کیلنڈر اور تجارتی تعطیلات</td>\n<td>NSE اور متعلقہ ایکسچینج ویب سائٹ</td>\n<td>ہفتہ وار اور ماہانہ میعاد ختم ہونے کے دن اور چھٹیوں کی فہرستیں سال بہ سال بدلتی رہتی ہیں۔ سرکاری کیلنڈر چیک کریں، میموری نہیں۔</td>\n</tr>\n<tr>\n<td>SEBI F&amp;O نقصان کا مطالعہ (مثال کے طور پر ستمبر 2024 کا مطالعہ)</td>\n<td>sebi.gov.in مطالعہ اور پریس ریلیز</td>\n<td>ایک مطالعہ اپنی مدت کو بیان کرتا ہے۔ ستمبر 2024 کے مطالعہ میں پایا گیا کہ تقریباً 91% انفرادی F&amp;O تاجروں نے FY2024 میں رقم کھو دی - یعنی FY2024، کوئی مستقل قانون نہیں۔</td>\n</tr>\n<tr>\n<td>مارجن، چوٹی مارجن، تصفیہ (T+1) اور عہد کے اصول</td>\n<td>SEBI اور NSE سرکلر کے علاوہ آپ کا اپنا بروکر</td>\n<td>قواعد اور مسدود کردہ درست مارجن وقت کے ساتھ اور بروکر کے لحاظ سے مختلف ہوتے ہیں۔ تصدیق کریں کہ آپ کے اکاؤنٹ کو درحقیقت کیا درکار ہے۔</td>\n</tr>\n<tr>\n<td>چارجز: STT، ایکسچینج فیس، GST، اسٹامپ ڈیوٹی</td>\n<td>شیڈول اور آپ کے اپنے بروکر کنٹریکٹ نوٹ کا تبادلہ کریں۔</td>\n<td>آپ کا معاہدہ نوٹ اس بات کا حتمی لفظ ہے جو آپ نے ادا کی ہے۔ اس سے اپنا لاگت نمبر دوبارہ بنائیں، پرانے بلاگ سے نہیں۔</td>\n</tr>\n<tr>\n<td>آپشن پریمیم اور ہیج کے اخراجات</td>\n<td>آپ کا بروکر ٹرمینل اور کنٹریکٹ نوٹ، موجودہ مارکیٹ ڈیٹا کے خلاف</td>\n<td>پریمیم ہر سیشن میں مارکیٹ کے ساتھ منتقل ہوتے ہیں۔ ایک ہیج جو پچھلے مہینے سستا تھا شاید آج نہ ہو۔</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ہر بدلنے والا نمبر جس پر آپ تجارت کرتے ہیں - لاٹ سائز، ایکسپائری، مارجن، چارج، ہیج لاگت، یا SEBI فگر - جس دن آپ اسے استعمال کرتے ہیں اسے اس کے آفیشل سورس پر دوبارہ چیک کیا جانا چاہیے۔ ایک نمبر صرف اتنا ہی اچھا ہے جتنا اس کے ساتھ منسلک تاریخ ہے۔ کوئی تاریخ، کوئی بھروسہ نہیں۔</p>\n</div></div>\n<h2 id=\"the-as-of-habit\">\"کے طور پر <date>\"عادت</h2>\n<p>یہاں ایک ہی چال میں پورا نظم و ضبط ہے۔ جب بھی آپ بدلتے ہوئے نمبر لکھیں تو اس کے ساتھ تاریخ لکھیں۔ \"NIFTY لاٹ 65 (جون 2026 تک)۔\" \"تقریباً 91% انفرادی F&amp;O تاجروں نے پیسہ کھو دیا ( SEBI مطالعہ، FY2024)۔\" تاریخ سجاوٹ نہیں ہے۔ یہ حقیقت پر ختم ہونے والی مہر ہے۔ جب آپ اگلے مہینے واپس آتے ہیں، تو ڈاک ٹکٹ آپ کو ایک نظر میں بتاتا ہے کہ آیا نمبر تازہ ہے یا اسے دوبارہ چیک کرنے کی ضرورت ہے۔</p>\n<p>مجھے اس کورس کے اپنے نمبروں کے بارے میں ایماندار رہنے دو، کیونکہ یہی اصول مجھے پابند کرتا ہے۔ جہاں یہ کورسز کہتے ہیں کہ NIFTY لاٹ تقریباً 65 ہے، یہ تقریباً اپریل سے جون 2026 تک درست ہے اور ایکسچینج کی نظرثانی کے اعداد و شمار کی قسم ہے۔ جہاں وہ یہ بتاتے ہیں کہ تقریباً 91% انفرادی F&amp;O تاجروں نے پیسے کھو دیے ہیں، یہ SEBI ستمبر 2024 کا مطالعہ ہے جو FY2024 کو بیان کرتا ہے۔ دونوں وقتی حقائق ہیں۔ ان کو توثیق کے لیے نقطہ آغاز کے طور پر سمجھیں، کبھی بھی مقررہ مستقل کے طور پر نہیں۔ اگر آپ اسے اب سے ایک سال بعد پڑھ رہے ہیں، تو فرض کریں کہ ان میں سے کم از کم ایک منتقل ہو گیا ہے اور چیک کریں۔</p>\n<figure class=\"quant-figure\">\n<svg viewBox=\"0 0 760 300\" style=\"width:100%;height:auto;max-width:760px;display:block;margin:0.5rem auto\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"دو پینلز کے درمیان تضاد۔ بائیں پینل پرانے ماخذ سے نقل کردہ ایک باسی نمبر دکھاتا ہے جو غلط پوزیشن اور مارجن سرپرائز کا باعث بنتا ہے۔ دائیں پینل ایک دوبارہ تصدیق شدہ نمبر دکھاتا ہے جو درست سائز اور صحیح مارجن کی طرف جاتا ہے۔\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"300\" rx=\"12\" fill=\"#0d1117\"/>\n  <text x=\"380\" y=\"32\" text-anchor=\"middle\" fill=\"#e6edf3\" font-weight=\"700\" font-size=\"16\" font-family=\"sans-serif\">قدیم نمبر بمقابلہ موجودہ نمبر</text>\n  <g font-family=\"sans-serif\">\n    <rect x=\"28\" y=\"56\" width=\"338\" height=\"212\" rx=\"10\" fill=\"#11161d\" stroke=\"#c44e52\" stroke-width=\"1.5\"/>\n    <text x=\"197\" y=\"84\" text-anchor=\"middle\" fill=\"#c44e52\" font-size=\"13.5\" font-weight=\"700\">STALE - کاپی کیا گیا، کوئی تاریخ نہیں۔</text>\n    <text x=\"50\" y=\"116\" fill=\"#cdd9e5\" font-size=\"11.5\">لاٹ سائز 2 سالہ PDF سے لیا گیا ہے۔</text>\n    <text x=\"50\" y=\"142\" fill=\"#cdd9e5\" font-size=\"11.5\">ایک فورم سے حوالہ دیا گیا اسٹیٹ، کوئی ذریعہ نہیں۔</text>\n    <text x=\"50\" y=\"168\" fill=\"#cdd9e5\" font-size=\"11.5\">مارجن کا قاعدہ یاد ہے، چیک نہیں کیا گیا۔</text>\n    <line x1=\"50\" y1=\"186\" x2=\"344\" y2=\"186\" stroke=\"#30363d\" stroke-width=\"1\"/>\n    <text x=\"50\" y=\"212\" fill=\"#c44e52\" font-size=\"12\" font-weight=\"700\">نتیجہ</text>\n    <text x=\"50\" y=\"234\" fill=\"#cdd9e5\" font-size=\"11.5\">غلط پوزیشن کا سائز، مارجن حیرت،</text>\n    <text x=\"50\" y=\"252\" fill=\"#cdd9e5\" font-size=\"11.5\">ایک ایسے نمبر پر بنایا گیا منصوبہ جس کی میعاد ختم ہو گئی۔</text>\n    <rect x=\"394\" y=\"56\" width=\"338\" height=\"212\" rx=\"10\" fill=\"#11161d\" stroke=\"#55a868\" stroke-width=\"1.5\"/>\n    <text x=\"563\" y=\"84\" text-anchor=\"middle\" fill=\"#55a868\" font-size=\"13.5\" font-weight=\"700\">CURRENT - تصدیق شدہ، تاریخ</text>\n    <text x=\"416\" y=\"116\" fill=\"#cdd9e5\" font-size=\"11.5\">لاٹ سائز آج nseindia.com پر پڑھا گیا۔</text>\n    <text x=\"416\" y=\"142\" fill=\"#cdd9e5\" font-size=\"11.5\">SEBI مطالعہ اور سال سے اعداد و شمار کا پتہ لگایا گیا۔</text>\n    <text x=\"416\" y=\"168\" fill=\"#cdd9e5\" font-size=\"11.5\">مارجن آپ کے بروکر سے تصدیق شدہ ہے۔</text>\n    <line x1=\"416\" y1=\"186\" x2=\"710\" y2=\"186\" stroke=\"#30363d\" stroke-width=\"1\"/>\n    <text x=\"416\" y=\"212\" fill=\"#55a868\" font-size=\"12\" font-weight=\"700\">نتیجہ</text>\n    <text x=\"416\" y=\"234\" fill=\"#cdd9e5\" font-size=\"11.5\">درست سائز، صحیح مارجن، اور a</text>\n    <text x=\"416\" y=\"252\" fill=\"#cdd9e5\" font-size=\"11.5\">نمبر آپ اس کی تاریخ کے ساتھ دفاع کر سکتے ہیں.</text>\n  </g>\n</svg>\n<figcaption style=\"text-align:center;color:#9a9a9a;font-size:0.82rem;margin-top:0.3rem\">وہی تاجر، وہی کوشش۔ فرق صرف اتنا ہے کہ آیا نمبر دوبارہ چیک کیا گیا اور تاریخ کی گئی۔</figcaption>\n</figure>\n<div class=\"callout mistake\"><span class=\"callout-tag\">عام غلطی</span><div><p>کلاسیکی ابتدائی غلطی کورس کے پرانے لاٹ سائز، یا سالوں پرانے نقصان کے اعدادوشمار کو اس طرح ٹریٹ کر رہی ہے جیسے یہ مستقل ہو۔ \"NIFTY لاٹ 65 ہے، کورس نے ایسا کہا\" یا \"91% F&amp;O ٹریڈرز ہار گئے، یہ صرف ایک حقیقت ہے\" - دونوں پوائنٹ ان ٹائم ہیں، اور دونوں بڑھ جائیں گے۔ بہتر اقدام یہ ہے کہ آئیڈیا کو سمجھنے کے لیے کورس نمبر کا استعمال کریں، پھر آفیشل سورس کھولیں اور موجودہ اعداد و شمار کی تصدیق کریں اس سے پہلے کہ اس پر کوئی حقیقی رقم لگائی جائے۔</p>\n</div></div>\n<h2 id=\"how-often-each-user-type-re-checks\">ہر صارف کی قسم کتنی بار دوبارہ چیک کرتی ہے۔</h2>\n<p>عادت سب کی ایک جیسی ہے۔ صرف تعدد بدلتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>صارف کی قسم</th>\n<th>وہ نمبر جو سب سے زیادہ اہمیت رکھتے ہیں۔</th>\n<th>کتنی بار دوبارہ تصدیق کرنی ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مدتی سرمایہ کار</td>\n<td>ٹیکس کے قوانین، چارجز، سیٹلمنٹ سائیکل</td>\n<td>ہر سال اور بجٹ کی تبدیلیوں کے ارد گرد ایک فوری جانچ پڑتال</td>\n</tr>\n<tr>\n<td>سوئنگ یا پوزیشنی تاجر</td>\n<td>لاٹ سائز، ایکسپائری کیلنڈر، چارجز</td>\n<td>ہر نیا معاہدہ سائیکل اور چھٹیوں کے مختصر ہفتے سے پہلے</td>\n</tr>\n<tr>\n<td>انٹرا ڈے یا ایف اینڈ او ٹریڈر</td>\n<td>لاٹ سائز، مارجن، ایکسپائری ڈے، چارجز</td>\n<td>ہر تازہ سیریز سے پہلے، اور کسی بھی وقت ایک سرکلر لینڈ کرتا ہے۔</td>\n</tr>\n<tr>\n<td>آپشن بیچنے والا یا ہیجر</td>\n<td>مارجن، عہد کے اصول، ہیج اور پریمیم کے اخراجات</td>\n<td>ہر پوزیشن سے پہلے، چونکہ مارجن اور اخراجات مسلسل حرکت کرتے ہیں۔</td>\n</tr>\n</tbody></table>\n<h2 id=\"a-quiet-word-on-the-human-side\">انسانی طرف ایک خاموش لفظ</h2>\n<p>ایک بدلتی ہوئی حقیقت کسی بھی تبادلے کے صفحے پر نہیں ہے۔ یہ تم ہو اگر ٹریڈنگ نقصانات کا پیچھا کرنے، خاندان سے پوزیشن چھپانے، یا کھیل میں رہنے کے لیے قرض لینے کی طرح محسوس کرنے لگی ہے، تو یہ کسی بھی مارجن اصول کی طرح سنجیدگی سے لینے کے قابل ہے۔ مسئلہ جوئے کی ہیلپ لائنز اور پیشہ ورانہ مشاورت کی خدمات موجود ہیں، اور کسی تک پہنچنا طاقت کی علامت ہے، ناکامی نہیں۔ یہ کورس کسی ایک سروس کی توثیق نہیں کرتا ہے - نقطہ صرف یہ ہے کہ مدد حقیقی ہے، یہ دستیاب ہے، اور اس کا استعمال ہمیشہ ایک درست اقدام ہے۔</p>\n<h2 id=\"when-this-fails\">جب یہ ناکام ہوجاتا ہے۔</h2>\n<p>یہاں تک کہ اچھے ذرائع کی بھی حد ہوتی ہے، لہذا صحیح طریقے سے شک میں رہیں۔</p>\n<p>ذرائع میں تاخیر۔ ایک سرکلر ویب سائٹ کے صفحہ، ایپ، یا PDF سے پہلے کی تاریخ سے مؤثر ہو سکتا ہے جسے آپ پڑھ رہے ہیں۔ بجٹ کے اعلانات اور قواعد میں تبدیلی کے ارد گرد، فیصلے اور صاف خلاصہ کے درمیان فرق کی توقع کریں۔ شک ہونے پر، اصل سرکلر پڑھیں، نہ کہ ریکیپ۔</p>\n<p>بروکرز مختلف ہیں۔ دو اکاؤنٹس ایک ہی پوزیشن کے لیے مختلف بلاک شدہ مارجن دکھا سکتے ہیں کیونکہ بروکر کی پالیسیاں اور بفرز کم از کم ایکسچینج کے اوپر ہیں۔ ایکسچینج اور SEBI نے منزل طے کی۔ آپ کا اپنا بروکر سیٹ کرتا ہے کہ آپ اصل میں کیا ادا کرتے ہیں اور کیا پوسٹ کرتے ہیں۔ اس لیے آپ کے پیسے کے لیے حتمی، بائنڈنگ نمبر آپ کے اکاؤنٹ میں اور آپ کے کنٹریکٹ نوٹ پر ہے، کسی بھی کورس سے کوئی عام شخصیت نہیں - اس میں شامل ہے۔</p>\n<p>اور کوئی میز ہمیشہ کے لیے مکمل نہیں ہوتا۔ نئی مصنوعات، نئے قوانین، اور نئے مطالعہ ظاہر ہوتے ہیں. اس صفحہ کو سوچنے کا ایک طریقہ سمجھیں، نہ کہ روابط کی ایک مقررہ فہرست۔ جو مہارت رہتی ہے وہ عادت ہے: ذریعہ تلاش کریں، موجودہ نمبر پڑھیں، تاریخ کے ساتھ اس پر مہر لگائیں، اور تجارت کرنے سے پہلے دوبارہ چیک کریں۔</p>\n<p>یہ باب صرف تعلیم کے لیے ہے اور سرمایہ کاری کا مشورہ نہیں ہے۔ یہاں ذکر کردہ ہر اعداد و شمار ایک پوائنٹ ان ٹائم مثال ہے جس کی تصدیق اس کے ماخذ پر کی جائے، نہ کہ آپ کے اپنے پیسوں کی سفارش۔</p>\n<h2 id=\"quick-self-check\">فوری خود چیک کریں۔</h2>\n<details>\n<summary><strong>1.</strong> تاریخ کے بغیر نمبر خطرناک کیوں ہے؟</summary><p>کیونکہ لاٹ سائزز، مارجنز، چارجز، اور مطالعہ کے اعدادوشمار جیسے حقائق کو تبدیل کرنا وقت کے ساتھ ساتھ تبدیل ہوتا رہتا ہے۔ تاریخ کے بغیر آپ یہ نہیں بتا سکتے کہ نمبر موجودہ ہے یا ختم ہو چکا ہے، اس لیے اس پر بنایا گیا ہر حساب خاموشی سے غلط ہو سکتا ہے۔</p>\n</details><details>\n<summary><strong>2.</strong> آپ موجودہ NIFTY لاٹ سائز اور معاہدے کی تفصیلات کی کہاں تصدیق کریں گے؟</summary><p>NSE nseindia.com پر ایکویٹی ڈیریویٹوز کنٹریکٹ کی معلومات کے صفحات پر، جس دن آپ پوزیشن کو سائز کرنے کا ارادہ رکھتے ہیں اسے پڑھیں۔ پرانے PDF، بلاگ، یا چیٹ گروپ سے نہیں۔</p>\n</details><details>\n<summary><strong>3.</strong> کورس کہتا ہے کہ تقریباً 91% انفرادی F&amp;O تاجروں نے رقم کھو دی۔ آپ کو اس اعداد و شمار کا علاج کیسے کرنا چاہئے؟</summary><p>SEBI ستمبر 2024 کے مطالعہ سے ایک وقتی حقیقت کے طور پر جو کہ FY2024 کی وضاحت کرتا ہے، sebi.gov.in پر تلاش کیا جاسکتا ہے۔ یہ اس مدت کے لیے ایک حقیقی تلاش ہے، کوئی مستقل قانون نہیں، اس لیے اسے آج کی سچائی کے طور پر پیش کرنے سے پہلے تازہ ترین مطالعہ کی جانچ کریں۔</p>\n</details><details>\n<summary><strong>4.</strong> دو تاجر ایک ہی پوزیشن پر فائز ہیں لیکن مختلف مارجن بلاک نظر آتے ہیں۔ کیوں، اور کون سا نمبر پابند ہے؟</summary><p>بروکرز کم از کم ایکسچینج کے اوپر اپنی پالیسیاں اور بفرز شامل کرتے ہیں، اس لیے بلاک شدہ رقم مختلف ہو سکتی ہے۔ آپ کے پیسے کے لیے بائنڈنگ نمبر وہی ہے جو آپ کا اپنا بروکر دکھاتا ہے اور جو آپ کے کنٹریکٹ نوٹ پر ظاہر ہوتا ہے۔</p>\n</details><details>\n<summary><strong>5.</strong> ایک لائن میں \"تاریخ کے مطابق\" عادت کیا ہے؟</summary><p>جب بھی آپ کوئی بدلتا ہوا نمبر لکھیں، اس کے ساتھ تاریخ لکھیں، پھر اس پر تجارت کرنے سے پہلے آفیشل سورس پر دوبارہ تصدیق کریں۔ تاریخ ایکسپائری سٹیمپ ہے جو آپ کو بتاتی ہے کہ کب دوبارہ چیک کرنا ہے۔</p>\n</details>\n","toc":[{"level":2,"text":"باسی نمبر اور سیکنڈ ہینڈ اعدادوشمار خطرناک کیوں ہیں؟","id":"why-stale-numbers-and-second-hand-stats-are-dangerous"},{"level":2,"text":"حقیقت سے ماخذ کی میز","id":"the-fact-to-source-table"},{"level":2,"text":"\"کے طور پر \"عادت","id":"the-as-of-habit"},{"level":2,"text":"ہر صارف کی قسم کتنی بار دوبارہ چیک کرتی ہے۔","id":"how-often-each-user-type-re-checks"},{"level":2,"text":"انسانی طرف ایک خاموش لفظ","id":"a-quiet-word-on-the-human-side"},{"level":2,"text":"جب یہ ناکام ہوجاتا ہے۔","id":"when-this-fails"},{"level":2,"text":"فوری خود چیک کریں۔","id":"quick-self-check"}],"imgCount":0,"hasContent":true}}
